    def click_shop_tab(self, label: str) -> ActionReceipt:
        if not isinstance(label, str) or not label:
            raise SemanticGateClosed("shop tab label is invalid")
        if not self.munitions_page_visible():
            raise SemanticGateClosed("shop page identity is absent")
        state = self.read_state()
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("shop tab snapshots are not coherent")
        labels = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith("/unselected/Label")
            and "ShopSupplyShopUI(Clone)/toggleGroup/" in text.path
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and re.sub(r"<[^>]*>", "", text.text).strip() == label
        )
        if len(labels) != 1 or labels[0].bounds is None:
            raise SemanticGateClosed("shop tab label is absent or ambiguous")
        label_bounds = labels[0].bounds
        controls = tuple(
            button
            for button in state.buttons
            if button.name == "Toggle(Clone)"
            and button.path.endswith(
                "ShopSupplyShopUI(Clone)/toggleGroup/Toggle(Clone)"
            )
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds is not None
            and button.bounds.left <= label_bounds.left
            and button.bounds.right >= label_bounds.right
            and button.bounds.top <= label_bounds.top
            and button.bounds.bottom >= label_bounds.bottom
        )
        if len(controls) != 1:
            raise SemanticGateClosed("shop tab control is absent or ambiguous")
        bounds = controls[0].bounds
        assert bounds is not None
        point = Point(
            (bounds.left + bounds.right) / 2, (bounds.top + bounds.bottom) / 2
        )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="shop/tab/" + label,
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=controls[0].path,
        )

    @staticmethod
    def _canonical_general_shop_name(display_name: str) -> str:
        book = re.fullmatch(r"舰艇(攻击|防御|辅助)教材T([1-4])", display_name)
        if book is not None:
            genre = {"攻击": "Red", "防御": "Blue", "辅助": "Yellow"}[book.group(1)]
            return f"Book{genre}T{book.group(2)}"
        box = re.fullmatch(r"(?:.+)?科技箱T([1-5])", display_name)
        if box is not None:
            return f"BoxT{box.group(1)}"
        plate = re.fullmatch(
            r"(主炮|鱼雷|防空炮|舰载机|通用)部件T([1-4])", display_name
        )
        if plate is not None:
            kind = {
                "主炮": "Gun",
                "鱼雷": "Torpedo",
                "防空炮": "Antiair",
                "舰载机": "Plane",
                "通用": "General",
            }[plate.group(1)]
            return f"Plate{kind}T{plate.group(2)}"
        if display_name == "心智魔方":
            return "Cube"
        if display_name == "心智单元":
            return "Chip"
        if display_name in ("心智单元Ⅱ", "心智单元II"):
            return "Array"
        if display_name == "九三式纯氧鱼雷":
            return "Type93PureOxygenTorpedo"
        if display_name == "一式穿甲弹":
            return "Type1ArmorPiercingShell"
        if display_name == "超重弹":
            return "SuperHeavyShell"
        if re.fullmatch(r"高级定向蓝图・[^・]+", display_name):
            return "DR"
        if re.fullmatch(r"定向蓝图・[^・]+", display_name):
            return "PR"
        if display_name == "满汉全席":
            return "FoodT6"
        if display_name == "皇家料理":
            return "FoodT5"
        if display_name == "快速完成工具":
            return "Drill"
        generic_book = re.fullmatch(r"舰艇教材T([1-4])", display_name)
        if generic_book is not None:
            return f"BookT{generic_book.group(1)}"
        generic_plate = re.fullmatch(r"强化部件T([1-4])", display_name)
        if generic_plate is not None:
            return f"PlateT{generic_plate.group(1)}"
        generic_retrofit = re.fullmatch(r"改造图纸T([1-4])", display_name)
        if generic_retrofit is not None:
            return f"RetrofitT{generic_retrofit.group(1)}"
        return "DefaultItem"

    def general_shop_items(self) -> Tuple[GeneralShopItemState, ...]:
        """Return the ten exact cards from the selected Supply Shop tab."""

        if not self.munitions_page_visible():
            raise SemanticGateClosed("supply shop is not selected")
        button_state = self.read_state()
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("general-shop item snapshots are not coherent")

        def one_text(suffix: str, *, digits: bool = False) -> str:
            matches = tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
                and (not digits or re.fullmatch(r"[0-9]+", text.text.strip()))
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "general-shop item text is absent or ambiguous"
                )
            return matches[0].text.strip()

        def one_image(suffix: str) -> ImageState:
            matches = tuple(
                image
                for image in ui_state.images
                if image.path.endswith(suffix)
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "general-shop item image is absent or ambiguous"
                )
            return matches[0]

        items = []
        for index in range(10):
            root = f"ShopSupplyShopUI(Clone)/scroll/content/{index}"
            buttons = tuple(
                button
                for button in button_state.buttons
                if button.name == str(index)
                and button.path.endswith(root)
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.bounds is not None
            )
            if len(buttons) != 1:
                raise SemanticGateClosed(
                    "general-shop item card is absent or ambiguous"
                )
            display_name = one_text(root + "/name_mask/name")
            amount = int(one_text(root + "/itemBg/item/icon_bg/count", digits=True))
            price = int(one_text(root + "/consume/contain/Text", digits=True))
            cost_sprite = one_image(root + "/consume/contain/icon").sprite
            cost_names = {
                "gold": "Coins",
                "gem": "Gems",
                "exploit": "Merit",
                "guildicon": "GuildCoins",
                "guild_coin": "GuildCoins",
                "res_guildicon": "GuildCoins",
                "core": "Core",
                "shuju": "Core",
                "medal": "Medal",
            }
            if cost_sprite not in cost_names:
                raise SemanticGateClosed("general-shop item currency is unknown")
            icon_sprite = one_image(root + "/itemBg/item/icon_bg/icon").sprite
            stock = tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(root + "/count_contain/label")
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            if len(stock) > 1:
                raise SemanticGateClosed("shop item stock is ambiguous")
            remaining = total = None
            if stock:
                match = re.fullmatch(
                    r"(?:可兑换次数)?([0-9]+)/([1-9][0-9]*)",
                    "".join(stock[0].text.split()),
                )
                if match is None:
                    raise SemanticGateClosed("shop item stock is malformed")
                remaining, total = map(int, match.groups())
                if remaining > total:
                    raise SemanticGateClosed("shop item stock exceeds its limit")
            items.append(
                GeneralShopItemState(
                    generation=ui_state.generation,
                    index=index,
                    display_name=display_name,
                    canonical_name=self._canonical_general_shop_name(display_name),
                    amount=amount,
                    cost=cost_names[cost_sprite],
                    price=price,
                    icon_sprite=icon_sprite,
                    bounds=buttons[0].bounds,
                    remaining=remaining,
                    total=total,
                )
            )
        return tuple(items)

    def shop_currency_balance(self, currency: str) -> int:
        """Read the exact balance for the selected ordinary shop currency."""

        if not self.munitions_page_visible():
            raise SemanticGateClosed("shop page identity is absent")
        nav = self.shop_selected_nav_label()
        tab = self.shop_selected_tab_label()
        allowed = {
            "Coins": ("补给商店", "军火"),
            "Gems": ("补给商店", "军火"),
            "Merit": ("补给商店", "军需"),
            "GuildCoins": ("补给商店", "舰队"),
            "Core": ("月度商店", "核心月度"),
            "Medal": ("月度商店", "勋章"),
        }
        if allowed.get(currency) != (nav, tab):
            raise SemanticGateClosed("shop currency does not match the selected tab")
        paths = {
            "Coins": "OverlayCamera/Overlay/UIMain/buttonList/top/resources/gold/Text",
            "Gems": "OverlayCamera/Overlay/UIMain/buttonList/top/resources/gem/Text",
            "Merit": "OverlayCamera/Overlay/UIMain/ShopSupplyShopUI(Clone)/bg/resList/res(Clone)/Text",
            "GuildCoins": "OverlayCamera/Overlay/UIMain/ShopSupplyShopUI(Clone)/bg/resList/res(Clone)/Text",
            "Core": "OverlayCamera/Overlay/UIMain/ShopSupplyShopUI(Clone)/bg/resList/res(Clone)/Text",
            "Medal": "OverlayCamera/Overlay/UIMain/ShopSupplyShopUI(Clone)/bg/resList/res(Clone)/Text",
        }
        state = self.read_ui_state()
        matches = tuple(
            text
            for text in state.texts
            if text.path.endswith(paths[currency])
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and re.fullmatch(r"[0-9]+", text.text.strip()) is not None
        )
        if len(matches) != 1:
            raise SemanticGateClosed("shop currency balance is absent or ambiguous")
        return int(matches[0].text.strip())

    def click_shop_refresh(self) -> ActionReceipt:
        """Open the exact selected shop's refresh confirmation."""

        if not self.shop_refresh_available():
            raise SemanticGateClosed("shop refresh is not available")
        state = self.read_state()
        path = "OverlayCamera/Overlay/UIMain/ShopSupplyShopUI(Clone)/timeBtn"
        buttons = tuple(
            button
            for button in state.buttons
            if button.path == path
            and button.name == "timeBtn"
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.raycast_top is not False
            and button.bounds is not None
        )
        if len(buttons) != 1:
            raise SemanticGateClosed("shop refresh control is absent or ambiguous")
        bounds = buttons[0].bounds
        assert bounds is not None
        point = Point(
            (bounds.left + bounds.right) / 2.0,
            (bounds.top + bounds.bottom) / 2.0,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="shop/refresh/open",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=buttons[0].path,
        )

    def shop_refresh_prompt(self) -> Optional[Tuple[str, int]]:
        """Return the exact currency and price from a supported refresh prompt."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        if not state.generation <= ui_state.generation <= state.generation + 2:
            raise SemanticGateClosed("shop refresh prompt snapshots are not coherent")
        root = "OverlayCamera/Overlay/UIMain/Msgbox(Clone)/window/"
        controls = {
            "confirm": root + "button_container/custom_button_1(Clone)",
            "cancel": root + "button_container/custom_button_2(Clone)",
        }
        buttons = {
            key: tuple(button for button in state.buttons if button.path.endswith(path))
            for key, path in controls.items()
        }
        contents = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith(root + "msg_panel/content")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if not contents and not any(buttons.values()):
            return None
        if any(len(value) != 1 for value in buttons.values()) or len(contents) != 1:
            raise SemanticGateClosed("shop refresh prompt is incomplete or ambiguous")
        labels = {
            key: tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(path + "/pic")
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
            )
            for key, path in controls.items()
        }
        if (
            any(len(value) != 1 for value in labels.values())
            or "".join(labels["confirm"][0].text.split()) != "确定"
            or "".join(labels["cancel"][0].text.split()) != "取消"
        ):
            raise SemanticGateClosed("shop refresh prompt labels changed")
        for button in (value[0] for value in buttons.values()):
            if not (
                button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.bounds is not None
            ):
                raise SemanticGateClosed("shop refresh prompt is not actionable")
        message = "".join(contents[0].text.split())
        match = re.fullmatch(
            r"是否花费([1-9][0-9]*)<color=#[0-9A-Fa-f]{6}>([^<]+)</color>刷新商品列表",
            message,
        )
        if match is None:
            raise SemanticGateClosed("shop refresh prompt cost is malformed")
        currency_names = {"舰队币": "GuildCoins"}
        currency = currency_names.get(match.group(2))
        if currency is None:
            raise SemanticGateClosed("shop refresh currency is unsupported")
        if self.shop_selected_tab_label() != "舰队":
            raise SemanticGateClosed("shop refresh prompt is on an unsupported tab")
        return currency, int(match.group(1))

    def click_shop_refresh_confirm(
        self, expected_currency: str, expected_price: int
    ) -> ActionReceipt:
        if self.shop_refresh_prompt() != (expected_currency, expected_price):
            raise SemanticGateClosed("shop refresh prompt changed")
        state = self.read_state()
        path = (
            "OverlayCamera/Overlay/UIMain/Msgbox(Clone)/window/"
            "button_container/custom_button_1(Clone)"
        )
        buttons = tuple(button for button in state.buttons if button.path.endswith(path))
        if len(buttons) != 1 or not buttons[0].actionable:
            raise SemanticGateClosed("shop refresh confirmation is not actionable")
        bounds = buttons[0].bounds
        point = buttons[0].point
        assert bounds is not None and point is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="shop/refresh/confirm",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=buttons[0].path,
        )

    @staticmethod
    def _canonical_operation_siren_shop_name(
        display_name: str, icon_sprite: str
    ) -> str:
        names = {
            "超空泡发生器": "SupercavitationGenerator",
            "可塑性机械臂": "NeuroplasticProstheticArm",
            "纳米陶铝合金": "NanoceramicAlloy",
            "结晶化热强钢": "CrystallizedHeatResistantSteel",
        }
        sprite_names = {
            "Wdashijiezhaungbeibi": "PurpleCoins",
            "Wsucaixiang1": "DevelopmentMaterialT1",
            "Wsucaixiang2": "DevelopmentMaterialT2",
            "Wsucaixiang3": "DevelopmentMaterialT3",
            "Wxingdonglihuifu1": "ActionPoint20",
            "Wxingdonglihuifu2": "ActionPoint50",
            "Wxingdonglihuifu3": "ActionPoint100",
        }
        if icon_sprite in sprite_names:
            return sprite_names[icon_sprite]
        if display_name in names:
            return names[display_name]
        if display_name.startswith("META通用战术") and icon_sprite in (
            "16031",
            "16032",
        ):
            return "METARedBook"
        raise SemanticGateClosed("Operation Siren shop item name is unknown")

    def operation_siren_shop_items(
        self,
    ) -> Tuple[OperationSirenShopItemState, ...]:
        """Read the post-2026 unified four-port exchange page."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("Operation Siren shop snapshots are not coherent")
        root = "OverlayCamera/Overlay/UIMain/blur_panel/adapt/new_shop/"
        currency_names = tuple(
            text
            for text in ui_state.texts
            if text.path == root + "frame/content/right/page/title/res/icon/name"
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.text.strip() == "特别兑换凭证"
        )
        currency_values = tuple(
            text
            for text in ui_state.texts
            if text.path == root + "frame/content/right/page/title/res/Text"
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and re.fullmatch(r"[0-9]+", text.text.strip())
        )
        ports = sorted(
            text.text.strip()
            for text in ui_state.texts
            if text.path.startswith(root + "frame/content/left/port_tpl")
            and text.path.endswith("/Text")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
        )
        if (
            len(currency_names) != 1
            or len(currency_values) != 1
            or ports != sorted(("NY", "利维浦", "圣彼得伯格", "直布罗特"))
        ):
            raise SemanticGateClosed(
                "unified Operation Siren shop identity is not proven"
            )

        anchors = {}
        for button in state.buttons:
            if not (
                button.path.startswith(root)
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.bounds is not None
                and (
                    (
                        button.name in ("item_tpl", "item_tpl(Clone)")
                        and "/container/item_tpl" in button.path
                    )
                    or (
                        button.name == "mask"
                        and "/container/item_tpl" in button.path
                        and button.path.endswith("/mask")
                    )
                )
            ):
                continue
            anchors.setdefault(button.bounds, button)
        cards = sorted(
            anchors.values(), key=lambda button: (button.bounds.top, button.bounds.left)
        )
        if not 4 <= len(cards) <= 20:
            raise SemanticGateClosed(
                "unified Operation Siren shop card count is outside 4..20"
            )

        def centered_text(card: ButtonState, suffix: str, pattern: str) -> str:
            assert card.bounds is not None
            matches = []
            for text in ui_state.texts:
                if (
                    not text.path.endswith(suffix)
                    or not text.active_in_hierarchy
                    or not text.active_and_enabled
                    or text.truncated
                    or text.bounds is None
                    or re.fullmatch(pattern, text.text.strip()) is None
                ):
                    continue
                x = (text.bounds.left + text.bounds.right) / 2.0
                y = (text.bounds.top + text.bounds.bottom) / 2.0
                if (
                    card.bounds.left <= x <= card.bounds.right
                    and card.bounds.top <= y <= card.bounds.bottom + 30.0
                ):
                    matches.append(text.text.strip())
            if len(matches) != 1:
                raise SemanticGateClosed("Operation Siren shop card text is ambiguous")
            return matches[0]

        def centered_icon(card: ButtonState, suffix: str) -> str:
            assert card.bounds is not None
            matches = []
            for image in ui_state.images:
                if (
                    not image.path.endswith(suffix)
                    or not image.active_in_hierarchy
                    or not image.active_and_enabled
                    or image.truncated
                    or image.bounds is None
                ):
                    continue
                x = (image.bounds.left + image.bounds.right) / 2.0
                y = (image.bounds.top + image.bounds.bottom) / 2.0
                if card.bounds.contains(Point(x=x, y=y)):
                    matches.append(image.sprite)
            if len(matches) != 1:
                raise SemanticGateClosed("Operation Siren shop card icon is ambiguous")
            return matches[0]

        result = []
        for index, card in enumerate(cards):
            display_name = centered_text(card, "/name_mask/name", r".+")
            amount = int(centered_text(card, "/IconTpl/icon_bg/count", r"[0-9]+"))
            price = int(centered_text(card, "/consume/contain/Text", r"[0-9]+"))
            counter = centered_text(card, "/count_contain/count", r"[0-9]+/[0-9]+")
            remaining, total = map(int, counter.split("/"))
            if remaining > total:
                raise SemanticGateClosed("Operation Siren shop counter is inconsistent")
            currency_sprite = centered_icon(card, "/consume/contain/icon")
            currency_names = {
                "Wdashijiezhaungbeibi": "SpecialExchangeTicket",
                "Wdashijiehuobi": "YellowCoins",
            }
            if currency_sprite not in currency_names:
                raise SemanticGateClosed("Operation Siren shop currency is unknown")
            icon_sprite = centered_icon(card, "/IconTpl/icon_bg/icon")
            result.append(
                OperationSirenShopItemState(
                    generation=ui_state.generation,
                    index=index,
                    display_name=display_name,
                    canonical_name=self._canonical_operation_siren_shop_name(
                        display_name, icon_sprite
                    ),
                    amount=amount,
                    remaining=remaining,
                    total=total,
                    price=price,
                    currency=currency_names[currency_sprite],
                    icon_sprite=icon_sprite,
                    bounds=card.bounds,
                )
            )
        return tuple(result)

    def operation_siren_shop_currency(self) -> int:
        self._retry_transition_read(
            self.operation_siren_shop_items,
            attempts=8,
            interval_seconds=0.2,
        )
        ui_state = self.read_ui_state()
        matches = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith("new_shop/frame/content/right/page/title/res/Text")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and re.fullmatch(r"[0-9]+", text.text.strip())
        )
        if len(matches) != 1:
            raise SemanticGateClosed("Operation Siren shop currency is ambiguous")
        return int(matches[0].text.strip())

    def click_operation_siren_shop_item(
        self,
        index: int,
        expected_name: str,
        expected_price: int,
    ) -> ActionReceipt:
        """Open one exact item on the unified Operation Siren exchange page."""

        if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < 20:
            raise SemanticGateClosed("Operation Siren shop item index is invalid")
        items = self._retry_transition_read(
            self.operation_siren_shop_items,
            attempts=8,
            interval_seconds=0.2,
        )
        item = next((candidate for candidate in items if candidate.index == index), None)
        if item is None or item.bounds is None:
            raise SemanticGateClosed("Operation Siren shop item is absent")
        if item.canonical_name != expected_name or item.price != expected_price:
            raise SemanticGateClosed("Operation Siren shop item identity changed")
        if item.remaining <= 0:
            raise SemanticGateClosed("Operation Siren shop item is sold out")

        state = self.read_state()
        root = "OverlayCamera/Overlay/UIMain/blur_panel/adapt/new_shop/"
        controls = tuple(
            button
            for button in state.buttons
            if button.path.startswith(root)
            and button.name in ("item_tpl", "item_tpl(Clone)")
            and "/container/item_tpl" in button.path
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds == item.bounds
        )
        if len(controls) != 1:
            raise SemanticGateClosed(
                "Operation Siren shop item control is absent or ambiguous"
            )
        bounds = item.bounds
        point = Point(
            x=(bounds.left + bounds.right) / 2,
            y=(bounds.top + bounds.bottom) / 2,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=f"os/shop/item/{index}/{expected_name}",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=controls[0].path,
        )

    @staticmethod
    def _canonical_operation_siren_voucher_name(icon_sprite: str) -> str:
        fixed = {
            "xinxizhongduan4": "LoggerUnlockT2",
            "tebiezuozhan": "HECombatPlan",
            "W120": "HiddenZoneDataLogger",
            "gold": "Coin",
            "16004": "BookRedT4",
            "16014": "BookBlueT4",
            "16024": "BookYellowT4",
            "21000": "Fragment",
            "Wluopanputong5": "LoggerObscureT5",
            "Wluopanputong6": "LoggerObscureT6",
            "Wsairenluopanputong5": "LoggerAbyssalT5",
            "Wsairenluopanputong6": "LoggerAbyssalT6",
            "Wyangben2": "TuningOffenseT2",
            "Wyangben4": "TuningSurvivalT2",
            "Wyangben6": "TuningCombatT2",
        }
        if icon_sprite in fixed:
            return fixed[icon_sprite]
        archive = re.fullmatch(r"Wdanganluopan([2-9])", icon_sprite)
        if archive is not None:
            return "LoggerArchiveT" + archive.group(1)
        raise SemanticGateClosed("Operation Siren voucher item icon is unknown")

    def operation_siren_voucher_items(
        self,
    ) -> Tuple[OperationSirenVoucherItemState, ...]:
        """Read the current WorldShopUI voucher catalog without scrolling."""

        state = self.read_state()
        back = self._unique(state, "os/voucher/back")
        if not (
            back.active_in_hierarchy
            and back.active_and_enabled
            and back.interactable
            and back.raycast_top is None
            and back.bounds is not None
        ):
            raise SemanticGateClosed("Operation Siren voucher identity is absent")
        ui_state = self.read_ui_state()
        if not state.generation <= ui_state.generation <= state.generation + 2:
            raise SemanticGateClosed(
                "Operation Siren voucher snapshots are not coherent"
            )
        root = "OverlayCamera/Overlay/UIMain/WorldShopUI(Clone)/"
        balance = tuple(
            text
            for text in ui_state.texts
            if text.path == root + "adapt/middle/content/res/number"
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and re.fullmatch(r"[0-9]+", text.text.strip())
        )
        currency_icons = tuple(
            image
            for image in ui_state.images
            if image.path == root + "adapt/middle/content/res/icon"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.sprite == "Wdashijiezhanbeiwuzi"
        )
        reset_days = tuple(
            text
            for text in ui_state.texts
            if text.path == root + "adapt/middle/content/resetTimer/number"
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and re.fullmatch(r"[0-9]+", text.text.strip())
        )
        if len(balance) != 1 or len(currency_icons) != 1 or len(reset_days) != 1:
            raise SemanticGateClosed("Operation Siren voucher header is malformed")

        card_root = root + "adapt/middle/content/world_shop/content/"
        cards = sorted(
            (
                button
                for button in state.buttons
                if button.path.startswith(card_root)
                and button.name in ("item_tpl", "item_tpl(Clone)")
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.bounds is not None
            ),
            key=lambda button: (button.bounds.top, button.bounds.left),
        )
        if len(cards) != 22:
            raise SemanticGateClosed("Operation Siren voucher must expose 22 cards")

        def card_text(card: ButtonState, suffix: str, pattern: str) -> str:
            assert card.bounds is not None
            matches = []
            for text in ui_state.texts:
                if (
                    not text.path.startswith(card_root)
                    or not text.path.endswith(suffix)
                    or not text.active_in_hierarchy
                    or not text.active_and_enabled
                    or text.truncated
                    or text.bounds is None
                    or re.fullmatch(pattern, text.text.strip()) is None
                ):
                    continue
                point = Point(
                    (text.bounds.left + text.bounds.right) / 2.0,
                    (text.bounds.top + text.bounds.bottom) / 2.0,
                )
                if (
                    card.bounds.left <= point.x <= card.bounds.right
                    and card.bounds.top - 20.0 <= point.y <= card.bounds.bottom + 30.0
                ):
                    matches.append(text.text.strip())
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "Operation Siren voucher card text is ambiguous"
                )
            return matches[0]

        def card_image(card: ButtonState, suffix: str) -> str:
            assert card.bounds is not None
            matches = []
            for image in ui_state.images:
                if (
                    not image.path.startswith(card_root)
                    or not image.path.endswith(suffix)
                    or not image.active_in_hierarchy
                    or not image.active_and_enabled
                    or image.truncated
                    or image.bounds is None
                ):
                    continue
                point = Point(
                    (image.bounds.left + image.bounds.right) / 2.0,
                    (image.bounds.top + image.bounds.bottom) / 2.0,
                )
                if (
                    card.bounds.left <= point.x <= card.bounds.right
                    and card.bounds.top - 20.0 <= point.y <= card.bounds.bottom + 30.0
                ):
                    matches.append(image.sprite)
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "Operation Siren voucher card icon is ambiguous"
                )
            return matches[0]

        items = []
        for index, card in enumerate(cards):
            display_name = card_text(card, "/name_mask/name", r".+")
            amount = int(card_text(card, "/icon_bg/count", r"[0-9]+"))
            counter = card_text(card, "/count_contain/count", r"[0-9]+/[0-9]+")
            remaining, total = map(int, counter.split("/"))
            price = int(card_text(card, "/consume/contain/Text", r"[0-9]+"))
            icon = card_image(card, "/icon_bg/icon")
            cost_icon = card_image(card, "/consume/contain/icon")
            currency = (
                "Oil"
                if cost_icon == "oil"
                else "Voucher"
                if cost_icon == "Wdashijiezhanbeiwuzi"
                else ""
            )
            if not currency or remaining > total:
                raise SemanticGateClosed("Operation Siren voucher card is inconsistent")
            sold_out = remaining == 0
            sellout = tuple(
                text
                for text in ui_state.texts
                if text.path.startswith(card_root)
                and text.path.endswith("/mask/tag/sellout_tag")
                and text.active_in_hierarchy
                and text.bounds is not None
                and text.text.strip() == "已售罄"
                and card.bounds.left
                <= (text.bounds.left + text.bounds.right) / 2.0
                <= card.bounds.right
                and card.bounds.top - 20.0
                <= (text.bounds.top + text.bounds.bottom) / 2.0
                <= card.bounds.bottom + 30.0
            )
            if sold_out != (len(sellout) == 1):
                raise SemanticGateClosed(
                    "Operation Siren voucher sellout state conflicts"
                )
            items.append(
                OperationSirenVoucherItemState(
                    generation=ui_state.generation,
                    index=index,
                    display_name=display_name,
                    canonical_name=self._canonical_operation_siren_voucher_name(icon),
                    amount=amount,
                    remaining=remaining,
                    total=total,
                    price=price,
                    currency=currency,
                    icon_sprite=icon,
                    sold_out=sold_out,
                    bounds=card.bounds,
                )
            )
        return tuple(items)

    def operation_siren_voucher_currency(self) -> int:
        self.operation_siren_voucher_items()
        ui_state = self.read_ui_state()
        matches = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith("WorldShopUI(Clone)/adapt/middle/content/res/number")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and re.fullmatch(r"[0-9]+", text.text.strip())
        )
        if len(matches) != 1:
            raise SemanticGateClosed("Operation Siren voucher balance is ambiguous")
        return int(matches[0].text.strip())

    def click_operation_siren_voucher_item(
        self,
        index: int,
        expected_name: str,
        expected_price: int,
        expected_currency: str,
    ) -> ActionReceipt:
        """Open one exact, visible Operation Siren voucher card."""

        if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < 22:
            raise SemanticGateClosed("Operation Siren voucher item index is invalid")
        items = self._retry_transition_read(
            self.operation_siren_voucher_items,
            attempts=8,
            interval_seconds=0.2,
        )
        item = next((candidate for candidate in items if candidate.index == index), None)
        if item is None or item.bounds is None:
            raise SemanticGateClosed("Operation Siren voucher item is absent")
        if (
            item.canonical_name != expected_name
            or item.price != expected_price
            or item.currency != expected_currency
        ):
            raise SemanticGateClosed("Operation Siren voucher item identity changed")
        if item.sold_out or item.remaining <= 0:
            raise SemanticGateClosed("Operation Siren voucher item is sold out")
        if not 0.0 <= item.bounds.left < item.bounds.right <= 1280.0 or not (
            0.0 <= item.bounds.top < item.bounds.bottom <= 720.0
        ):
            raise SemanticGateClosed("Operation Siren voucher item is outside viewport")

        state = self.read_state()
        root = "OverlayCamera/Overlay/UIMain/WorldShopUI(Clone)/adapt/middle/content/world_shop/content/"
        controls = tuple(
            button
            for button in state.buttons
            if button.path.startswith(root)
            and button.name in ("item_tpl", "item_tpl(Clone)")
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds == item.bounds
        )
        if len(controls) != 1:
            raise SemanticGateClosed(
                "Operation Siren voucher item control is absent or ambiguous"
            )
        bounds = item.bounds
        point = Point(
            x=(bounds.left + bounds.right) / 2.0,
            y=(bounds.top + bounds.bottom) / 2.0,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=f"os/voucher/item/{index}/{expected_name}",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=controls[0].path,
        )

    def operation_siren_voucher_purchase_dialog_quantity(
        self,
        expected_display_name: str,
        expected_icon_sprite: str,
    ) -> Optional[int]:
        """Read an exact voucher exchange dialog without trusting localized labels."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        if not state.generation <= ui_state.generation <= state.generation + 2:
            raise SemanticGateClosed(
                "Operation Siren voucher dialog snapshots are not coherent"
            )
        single_root = "OverlayCamera/Overlay/UIMain/ShopsUISinglebox(Clone)/window"
        single_control_paths = (
            single_root + "/actions/confirm_btn",
            single_root + "/actions/cancel_btn",
        )
        single_controls = tuple(
            tuple(button for button in state.buttons if button.path == path)
            for path in single_control_paths
        )
        single_names = tuple(
            text
            for text in ui_state.texts
            if text.path
            == single_root + "/item/display_panel/name_container/name/Text"
        )
        if single_names or any(single_controls):
            if any(len(matches) != 1 for matches in single_controls):
                raise SemanticGateClosed(
                    "Operation Siren voucher single exchange controls are ambiguous"
                )
            for button in (matches[0] for matches in single_controls):
                if not (
                    button.active_in_hierarchy
                    and button.active_and_enabled
                    and button.interactable
                    and button.raycast_top is None
                    and button.bounds is not None
                ):
                    raise SemanticGateClosed(
                        "Operation Siren voucher single exchange control is not actionable"
                    )
            single_names = tuple(
                text
                for text in single_names
                if text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            if len(single_names) != 1 or not (
                single_names[0].text.strip() == expected_display_name
                or (
                    expected_display_name.endswith("..")
                    and single_names[0].text.strip().startswith(
                        expected_display_name[:-2]
                    )
                )
            ):
                raise SemanticGateClosed(
                    "Operation Siren voucher single exchange item name changed"
                )
            single_icons = tuple(
                image
                for image in ui_state.images
                if image.path
                == single_root + "/item/left/IconTpl/icon_bg/icon"
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.sprite == expected_icon_sprite
            )
            if len(single_icons) != 1:
                raise SemanticGateClosed(
                    "Operation Siren voucher single exchange item icon changed"
                )
            single_counts = tuple(
                text
                for text in ui_state.texts
                if text.path == single_root + "/item/left/IconTpl/icon_bg/count"
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and re.fullmatch(r"[1-9][0-9]*", text.text.strip())
            )
            if len(single_counts) != 1:
                raise SemanticGateClosed(
                    "Operation Siren voucher single exchange quantity is ambiguous"
                )
            return int(single_counts[0].text.strip())

        root = "OverlayCamera/Overlay/UIMain/ShopsUIMsgbox(Clone)"
        control_paths = (
            root + "/actions/confirm_button",
            root + "/actions/cancel_button",
        )
        controls = tuple(
            tuple(button for button in state.buttons if button.path == path)
            for path in control_paths
        )
        name_path = root + "/item/panel_bg/display_panel/name_container/name/Text"
        names = tuple(text for text in ui_state.texts if text.path == name_path)
        if not names and not any(controls):
            return None
        if any(len(matches) != 1 for matches in controls):
            raise SemanticGateClosed(
                "Operation Siren voucher dialog controls are ambiguous"
            )
        for button in (matches[0] for matches in controls):
            if not (
                button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.raycast_top is None
                and button.bounds is not None
            ):
                raise SemanticGateClosed(
                    "Operation Siren voucher dialog control is not actionable"
                )
        names = tuple(
            text
            for text in names
            if text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if len(names) != 1 or not (
            names[0].text.strip() == expected_display_name
            or (
                expected_display_name.endswith("..")
                and names[0].text.strip().startswith(expected_display_name[:-2])
            )
        ):
            raise SemanticGateClosed(
                "Operation Siren voucher dialog item name changed"
            )
        icon_paths = (
            root + "/item/panel_bg/left/IconTpl/icon_bg/icon",
            root + "/got/panel_bg/list/item/icon_bg/icon",
        )
        for path in icon_paths:
            matches = tuple(
                image
                for image in ui_state.images
                if image.path == path
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.sprite == expected_icon_sprite
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "Operation Siren voucher dialog item icon changed"
                )
        values = tuple(
            text
            for text in ui_state.texts
            if text.path == root + "/count/number_panel/value"
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and re.fullmatch(r"[1-9][0-9]*", text.text.strip())
        )
        if len(values) != 1:
            raise SemanticGateClosed(
                "Operation Siren voucher dialog quantity is ambiguous"
            )
        return int(values[0].text.strip())

    def click_operation_siren_voucher_purchase_confirm(
        self,
        expected_display_name: str,
        expected_icon_sprite: str,
        expected_quantity: int,
    ) -> ActionReceipt:
        quantity = self.operation_siren_voucher_purchase_dialog_quantity(
            expected_display_name, expected_icon_sprite
        )
        if quantity != expected_quantity:
            raise SemanticGateClosed("Operation Siren voucher quantity changed")
        state = self.read_state()
        paths = (
            "OverlayCamera/Overlay/UIMain/ShopsUIMsgbox(Clone)/actions/confirm_button",
            "OverlayCamera/Overlay/UIMain/ShopsUISinglebox(Clone)/window/actions/confirm_btn",
        )
        buttons = tuple(button for button in state.buttons if button.path in paths)
        if len(buttons) != 1:
            raise SemanticGateClosed(
                "Operation Siren voucher confirmation is ambiguous"
            )
        button = buttons[0]
        if not (
            button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.raycast_top is None
            and button.bounds is not None
        ):
            raise SemanticGateClosed(
                "Operation Siren voucher confirmation is not actionable"
            )
        bounds = button.bounds
        point = Point(
            (bounds.left + bounds.right) / 2.0,
            (bounds.top + bounds.bottom) / 2.0,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="os/voucher/purchase/confirm",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=button.path,
        )

    def click_shop_item(self, index: int) -> ActionReceipt:
        if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < 10:
            raise SemanticGateClosed("shop item index is invalid")
        items = self.general_shop_items()
        item = next(
            (candidate for candidate in items if candidate.index == index), None
        )
        if item is None or item.bounds is None:
            raise SemanticGateClosed("shop item is absent")
        state = self.read_state()
        root = f"ShopSupplyShopUI(Clone)/scroll/content/{index}"
        buttons = tuple(
            button
            for button in state.buttons
            if button.name == str(index)
            and button.path.endswith(root)
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.raycast_top is not False
            and button.bounds is not None
        )
        if len(buttons) != 1:
            raise SemanticGateClosed("shop item control is absent or ambiguous")
        bounds = buttons[0].bounds
        assert bounds is not None
        point = Point(
            x=(bounds.left + bounds.right) / 2,
            y=(bounds.top + bounds.bottom) / 2,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=f"shop/item/{index}/{item.canonical_name}",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=buttons[0].path,
        )

    def shop_purchase_dialog_quantity(
        self, expected_display_name: str
    ) -> Optional[int]:
        state = self.read_state()
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("shop purchase snapshots are not coherent")
        root = "OverlayCamera/Overlay/UIMain/ShopsUIMsgbox(Clone)"
        controls = {
            "confirm_button": root + "/actions/confirm_button",
            "cancel_button": root + "/actions/cancel_button",
        }
        matched_controls = {
            name: tuple(button for button in state.buttons if button.path == path)
            for name, path in controls.items()
        }
        name_path = root + "/item/panel_bg/display_panel/name_container/name/Text"
        names = tuple(text for text in ui_state.texts if text.path == name_path)
        if not names and not any(matched_controls.values()):
            return None
        if any(len(value) != 1 for value in matched_controls.values()):
            raise SemanticGateClosed("shop purchase controls are ambiguous")
        for button in (value[0] for value in matched_controls.values()):
            if not (
                button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.raycast_top is None
                and button.bounds is not None
            ):
                raise SemanticGateClosed("shop purchase control is not actionable")

        def exact_text(
            path: str, expected: Optional[str] = None
        ) -> Tuple[TextState, ...]:
            return tuple(
                text
                for text in ui_state.texts
                if text.path == path
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
                and (expected is None or "".join(text.text.split()) == expected)
            )

        confirm = exact_text(controls["confirm_button"] + "/label", "兑换")
        cancel = exact_text(controls["cancel_button"] + "/label", "取消")
        names = exact_text(name_path)
        values = exact_text(root + "/count/number_panel/value")
        if (
            len(confirm) != 1
            or len(cancel) != 1
            or len(names) != 1
            or not (
                names[0].text.strip() == expected_display_name
                or (
                    expected_display_name.endswith("..")
                    and names[0].text.strip().startswith(
                        expected_display_name[:-2]
                    )
                )
            )
            or len(values) != 1
            or re.fullmatch(r"[1-9][0-9]*", values[0].text.strip()) is None
        ):
            raise SemanticGateClosed("shop purchase dialog identity changed")
        return int(values[0].text.strip())

    def click_shop_purchase_confirm(
        self, expected_display_name: str, expected_quantity: int
    ) -> ActionReceipt:
        quantity = self.shop_purchase_dialog_quantity(expected_display_name)
        if quantity != expected_quantity:
            raise SemanticGateClosed("shop purchase quantity changed")
        state = self.read_state()
        path = (
            "OverlayCamera/Overlay/UIMain/ShopsUIMsgbox(Clone)/actions/confirm_button"
        )
        buttons = tuple(button for button in state.buttons if button.path == path)
        if len(buttons) != 1:
            raise SemanticGateClosed("shop purchase confirmation is ambiguous")
        button = buttons[0]
        if not (
            button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.raycast_top is None
            and button.bounds is not None
        ):
            raise SemanticGateClosed("shop purchase confirmation is not actionable")
        bounds = button.bounds
        assert bounds is not None
        point = Point(
            (bounds.left + bounds.right) / 2, (bounds.top + bounds.bottom) / 2
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="shop/purchase/confirm",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=button.path,
        )

    def campaign_event_entrance_available(self) -> bool:
        """Report whether the proven campaign menu exposes an event card."""

        if not self.campaign_menu_is_entry():
            raise SemanticGateClosed("campaign event availability requires menu")
        state = self.read_state()
        prefix = "UICamera/Canvas/UIMain/LevelMainScene(Clone)/entrance/enters/"
        event_buttons = tuple(
            button
            for button in state.buttons
            if button.path.startswith(prefix)
            and button.name not in ("enter_main",)
            and "/enter_world/" not in button.path
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds is not None
        )
        # Current menus use a distinct event entrance under `enters`; if it is
        # absent, ALAS' CAMPAIGN_MENU_NO_EVENT condition is true.
        return bool(event_buttons)

    def click_campaign_event_entrance(self) -> ActionReceipt:
        """Click the exact current event card whose child owns the raycast."""

        if not self.campaign_menu_is_entry():
            raise SemanticGateClosed("campaign event entrance requires menu")
        state = self.read_state()
        target = self._unique(state, "campaign-menu/event")
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
            and not self._blocking_rules(state, "campaign-menu/event")
        ):
            raise SemanticGateClosed("campaign event entrance is not actionable")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="campaign-menu/event",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def event_campaign_page_visible(self) -> bool:
        return self._event_campaign_page_visible_in_state(self.read_state())

    def event_campaign_page_state(self) -> CampaignPageState:
        """Prove one complete current event battle selector without input."""

        button_state = self.read_state()
        root_marker = "/LevelSelectSPFullUI(Clone)"
        active_event_buttons = tuple(
            button
            for button in button_state.buttons
            if root_marker in button.path
            and button.active_in_hierarchy
            and button.active_and_enabled
        )
        roots = {
            button.path[: button.path.index(root_marker) + len(root_marker)]
            for button in active_event_buttons
            if button.path.count(root_marker) == 1
        }
        if not active_event_buttons:
            raise SemanticTargetMissing("event campaign page is absent")
        if len(roots) != 1 or any(
            button.path.count(root_marker) != 1
            for button in active_event_buttons
        ):
            raise SemanticGateClosed("event campaign page root is ambiguous")
        root = next(iter(roots))
        if not root.endswith(
            "/LevelMainScene(Clone)/LevelSelectSPFullUI(Clone)"
        ):
            raise SemanticGateClosed("event campaign page root is unsupported")
        page_root = root[: -len("/LevelSelectSPFullUI(Clone)")]

        markers = tuple(
            button
            for button in self._matches(button_state, "event/mode/story")
            if button.path == root + "/Battle/Mask/Story/Switch"
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds is not None
        )
        if len(markers) != 1:
            raise SemanticGateClosed(
                "event campaign battle selector marker is absent or ambiguous"
            )

        back_matches = tuple(
            button
            for button in self._matches(button_state, "campaign-menu/page/back")
            if button.active_in_hierarchy
            and button.active_and_enabled
        )
        if len(back_matches) != 1:
            raise SemanticGateClosed(
                "event campaign page back identity is absent or ambiguous"
            )
        back = back_matches[0]
        if back.path != page_root + "/top/top_chapter/back_button":
            raise SemanticGateClosed(
                "event campaign page back belongs to another page root"
            )
        if not back.actionable or self._blocking_rules(
            button_state, "campaign-menu/page/back"
        ):
            raise SemanticGateClosed("event campaign page back is not available")

        if any(
            button.active_in_hierarchy
            and button.active_and_enabled
            and (
                "ActivityMainUI(Clone)/" in button.path
                or "/LevelMainScene(Clone)/float/levels/items/Chapter_"
                in button.path
            )
            for button in button_state.buttons
        ):
            raise SemanticGateClosed(
                "event campaign page overlaps another page root"
            )
        if self._event_campaign_detail_visible(button_state) or any(
            button.active_in_hierarchy
            and (
                "/LevelStageInfoView(Clone)/" in button.path
                or "/LevelInfoSPUI(Clone)/" in button.path
                or "/LevelFleetSelectView(Clone)/" in button.path
            )
            for button in button_state.buttons
        ):
            raise SemanticGateClosed(
                "event campaign page overlaps a preparation layer"
            )

        stage_control = re.compile(
            re.escape(root)
            + r"/Battle/Nodes/Chapter_([0-9]+)/main$"
        )
        stage_ids = []
        for button in button_state.buttons:
            match = stage_control.fullmatch(button.path)
            if (
                button.name == "main"
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.bounds is not None
                and match is not None
            ):
                stage_ids.append(match.group(1))
        if not stage_ids or len(set(stage_ids)) != len(stage_ids):
            raise SemanticGateClosed(
                "event campaign stage buttons are absent or ambiguous"
            )

        ui_state = self.read_ui_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("event campaign snapshots are not coherent")
        return self._event_campaign_page_state(button_state, ui_state)

    def event_points(self) -> int:
        """Read the exact event-point counter from a proven event selector."""

        return self._retry_transition_read(self._event_points_once)

    def event_coin(self, stage_code: Optional[str] = None) -> int:
        """Read coins from a proven event selector or requested stage detail."""

        return self._retry_transition_read(
            lambda: self._event_coin_once(stage_code=stage_code)
        )

    def _event_coin_once(self, *, stage_code: Optional[str]) -> int:
        try:
            surface_generation = self.event_campaign_page_state().generation
            surface_kind = "selector"
        except SemanticGateClosed:
            if stage_code is None:
                raise
            preparation = self.campaign_preparation_state(stage_code)
            if preparation is None:
                raise SemanticGateClosed(
                    "event coin requires the selector or requested stage detail"
                )
            surface_generation = preparation.generation
            surface_kind = preparation.kind
        ui_state = self.read_ui_state()
        if surface_kind == "selector":
            surface_after_generation = self.event_campaign_page_state().generation
        else:
            assert stage_code is not None
            preparation_after = self.campaign_preparation_state(stage_code)
            if preparation_after is None or preparation_after.kind != surface_kind:
                raise SemanticGateClosed("event coin surface changed during observation")
            surface_after_generation = preparation_after.generation
        if (
            ui_state.generation < surface_generation
            or ui_state.generation > surface_after_generation
        ):
            raise SemanticGateClosed("event coin snapshots are not coherent")
        suffix = "ResPanel(Clone)/frame/gold/gold_value"
        matches = tuple(
            item
            for item in ui_state.texts
            if item.path.endswith(suffix)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if (
            len(matches) != 1
            or re.fullmatch(r"[0-9]+", matches[0].text.strip()) is None
        ):
            raise SemanticGateClosed("event coin counter is absent or malformed")
        return int(matches[0].text.strip())

    def _event_points_once(self) -> int:
        try:
            _buttons, raid_ui, raid_root, _stages = (
                self._amatsukaze_raid_page_state()
            )
        except SemanticGateClosed as exc:
            if str(exc) not in (
                "current Raid page is absent",
                "current Raid page is obscured by fleet selection",
            ):
                raise
        else:
            path = raid_root + "/adapt/right/ptaward/Text"
            matches = tuple(
                item
                for item in raid_ui.texts
                if item.path == path
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
                and re.fullmatch(r"[0-9]+", item.text.strip()) is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "current Raid point counter is absent or ambiguous"
                )
            return int(matches[0].text.strip())

        ui_state = self.read_ui_state()
        page = self.event_campaign_page_state()
        if (
            page.generation < ui_state.generation
            or page.generation > ui_state.generation + 2
        ):
            raise SemanticGateClosed("event point snapshots are not coherent")
        suffix = (
            "LevelMainScene(Clone)/main/right_chapter/"
            "event_btns/pt_text/Text"
        )
        matches = tuple(
            item
            for item in ui_state.texts
            if item.path.endswith(suffix)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if len(matches) != 1:
            raise SemanticGateClosed("event point counter is absent or ambiguous")
        value = re.fullmatch(r"[xX]([0-9]+)", matches[0].text.strip())
        if value is None:
            raise SemanticGateClosed("event point counter is malformed")
        return int(value.group(1))

    def _event_campaign_page_visible_in_state(self, state: OracleState) -> bool:
        return bool(
            len(self._matches(state, "event/mode/story")) == 1
            or any(
                button.path.endswith("LevelSelectSPFullUI(Clone)/Story/Battle/Switch")
                for button in state.buttons
            )
            or self._event_campaign_detail_visible(state)
        )

    def event_campaign_stage_selector_visible(self) -> bool:
        """Require at least one concrete event-stage node, not its detail."""

        state = self.read_state()
        if self._event_campaign_detail_visible(state):
            return False
        stage_pattern = re.compile(
            r".*/LevelSelectSPFullUI\(Clone\)/Battle/Nodes/"
            r"Chapter_[1-9][0-9]*/main$"
        )
        stages = tuple(
            button
            for button in state.buttons
            if stage_pattern.fullmatch(button.path)
            and button.name == "main"
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds is not None
        )
        mode_markers = tuple(
            button
            for button in state.buttons
            if button.path.endswith(
                "LevelSelectSPFullUI(Clone)/Battle/Mask/Story/Switch"
            )
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
        )
        return bool(stages and len(mode_markers) == 1)

    def _event_campaign_aside_tab(
        self, destination: str
    ) -> Tuple[OracleState, ButtonState, bool]:
        """Resolve one post-2024 event chapter tab from typed text and geometry."""

        labels = {
            "part1": "上篇",
            "part2": "下篇",
            "sp": "SP",
            "ex": "EX",
        }
        label = labels.get(destination)
        if label is None:
            raise SemanticGateClosed("event campaign aside destination is invalid")

        button_state = self.read_state()
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("event campaign aside snapshots are not coherent")
        # This validates the concrete combat-stage page and prevents the
        # similarly named labels from being accepted on an unrelated surface.
        self._event_campaign_page_state(button_state, ui_state)

        root = "LevelSelectSPFullUI(Clone)/Battle/MapItems/List/"
        tab_text = re.compile(
            re.escape(root) + r"Item(?:\(Clone\))?/(Selected|Unselect)/Text$"
        )
        labels_found = []
        for text in ui_state.texts:
            match = tab_text.search(text.path)
            if (
                match is None
                or text.text.strip() != label
                or not text.active_in_hierarchy
                or not text.active_and_enabled
                or text.truncated
                or text.bounds is None
            ):
                continue
            labels_found.append((text, match.group(1) == "Selected"))
        if len(labels_found) != 1:
            raise SemanticGateClosed(
                "event campaign aside label is absent or ambiguous"
            )
        text, selected = labels_found[0]

        item_path = text.path.rsplit("/", 2)[0]
        candidates = tuple(
            button
            for button in button_state.buttons
            if button.path == item_path
            and button.name in ("Item", "Item(Clone)")
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.bounds is not None
            and not (
                button.bounds.bottom < text.bounds.top
                or button.bounds.top > text.bounds.bottom
            )
        )
        if len(candidates) != 1:
            raise SemanticGateClosed(
                "event campaign aside control is absent or ambiguous"
            )
        return button_state, candidates[0], selected

    def event_campaign_aside_selected(self, destination: str) -> bool:
        """Report whether an exact event chapter tab is currently selected."""

        _, _, selected = self._event_campaign_aside_tab(destination)
        return selected

    def click_event_campaign_aside(self, destination: str) -> ActionReceipt:
        """Select an exact post-2024 event chapter tab."""

        state, button, selected = self._event_campaign_aside_tab(destination)
        if selected:
            raise SemanticGateClosed("event campaign aside is already selected")
        if (
            not button.interactable
            or button.bounds is None
            or self._blocking_rules(state, "event/chapter/" + destination)
        ):
            raise SemanticGateClosed("event campaign aside is not actionable")
        point = Point(
            (button.bounds.left + button.bounds.right) / 2.0,
            (button.bounds.top + button.bounds.bottom) / 2.0,
        )
        if not button.bounds.contains(point) or not (
            0 <= point.x < self.fingerprint.width
            and 0 <= point.y < self.fingerprint.height
        ):
            raise SemanticGateClosed("event campaign aside geometry is invalid")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before event aside input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="event/chapter/" + destination,
            generation=state.generation,
            point=point,
            bounds=button.bounds,
            path=button.path,
        )

    def _event_campaign_detail_visible(self, state: OracleState) -> bool:
        roots = (
            "LevelInfoSPUI(Clone)/panel/start_button",
            "LevelInfoSPUI(Clone)/panel/btnBack",
        )
        observed = []
        for suffix in roots:
            matches = tuple(
                button
                for button in state.buttons
                if button.path.endswith(suffix)
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.bounds is not None
            )
            if len(matches) != 1:
                return False
            observed.append(matches[0])
        return all("LevelInfoSPUI(Clone)/panel/" in item.path for item in observed)

    def event_story_page_state(self) -> Tuple[int, int, Optional[int]]:
        """Return completed, total, and first visible story-node id."""

        state = self.read_state()
        story_root = "LevelSelectSPFullUI(Clone)/Story/Nodes/Viewport/Content/"
        nodes = tuple(
            button
            for button in state.buttons
            if story_root in button.path
            and button.path.rsplit("/", 1)[-1].isdigit()
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds is not None
        )
        if not nodes:
            raise SemanticGateClosed("event story nodes are absent")
        ui = self.read_ui_state()
        progress = tuple(
            text.text.strip()
            for text in ui.texts
            if text.path.endswith("LevelSelectSPFullUI(Clone)/Story/Desc/Digit")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and re.fullmatch(r"[0-9]+/[0-9]+", text.text.strip())
        )
        if len(progress) != 1:
            raise SemanticGateClosed("event story progress is ambiguous")
        completed, total = map(int, progress[0].split("/"))
        if completed > total or total != len(nodes):
            raise SemanticGateClosed("event story progress conflicts with nodes")
        visible = tuple(
            int(button.path.rsplit("/", 1)[-1])
            for button in nodes
            if button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
            and 0 <= button.bounds.left < button.bounds.right <= self.fingerprint.width
            and 0 <= button.bounds.top < button.bounds.bottom <= self.fingerprint.height
        )
        return completed, total, min(visible) if visible else None

    def event_story_dialogue_visible(self) -> bool:
        """Return whether the current overlay is the exact modern story UI."""

        state = self.read_state()
        roots = tuple(
            button
            for button in state.buttons
            if button.path.endswith("Overlay/UIOverlay/NewStoryUI(Clone)")
            and button.name == "NewStoryUI(Clone)"
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.bounds is not None
        )
        skips = self._matches(state, "story/skip")
        return bool(len(roots) == 1 and len(skips) == 1)

    def event_story_skip_prompt_visible(self) -> bool:
        """Require the exact two-button skip prompt nested in NewStoryUI."""

        state = self.read_state()
        confirm = self._matches(state, "story/skip/confirm")
        cancel = self._matches(state, "story/skip/cancel")
        contents = tuple(
            button
            for button in state.buttons
            if button.name == "content"
            and button.path.endswith(
                "NewStoryUI(Clone)/front/Msgbox(Clone)/window/msg_panel/content"
            )
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.bounds is not None
        )
        return bool(
            len(confirm) == 1
            and len(cancel) == 1
            and len(contents) == 1
            and confirm[0].actionable
            and cancel[0].actionable
        )

    def click_event_story_skip_confirm(self) -> ActionReceipt:
        if not self.event_story_skip_prompt_visible():
            raise SemanticGateClosed("event story skip prompt identity is absent")
        state = self.read_state()
