    @staticmethod
    def _operation_siren_current_fleet_from_ui_state(state: UiState) -> int:
        path = (
            "top/adapt/left_stage/other/fleet_bar/text_selected/x"
        )
        matches = tuple(
            item
            for item in state.images
            if item.name == "x"
            and item.path.endswith(path)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if len(matches) != 1 or matches[0].sprite not in {"1", "2", "3", "4"}:
            raise SemanticGateClosed(
                "operation siren current fleet is absent or ambiguous"
            )
        return int(matches[0].sprite)

    def operation_siren_current_fleet(self) -> int:
        """Read the selected Operation Siren fleet from its exact sprite."""

        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        return self._operation_siren_current_fleet_from_ui_state(
            self.read_ui_state()
        )

    def operation_siren_current_fleet_defeated(self) -> bool:
        """Return whether the selected fleet already lost its Month Boss attempt.

        Original ALAS ``FLEET_LOW_RESOLVE`` is a left HUD color check, not a
        map-chibi classifier.  The map ``marks/damage/1`` icon is only a
        post-combat remainder on that fleet's own model; stacked fleets in a
        locked room can show another fleet's mark while walking, so callers
        must not use a one-frame map sample to skip a fresh fleet.
        """

        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        state = self.read_ui_state()
        fleet = self._operation_siren_current_fleet_from_ui_state(state)
        fleet_root = (
            f"/LevelGrid/DragLayer/plane/cells/fleet_{fleet}"
        )
        markers = tuple(
            image
            for image in state.images
            if image.path.endswith(fleet_root + "/marks/damage/1")
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
        )
        if len(markers) > 1:
            raise SemanticGateClosed(
                "operation siren selected-fleet low-resolve marker is ambiguous"
            )
        if markers:
            marker = markers[0]
            if marker.name != "1" or marker.sprite != "200":
                raise SemanticGateClosed(
                    "operation siren selected-fleet low-resolve marker is not reviewed"
                )
            return True

        anchors = tuple(
            image
            for image in state.images
            if image.name == "shadow"
            and image.path.endswith(fleet_root + "/shadow")
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
        )
        if len(anchors) != 1:
            raise SemanticGateClosed(
                "operation siren selected-fleet map anchor is absent or ambiguous"
            )
        return False

    def operation_siren_current_fleet_needs_repair(self) -> bool:
        """Return whether the selected fleet has a sunk ship in the left panel."""

        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        state = self.read_state()
        pattern = re.compile(
            r".+/top/adapt/left_stage/bg/fleet/(?:main|vanguard)/"
            r"shiptpl\(Clone\)/agony$"
        )
        markers = tuple(
            button
            for button in state.buttons
            if button.name == "agony"
            and pattern.fullmatch(button.path)
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
        )
        if len(markers) > 6:
            raise SemanticGateClosed(
                "operation siren repair markers are ambiguous"
            )
        signatures = {
            (
                round(marker.bounds.left, 3),
                round(marker.bounds.top, 3),
                round(marker.bounds.right, 3),
                round(marker.bounds.bottom, 3),
            )
            for marker in markers
            if marker.bounds is not None
        }
        if len(signatures) != len(markers):
            raise SemanticGateClosed("operation siren repair markers overlap")
        return bool(markers)

    def operation_siren_radar_targets(
        self, target_kind: str
    ) -> Tuple[Tuple[int, int], ...]:
        """Read exact relative grid positions from the Operation Siren radar."""

        if target_kind not in {
            "port",
            "task",
            "guidepost",
            "question",
            "switch",
            "boss",
        }:
            raise SemanticGateClosed(
                "operation siren radar target kind is not reviewed"
            )
        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        state = self.read_ui_state()
        # Local maps routinely exceed the observer's bounded Image slice.
        # These radar targets are positive, exact hierarchy/sprite matches;
        # truncation may make an absent target unknowable, but it does not
        # invalidate a target that is present in the typed slice.
        radar_root = (
            "top/adapt/right_stage/compass_panel/ring/compass/range/"
        )
        path = radar_root + "mark"
        sprite_kind = (
            "guidepost" if target_kind in {"question", "switch"} else target_kind
        )
        join_event_ids = None
        if target_kind in {"question", "switch"}:
            # Original RadarGrid.predict_question() is a white ``?`` on the
            # radar, not a world-model classifier.  The observer groups those
            # white radar icons as sprite ``guidepost``.  The monthly-boss
            # compass can show two: the upper wormhole is the same entrance
            # normal uses, and the right buoy is not.  Join radar ids to the
            # world model ALAS actually walks onto.  Taban plates remain the
            # adjacent hard-room switch, not a second question class.
            # Identity join does not need clickable bounds; a truncated
            # wormhole still names the radar icon that is the entrance.
            if target_kind == "question":
                model_pattern = re.compile(
                    r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
                    r"cell_[0-9]+_[0-9]+/attachments/event_([0-9]+)/icon/model/"
                    r"chongdong02\(Clone\)$"
                )
                model_name = "chongdong02(Clone)"
                model_sprite = "chongdong42"
            else:
                model_pattern = re.compile(
                    r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
                    r"cell_[0-9]+_[0-9]+/attachments/event_([0-9]+)/icon/model/"
                    r"taban_jinzhi\(Clone\)/taban$"
                )
                model_name = "taban"
                model_sprite = "taban01"
            join_event_ids = {
                match.group(1)
                for item in state.images
                if (match := model_pattern.fullmatch(item.path)) is not None
                and item.name == model_name
                and item.sprite == model_sprite
                and item.active_in_hierarchy
                and item.active_and_enabled
            }
            # Inside the monthly-boss room there is no wormhole.  Original
            # ALAS still walks the remaining white ``?`` waypoints, so fall
            # back to every radar guidepost when no chongdong join exists.
            if target_kind == "question" and not join_event_ids:
                join_event_ids = None
        if target_kind in {"guidepost", "question", "switch", "task", "boss"}:
            event_pattern = re.compile(r"[0-9]+$")
            matches = tuple(
                item
                for item in state.images
                if (
                    (
                        item.path.endswith(radar_root + item.name)
                        and event_pattern.fullmatch(item.name)
                    )
                    or (target_kind == "task" and item.path.endswith(path))
                )
                and item.sprite == sprite_kind
                and (
                    join_event_ids is None
                    or item.name in join_event_ids
                )
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
        else:
            matches = tuple(
                item
                for item in state.images
                if item.name == "mark"
                and item.path.endswith(path)
                and item.sprite == target_kind
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
        targets = []
        for item in matches:
            assert item.bounds is not None
            center_x = (item.bounds.left + item.bounds.right) / 2.0
            center_y = (item.bounds.top + item.bounds.bottom) / 2.0
            raw_x = (center_x - 1140.0) / 11.7
            raw_y = (center_y - 226.0) / 11.7
            grid_x = int(round(raw_x))
            grid_y = int(round(raw_y))
            if (
                abs(raw_x - grid_x) > 0.35
                or abs(raw_y - grid_y) > 0.35
                or max(abs(grid_x), abs(grid_y)) > 7
            ):
                raise SemanticGateClosed(
                    "operation siren radar target is not grid-aligned"
                )
            targets.append((grid_x, grid_y))
        if len(set(targets)) != len(targets):
            raise SemanticGateClosed("operation siren radar targets are ambiguous")
        # Radar.select() iterates its x-major grid dictionary.  Preserve that
        # ordering because original task code deliberately addresses index 0
        # and index 1 for multi-waypoint rooms.
        return tuple(sorted(targets))

    def operation_siren_nearest_daemon_target(
        self,
    ) -> Optional[OperationSirenDaemonTarget]:
        """Select the nearest reviewed non-port radar object without pixels.

        Original ``Radar.nearest_object()`` considers enemies, resources,
        meowfficers, exclamation marks, questions, and archives.  Current
        semantic evidence has exact Unity sprite identities only for enemies,
        exclamation marks, and questions.  Any other direct radar-object
        sprite therefore closes the gate instead of being guessed.  Targets
        farther than the original three-step radius also close the gate until
        the EMP one-step condition has a typed observation.
        """

        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        state = self.read_ui_state()
        radar_root = (
            "top/adapt/right_stage/compass_panel/ring/compass/range/"
        )
        event_name = re.compile(r"(?:mark|[0-9]+)$")
        reviewed = {
            "battle": "enemy",
            "boss": "enemy",
            "task": "event",
            "guidepost": "question",
        }
        objects = []
        ports = set()
        for item in state.images:
            if not (
                item.path.endswith(radar_root + item.name)
                and event_name.fullmatch(item.name)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            ):
                continue
            assert item.bounds is not None
            center_x = (item.bounds.left + item.bounds.right) / 2.0
            center_y = (item.bounds.top + item.bounds.bottom) / 2.0
            raw_x = (center_x - 1140.0) / 11.7
            raw_y = (center_y - 226.0) / 11.7
            grid_x = int(round(raw_x))
            grid_y = int(round(raw_y))
            if (
                abs(raw_x - grid_x) > 0.35
                or abs(raw_y - grid_y) > 0.35
                or math.hypot(grid_x, grid_y) > 5.15
            ):
                raise SemanticGateClosed(
                    "operation siren daemon radar target is not grid-aligned"
                )
            position = (grid_x, grid_y)
            if item.sprite == "port":
                ports.add(position)
                continue
            kind = reviewed.get(item.sprite)
            if kind is None:
                raise SemanticGateClosed(
                    "operation siren daemon radar target kind is not reviewed"
                )
            objects.append((position, kind))

        # Mirror Radar.predict(): a white question directly beside a port is
        # the port glyph's edge, not an independent object.
        objects = [
            (position, kind)
            for position, kind in objects
            if not (
                kind == "question"
                and any(
                    abs(position[0] - port[0])
                    + abs(position[1] - port[1])
                    == 1
                    for port in ports
                )
            )
        ]
        positions = [position for position, _ in objects]
        if len(set(positions)) != len(positions):
            raise SemanticGateClosed(
                "operation siren daemon radar targets are ambiguous"
            )
        if not objects:
            if state.image_truncated:
                raise SemanticGateClosed(
                    "operation siren daemon radar absence is not observable"
                )
            return None

        distance = min(abs(x) + abs(y) for (x, y), _ in objects)
        nearest = [
            (position, kind)
            for position, kind in objects
            if abs(position[0]) + abs(position[1]) == distance
        ]
        if len(nearest) != 1:
            raise SemanticGateClosed(
                "operation siren nearest daemon target is ambiguous"
            )
        source_position, target_kind = nearest[0]
        # point_limit(camera_sight=(-4, -3, 3, 3)) from Radar.nearest_object.
        relative_position = (
            max(-4, min(3, source_position[0])),
            max(-3, min(3, source_position[1])),
        )
        if math.hypot(*relative_position) > 3.0:
            raise SemanticGateClosed(
                "operation siren daemon move requires typed EMP step state"
            )
        return OperationSirenDaemonTarget(
            generation=state.generation,
            target_kind=target_kind,
            source_position=source_position,
            relative_position=relative_position,
        )

    def click_operation_siren_daemon_target(
        self, expected: OperationSirenDaemonTarget
    ) -> ActionReceipt:
        """Recheck one daemon target identity immediately before its click."""

        if not isinstance(expected, OperationSirenDaemonTarget):
            raise TypeError("operation siren daemon target is not typed")
        current = self.operation_siren_nearest_daemon_target()
        if current is None or (
            current.target_kind != expected.target_kind
            or current.source_position != expected.source_position
            or current.relative_position != expected.relative_position
            or current.generation < expected.generation
        ):
            raise SemanticGateClosed(
                "operation siren daemon target changed before input"
            )
        return self.click_operation_siren_relative_grid(
            expected.relative_position
        )

    def operation_siren_obscure_exit_passage_position(
        self,
    ) -> Optional[Tuple[int, int]]:
        """Return the exact absolute grid of an obscure-zone exit passage."""

        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        state = self.read_ui_state()
        titles = tuple(
            item
            for item in state.texts
            if item.path.endswith("top/adapt/top_stage/title/name")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
            and item.text.endswith("-隐秘海域")
        )
        tips = tuple(
            item
            for item in state.texts
            if item.path.endswith("top/adapt/right_stage/tip_word/Text")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
            and item.text == "从塞壬特殊通行装置离开隐秘海域"
        )
        portal_pattern = re.compile(
            r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
            r"cell_([0-9]+)_([0-9]+)/attachments/event_1000034/icon/model/"
            r"chuansong01\(Clone\)/Xyz/Ring01/01$"
        )
        portals = tuple(
            item
            for item in state.images
            if portal_pattern.fullmatch(item.path)
            and item.name == "01"
            and item.sprite == "chuansong01"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        # The title and exit hint are present throughout an uncleared obscure
        # zone. The passage model itself is the transition-ready marker.
        if not portals:
            return None
        evidence = (titles, tips, portals)
        if any(len(items) != 1 for items in evidence):
            raise SemanticGateClosed(
                "operation siren obscure exit passage is incomplete or ambiguous"
            )
        match = portal_pattern.fullmatch(portals[0].path)
        assert match is not None
        return (int(match.group(1)), int(match.group(2)))

    def operation_siren_post_search_loot_visible(self) -> bool:
        """Recognize the loot inventory that can cover a cleared special map."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        back_suffix = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/title/"
            "back_button"
        )
        backs = tuple(
            button
            for button in state.buttons
            if button.name == "back_button"
            and button.path.endswith(back_suffix)
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
        )
        item_pattern = re.compile(
            r".*OverlayCamera/Overlay/UIMain/blur_panel/adapt/shop/frame/"
            r"scrollview/view/item_tpl(?:\(Clone\))?$"
        )
        items = tuple(
            button
            for button in state.buttons
            if item_pattern.fullmatch(button.path)
            and button.name in {"item_tpl", "item_tpl(Clone)"}
            and button.active_in_hierarchy
            and button.active_and_enabled
        )
        titles = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith("top/adapt/top_stage/title/name")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and text.text.endswith(
                ("-隐秘海域", "-深渊海域", "-塞壬要塞海域")
            )
        )
        return len(backs) == 1 and bool(items) and len(titles) == 1

    def click_operation_siren_post_search_loot_back(self) -> ActionReceipt:
        """Dismiss the exact post-search loot inventory through its back button."""

        if not self.operation_siren_post_search_loot_visible():
            raise SemanticGateClosed(
                "operation siren post-search loot overlay is absent"
            )
        state = self.read_state()
        suffix = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/title/"
            "back_button"
        )
        matches = tuple(
            button
            for button in state.buttons
            if button.name == "back_button"
            and button.path.endswith(suffix)
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
        )
        if len(matches) != 1:
            raise SemanticGateClosed(
                "operation siren post-search loot back is ambiguous"
            )
        target = matches[0]
        assert target.point is not None and target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed(
                "foreground changed before post-search loot dismissal"
            )
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/auto-search/loot/back",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def operation_siren_obscure_exit_camera_swipe(
        self,
    ) -> OperationSirenGlobeSwipeReceipt:
        """Move the proven obscure exit object toward the safe viewport."""

        if self._swipe is None:
            raise SemanticGateClosed("operation siren swipe backend is absent")
        if self.operation_siren_obscure_exit_passage_position() is None:
            raise SemanticGateClosed("operation siren obscure exit passage is absent")
        pattern = re.compile(
            r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
            r"cell_[0-9]+_[0-9]+/attachments/event_1000034/icon/model/"
            r"chuansong01\(Clone\)/Xyz/Ring01/01$"
        )

        def portal(state: UiState) -> ImageState:
            matches = tuple(
                item
                for item in state.images
                if pattern.fullmatch(item.path)
                and item.name == "01"
                and item.sprite == "chuansong01"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "operation siren obscure exit object is ambiguous"
                )
            return matches[0]

        state = self.read_ui_state()
        target = portal(state)
        bounds = target.bounds
        assert bounds is not None
        center = Point(
            (bounds.left + bounds.right) / 2.0,
            (bounds.top + bounds.bottom) / 2.0,
        )
        delta_x = max(-280, min(280, int(round(640.0 - center.x))))
        delta_y = max(-240, min(240, int(round(360.0 - center.y))))
        if abs(delta_x) < 24 and abs(delta_y) < 24:
            raise SemanticGateClosed(
                "operation siren obscure exit object is already in view"
            )
        # Keep the gesture origin away from the selected fleet chibi and leave
        # enough room in the requested direction for the bounded drag.
        start = (
            360 if delta_x >= 0 else 640,
            300 if delta_y >= 0 else 500,
        )
        end = (start[0] + delta_x, start[1] + delta_y)
        if not (
            160 <= end[0] <= 840
            and 140 <= end[1] <= 620
            and self._foreground_component() == self.fingerprint.component
        ):
            raise SemanticGateClosed(
                "operation siren obscure exit camera swipe is not safe"
            )
        before_distance = math.hypot(center.x - 640.0, center.y - 360.0)
        pre_generation = state.generation
        self._swipe(start[0], start[1], end[0], end[1], 450)
        post_generation = None
        last_center = center
        for _ in range(80):
            self._sleep(0.25)
            candidate = self.read_ui_state()
            moved = portal(candidate)
            moved_bounds = moved.bounds
            assert moved_bounds is not None
            moved_center = Point(
                (moved_bounds.left + moved_bounds.right) / 2.0,
                (moved_bounds.top + moved_bounds.bottom) / 2.0,
            )
            last_center = moved_center
            if (
                candidate.generation > pre_generation
                and math.hypot(
                    moved_center.x - 640.0, moved_center.y - 360.0
                )
                < before_distance - 20.0
            ):
                post_generation = candidate.generation
                break
        if post_generation is None:
            raise SemanticGateClosed(
                "operation siren obscure exit camera did not approach passage "
                f"({center.x:.1f},{center.y:.1f})->"
                f"({last_center.x:.1f},{last_center.y:.1f})"
            )
        return OperationSirenGlobeSwipeReceipt(
            semantic_id="os/map/obscure-exit/swipe",
            pre_generation=pre_generation,
            post_generation=post_generation,
            start=start,
            end=end,
            duration_ms=450,
        )

    def click_operation_siren_obscure_exit_passage(self) -> ActionReceipt:
        """Click the exact obscure exit object after it enters safe view."""

        if self.operation_siren_obscure_exit_passage_position() is None:
            raise SemanticGateClosed("operation siren obscure exit passage is absent")
        state = self.read_ui_state()
        pattern = re.compile(
            r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
            r"cell_[0-9]+_[0-9]+/attachments/event_1000034/icon/model/"
            r"chuansong01\(Clone\)/Xyz/Ring01/01$"
        )
        matches = tuple(
            item
            for item in state.images
            if pattern.fullmatch(item.path)
            and item.name == "01"
            and item.sprite == "chuansong01"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if len(matches) != 1:
            raise SemanticGateClosed(
                "operation siren obscure exit object is ambiguous"
            )
        bounds = matches[0].bounds
        assert bounds is not None
        point = Point(
            (bounds.left + bounds.right) / 2.0,
            (bounds.top + bounds.bottom) / 2.0,
        )
        if (
            not 80.0 <= point.x <= 960.0
            or not 100.0 <= point.y <= 620.0
            or self._foreground_component() != self.fingerprint.component
        ):
            raise SemanticGateClosed(
                "operation siren obscure exit object is outside safe view"
            )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="os/map/obscure-exit/passage",
            generation=state.generation,
            point=point,
            bounds=bounds,
            path=matches[0].path,
        )

    def click_operation_siren_relative_grid(
        self,
        relative_position: Tuple[int, int],
        *,
        prefer_adjacent_event: bool = False,
    ) -> ActionReceipt:
        """Click one exact typed world grid relative to the camera center."""

        if (
            not isinstance(relative_position, tuple)
            or len(relative_position) != 2
            or any(type(value) is not int for value in relative_position)
            or any(abs(value) > 4 for value in relative_position)
        ):
            raise SemanticGateClosed(
                "operation siren relative grid position is malformed"
            )
        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        state = self.read_ui_state()
        # As above, world-grid navigation relies only on positive exact paths.
        # The map Image slice can be truncated while the center and requested
        # grid are both fully represented.
        pattern = re.compile(
            r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/quads/"
            r"world_quad_([0-9]+)_([0-9]+)/walk_quad$"
        )
        grids = []
        for item in state.images:
            match = pattern.fullmatch(item.path)
            if (
                match is None
                or item.name != "walk_quad"
                or item.sprite != "cell_white"
                or not item.active_in_hierarchy
                or not item.active_and_enabled
                or item.truncated
                or item.bounds is None
            ):
                continue
            grids.append((int(match.group(1)), int(match.group(2)), item))
        centers = tuple(
            (row, column, item)
            for row, column, item in grids
            if item.bounds is not None
            and item.bounds.contains(Point(640.0, 360.0))
        )
        if not centers:
            occupied_center_pattern = re.compile(
                r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
                r"cell_([0-9]+)_([0-9]+)/attachments/event_[0-9]+/"
                r"icon/model/taban\(Clone\)/taban$"
            )
            centers = tuple(
                (int(match.group(1)), int(match.group(2)), item)
                for item in state.images
                if (match := occupied_center_pattern.fullmatch(item.path)) is not None
                and item.name == "taban"
                and item.sprite == "taban01"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
                and item.bounds.contains(Point(640.0, 360.0))
            )
        if len(centers) != 1:
            raise SemanticGateClosed(
                "operation siren camera center grid is absent or ambiguous"
            )
        center_row, center_column, _ = centers[0]
        target_row = center_row + relative_position[1]
        target_column = center_column + relative_position[0]
        targets = tuple(
            item
            for row, column, item in grids
            if row == target_row and column == target_column
        )
        click_bounds = None
        click_path = None
        if len(targets) == 1 and targets[0].bounds is not None:
            click_bounds = targets[0].bounds
            click_path = targets[0].path
        if prefer_adjacent_event and abs(relative_position[0]) + abs(relative_position[1]) <= 3:
            event_pattern = re.compile(
                r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
                rf"cell_{target_row}_{target_column}/attachments/event_[0-9]+/"
                r"(?:icon/model/(?:fubiao3|taban_jinzhi|chongdong02)\(Clone\)"
                r"(?:/taban)?|"
                r"char/shadow)$"
            )
            events = tuple(
                item
                for item in state.images
                if event_pattern.fullmatch(item.path)
                and (
                    (item.name == "fubiao3(Clone)" and item.sprite == "fubiao3")
                    or (
                        item.name == "chongdong02(Clone)"
                        and item.sprite == "chongdong42"
                    )
                    or (item.name == "taban" and item.sprite == "taban01")
                    or (item.name == "shadow" and item.sprite == "shadow")
                )
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(events) > 1:
                raise SemanticGateClosed(
                    "operation siren adjacent event target is ambiguous"
                )
            if len(events) == 1:
                assert events[0].bounds is not None
                click_bounds = events[0].bounds
                click_path = events[0].path
        if click_bounds is None or click_path is None:
            raise SemanticGateClosed(
                "operation siren relative target grid is absent or ambiguous"
            )
        point = Point(
            (click_bounds.left + click_bounds.right) / 2.0,
            (click_bounds.top + click_bounds.bottom) / 2.0,
        )
        if (
            not click_bounds.contains(point)
            or not 80.0 <= point.x <= 960.0
            or not 100.0 <= point.y <= 620.0
            or self._foreground_component() != self.fingerprint.component
        ):
            raise SemanticGateClosed(
                "operation siren relative target click is not safe"
            )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=(
                "os/map/grid/relative/"
                f"{relative_position[0]}/{relative_position[1]}"
            ),
            generation=state.generation,
            point=point,
            bounds=click_bounds,
            path=click_path,
        )

    def click_operation_siren_radar_guidepost(
        self, relative_position: Tuple[int, int]
    ) -> ActionReceipt:
        """Click an adjacent guidepost from exact radar and fleet anchors."""

        if (
            not isinstance(relative_position, tuple)
            or len(relative_position) != 2
            or any(type(value) is not int for value in relative_position)
            or relative_position not in {
                (0, 1), (-1, 0), (1, 0), (0, -1), (0, -2), (0, -3)
            }
        ):
            raise SemanticGateClosed(
                "operation siren guidepost position is malformed"
            )
        if relative_position not in self.operation_siren_radar_targets("guidepost"):
            raise SemanticGateClosed(
                "operation siren guidepost changed before input"
            )
        state = self.read_ui_state()
        fleet = self._operation_siren_current_fleet_from_ui_state(state)
        fleet_path = (
            f"/LevelGrid/DragLayer/plane/cells/fleet_{fleet}/shadow"
        )
        fleet_anchors = tuple(
            item
            for item in state.images
            if item.name == "shadow"
            and item.sprite == "shadow"
            and item.path.endswith(fleet_path)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if len(fleet_anchors) != 1:
            raise SemanticGateClosed(
                "operation siren selected-fleet guidepost anchor is ambiguous"
            )
        fleet_bounds = fleet_anchors[0].bounds
        assert fleet_bounds is not None
        fleet_x = (fleet_bounds.left + fleet_bounds.right) / 2.0
        fleet_y = (fleet_bounds.top + fleet_bounds.bottom) / 2.0
        expected_x = fleet_x + relative_position[0] * 99.0
        expected_y = fleet_y + relative_position[1] * 70.0
        guidepost_pattern = re.compile(
            r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
            r"cell_[0-9]+_[0-9]+/attachments/event_[0-9]+/char/shadow$"
        )
        candidates = []
        for item in state.images:
            if (
                not guidepost_pattern.fullmatch(item.path)
                or item.name != "shadow"
                or item.sprite != "shadow"
                or not item.active_in_hierarchy
                or not item.active_and_enabled
                or item.truncated
                or item.bounds is None
            ):
                continue
            center_x = (item.bounds.left + item.bounds.right) / 2.0
            center_y = (item.bounds.top + item.bounds.bottom) / 2.0
            if (
                abs(center_x - expected_x) <= 24.0
                and abs(center_y - expected_y) <= 24.0
            ):
                candidates.append((item, Point(center_x, center_y)))
        if len(candidates) != 1:
            raise SemanticGateClosed(
                "operation siren adjacent guidepost is absent or ambiguous"
            )
        target, point = candidates[0]
        assert target.bounds is not None
        if (
            not target.bounds.contains(point)
            or not 80.0 <= point.x <= 960.0
            or not 100.0 <= point.y <= 620.0
            or self._foreground_component() != self.fingerprint.component
        ):
            raise SemanticGateClosed(
                "operation siren adjacent guidepost click is not safe"
            )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=(
                "os/map/guidepost/relative/"
                f"{relative_position[0]}/{relative_position[1]}"
            ),
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_radar_boss(
        self, relative_position: Tuple[int, int]
    ) -> ActionReceipt:
        """Click the exact boss shadow relative to the selected fleet anchor."""

        if (
            not isinstance(relative_position, tuple)
            or len(relative_position) != 2
            or any(type(value) is not int for value in relative_position)
            or max(abs(value) for value in relative_position) > 4
        ):
            raise SemanticGateClosed(
                "operation siren boss position is malformed"
            )
        if relative_position not in self.operation_siren_radar_targets("boss"):
            raise SemanticGateClosed(
                "operation siren boss target changed before input"
            )
        state = self.read_ui_state()
        fleet = self._operation_siren_current_fleet_from_ui_state(state)
        fleet_path = f"/LevelGrid/DragLayer/plane/cells/fleet_{fleet}/shadow"
        anchors = tuple(
            item
            for item in state.images
            if item.name == "shadow"
            and item.sprite == "shadow"
            and item.path.endswith(fleet_path)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if len(anchors) > 1 or (not anchors and relative_position != (0, 0)):
            raise SemanticGateClosed(
                "operation siren selected-fleet boss anchor is ambiguous"
            )
        expected_x = None
        expected_y = None
        if anchors:
            fleet_bounds = anchors[0].bounds
            assert fleet_bounds is not None
            fleet_x = (fleet_bounds.left + fleet_bounds.right) / 2.0
            fleet_y = (fleet_bounds.top + fleet_bounds.bottom) / 2.0
            expected_x = fleet_x + relative_position[0] * 99.0
            expected_y = fleet_y + relative_position[1] * 70.0
        enemy_pattern = re.compile(
            r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
            r"cell_[0-9]+_[0-9]+/attachments/enemy_[0-9]+/live/char/shadow$"
        )
        event_pattern = re.compile(
            r"LevelCamera/Canvas/UIMain/LevelGrid/DragLayer/plane/cells/"
            r"cell_[0-9]+_[0-9]+/attachments/event_([0-9]+)/char/shadow$"
        )
        radar_root = "top/adapt/right_stage/compass_panel/ring/compass/range/"
        exact_boss_event_ids = {
            item.name
            for item in state.images
            if item.path.endswith(radar_root + item.name)
            and re.fullmatch(r"[0-9]+", item.name)
            and item.sprite == "boss"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        }
        candidates = []
        for item in state.images:
            event_match = event_pattern.fullmatch(item.path)
            exact_event = (
                event_match is not None
                and event_match.group(1) in exact_boss_event_ids
            )
            if (
                not (
                    enemy_pattern.fullmatch(item.path)
                    or exact_event
                )
                or item.name != "shadow"
                or item.sprite != "shadow"
                or not item.active_in_hierarchy
                or not item.active_and_enabled
                or item.truncated
                or item.bounds is None
            ):
                continue
            point = Point(
                (item.bounds.left + item.bounds.right) / 2.0,
                (item.bounds.top + item.bounds.bottom) / 2.0,
            )
            if exact_event or expected_x is None or (
                abs(point.x - expected_x) <= 24.0
                and abs(point.y - expected_y) <= 24.0
            ):
                candidates.append((item, point))
        if len(candidates) != 1:
            raise SemanticGateClosed(
                "operation siren exact boss shadow is absent or ambiguous"
            )
        target, point = candidates[0]
        assert target.bounds is not None
        if (
            not target.bounds.contains(point)
            or not 80.0 <= point.x <= 960.0
            or not 100.0 <= point.y <= 620.0
            or self._foreground_component() != self.fingerprint.component
        ):
            raise SemanticGateClosed(
                "operation siren exact boss click is not safe"
            )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=(
                "os/map/boss/relative/"
                f"{relative_position[0]}/{relative_position[1]}"
            ),
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def operation_siren_auto_search_state(self) -> str:
        """Return the exact local-map auto-search switch state.

        The visible ``off`` control is not proof that auto-search is locked:
        the same Unity button is used for an unlocked switch that the player
        has simply turned off.  Callers may attempt that reviewed button once
        and must use the subsequent state transition, rather than the initial
        appearance, to decide whether the account can start auto-search.
        """

        self.operation_siren_state()
        state = self.read_state()

        def actionable(semantic_id: str) -> bool:
            matches = tuple(
                target
                for target in self._matches(state, semantic_id)
                if target.active_in_hierarchy
                and target.active_and_enabled
                and target.interactable
                and target.point is not None
                and target.bounds is not None
                and target.bounds.contains(target.point)
            )
            if len(matches) > 1:
                raise SemanticGateClosed(
                    "operation siren auto-search state is ambiguous"
                )
            return len(matches) == 1

        enabled = actionable("os/map/auto-search/on")
        disabled = actionable("os/map/auto-search/off")
        if enabled == disabled:
            raise SemanticGateClosed(
                "operation siren auto-search state is absent or inconsistent"
            )
        return "on" if enabled else "off"

    def operation_siren_strategic_search_state(self) -> str:
        """Return ``off``, ``configuring``, or ``on`` from exact Unity controls."""

        state = self.read_state()

        def present(semantic_id: str) -> bool:
            matches = tuple(
                target
                for target in self._matches(state, semantic_id)
                if target.active_in_hierarchy
                and target.active_and_enabled
                and target.interactable
                and target.point is not None
                and target.bounds is not None
                and target.bounds.contains(target.point)
            )
            if len(matches) > 1:
                raise SemanticGateClosed(
                    "operation siren strategic-search state is ambiguous"
                )
            return len(matches) == 1

        confirm = present("os/strategic-search/confirm")
        cancel = present("os/strategic-search/cancel")
        if confirm or cancel:
            if not (confirm and cancel):
                raise SemanticGateClosed(
                    "operation siren strategic-search popup is incomplete"
                )
            return "configuring"

        self.operation_siren_state()
        enabled = present("os/map/strategic-search/on")
        disabled = present("os/map/strategic-search/off")
        if enabled == disabled:
            raise SemanticGateClosed(
                "operation siren strategic-search state is absent or inconsistent"
            )
        return "on" if enabled else "off"

    def operation_siren_strategic_search_scroll_to_bottom(
        self, timeout_seconds: float = 5.0
    ) -> ActionReceipt:
        """Expose the lower strategic-search options through the exact scrollbar."""

        if self._swipe is None:
            raise SemanticGateClosed(
                "operation siren strategic-search swipe backend is absent"
            )
        if self.operation_siren_strategic_search_state() != "configuring":
            raise SemanticGateClosed(
                "operation siren strategic-search popup is absent"
            )
        before = self.read_ui_state()
        handle_suffix = (
            "WorldSwitchPlanningUI(Clone)/window/content/scrollbar/"
            "Sliding Area/Handle"
        )
        handles = tuple(
            image
            for image in before.images
            if image.name == "Handle"
            and image.path.endswith(handle_suffix)
            and image.sprite == "scroll_bar"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.raycast_target
            and not image.truncated
            and image.bounds is not None
        )
        if len(handles) != 1:
            raise SemanticGateClosed(
                "operation siren strategic-search scrollbar is absent or ambiguous"
            )
        bounds = handles[0].bounds
        assert bounds is not None
        if not (
            898 <= bounds.left < bounds.right <= 915
            and 210 <= bounds.top < bounds.bottom <= 475
        ):
            raise SemanticGateClosed(
                "operation siren strategic-search scrollbar geometry changed"
            )
        start = Point(
            (bounds.left + bounds.right) / 2.0,
            (bounds.top + bounds.bottom) / 2.0,
        )
        end = Point(start.x, 430.0)
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed(
                "game activity changed before strategic-search scroll"
            )
        self._swipe(
            int(round(start.x)),
            int(round(start.y)),
            int(round(end.x)),
            int(round(end.y)),
            450,
        )
        deadline = self._monotonic() + timeout_seconds
        while self._monotonic() < deadline:
            self._sleep(0.25)
            after = self.read_ui_state()
            matches = self._toggle_matches(
                after, "os/strategic-search/auto-submit/on"
            )
            if len(matches) > 1:
                raise SemanticGateClosed(
                    "operation siren strategic-search auto-submit is ambiguous"
                )
            if len(matches) == 1:
                toggle = matches[0]
                if (
                    after.generation > before.generation
                    and toggle.point is not None
                    and toggle.bounds is not None
                    and toggle.bounds.contains(toggle.point)
                    and 0 <= toggle.point.x < self.fingerprint.width
                    and 0 <= toggle.point.y < self.fingerprint.height
                ):
                    return ActionReceipt(
                        semantic_id="os/strategic-search/scroll/bottom",
                        generation=after.generation,
                        point=end,
                        bounds=toggle.bounds,
                        path=toggle.path,
                    )
        raise SemanticGateClosed(
            "operation siren strategic-search scroll was not proven"
        )

    def operation_siren_auto_search_info_count(self) -> int:
        """Count the exact paired auto-search notifications on the OS map."""

        state = self.read_ui_state()
        path = (
            "OverlayCamera/Overlay/UIOverlay/TipPanel(Clone)/Grid/"
            "toolTip(Clone)/Text"
        )
        reviewed = {
            "<color=white>当前所选舰队开始自律寻敌</color>",
            "<color=white>当前所选舰队视野内无可自律事件，无法继续自律寻敌</color>",
        }
        matches = tuple(
            item
            for item in state.texts
            if item.path.endswith(path)
            and item.text.strip() in reviewed
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        return len(matches)

    def operation_siren_fleet_lock_state(self) -> str:
        """Read the exact image-only fleet-lock switch state."""

        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        state = self.read_ui_state()
        root = (
            "LevelCamera/Canvas/LevelOrigin/top/adapt/right_stage/btn_list/"
            "auto_switch/"
        )
        matches = tuple(
            item
            for item in state.images
            if item.path in {root + "on", root + "off"}
            and item.name in {"on", "off"}
            and item.sprite in {"auto_switch_on", "auto_switch_off"}
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if len(matches) != 1:
            raise SemanticGateClosed(
                "operation siren fleet-lock state is absent or ambiguous"
            )
        return matches[0].name

    def click_operation_siren_fleet_lock(self, expected_state: str) -> ActionReceipt:
        """Toggle the image-only fleet lock after proving its exact state."""

        if expected_state not in {"on", "off"}:
            raise SemanticGateClosed("operation siren fleet-lock state is malformed")
        if self.operation_siren_fleet_lock_state() != expected_state:
            raise SemanticGateClosed("operation siren fleet-lock state changed")
        state = self.read_ui_state()
        path = (
            "LevelCamera/Canvas/LevelOrigin/top/adapt/right_stage/btn_list/"
            f"auto_switch/{expected_state}"
        )
        matches = tuple(
            item
            for item in state.images
            if item.path == path
            and item.name == expected_state
            and item.bounds is not None
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(matches) != 1:
            raise SemanticGateClosed("operation siren fleet-lock target changed")
        target = matches[0]
        assert target.bounds is not None
        point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before fleet-lock input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=f"os/map/fleet-lock/{expected_state}",
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_fleet_bar(self) -> ActionReceipt:
        """Open the exact fleet bar whose Unity button has no raycast-top bit."""

        if not self.operation_siren_local_map_visible():
            raise SemanticGateClosed("operation siren local-map identity is absent")
        last_error: Optional[SemanticGateClosed] = None
        for attempt in range(5):
            state = self.read_state()
            matches = tuple(
                button
                for button in state.buttons
                if button.name == "fleet_bar"
                and button.path.endswith(
                    "top/adapt/left_stage/other/fleet_bar"
                )
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.point is not None
                and button.bounds is not None
                and button.bounds.contains(button.point)
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "operation siren fleet bar is absent or ambiguous"
                )
            target = matches[0]
            assert target.point is not None and target.bounds is not None
            ui_state = self.read_ui_state()
            if not state.generation <= ui_state.generation <= state.generation + 2:
                last_error = SemanticGateClosed(
                    "operation siren fleet-bar snapshots are not coherent"
                )
                if attempt < 4:
                    self._sleep(0.3)
                    continue
                raise last_error
            controls = tuple(
                image
                for image in ui_state.images
                if image.name == "fleet_bar"
                and image.path == target.path
                and image.sprite == "btn_switch"
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds == target.bounds
            )
            if len(controls) != 1:
                raise SemanticGateClosed(
                    "operation siren fleet-bar control is absent or ambiguous"
                )
            # Use the exact Unity Button's own event point.  The stronghold layout
            # consumes the whole fleet_bar component even though the legacy CN
            # screenshot asset highlighted only its right-hand decoration.
            point = target.point
            if self._foreground_component() != self.fingerprint.component:
                raise SemanticGateClosed(
                    "foreground changed before fleet-bar input"
                )
            self._tap(int(round(point.x)), int(round(point.y)))
            return ActionReceipt(
                semantic_id="os/map/fleet-selector/open",
                generation=state.generation,
                point=point,
                bounds=target.bounds,
                path=target.path,
            )
        assert last_error is not None
        raise last_error

    def operation_siren_fleet_selector_open(self) -> bool:
        """Return whether the exact four-row fleet selector is mounted."""

        state = self.read_state()
        root = "top/adapt/left_stage/mask/list/"
        expected = {"item", *(f"item ({index})" for index in range(1, 4))}
        matches = {
            button.name
            for button in state.buttons
            if button.name in expected
            and button.path.endswith(root + button.name)
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
        }
        if matches and matches != expected:
            raise SemanticGateClosed("operation siren fleet selector is incomplete")
        return matches == expected

    def click_operation_siren_fleet_selector(self, fleet_index: int) -> ActionReceipt:
        """Select fleet 1..4 from the exact expanded selector row."""

        if type(fleet_index) is not int or fleet_index not in range(1, 5):
            raise SemanticGateClosed("operation siren fleet index is malformed")
        if not self.operation_siren_fleet_selector_open():
            raise SemanticGateClosed("operation siren fleet selector is closed")
        state = self.read_state()
        suffix = "item" if fleet_index == 1 else f"item ({fleet_index - 1})"
        path = "top/adapt/left_stage/mask/list/" + suffix
        matches = tuple(
            button
            for button in state.buttons
            if button.path.endswith(path)
            and button.name == suffix
            and button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
        )
        if len(matches) != 1:
            raise SemanticGateClosed("operation siren fleet selector row changed")
        target = matches[0]
        assert target.point is not None and target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before fleet selection")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id=f"os/map/fleet-selector/{fleet_index}",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_back(self) -> ActionReceipt:
        """Leave the proven local Operation Siren map through its top back."""

        self.operation_siren_state()
        state = self.read_state()
        target = self._unique(state, "os/page/back")
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
        ):
            raise SemanticGateClosed("operation siren back is not actionable")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/page/back",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_globe(self) -> ActionReceipt:
        """Open the world map from a proven Operation Siren local map."""

        self.operation_siren_state()
        state = self.read_state()
        target = self._unique(state, "os/map/globe")
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
            and not self._blocking_rules(state, "os/map/globe")
        ):
            raise SemanticGateClosed("operation siren globe entrance is not actionable")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/map/globe",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_map_exit(self) -> ActionReceipt:
        """Leave a locked special-zone room through its exact exit control."""

        if not self.operation_siren_local_map_visible():
            # A prior accepted exit can unmount this owner between ALAS'
            # presence probe and the final target re-read.  Classify that
            # atomic transition as a missing target so idempotent callers do
            # not issue a duplicate tap on the ordinary map.
            raise SemanticTargetMissing(
                "operation siren local-map identity is absent"
            )
        state = self.read_state()
        target = self._unique(state, "os/map/exit")
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
        ):
            raise SemanticGateClosed("operation siren map exit is not actionable")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before map exit input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/map/exit",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    @staticmethod
    def _operation_siren_globe_zone_name_from_ui(ui_state: UiState) -> str:
        path = "SVFloatPanel(Clone)/point/line/bg/title/name/subText"
        matches = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith(path)
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if len(matches) != 1:
            raise SemanticGateClosed(
                "operation siren selected-zone title is absent or ambiguous"
            )
        decorated = re.sub(r"<[^>]*>", "", matches[0].text).strip()
        zone_name = re.split(r"\s*[-—–－]\s*", decorated, maxsplit=1)[0].strip()
        if not zone_name:
            raise SemanticGateClosed("operation siren selected-zone title is empty")
        return zone_name

    def operation_siren_globe_state(self) -> OperationSirenGlobeState:
        """Read the selected zone and global exploration summary."""

        button_state = self.read_state()
        back = self._unique(button_state, "os/globe/map")
        if not (
            back.active_in_hierarchy
            and back.active_and_enabled
            and back.interactable
            and back.raycast_top is None
            and back.point is not None
            and back.bounds is not None
            and back.bounds.contains(back.point)
        ):
            raise SemanticGateClosed("operation siren globe identity is absent")
        # ``read_state`` just proved the foreground component and package-pinned
        # observer identity.  Read the adjacent UI projection without another
        # expensive dumpsys call, then enforce generation coherence below.
        ui_state = self.read_ui_state(check_foreground=False)
        if not (
            button_state.generation
            <= ui_state.generation
            <= button_state.generation + 2
        ):
            raise SemanticGateClosed("operation siren globe snapshots are not coherent")

        def suffix(path: str) -> str:
            matches = tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(path)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "operation siren globe text is absent or ambiguous: " + path
                )
            return re.sub(r"<[^>]*>", "", matches[0].text).strip()

        zone_name = self._operation_siren_globe_zone_name_from_ui(ui_state)
        # The globe pin decorates the canonical zone name with its current
        # state (for example ``NA海域西北D-安全海域``).  ALAS owns
        # zone resolution and its Zone table contains the undecorated name,
        # just like the local-map OCR path after it removes the same suffix.
        # Keep the typed boundary equivalent by exposing only that base name.
        zone_type = suffix("SVFloatPanel(Clone)/point/line/bg/icon/marking/Text")
        danger = suffix("SVFloatPanel(Clone)/point/line/bg/danger_text")
        zone_progress = suffix(
            "SVFloatPanel(Clone)/point/line/bg/title/achievement/number"
        )
        world_root = "top/adapt/right_chapter/line/display_panel/world_info/"
        world_progress = suffix(world_root + "explore/achievement/number")
        suppression = suffix(world_root + "explore/pressing/number")
        mileage = suffix(world_root + "explore/mileage/number")
        fleet_power = suffix(world_root + "power/bg/Number")
        offense = suffix(world_root + "buff/buff_damage/Text")
        survival = suffix(world_root + "buff/buff_health/Text")
        tactical = suffix(world_root + "buff/buff_attack/Text")
        reset = suffix("top/adapt/top_chapter/reset_coutdown/Text")

        def fraction(value: str, label: str) -> Tuple[int, int]:
            match = re.fullmatch(r"([0-9]+)/([0-9]+)", value)
            if match is None:
                raise SemanticGateClosed("operation siren " + label + " is malformed")
            actual, capacity = map(int, match.groups())
            if actual > capacity:
                raise SemanticGateClosed(
                    "operation siren " + label + " is inconsistent"
                )
            return actual, capacity

        zone_actual, zone_capacity = fraction(zone_progress, "zone progress")
        world_actual, world_capacity = fraction(world_progress, "world progress")
        reset_match = re.fullmatch(r"距离大型作战重置\s*([0-9]+)\s*天", reset)
        integer_values = (
            danger,
            suppression,
            mileage,
            fleet_power,
            offense,
            survival,
            tactical,
        )
        if (
            not zone_name
            or zone_type
            not in {
                "危险海域",
                "普通海域",
                "安全海域",
                "隐秘海域",
                "深渊海域",
                "塞壬要塞",
                "档案海域",
                "未知海域",
            }
            or world_capacity == 0
            or reset_match is None
            or any(re.fullmatch(r"[0-9]+", value) is None for value in integer_values)
        ):
            raise SemanticGateClosed("operation siren globe summary is malformed")
        if zone_type == "塞壬要塞":
            stronghold_images = {
                "SVFloatPanel(Clone)/point/line/bg/icon": "daxuanwo",
                "SVFloatPanel(Clone)/point/line/bg/icon/marking": "mark_danger",
                "SVFloatPanel(Clone)/point/line/bg/icon/marking/mark_bg": (
                    "mark_bg_danger"
                ),
                "SVFloatPanel(Clone)/point/line/bg/sairen": "sairen_mask",
                "SVFloatPanel(Clone)/point/line/bg": "bg_danger",
                "SVFloatPanel(Clone)/point/line": "click_point_danger",
                "SVFloatPanel(Clone)/point": "click_point_danger",
            }
            for path, sprite in stronghold_images.items():
                matches = tuple(
                    image
                    for image in ui_state.images
                    if image.path.endswith(path)
                    and image.sprite == sprite
                    and image.active_in_hierarchy
                    and image.active_and_enabled
                    and not image.truncated
                    and image.bounds is not None
                )
                if len(matches) != 1:
                    raise SemanticGateClosed(
                        "operation siren stronghold marker is absent or ambiguous"
                    )
        return OperationSirenGlobeState(
            zone_name=zone_name,
            zone_type=zone_type,
            danger_level=int(danger),
            zone_achievement=zone_actual,
            zone_achievement_capacity=zone_capacity,
            world_achievement=world_actual,
            world_achievement_capacity=world_capacity,
            suppression=int(suppression),
            mileage=int(mileage),
            fleet_power=int(fleet_power),
            offense_adaptability=int(offense),
            survival_adaptability=int(survival),
            tactical_adaptability=int(tactical),
            reset_days=int(reset_match.group(1)),
        )

    def operation_siren_globe_visible(self) -> bool:
        """Recognize the globe even while no zone detail panel is pinned."""

        try:
            state = self.read_state()
            back = self._unique(state, "os/globe/map")
        except (SemanticGateClosed, SemanticTargetMissing):
            return False
        return bool(
            back.active_in_hierarchy
            and back.active_and_enabled
            and back.bounds is not None
        )

    def operation_siren_globe_unpin(self) -> OperationSirenGlobeSwipeReceipt:
        """Dismiss one exact selected-zone pin with its required short drag."""

        self.operation_siren_globe_state()
        ui_state = self.read_ui_state(check_foreground=False)
        pin_path = "SVFloatPanel(Clone)/point"
        pins = tuple(
            image
            for image in ui_state.images
            if image.name == "point"
            and image.path.endswith(pin_path)
            and image.sprite
            in {"click_point_safe", "click_point_danger", "click_point_normal"}
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
        )
        if len(pins) != 1:
            raise SemanticGateClosed(
                "operation siren selected-zone pin is absent or ambiguous"
            )
        if self._swipe is None:
            raise SemanticGateClosed("operation siren globe swipe backend is absent")
        initial_generation = ui_state.generation
        for delta_x, delta_y in (
            (-32, -24),
            (32, -24),
            (-32, 24),
            (32, 24),
        ):
            candidate = self.read_ui_state()
            current_pins = tuple(
                image
                for image in candidate.images
                if image.name == "point"
                and image.path.endswith(pin_path)
                and image.sprite
                in {"click_point_safe", "click_point_danger", "click_point_normal"}
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
            )
            if len(current_pins) != 1:
                raise SemanticGateClosed(
                    "operation siren selected-zone pin changed before unpin"
                )
            bounds = current_pins[0].bounds
            assert bounds is not None
            start = (
                int(round((bounds.left + bounds.right) / 2.0)),
                int(round((bounds.top + bounds.bottom) / 2.0)),
            )
            end = (start[0] + delta_x, start[1] + delta_y)
            if not Bounds(20.0, 220.0, 980.0, 620.0).contains(Point(*end)):
                continue
            if self._foreground_component() != self.fingerprint.component:
                raise SemanticGateClosed(
                    "foreground changed before operation siren selected-zone unpin"
                )
            self._swipe(start[0], start[1], end[0], end[1], 150)
            post_generation = None
            for _ in range(2):
                self._sleep(0.25)
                try:
                    after = self.read_ui_state(check_foreground=False)
                except SemanticGateClosed:
                    continue
                remaining = tuple(
                    image
                    for image in after.images
                    if image.path.endswith(pin_path)
                    and image.active_in_hierarchy
                )
                if (
                    after.generation > candidate.generation
                    and not remaining
                ):
                    post_generation = after.generation
                    break
            if post_generation is not None:
                if not self.operation_siren_globe_visible():
                    raise SemanticGateClosed(
                        "operation siren globe disappeared after selected-zone unpin"
                    )
                return OperationSirenGlobeSwipeReceipt(
                    semantic_id="os/globe/zone/unpin",
                    pre_generation=initial_generation,
                    post_generation=post_generation,
                    start=start,
                    end=end,
                    duration_ms=150,
                )
        raise SemanticGateClosed(
            "operation siren selected-zone unpin was not proven"
        )

    def operation_siren_storage_visible(self) -> bool:
        """Recognize the Operation Siren inventory by its exact page back control."""

        try:
            state = self.read_state()
            back = self._unique(state, "os/storage/back")
        except (SemanticGateClosed, SemanticTargetMissing):
            return False
        return bool(
            back.active_in_hierarchy
            and back.active_and_enabled
            and back.bounds is not None
        )

    def operation_siren_storage_state(self) -> OperationSirenStorageState:
        """Read visible coordinate records from the typed inventory hierarchy."""

        button_state = self.read_state()
        back = self._unique(button_state, "os/storage/back")
        if not (
            back.active_in_hierarchy
            and back.active_and_enabled
            and back.bounds is not None
        ):
            raise SemanticGateClosed("operation siren storage identity is absent")
        ui_state = self.read_ui_state()
        if not (
            button_state.generation
            <= ui_state.generation
            <= button_state.generation + 2
        ):
            raise SemanticGateClosed(
                "operation siren storage snapshots are not coherent"
            )

        suffix = "/WorldInventoryUI(Clone)/adapt/item_scrollview/Viewport/item_grid/"
        item_buttons: Dict[int, ButtonState] = {}
        for button in button_state.buttons:
            match = re.search(re.escape(suffix) + r"([0-9]+)$", button.path)
            if match is None:
                continue
            item_id = int(match.group(1))
            if item_id in item_buttons:
                raise SemanticGateClosed("operation siren storage item is ambiguous")
            item_buttons[item_id] = button

        items = []
        for item_id, button in sorted(item_buttons.items()):
            root = button.path + "/bg/"
            names = tuple(
                text
                for text in ui_state.texts
                if text.path == root + "name"
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            counts = tuple(
                text
                for text in ui_state.texts
                if text.path == root + "icon_bg/count"
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            if len(names) != 1 or len(counts) != 1:
                raise SemanticGateClosed(
                    "operation siren storage item text is incomplete"
                )
            display_name = re.sub(r"<[^>]*>", "", names[0].text).strip()
            count_text = counts[0].text.strip()
            sample_types = {
                301: ("SAMPLE_OFFENSE", "Wyangben1"),
                302: ("SAMPLE_SURVIVAL", "Wyangben3"),
                303: ("SAMPLE_COMBAT", "Wyangben5"),
                304: ("SAMPLE_QUALITY_OFFENSE", "Wyangben2"),
                305: ("SAMPLE_QUALITY_SURVIVAL", "Wyangben4"),
                306: ("SAMPLE_QUALITY_COMBAT", "Wyangben6"),
            }
            if item_id in sample_types:
                item_type, expected_sprite = sample_types[item_id]
                icons = tuple(
                    image
                    for image in ui_state.images
                    if image.path == root + "icon_bg/icon"
                    and image.active_in_hierarchy
                    and image.active_and_enabled
                    and not image.truncated
                    and image.bounds is not None
                )
                if len(icons) != 1 or icons[0].sprite != expected_sprite:
                    raise SemanticGateClosed(
                        "operation siren tuning sample identity changed"
                    )
            elif display_name.startswith("海域坐标:"):
                item_type = "OBSCURE"
            elif display_name.startswith("塞壬坐标:"):
                item_type = "ABYSSAL"
            else:
                # Other inventory objects belong to logger flows and
                # must not be inferred as a coordinate from their numeric id.
                continue
            if re.fullmatch(r"[1-9][0-9]*", count_text) is None:
                raise SemanticGateClosed(
                    "operation siren coordinate count is malformed"
                )
            bounds = button.bounds
            if bounds is None:
                raise SemanticGateClosed("operation siren coordinate bounds are absent")
            actionable = bool(
                button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.point is not None
                and bounds.contains(button.point)
                and 0 <= button.point.x < self.fingerprint.width
                and 0 <= button.point.y < self.fingerprint.height
                and 80 <= bounds.top < bounds.bottom <= 602
                and 0 <= bounds.left < bounds.right <= 1230
                and not self._blocking_rules(button_state, "os/storage/back")
            )
            items.append(
                OperationSirenStorageItemState(
                    generation=button_state.generation,
                    item_id=item_id,
                    item_type=item_type,
                    display_name=display_name,
                    count=int(count_text),
                    bounds=bounds,
                    actionable=actionable,
                )
            )
        return OperationSirenStorageState(
            generation=button_state.generation,
            items=tuple(items),
        )

    def click_operation_siren_storage_item(self, item_type: str) -> ActionReceipt:
        """Select one fully visible coordinate card without confirming its use."""

        if item_type not in ("OBSCURE", "ABYSSAL"):
            raise ValueError("operation siren storage item type is invalid")
        storage = self.operation_siren_storage_state()
        candidates = tuple(
            item
            for item in storage.items
            if item.item_type == item_type and item.actionable
        )
        if not candidates:
            raise SemanticTargetMissing(
                "actionable operation siren coordinate is absent: " + item_type
            )
        selected = candidates[0]
        state = self.read_state()
        path_suffix = (
            "/WorldInventoryUI(Clone)/adapt/item_scrollview/Viewport/"
            "item_grid/" + str(selected.item_id)
        )
        matches = tuple(
            button for button in state.buttons if button.path.endswith(path_suffix)
        )
        if len(matches) != 1:
            raise SemanticGateClosed("operation siren coordinate changed before input")
        button = matches[0]
        if button.bounds is None or button.point is None:
            raise SemanticGateClosed("operation siren coordinate geometry disappeared")
        if not (
            button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.bounds.contains(button.point)
            and 80 <= button.bounds.top < button.bounds.bottom <= 602
            and 0 <= button.bounds.left < button.bounds.right <= 1230
        ):
            raise SemanticGateClosed(
                "operation siren coordinate is no longer actionable"
            )
        visible = Bounds(
            max(0.0, button.bounds.left),
            max(0.0, button.bounds.top),
            min(float(self.fingerprint.width), button.bounds.right),
            min(float(self.fingerprint.height), button.bounds.bottom),
        )
        if visible.left >= visible.right or visible.top >= visible.bottom:
            raise SemanticGateClosed("operation siren coordinate is outside the screen")
        point = Point(
            (visible.left + visible.right) / 2.0,
            (visible.top + visible.bottom) / 2.0,
        )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="os/storage/item/" + item_type.lower(),
            generation=state.generation,
            point=point,
            bounds=button.bounds,
            path=button.path,
        )

    def operation_siren_storage_scroll_for_abyssal(
        self, timeout_seconds: float = 5.0
    ) -> OperationSirenStorageScrollReceipt:
        """Move the inventory viewport until an abyssal coordinate is fully visible."""

        if self._swipe is None:
            raise SemanticGateClosed("operation siren storage swipe backend is absent")
        before = self.operation_siren_storage_state()
        if any(
            item.item_type == "ABYSSAL" and item.actionable for item in before.items
        ):
            raise SemanticGateClosed(
                "operation siren abyssal coordinate already actionable"
            )
        if not any(item.item_type == "ABYSSAL" for item in before.items):
            raise SemanticTargetMissing("operation siren abyssal coordinate is absent")
        start = (640, 560)
        end = (640, 260)
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before storage scroll")
        self._swipe(start[0], start[1], end[0], end[1], 450)
        deadline = self._monotonic() + timeout_seconds
        while self._monotonic() < deadline:
            self._sleep(0.25)
            after = self.operation_siren_storage_state()
            actionable = tuple(
                item
                for item in after.items
                if item.item_type == "ABYSSAL" and item.actionable
            )
            if after.generation > before.generation and actionable:
                return OperationSirenStorageScrollReceipt(
                    semantic_id="os/storage/scroll/abyssal",
                    pre_generation=before.generation,
                    post_generation=after.generation,
                    start=start,
                    end=end,
                    visible_abyssal_count=len(actionable),
                )
        raise SemanticGateClosed("operation siren storage scroll was not proven")

    def click_operation_siren_storage_back(self) -> ActionReceipt:
        """Leave the proven Operation Siren inventory through its exact back control."""

        if not self.operation_siren_storage_visible():
            raise SemanticGateClosed("operation siren storage identity is absent")
        state = self.read_state()
        target = self._unique(state, "os/storage/back")
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
            and not self._blocking_rules(state, "os/storage/back")
        ):
            raise SemanticGateClosed("operation siren storage back is not actionable")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/storage/back",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def operation_siren_storage_detail(self) -> Optional[Tuple[str, str, int]]:
        """Return the selected coordinate detail without authorizing checkout."""

        state = self.read_state()
        close_matches = self._matches(state, "os/storage/detail/close")
        checkout_matches = self._matches(state, "os/storage/detail/checkout")
        if not close_matches and not checkout_matches:
            return None
        if len(close_matches) != 1 or len(checkout_matches) != 1:
            raise SemanticGateClosed("operation siren storage detail is ambiguous")
        for target in (close_matches[0], checkout_matches[0]):
            if not (
                target.active_in_hierarchy
                and target.active_and_enabled
                and target.interactable
                and target.point is not None
                and target.bounds is not None
                and target.bounds.contains(target.point)
            ):
                raise SemanticGateClosed(
                    "operation siren storage detail is not actionable"
                )
        ui_state = self.read_ui_state()
        if not state.generation <= ui_state.generation <= state.generation + 2:
            raise SemanticGateClosed(
                "operation siren storage detail snapshots are not coherent"
            )

        def exact_text(suffix: str) -> str:
            matches = tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "operation siren storage detail text is incomplete"
                )
            return re.sub(r"<[^>]*>", "", matches[0].text).strip()

        name = exact_text(
            "item_usage_panel/window/item/display_panel/name_container/name/Text"
        )
        description = exact_text("item_usage_panel/window/item/display_panel/desc/Text")
        count = exact_text("item_usage_panel/window/item/left/IconTpl/icon_bg/count")
        if not (
            name.startswith(("海域坐标:", "塞壬坐标:"))
            and description
            and re.fullmatch(r"[1-9][0-9]*", count)
        ):
            raise SemanticGateClosed("operation siren storage detail is malformed")
        return name, description, int(count)

    def click_operation_siren_storage_detail_close(self) -> ActionReceipt:
        """Close the proven coordinate detail without consuming its item."""

        if self.operation_siren_storage_detail() is None:
            raise SemanticGateClosed("operation siren storage detail is absent")
        state = self.read_state()
        target = self._unique(state, "os/storage/detail/close")
        assert target.point is not None and target.bounds is not None
        if self._blocking_rules(state, "os/storage/detail/close"):
            raise SemanticGateClosed("operation siren storage detail close is blocked")
        point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="os/storage/detail/close",
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

