    def _operation_siren_mission_overview_state(
        self,
    ) -> Tuple[
        OracleState, ButtonState, Tuple[ButtonState, ...], Tuple[ButtonState, ...]
    ]:
        """Read the pinned WorldDailyTaskUI without inferring from pixels."""

        state = self.read_state()
        back = self._unique(state, "os/mission-overview/back")
        if (
            not back.active_in_hierarchy
            or not back.active_and_enabled
            or not back.interactable
            or back.raycast_top is not None
            or back.point is None
            or back.bounds is None
            or not back.bounds.contains(back.point)
            or self._blocking_rules(state, "os/mission-overview/back")
        ):
            raise SemanticGateClosed(
                "operation siren mission overview is not actionable"
            )

        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
            or ui_state.image_truncated
            or ui_state.method_mask & 0x8 == 0
        ):
            raise SemanticGateClosed(
                "operation siren mission overview snapshots are incomplete"
            )
        titles = tuple(
            image
            for image in ui_state.images
            if image.path.endswith("Overlay/UIMain/blur_panel/adapt/top/title/title")
            and image.name == "title"
            and image.sprite == "task_daily_task"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
        )
        if len(titles) != 1:
            raise SemanticGateClosed(
                "operation siren mission overview title is absent or ambiguous"
            )

        row_pattern = re.compile(
            r"(?:^|/)Overlay/UIMain/blur_panel/adapt/tasks/frame/viewport/"
            r"content/task_tpl(?:\(Clone\))?/button/(active|inactive)$"
        )
        active_rows = []
        inactive_rows = []
        for candidate in state.buttons:
            match = row_pattern.search(candidate.path)
            if match is None or candidate.name != match.group(1):
                continue
            if not candidate.active_in_hierarchy or not candidate.active_and_enabled:
                continue
            (active_rows if match.group(1) == "active" else inactive_rows).append(
                candidate
            )
        return state, back, tuple(active_rows), tuple(inactive_rows)

    def operation_siren_mission_overview_visible(self) -> bool:
        try:
            self._operation_siren_mission_overview_state()
        except SemanticGateClosed:
            return False
        return True

    def operation_siren_mission_overview_empty(self) -> bool:
        """Prove that the complete mounted list has no unaccepted task row."""

        _, _, active_rows, inactive_rows = (
            self._operation_siren_mission_overview_state()
        )
        if active_rows:
            return False
        if not inactive_rows:
            raise SemanticGateClosed(
                "operation siren mission overview has no typed task rows"
            )
        return True

    def operation_siren_mission_overview_accept_available(self) -> bool:
        _, _, active_rows, _ = self._operation_siren_mission_overview_state()
        return any(
            row.actionable
            and row.point is not None
            and 0 <= row.point.x < self.fingerprint.width
            and 0 <= row.point.y < self.fingerprint.height
            for row in active_rows
        )

    def click_operation_siren_mission_overview_accept(self) -> ActionReceipt:
        state, _, active_rows, _ = self._operation_siren_mission_overview_state()
        actionable = tuple(
            row
            for row in active_rows
            if row.actionable
            and row.point is not None
            and row.bounds is not None
            and 0 <= row.point.x < self.fingerprint.width
            and 0 <= row.point.y < self.fingerprint.height
        )
        if len(actionable) != 1:
            raise SemanticGateClosed(
                "operation siren mission overview accept row is absent or ambiguous"
            )
        target = actionable[0]
        assert target.point is not None
        assert target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed(
                "game activity changed before mission overview input"
            )
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/mission-overview/accept",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_mission_overview_back(self) -> ActionReceipt:
        if not self.operation_siren_mission_overview_visible():
            raise SemanticGateClosed("operation siren mission overview is absent")
        return self.click("os/mission-overview/back")

    def _operation_siren_mission_list_state(
        self,
    ) -> Tuple[
        OracleState,
        UiState,
        ButtonState,
        Tuple[ButtonState, ...],
        Tuple[ButtonState, ...],
    ]:
        state = self.read_state()
        close = self._unique(state, "os/mission-list/close")
        if (
            not close.active_in_hierarchy
            or not close.active_and_enabled
            or not close.interactable
            or close.raycast_top is not None
            or close.point is None
            or close.bounds is None
            or not close.bounds.contains(close.point)
            or self._blocking_rules(state, "os/mission-list/close")
        ):
            raise SemanticGateClosed("operation siren mission list is not actionable")
        ui_state = self.read_text_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed(
                "operation siren mission list snapshots are not coherent"
            )
        titles = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith(
                "WorldInformationUI(Clone)/adapt/right_panel/title/task_all"
            )
            and text.text == "任务总汇"
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if len(titles) != 1:
            raise SemanticGateClosed(
                "operation siren mission list title is absent or ambiguous"
            )
        row_pattern = re.compile(
            r"(?:^|/)WorldInformationUI\(Clone\)/adapt/right_panel/main/"
            r"viewport/content/task_tpl(?:\(Clone\))?/base_panel/(btn_go|btn_get)$"
        )
        go_rows = []
        finish_rows = []
        for button in state.buttons:
            match = row_pattern.search(button.path)
            if match is None or button.name != match.group(1):
                continue
            if not button.active_in_hierarchy or not button.active_and_enabled:
                continue
            (go_rows if button.name == "btn_go" else finish_rows).append(button)
        key = lambda item: (
            item.bounds.top if item.bounds is not None else math.inf,
            item.path,
        )
        return (
            state,
            ui_state,
            close,
            tuple(sorted(go_rows, key=key)),
            tuple(sorted(finish_rows, key=key)),
        )

    def operation_siren_mission_list_visible(self) -> bool:
        try:
            self._operation_siren_mission_list_state()
        except SemanticGateClosed:
            return False
        return True

    @staticmethod
    def _operation_siren_actionable_rows(
        rows: Sequence[ButtonState], width: int, height: int
    ) -> Tuple[ButtonState, ...]:
        return tuple(
            row
            for row in rows
            if row.active_in_hierarchy
            and row.active_and_enabled
            and row.interactable
            and row.raycast_top is None
            and row.point is not None
            and row.bounds is not None
            and row.bounds.contains(row.point)
            and row.bounds.bottom > 0
            and row.bounds.top < height
            and 0 <= row.point.x < width
            and 0 <= row.point.y < height
        )

    @staticmethod
    def _operation_siren_monthly_boss_rows(
        ui_state: UiState, rows: Sequence[ButtonState]
    ) -> Tuple[ButtonState, ...]:
        title_suffix = "/base_panel/base_show/title/Text"
        titles = tuple(
            text
            for text in ui_state.texts
            if "WorldInformationUI(Clone)/adapt/right_panel/main/viewport/content/"
            in text.path
            and text.path.endswith(title_suffix)
            and "仲裁机关" in re.sub(r"<[^>]*>", "", text.text)
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        monthly_rows = []
        for title in titles:
            assert title.bounds is not None
            candidates = tuple(
                row
                for row in rows
                if row.bounds is not None
                and row.bounds.bottom >= title.bounds.top
                and row.bounds.top <= title.bounds.bottom
            )
            if len(candidates) != 1:
                raise SemanticGateClosed(
                    "operation siren monthly boss row is absent or ambiguous"
                )
            if candidates[0] not in monthly_rows:
                monthly_rows.append(candidates[0])
        return tuple(monthly_rows)

    def operation_siren_mission_checkout_available(
        self, *, exclude_monthly_boss: bool = False
    ) -> bool:
        _, ui_state, _, rows, _ = self._operation_siren_mission_list_state()
        if exclude_monthly_boss:
            monthly_rows = self._operation_siren_monthly_boss_rows(ui_state, rows)
            rows = tuple(row for row in rows if row not in monthly_rows)
        return bool(
            self._operation_siren_actionable_rows(
                rows, self.fingerprint.width, self.fingerprint.height
            )
        )

    def operation_siren_mission_finish_available(self) -> bool:
        _, _, _, _, rows = self._operation_siren_mission_list_state()
        return bool(
            self._operation_siren_actionable_rows(
                rows, self.fingerprint.width, self.fingerprint.height
            )
        )

    def operation_siren_month_boss_difficulty(self) -> Optional[str]:
        """Read the monthly Arbiter task title from the mounted mission list."""

        _, ui_state, _, _, _ = self._operation_siren_mission_list_state()
        title_suffix = "/base_panel/base_show/title/Text"
        titles = tuple(
            re.sub(r"<[^>]*>", "", text.text).strip()
            for text in ui_state.texts
            if "WorldInformationUI(Clone)/adapt/right_panel/main/viewport/content/"
            in text.path
            and text.path.endswith(title_suffix)
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        matches = tuple(title for title in titles if "仲裁机关" in title)
        if not matches:
            return None
        if len(matches) != 1:
            raise SemanticGateClosed("operation siren monthly boss task is ambiguous")
        title = matches[0]
        if title.startswith("普通作战"):
            return "normal"
        if title.startswith("困难作战"):
            return "hard"
        raise SemanticGateClosed("operation siren monthly boss difficulty is unknown")

    def _click_operation_siren_mission_row(
        self, action: str, *, exclude_monthly_boss: bool = False
    ) -> ActionReceipt:
        if action not in ("checkout", "finish"):
            raise ValueError("operation siren mission action is unsupported")
        state, ui_state, _, go_rows, finish_rows = (
            self._operation_siren_mission_list_state()
        )
        rows = go_rows if action == "checkout" else finish_rows
        if action == "checkout" and exclude_monthly_boss:
            monthly_rows = self._operation_siren_monthly_boss_rows(ui_state, rows)
            rows = tuple(row for row in rows if row not in monthly_rows)
        actionable = self._operation_siren_actionable_rows(
            rows, self.fingerprint.width, self.fingerprint.height
        )
        if not actionable:
            raise SemanticGateClosed("operation siren mission row is absent")
        target = actionable[0]
        assert target.point is not None
        assert target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before mission row input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/mission-list/" + action,
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_mission_checkout(
        self, *, exclude_monthly_boss: bool = False
    ) -> ActionReceipt:
        return self._click_operation_siren_mission_row(
            "checkout", exclude_monthly_boss=exclude_monthly_boss
        )

    def click_operation_siren_mission_finish(self) -> ActionReceipt:
        return self._click_operation_siren_mission_row("finish")

    def click_operation_siren_globe_zone(
        self,
        expected_zone_name: str,
        point: Tuple[float, float],
    ) -> ActionReceipt:
        """Select one ALAS-resolved globe zone and prove the typed pin changed."""

        if not self.operation_siren_globe_visible():
            raise SemanticGateClosed("operation siren globe identity is absent")
        before_ui = self.read_ui_state(check_foreground=False)
        before_name = None
        try:
            before_name = self._operation_siren_globe_zone_name_from_ui(before_ui)
        except SemanticGateClosed:
            # A camera drag intentionally unpins the previous zone.  The new
            # target is still proven below by its exact typed detail title.
            pass
        if not expected_zone_name or expected_zone_name == before_name:
            raise SemanticGateClosed("operation siren globe zone intent is invalid")
        if (
            not isinstance(point, tuple)
            or len(point) != 2
            or any(
                isinstance(value, bool) or not isinstance(value, (int, float))
                for value in point
            )
        ):
            raise SemanticGateClosed("operation siren globe zone point is malformed")
        x, y = (int(round(point[0])), int(round(point[1])))
        safe = Bounds(20.0, 220.0, 980.0, 620.0)
        target_point = Point(float(x), float(y))
        if not safe.contains(target_point):
            raise SemanticGateClosed(
                "operation siren globe zone point is outside the map"
            )

        self._tap(x, y)
        selected_name = None
        selected_generation = None
        # Globe probes deliberately cover a sparse recovery grid.  Six
        # quarter-second typed snapshots retain an animation margin while
        # bounding the cost of an empty coordinate.
        for _ in range(6):
            self._sleep(0.25)
            try:
                candidate = self.read_ui_state(check_foreground=False)
                candidate_name = self._operation_siren_globe_zone_name_from_ui(
                    candidate
                )
            except SemanticGateClosed:
                continue
            if candidate.generation <= before_ui.generation:
                continue
            if candidate_name == expected_zone_name:
                selected_generation = candidate.generation
                break
            if candidate_name != before_name:
                selected_generation = candidate.generation
                selected_name = candidate_name
                break
        if selected_generation is None:
            raise SemanticGateClosed(
                "operation siren globe zone selection was not proven"
            )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed(
                "game activity changed after operation siren globe zone input"
            )
        return ActionReceipt(
            semantic_id=(
                "os/globe/zone/select"
                if selected_name is None
                else "os/globe/zone/select-mismatch"
            ),
            generation=selected_generation,
            point=target_point,
            bounds=Bounds(float(x - 8), float(y - 8), float(x + 8), float(y + 8)),
            path="operation-siren/globe/zone/" + expected_zone_name,
        )

    def operation_siren_globe_swipe(
        self,
        start: Tuple[int, int],
        end: Tuple[int, int],
        duration_ms: int,
    ) -> OperationSirenGlobeSwipeReceipt:
        """Dispatch one bounded globe-camera gesture and prove the globe survived."""

        if self._swipe is None:
            raise SemanticGateClosed("operation siren globe swipe backend is absent")
        state = self.read_state()
        back = self._unique(state, "os/globe/map")
        if not (
            back.active_in_hierarchy
            and back.active_and_enabled
            and back.bounds is not None
        ):
            raise SemanticGateClosed("operation siren globe identity is absent")
        pre_generation = self._last_generation or 0
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed(
                "foreground changed before operation siren globe swipe"
            )
        self._swipe(start[0], start[1], end[0], end[1], duration_ms)
        post_generation = None
        for _ in range(12):
            self._sleep(0.25)
            try:
                candidate = self.read_state()
                candidate_back = self._unique(candidate, "os/globe/map")
            except (SemanticGateClosed, SemanticTargetMissing):
                continue
            if (
                candidate.generation > pre_generation
                and candidate_back.active_in_hierarchy
                and candidate_back.active_and_enabled
                and candidate_back.bounds is not None
            ):
                post_generation = candidate.generation
                break
        if post_generation is None:
            raise SemanticGateClosed(
                "operation siren globe swipe post-state was not proven"
            )
        return OperationSirenGlobeSwipeReceipt(
            semantic_id="os/globe/swipe",
            pre_generation=pre_generation,
            post_generation=post_generation,
            start=start,
            end=end,
            duration_ms=duration_ms,
        )

    def click_operation_siren_globe_zone_enter(self) -> ActionReceipt:
        """Enter the exact currently pinned Operation Siren zone."""

        self.operation_siren_globe_state()
        state = self.read_state()
        targets = tuple(
            semantic_id
            for semantic_id in (
                "os/globe/zone-enter",
                "os/globe/zone-return",
                "os/globe/zone-back",
            )
            if len(self._matches(state, semantic_id)) == 1
        )
        if len(targets) != 1:
            raise SemanticGateClosed(
                "operation siren globe zone entrance is absent or ambiguous"
            )
        semantic_id = targets[0]
        target = self._unique(state, semantic_id)
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.bounds is not None
        ):
            raise SemanticGateClosed(
                "operation siren globe zone entrance is not actionable"
            )
        point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_globe_zone_switch(self) -> ActionReceipt:
        """Open the exact zone-type selector on the currently pinned zone."""

        self.operation_siren_globe_state()
        state = self.read_state()
        target = self._unique(state, "os/globe/zone-switch")
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
        ):
            raise SemanticGateClosed(
                "operation siren globe zone switch is not actionable"
            )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before zone switch input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="os/globe/zone-switch",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def operation_siren_globe_zone_types(self) -> Tuple[str, ...]:
        """Return the exact ALAS zone types offered by the open selector."""

        state = self.read_state()
        mask = self._unique(state, "os/globe/zone-type-mask")
        if not (
            mask.active_in_hierarchy
            and mask.active_and_enabled
            and mask.interactable
            and mask.bounds is not None
        ):
            raise SemanticGateClosed("operation siren zone-type selector is absent")
        ui_state = self.read_ui_state()
        root = "SVFloatPanel(Clone)/select_mask/marking/toggles/"
        display_to_type = {
            "普通海域": "DANGEROUS",
            "危险海域": "DANGEROUS",
            "安全海域": "SAFE",
            "隐秘海域": "OBSCURE",
            "深渊海域": "ABYSSAL",
            "塞壬要塞": "STRONGHOLD",
            "档案海域": "ARCHIVE",
            "未知海域": "UNKNOWN",
        }
        labels = tuple(
            text
            for text in ui_state.texts
            if root in text.path
            and text.path.endswith("/Text")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if not labels or any(text.text.strip() not in display_to_type for text in labels):
            raise SemanticGateClosed("operation siren zone-type label is unknown")
        normalized = tuple(display_to_type[text.text.strip()] for text in labels)
        if len(set(normalized)) != len(normalized):
            raise SemanticGateClosed("operation siren zone-type selector is ambiguous")
        return normalized

    def click_operation_siren_globe_zone_type(
        self, expected_type: str
    ) -> ActionReceipt:
        """Select one exact typed alternative from the open zone selector."""

        if expected_type not in {
            "DANGEROUS", "SAFE", "OBSCURE", "ABYSSAL", "STRONGHOLD", "ARCHIVE"
        }:
            raise SemanticGateClosed("operation siren zone type is malformed")
        if expected_type not in self.operation_siren_globe_zone_types():
            raise SemanticGateClosed("operation siren zone type is unavailable")
        ui_state = self.read_ui_state()
        type_to_labels = {
            "DANGEROUS": {"普通海域", "危险海域"},
            "SAFE": {"安全海域"},
            "OBSCURE": {"隐秘海域"},
            "ABYSSAL": {"深渊海域"},
            "STRONGHOLD": {"塞壬要塞"},
            "ARCHIVE": {"档案海域"},
        }
        root = "SVFloatPanel(Clone)/select_mask/marking/toggles/"
        targets = tuple(
            text
            for text in ui_state.texts
            if root in text.path
            and text.path.endswith("/Text")
            and text.text.strip() in type_to_labels[expected_type]
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if len(targets) != 1:
            raise SemanticGateClosed("operation siren zone-type target is ambiguous")
        target = targets[0]
        assert target.bounds is not None
        point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before zone-type input")
        self._tap(int(round(point.x)), int(round(point.y)))
        for _ in range(12):
            self._sleep(0.25)
            try:
                after = self.operation_siren_globe_state()
            except SemanticGateClosed:
                continue
            if after.zone_type in type_to_labels[expected_type]:
                break
        else:
            raise SemanticGateClosed(
                "operation siren zone-type selection was not proven"
            )
        return ActionReceipt(
            semantic_id="os/globe/zone-type/" + expected_type.lower(),
            generation=ui_state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def _operation_siren_action_point_read(
        self,
    ) -> Tuple[
        OracleState,
        OperationSirenActionPointState,
        Tuple[ImageState, ...],
    ]:
        button_state = self.read_state()
        use = self._unique(button_state, "os/action-point/use")
        cancel = self._unique(button_state, "os/action-point/cancel")
        if not all(
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
            for target in (use, cancel)
        ):
            raise SemanticGateClosed(
                "operation siren action point controls are incomplete"
            )

        ui_state = self.read_ui_state()
        if not (
            button_state.generation
            <= ui_state.generation
            <= button_state.generation + 2
        ):
            raise SemanticGateClosed(
                "operation siren action point snapshots are not coherent"
            )
        root = (
            "WorldStaminaRecoverUI(Clone)/window/world_stamina_panel/content/"
        )
        current_text = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith(root + "tip_bg/stamina/value")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and re.fullmatch(r"[0-9]{1,3}", text.text.strip())
        )
        if len(current_text) != 1:
            raise SemanticGateClosed(
                "operation siren current action points are absent or ambiguous"
            )

        item_suffix = "item(Clone)/IconTpl/icon_bg/icon"
        expected_sprites = (
            "oil",
            "Wxingdonglihuifu1",
            "Wxingdonglihuifu2",
            "Wxingdonglihuifu3",
        )
        icons = tuple(
            sorted(
                (
                    image
                    for image in ui_state.images
                    if image.path.endswith(root + "item_list/" + item_suffix)
                    and image.sprite in expected_sprites
                    and image.active_in_hierarchy
                    and image.active_and_enabled
                    and not image.truncated
                    and image.bounds is not None
                ),
                key=lambda image: image.bounds.left if image.bounds else math.inf,
            )
        )
        if (
            len(icons) != 4
            or tuple(image.sprite for image in icons) != expected_sprites
        ):
            raise SemanticGateClosed(
                "operation siren action point item icons are incomplete"
            )
        count_texts = tuple(
            sorted(
                (
                    text
                    for text in ui_state.texts
                    if text.path.endswith(
                        root + "item_list/item(Clone)/IconTpl/icon_bg/count"
                    )
                    and text.active_in_hierarchy
                    and text.active_and_enabled
                    and not text.truncated
                    and text.bounds is not None
                    and re.fullmatch(r"[0-9]+", text.text.strip())
                ),
                key=lambda text: text.bounds.left if text.bounds else math.inf,
            )
        )
        if len(count_texts) != 4:
            raise SemanticGateClosed(
                "operation siren action point item counts are incomplete"
            )
        for icon, count in zip(icons, count_texts):
            assert icon.bounds is not None and count.bounds is not None
            if abs(
                (icon.bounds.left + icon.bounds.right) / 2.0
                - (count.bounds.left + count.bounds.right) / 2.0
            ) > 60.0:
                raise SemanticGateClosed(
                    "operation siren action point item pairing changed"
                )

        selected = tuple(
            image
            for image in ui_state.images
            if image.path.endswith(root + "item_list/item(Clone)/select")
            and image.sprite == "selected"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
        )
        if len(selected) != 1:
            raise SemanticGateClosed(
                "operation siren selected action point item is ambiguous"
            )
        assert selected[0].bounds is not None
        selected_center = (
            selected[0].bounds.left + selected[0].bounds.right
        ) / 2.0
        icon_centers = tuple(
            (image.bounds.left + image.bounds.right) / 2.0
            for image in icons
            if image.bounds is not None
        )
        selected_index = min(
            range(4), key=lambda index: abs(icon_centers[index] - selected_center)
        )
        if abs(icon_centers[selected_index] - selected_center) > 25.0:
            raise SemanticGateClosed(
                "operation siren selected action point item is unbound"
            )

        purchase_cost: Optional[int] = None
        purchase_points: Optional[int] = None
        purchase_remaining: Optional[int] = None
        purchase_limit: Optional[int] = None
        purchase_texts = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith(root + "Text")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if selected_index == 0:
            if len(purchase_texts) != 1:
                raise SemanticGateClosed(
                    "operation siren oil purchase terms are absent or ambiguous"
                )
            purchase_plain = re.sub(
                r"</?color(?:=#[0-9A-Fa-f]{6})?>",
                "",
                purchase_texts[0].text,
            )
            purchase_values = tuple(
                int(value) for value in re.findall(r"[0-9]+", purchase_plain)
            )
            if (
                len(purchase_values) != 4
                or "<" in purchase_plain
                or ">" in purchase_plain
            ):
                raise SemanticGateClosed(
                    "operation siren oil purchase terms are malformed"
                )
            (
                purchase_cost,
                purchase_points,
                purchase_remaining,
                purchase_limit,
            ) = purchase_values
            if (
                purchase_cost <= 0
                or purchase_points not in range(1, 601)
                or purchase_limit != 5
                or purchase_remaining not in range(6)
            ):
                raise SemanticGateClosed(
                    "operation siren oil purchase terms changed"
                )
        return (
            button_state,
            OperationSirenActionPointState(
                generation=ui_state.generation,
                current=int(current_text[0].text.strip()),
                item_counts=tuple(
                    int(text.text.strip()) for text in count_texts
                ),
                selected_index=selected_index,
                oil_purchase_cost=purchase_cost,
                oil_purchase_points=purchase_points,
                oil_purchase_remaining=purchase_remaining,
                oil_purchase_limit=purchase_limit,
            ),
            icons,
        )

    def operation_siren_action_point_state(
        self,
    ) -> OperationSirenActionPointState:
        return self._retry_transition_read(
            lambda: self._operation_siren_action_point_read()[1]
        )

    def operation_siren_action_point_visible(self) -> bool:
        state = self.read_state()
        try:
            use = self._unique(state, "os/action-point/use")
            cancel = self._unique(state, "os/action-point/cancel")
        except SemanticTargetMissing:
            return False
        return all(
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.point is not None
            and target.bounds is not None
            for target in (use, cancel)
        )

    def click_operation_siren_action_point_open(self) -> ActionReceipt:
        """Open the AP panel from the exact WorldMap stamina resource."""

        # Require the complete local-map resource header, not merely a button
        # with the same short Unity name.
        self.operation_siren_state()
        button_state = self.read_state()
        target = self._unique(button_state, "os/action-point/open")
        if not (
            target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
        ):
            raise SemanticGateClosed(
                "operation siren action point entry is not actionable"
            )
        ui_state = self.read_ui_state()
        value_texts = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith(
                "top/adapt/top_stage/resources/WorldResPanel(Clone)/res/"
                "stamina/value"
            )
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and re.fullmatch(r"[0-9]+", text.text.strip()) is not None
        )
        if (
            len(value_texts) != 1
            or not button_state.generation
            <= ui_state.generation
            <= button_state.generation + 2
        ):
            raise SemanticGateClosed(
                "operation siren action point value is absent or ambiguous"
            )
        value = value_texts[0]
        assert value.bounds is not None
        point = Point(
            (value.bounds.left + value.bounds.right) / 2.0,
            (value.bounds.top + value.bounds.bottom) / 2.0,
        )
        if not target.bounds.contains(point):
            raise SemanticGateClosed(
                "operation siren action point value left its resource control"
            )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before action point input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="os/action-point/open",
            generation=button_state.generation,
            point=point,
            bounds=value.bounds,
            path=value.path,
        )

    def click_operation_siren_action_point_item(
        self, item_index: int
    ) -> ActionReceipt:
        if item_index not in range(4):
            raise ValueError("operation siren action point item must be 0 through 3")
        button_state, before, icons = self._operation_siren_action_point_read()
        if before.selected_index == item_index:
            raise SemanticGateClosed(
                "operation siren action point item is already selected"
            )
        target = icons[item_index]
        assert target.bounds is not None
        point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before action point input")
        self._tap(int(round(point.x)), int(round(point.y)))
        for _ in range(12):
            self._sleep(0.25)
            after = self.operation_siren_action_point_state()
            if (
                after.selected_index == item_index
                and after.current == before.current
                and after.item_counts == before.item_counts
            ):
                break
        else:
            raise SemanticGateClosed(
                "operation siren action point selection was not proven"
            )
        return ActionReceipt(
            semantic_id=f"os/action-point/item/{item_index}",
            generation=button_state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_operation_siren_action_point_control(
        self, use: bool
    ) -> ActionReceipt:
        button_state, _, _ = self._operation_siren_action_point_read()
        semantic_id = "os/action-point/use" if use else "os/action-point/cancel"
        target = self._unique(button_state, semantic_id)
        if target.point is None or target.bounds is None:
            raise SemanticGateClosed(
                "operation siren action point control is not actionable"
            )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before action point input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=button_state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def _operation_siren_port_repair_cost_in_state(
        self, state: OracleState
    ) -> Optional[int]:
        """Bind the dock-wide repair prompt to its exact typed cost."""

        confirm = self._matches(state, "os/port/dock/repair-confirm")
        cancel = self._matches(state, "os/port/dock/repair-cancel")
        if len(confirm) > 1 or len(cancel) > 1:
            raise SemanticGateClosed("operation siren repair prompt is ambiguous")
        if not confirm and not cancel:
            return None
        if (
            len(confirm) != 1
            or len(cancel) != 1
            or not confirm[0].actionable
            or not cancel[0].actionable
        ):
            raise SemanticGateClosed("operation siren repair prompt is incomplete")

        before_signature = self._msgbox_button_signature(state)
        text_state = self.read_text_state()
        after = self.read_state()
        if not (
            state.generation <= text_state.generation <= after.generation
            and state.scene_handle == after.scene_handle
            and before_signature == self._msgbox_button_signature(after)
        ):
            raise SemanticGateClosed(
                "operation siren repair prompt snapshots are not coherent"
            )

        def exact_text(suffix: str) -> Optional[str]:
            matches = tuple(
                text
                for text in text_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            if len(matches) > 1:
                raise SemanticGateClosed(
                    "operation siren repair prompt text is ambiguous"
                )
            return matches[0].text if matches else None

        content = exact_text("Msgbox(Clone)/window/msg_panel/content")
        cancel_text = exact_text(
            "Msgbox(Clone)/window/button_container/custom_button_2(Clone)/pic"
        )
        confirm_text = exact_text(
            "Msgbox(Clone)/window/button_container/custom_button_1(Clone)/pic"
        )
        if content is None or cancel_text is None or confirm_text is None:
            raise SemanticGateClosed("operation siren repair prompt text is incomplete")
        plain = re.sub(r"<[^>]*>", "", content).strip()
        match = re.fullmatch(r"修复所有舰船需要：\s*\*([1-9][0-9]*)", plain)
        if (
            match is None
            or "".join(cancel_text.split()) != "取消"
            or "".join(confirm_text.split()) != "确定"
        ):
            raise SemanticGateClosed("operation siren repair prompt is unknown")
        return int(match.group(1))

    def operation_siren_port_repair_cost(self) -> Optional[int]:
        return self._retry_transition_read(
            lambda: self._operation_siren_port_repair_cost_in_state(
                self.read_state()
            )
        )

    def click_operation_siren_port_repair(
        self, confirm: bool
    ) -> ActionReceipt:
        state = self.read_state()
        if self._operation_siren_port_repair_cost_in_state(state) is None:
            raise SemanticGateClosed("operation siren repair prompt is absent")
        semantic_id = (
            "os/port/dock/repair-confirm"
            if confirm
            else "os/port/dock/repair-cancel"
        )
        target = self._unique(state, semantic_id)
        if not target.actionable or target.point is None or target.bounds is None:
            raise SemanticGateClosed(
                "operation siren repair choice is not actionable"
            )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before repair input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def _operation_siren_exit_prompt_state(self) -> Optional[OracleState]:
        """Return one button snapshot only when its exact exit text is coherent."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        zone_titles = tuple(
            text.text.strip()
            for text in ui_state.texts
            if text.path.endswith("/top_stage/title/name")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and text.text.strip()
        )
        retained_progress_prompts = {
            f"是否确定从{title}中离开？\n"
            "（离开后当前作战进度将会保留，本月内再次进入可继续挑战）"
            for title in zone_titles
        }
        reset_progress_prompts = {
            f"是否确定从{title}中离开？\n"
            "（离开后当前作战进度将会重置，已获得的奖励无法重复领取）"
            for title in zone_titles
        }
        prompt = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith("Msgbox(Clone)/window/msg_panel/content")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and (
                text.text.strip()
                in {
                    "需要暂时离开大型作战么？",
                    "当前海域无法通过边界区域离开。是否继续？",
                    "离开当前海域后，潜艇舰队会自动返回我方港口待命，是否离开？",
                    "是否确定从该处隐秘海域离开？\n"
                    "（离开后将无法再次返回）",
                    "是否确定从深渊海域离开？\n"
                    "（警告：离开后将无法再次返回挑战强敌！）",
                }
                or text.text.strip() in retained_progress_prompts
                or text.text.strip() in reset_progress_prompts
            )
        )
        return state if (
            len(prompt) == 1
            and len(self._matches(state, "os/exit/confirm")) == 1
            and len(self._matches(state, "os/exit/cancel")) == 1
        ) else None

    def operation_siren_exit_prompt_visible(self) -> bool:
        return self._operation_siren_exit_prompt_state() is not None

    def operation_siren_abyssal_entry_prompt_visible(self) -> bool:
        """Recognize the one-way abyssal entry warning exactly."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        prompts = tuple(
            text.text.strip()
            for text in ui_state.texts
            if text.path.endswith("Msgbox(Clone)/window/msg_panel/content")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        return bool(
            prompts
            == (
                "深渊海域作战难度较高且不可重复进入，\n"
                "请确认舰队战备后前往作战",
            )
            and len(self._matches(state, "os/exit/confirm")) == 1
            and len(self._matches(state, "os/exit/cancel")) == 1
        )

    def operation_siren_abyssal_exit_available(self) -> bool:
        """Return whether the nearest abyssal passage has been unlocked.

        The client replaces ``taban_jinzhi(Clone)`` with ``taban(Clone)``
        after the boss settlement. Both models can remain in the scene graph
        outside the viewport, so compare the event model nearest the viewport
        centre instead of accepting any unlocked floor model in the map.
        """

        ui_state = self.read_ui_state()
        titles = tuple(
            text.text.strip()
            for text in ui_state.texts
            if text.path.endswith("/top_stage/title/name")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and text.text.strip().endswith("-深渊海域")
        )
        if len(titles) != 1:
            return False

        models = []
        for image in ui_state.images:
            if not image.active_in_hierarchy or image.bounds is None:
                continue
            if "/attachments/event_" not in image.path:
                continue
            if not image.path.endswith("/taban"):
                continue
            if "/icon/model/taban(Clone)/" in image.path:
                unlocked = True
            elif "/icon/model/taban_jinzhi(Clone)/" in image.path:
                unlocked = False
            else:
                continue
            center_x = (image.bounds.left + image.bounds.right) / 2.0
            center_y = (image.bounds.top + image.bounds.bottom) / 2.0
            distance = math.hypot(
                center_x - self.fingerprint.width / 2.0,
                center_y - self.fingerprint.height / 2.0,
            )
            models.append((distance, unlocked))

        if not models:
            return False
        models.sort(key=lambda item: item[0])
        nearest_distance, nearest_unlocked = models[0]
        return nearest_distance <= self.fingerprint.height and nearest_unlocked

    def click_operation_siren_abyssal_exit(self) -> ActionReceipt:
        """Move onto the nearest exact unlocked abyssal passage model."""

        if not self.operation_siren_abyssal_exit_available():
            raise SemanticGateClosed("unlocked abyssal passage is absent")
        state = self.read_ui_state()
        candidates = []
        for image in state.images:
            if (
                image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
                and "/attachments/event_" in image.path
                and image.path.endswith(
                    "/icon/model/taban(Clone)/taban"
                )
                and image.name == "taban"
                and image.sprite == "taban01"
            ):
                center_x = (image.bounds.left + image.bounds.right) / 2.0
                center_y = (image.bounds.top + image.bounds.bottom) / 2.0
                candidates.append(
                    (
                        math.hypot(
                            center_x - self.fingerprint.width / 2.0,
                            center_y - self.fingerprint.height / 2.0,
                        ),
                        image,
                        Point(center_x, center_y),
                    )
                )
        candidates.sort(key=lambda item: item[0])
        if not candidates:
            raise SemanticGateClosed("unlocked abyssal passage is absent")
        _, target, point = candidates[0]
        assert target.bounds is not None
        if (
            not target.bounds.contains(point)
            or not 80.0 <= point.x <= 960.0
            or not 100.0 <= point.y <= 620.0
            or self._foreground_component() != self.fingerprint.component
        ):
            raise SemanticGateClosed("unlocked abyssal passage is not safely visible")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="os/abyssal/exit",
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

