    def dorm_feed_state(self) -> DormFeedState:
        """Read the open dorm feed panel without changing inventory."""

        button_state = self.read_state()
        close = self._unique(button_state, "dorm/feed/close")
        if not close.actionable or self._blocking_rules(
            button_state, "dorm/feed/close"
        ):
            raise SemanticGateClosed("dorm feed panel identity is not proven")
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("dorm feed snapshots are not coherent")

        def exact_text(path: str) -> str:
            matches = tuple(
                item
                for item in ui_state.texts
                if item.path.endswith(path)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "dorm feed text is absent or ambiguous: " + path
                )
            return re.sub(r"<[^>]*>", "", matches[0].text).strip()

        fill = re.fullmatch(
            r"([0-9]+)/([1-9][0-9]*)",
            exact_text("BackYardFeedUI(Clone)/frame/Text"),
        )
        if fill is None:
            raise SemanticGateClosed("dorm feed capacity is malformed")
        food, capacity = map(int, fill.groups())
        if food > capacity:
            raise SemanticGateClosed("dorm feed capacity is inconsistent")

        items = []
        for item_id in range(50001, 50007):
            root = "BackYardFeedUI(Clone)/frame/food_{0}/".format(item_id)
            value_match = re.fullmatch(r"食物([1-9][0-9]*)", exact_text(root + "Text"))
            count_text = exact_text(root + "icon_bg/count")
            if value_match is None or re.fullmatch(r"[0-9]+", count_text) is None:
                raise SemanticGateClosed("dorm feed inventory is malformed")
            semantic_id = "dorm/feed/item/{0}".format(item_id)
            images = tuple(
                image
                for image in ui_state.images
                if image.name == "icon_bg"
                and image.path.endswith(root + "icon_bg")
                and image.active_in_hierarchy
                and image.active_and_enabled
                and image.raycast_target
                and image.raycast_top is True
                and not image.truncated
                and image.bounds is not None
            )
            if len(images) != 1:
                raise SemanticGateClosed("dorm feed item image is absent or ambiguous")
            image = images[0]
            if self._blocking_rules(button_state, semantic_id):
                raise SemanticGateClosed("dorm feed item is not safely actionable")
            assert image.bounds is not None
            button = ButtonState(
                name=image.name,
                path=image.path,
                active_in_hierarchy=image.active_in_hierarchy,
                active_and_enabled=image.active_and_enabled,
                interactable=True,
                raycast_top=image.raycast_top,
                point=Point(
                    (image.bounds.left + image.bounds.right) / 2.0,
                    (image.bounds.top + image.bounds.bottom) / 2.0,
                ),
                bounds=image.bounds,
                raw=image.raw,
            )
            items.append(
                DormFoodState(
                    item_id=item_id,
                    value=int(value_match.group(1)),
                    count=int(count_text),
                    button=button,
                )
            )
        return DormFeedState(food=food, capacity=capacity, items=tuple(items))

    def click_dorm_food(self, item_id: int) -> ActionReceipt:
        """Click one ALAS dorm food card after exact typed revalidation."""

        if item_id not in range(50001, 50007):
            raise ValueError("dorm food item id must be 50001 through 50006")
        feed = self._retry_transition_read(
            self.dorm_feed_state,
            attempts=20,
            interval_seconds=0.25,
        )
        matches = tuple(item for item in feed.items if item.item_id == item_id)
        if len(matches) != 1:
            raise SemanticGateClosed("dorm feed item identity is ambiguous")
        target = matches[0].button
        semantic_id = "dorm/feed/item/{0}".format(item_id)
        button_state = self.read_state()
        if (
            not target.actionable
            or target.point is None
            or target.bounds is None
            or self._blocking_rules(button_state, semantic_id)
        ):
            raise SemanticGateClosed("dorm feed item is not safely actionable")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=button_state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_tactical_empty_slot(self, slot: int) -> ActionReceipt:
        """Click one visually ordered empty tactical slot after exact revalidation."""

        if slot not in range(1, 5):
            raise ValueError("tactical slot must be 1 through 4")
        state = self.read_state()
        targets = self._tactical_empty_slot_targets(state)
        try:
            target = targets[slot]
        except KeyError as exc:
            raise SemanticGateClosed("tactical slot is not empty") from exc
        if self._blocking_rules(state, "tactical/slot/{0}".format(slot)):
            raise SemanticGateClosed("tactical slot input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        assert target.point is not None and target.bounds is not None
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="tactical/slot/{0}".format(slot),
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def click_tactical_first_empty_slot(self) -> ActionReceipt:
        """Click the leftmost current tactical empty slot."""

        state = self.read_state()
        targets = self._tactical_empty_slot_targets(state)
        if not targets:
            raise SemanticGateClosed("tactical class has no empty slot")
        slot = min(targets)
        target = targets[slot]
        if self._blocking_rules(state, "tactical/slot/{0}".format(slot)):
            raise SemanticGateClosed("tactical slot input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        assert target.point is not None and target.bounds is not None
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="tactical/slot/{0}".format(slot),
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def _tactical_empty_slot_targets(
        self, state: UiState
    ) -> Mapping[int, ButtonState]:
        """Return current empty slots keyed by their physical left-to-right index."""

        prefix = "NewNavalTacticsUI(Clone)/adpter/NewNavalTacticsStudentsPage(Clone)/"
        empty = tuple(
            button
            for button in state.buttons
            if button.name in ("add", "add(Clone)")
            and button.path.endswith(prefix + button.name)
            and button.actionable
            and button.point is not None
        )
        occupied = tuple(
            button
            for button in state.buttons
            if re.fullmatch(r"[1-9][0-9]{5}", button.name) is not None
            and prefix in button.path
            and button.path.endswith("/" + button.name)
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.point is not None
        )
        columns = tuple(sorted((*empty, *occupied), key=lambda button: button.point.x))
        if len(columns) != 4 or len({button.point.x for button in columns}) != 4:
            raise SemanticGateClosed("tactical slot controls are incomplete")
        return {
            index: button
            for index, button in enumerate(columns, start=1)
            if button in empty
        }

    def tactical_empty_slots_ready(self) -> bool:
        """Report whether at least one complete current tactical empty slot exists."""

        state = self.read_state()
        try:
            return bool(self._tactical_empty_slot_targets(state))
        except SemanticGateClosed:
            return False

    def tactical_candidate_ships(self) -> Tuple[TacticalCandidateShipState, ...]:
        """Read visible tactical Dock candidates in ALAS grid order."""

        button_state = self.read_state()
        back = self._unique(button_state, "tactical/dock/back")
        confirm = self._unique(button_state, "tactical/dock/confirm")
        if not back.active_and_enabled or not confirm.active_and_enabled:
            raise SemanticGateClosed("tactical Dock identity is not proven")
        prefix = "DockyardUI(Clone)/main/ship_container/ships/"
        buttons = tuple(
            button
            for button in button_state.buttons
            if re.fullmatch(r"[1-9][0-9]{5,7}", button.name) is not None
            and button.path.endswith(prefix + button.name)
            and button.bounds is not None
            and button.bounds.right > 0
            and button.bounds.bottom > 0
            and button.bounds.left < self.fingerprint.width
            and button.bounds.top < 500
        )
        if not buttons or len({button.name for button in buttons}) != len(buttons):
            raise SemanticGateClosed("tactical Dock candidates are absent or ambiguous")
        buttons = tuple(
            sorted(
                buttons,
                key=lambda button: (
                    round(button.bounds.top / 50.0),
                    button.bounds.left,
                ),
            )
        )
        ui_state = self.read_text_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("tactical Dock snapshots are not coherent")

        candidates = []
        for position, button in enumerate(buttons):
            root = button.path + "/content/"

            def exact_text(suffix: str) -> str:
                matches = tuple(
                    text
                    for text in ui_state.texts
                    if text.path == root + suffix
                    and text.active_in_hierarchy
                    and text.active_and_enabled
                    and not text.truncated
                    and text.bounds is not None
                )
                if len(matches) != 1:
                    raise SemanticGateClosed(
                        "tactical Dock text is absent or ambiguous: " + suffix
                    )
                return re.sub(r"<[^>]*>", "", matches[0].text).strip()

            name = exact_text("info/name_mask/name")
            level_text = exact_text("dockyard/lv/Text")
            if not name or re.fullmatch(r"[1-9][0-9]{0,2}", level_text) is None:
                raise SemanticGateClosed("tactical Dock candidate is malformed")
            candidates.append(
                TacticalCandidateShipState(
                    position=position,
                    ship_id=int(button.name),
                    ship_name=name,
                    level=int(level_text),
                    button=button,
                )
            )
        return tuple(candidates)

    def click_tactical_ship(self, ship_id: int) -> ActionReceipt:
        candidates = self.tactical_candidate_ships()
        matches = tuple(
            candidate for candidate in candidates if candidate.ship_id == ship_id
        )
        if len(matches) != 1:
            raise SemanticGateClosed("tactical Dock ship identity changed")
        target = matches[0].button
        if not target.actionable or target.point is None or target.bounds is None:
            raise SemanticGateClosed("tactical Dock ship is not safely actionable")
        state = self.read_state()
        current = tuple(
            button for button in state.buttons if button.path == target.path
        )
        if len(current) != 1 or not current[0].actionable:
            raise SemanticGateClosed("tactical Dock ship changed before input")
        target = current[0]
        assert target.point is not None and target.bounds is not None
        if self._blocking_rules(state, "tactical/dock/ship"):
            raise SemanticGateClosed("tactical Dock ship input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="tactical/dock/ship/{0}".format(ship_id),
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def tactical_skills(self) -> Tuple[TacticalSkillState, ...]:
        """Read visible skill rows in the tactical skill-selection dialog."""

        button_state = self.read_state()
        confirm = self._unique(button_state, "tactical/skill/confirm")
        if not confirm.active_and_enabled:
            raise SemanticGateClosed("tactical skill dialog identity is not proven")
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("tactical skill snapshots are not coherent")
        rows_path_fragment = (
            "NewNavalTacticsSkillsPage(Clone)/frame/skill_container/content/"
        )
        rows = tuple(
            image
            for image in ui_state.images
            if image.name in ("skill", "skill(Clone)")
            and image.path.endswith(rows_path_fragment + image.name)
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.raycast_target
            and not image.truncated
            and image.bounds is not None
            and image.bounds.bottom > 0
            and image.bounds.top < self.fingerprint.height
        )
        rows = tuple(sorted(rows, key=lambda image: image.bounds.top))
        if not rows or len(rows) > 4:
            raise SemanticGateClosed("tactical skill rows are absent or ambiguous")

        result = []
        for position, row in enumerate(rows):
            assert row.bounds is not None

            def text_with_suffix(suffix: str) -> str:
                matches = tuple(
                    text
                    for text in ui_state.texts
                    if rows_path_fragment in text.path
                    and text.path.endswith(suffix)
                    and text.active_in_hierarchy
                    and text.active_and_enabled
                    and not text.truncated
                    and text.bounds is not None
                    and row.bounds.contains(
                        Point(
                            (text.bounds.left + text.bounds.right) / 2.0,
                            (text.bounds.top + text.bounds.bottom) / 2.0,
                        )
                    )
                )
                if len(matches) != 1:
                    raise SemanticGateClosed(
                        "tactical skill text is absent or ambiguous: " + suffix
                    )
                return re.sub(r"<[^>]*>", "", matches[0].text).strip()

            name = text_with_suffix("/name/Text/subText")
            level = text_with_suffix("/name/level")
            next_value = text_with_suffix("/next")
            if not name or re.fullmatch(r"Lv\.[1-9][0-9]?", level) is None:
                raise SemanticGateClosed("tactical skill row is malformed")
            result.append(
                TacticalSkillState(
                    position=position,
                    name=name,
                    level_text=next_value,
                    max_level=next_value.upper() == "MAX",
                    button=ButtonState(
                        name=row.name,
                        path=row.path,
                        active_in_hierarchy=row.active_in_hierarchy,
                        active_and_enabled=row.active_and_enabled,
                        interactable=True,
                        raycast_top=row.raycast_top,
                        point=Point(
                            (row.bounds.left + row.bounds.right) / 2.0,
                            (row.bounds.top + row.bounds.bottom) / 2.0,
                        ),
                        bounds=row.bounds,
                        raw=row.raw,
                    ),
                )
            )
        return tuple(result)

    def click_tactical_skill(self, position: int) -> ActionReceipt:
        skills = self.tactical_skills()
        matches = tuple(skill for skill in skills if skill.position == position)
        if len(matches) != 1 or matches[0].max_level:
            raise SemanticGateClosed("tactical skill is absent or already maxed")
        target = matches[0].button
        if not target.actionable or target.point is None or target.bounds is None:
            raise SemanticGateClosed("tactical skill is not safely actionable")
        state = self.read_state()
        if self._blocking_rules(state, "tactical/skill/item"):
            raise SemanticGateClosed("tactical skill input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="tactical/skill/{0}".format(position),
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def tactical_books(self) -> Tuple[TacticalBookState, ...]:
        """Read visible tactical books in the same order as ALAS BOOKS_GRID."""

        button_state = self.read_state()
        start = self._unique(button_state, "tactical/book/start")
        cancel = self._unique(button_state, "tactical/book/cancel")
        if not start.active_and_enabled or not cancel.active_and_enabled:
            raise SemanticGateClosed("tactical book dialog identity is not proven")
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("tactical book snapshots are not coherent")

        root = "NewNavalTacticsLessonPage(Clone)/items/scorll/content/"
        items = tuple(
            image
            for image in ui_state.images
            if image.name in ("item", "item(Clone)")
            and image.path.endswith(root + image.name)
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.raycast_target
            and image.raycast_top is True
            and not image.truncated
            and image.bounds is not None
            and image.bounds.right > 0
            and image.bounds.bottom > 0
            and image.bounds.left < self.fingerprint.width
            and image.bounds.top < self.fingerprint.height
        )
        items = tuple(
            sorted(
                items,
                key=lambda image: (
                    round(image.bounds.top / 50.0),
                    image.bounds.left,
                ),
            )
        )
        if not items or len(items) > 12:
            raise SemanticGateClosed("tactical book items are absent or ambiguous")

        def center(bounds: Bounds) -> Point:
            return Point(
                (bounds.left + bounds.right) / 2.0,
                (bounds.top + bounds.bottom) / 2.0,
            )

        books = []
        seen_ids = set()
        for position, item in enumerate(items):
            assert item.bounds is not None
            icon_matches = tuple(
                image
                for image in ui_state.images
                if image.name == "icon"
                and image.path.startswith(item.path + "/icon_bg/")
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
                and item.bounds.contains(center(image.bounds))
                and re.fullmatch(r"160[012][1-4]", image.sprite) is not None
            )
            count_matches = tuple(
                text
                for text in ui_state.texts
                if text.name == "count"
                and text.path.startswith(item.path + "/icon_bg/")
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
                and item.bounds.contains(center(text.bounds))
                and re.fullmatch(r"[0-9]+", text.text.strip()) is not None
            )
            addition_matches = tuple(
                text
                for text in ui_state.texts
                if text.name == "addition"
                and text.path.startswith(item.path + "/")
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
                and item.bounds.left <= center(text.bounds).x <= item.bounds.right
                and item.bounds.top - 10 <= center(text.bounds).y <= item.bounds.bottom
            )
            if (
                len(icon_matches) != 1
                or len(count_matches) != 1
                or len(addition_matches) != 1
            ):
                raise SemanticGateClosed(
                    "tactical book identity text is absent or ambiguous"
                )
            item_id = icon_matches[0].sprite
            if item_id in seen_ids:
                raise SemanticGateClosed("tactical book item ID is duplicated")
            seen_ids.add(item_id)
            addition = addition_matches[0].text.strip()
            if addition not in ("", "EXP150%", "EXP200%"):
                raise SemanticGateClosed("tactical book EXP bonus is malformed")
            selected = any(
                image.name == "selected"
                and image.path.startswith(item.path + "/selected")
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
                and item.bounds.contains(center(image.bounds))
                for image in ui_state.images
            )
            books.append(
                TacticalBookState(
                    position=position,
                    item_id=item_id,
                    genre=int(item_id[-2]) + 1,
                    tier=int(item_id[-1]),
                    exp_bonus=bool(addition),
                    count=int(count_matches[0].text.strip()),
                    selected=selected,
                    image=item,
                )
            )
        if sum(book.selected for book in books) != 1:
            raise SemanticGateClosed("tactical selected book is absent or ambiguous")
        return tuple(books)

    def tactical_book_skill_progress(self) -> str:
        """Return the selected skill's pre-book progress as ``current/total``."""

        button_state = self.read_state()
        start = self._unique(button_state, "tactical/book/start")
        cancel = self._unique(button_state, "tactical/book/cancel")
        if not start.active_and_enabled or not cancel.active_and_enabled:
            raise SemanticGateClosed("tactical book progress page identity is not proven")
        text_state = self.read_text_state()
        if (
            text_state.generation < button_state.generation
            or text_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("tactical book progress snapshots are not coherent")
        root = "NewNavalTacticsLessonPage(Clone)/skill/info/next"
        labels = tuple(
            text
            for text in text_state.texts
            if text.path.endswith(root + "/label")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        progress = tuple(
            text
            for text in text_state.texts
            if text.path.endswith(root)
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        if len(labels) != 1 or labels[0].text.strip() != "NEXT:" or len(progress) != 1:
            raise SemanticGateClosed("tactical book progress text is absent or ambiguous")
        match = re.fullmatch(
            r"([0-9]+)\+<color=#A9F548FF>[0-9]+</color>/([0-9]+)",
            progress[0].text.strip(),
        )
        if match is None:
            raise SemanticGateClosed("tactical book progress text is malformed")
        current, total = (int(value) for value in match.groups())
        if total not in (100, 200, 400, 800, 1400, 2200, 3200, 4400, 5800) or not 0 <= current <= total:
            raise SemanticGateClosed("tactical book progress values are invalid")
        return "{0}/{1}".format(current, total)

    def click_tactical_book(self, position: int) -> ActionReceipt:
        books = self.tactical_books()
        matches = tuple(book for book in books if book.position == position)
        if len(matches) != 1 or matches[0].count <= 0:
            raise SemanticGateClosed("tactical book is absent or exhausted")
        target = matches[0].image
        if target.raycast_top is not True or target.bounds is None:
            raise SemanticGateClosed("tactical book is not safely actionable")
        state = self.read_state()
        if self._blocking_rules(state, "tactical/book/item"):
            raise SemanticGateClosed("tactical book input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="tactical/book/{0}".format(position),
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def research_projects(self) -> Tuple[ResearchProjectState, ...]:
        """Read the five visible research cards from typed Unity state."""

        return self._retry_transition_read(
            self._research_projects_once,
            attempts=12,
            interval_seconds=0.5,
        )

    def _research_projects_once(self) -> Tuple[ResearchProjectState, ...]:
        """Read one exact, internally coherent five-card snapshot."""

        button_state = self.read_state()
        back = self._unique(button_state, "research/page/back")
        if not back.actionable or self._blocking_rules(
            button_state, "research/page/back"
        ):
            raise SemanticGateClosed("research page identity is not proven")
        indexed = []
        pattern = re.compile(
            r"(?:^|/)TechnologyUI\(Clone\)/main/base_page/srcoll_rect/"
            r"content/([1-5])$"
        )
        for button in button_state.buttons:
            match = pattern.search(button.path)
            if (
                match is not None
                and button.name == match.group(1)
                and button.actionable
                and button.point is not None
                and 0 <= button.point.x < self.fingerprint.width
                and 0 <= button.point.y < self.fingerprint.height
            ):
                indexed.append((int(match.group(1)), button))
        if len(indexed) != 5 or len({item[0] for item in indexed}) != 5:
            raise SemanticGateClosed("research project Buttons are incomplete")
        indexed.sort(key=lambda item: (item[1].point.x, item[0]))

        ui_state = self.read_ui_state()
        if ui_state.image_truncated or ui_state.method_mask & 0x8 == 0:
            raise SemanticGateClosed("typed research Image snapshot is incomplete")
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("research snapshots are not coherent")

        def text_at(path: str) -> str:
            matches = tuple(
                item
                for item in ui_state.texts
                if item.path == path
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "research project text is absent or ambiguous: " + path
                )
            return matches[0].text.strip()

        projects = []
        for slot, (unity_index, button) in enumerate(indexed, start=1):
            root = button.path + "/frame/"
            code = text_at(root + "name_bg/Text")
            subtitle = text_at(root + "sub_name")
            marker = re.sub(r"<[^>]*>", "", text_at(root + "marks/Text")).strip()
            status = self._research_status_from_text(marker)
            duration = self.parse_countdown_seconds(text_at(root + "marks/time"))
            version_path = root + "top/label/version"
            versions = tuple(
                image
                for image in ui_state.images
                if image.path == version_path
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
            )
            if len(versions) != 1:
                raise SemanticGateClosed("research project series is ambiguous")
            version = re.fullmatch(r"version_([1-9][0-9]*)", versions[0].sprite)
            if version is None or not code:
                raise SemanticGateClosed("research project identity is malformed")
            projects.append(
                ResearchProjectState(
                    slot=slot,
                    unity_index=unity_index,
                    code=code,
                    subtitle=subtitle,
                    series=int(version.group(1)),
                    status=status,
                    duration_seconds=duration,
                    button=button,
                )
            )
        return tuple(projects)

    def click_research_project(self, slot: int) -> ActionReceipt:
        if slot not in range(1, 6):
            raise ValueError("research project slot must be 1 through 5")
        projects = self.research_projects()
        matches = tuple(project for project in projects if project.slot == slot)
        if len(matches) != 1:
            raise SemanticGateClosed("research project slot identity changed")
        expected = matches[0]
        state = self.read_state()
        current = tuple(
            button
            for button in state.buttons
            if button.path == expected.button.path
            and button.name == str(expected.unity_index)
        )
        if len(current) != 1 or not current[0].actionable:
            raise SemanticGateClosed("research project changed before input")
        target = current[0]
        if self._blocking_rules(state, "research/project/{0}".format(slot)):
            raise SemanticGateClosed("research project input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        assert target.point is not None and target.bounds is not None
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="research/project/{0}".format(slot),
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    @staticmethod
    def _research_status_from_text(value: str) -> ResearchProjectStatus:
        plain = re.sub(r"<[^>]*>", "", value).strip()
        statuses = {
            "查看详情": ResearchProjectStatus.DETAIL,
            "进行中": ResearchProjectStatus.RUNNING,
            "等待中": ResearchProjectStatus.WAITING,
            # The live CN queue currently labels a queued item as
            # “等待进行”, rather than the older “等待中” wording.
            "等待进行": ResearchProjectStatus.WAITING,
            "研究完成": ResearchProjectStatus.FINISHED,
        }
        try:
            return statuses[plain]
        except KeyError as exc:
            raise SemanticGateClosed(
                "research status is not reviewed: " + plain
            ) from exc

    def research_detail_state(self) -> ResearchDetailState:
        """Read the selected research detail and its exact action state."""

        button_state = self.read_state()
        root_button = self._unique(button_state, "research/detail/root")
        if not root_button.actionable or self._blocking_rules(
            button_state, "research/detail/root"
        ):
            raise SemanticGateClosed("research detail identity is not proven")
        ui_state = self.read_ui_state()
        if (
            ui_state.image_truncated
            or ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("research detail snapshots are incomplete")

        root = "TechnologyUI(Clone)/main/base_page/selecte_panel/technology_card/frame/"
        panel = "TechnologyUI(Clone)/main/base_page/selecte_panel/"

        def exact_text(suffix: str) -> str:
            path = root + suffix
            matches = tuple(
                item
                for item in ui_state.texts
                if item.path.endswith(path)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "research detail text is absent or ambiguous: " + suffix
                )
            return matches[0].text.strip()

        code = exact_text("name_bg/Text")
        subtitle = exact_text("sub_name")

        def panel_text(suffix: str) -> str:
            path = panel + suffix
            matches = tuple(
                item
                for item in ui_state.texts
                if item.path.endswith(path)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "research detail text is absent or ambiguous: " + suffix
                )
            return matches[0].text.strip()

        action_ids = {
            "start": "research/detail/start",
            "stop": "research/detail/stop",
            "finish": "research/detail/finish",
            "queue": "research/detail/queue",
        }
        actions = {}
        for key, semantic_id in action_ids.items():
            matches = self._matches(button_state, semantic_id)
            if len(matches) > 1:
                raise SemanticGateClosed("research detail action is ambiguous: " + key)
            if key == "queue":
                actions[key] = self._research_queue_add_proven(
                    button_state, ui_state=ui_state
                )
            else:
                actions[key] = bool(matches and matches[0].actionable)

        duration = self.parse_countdown_seconds(panel_text("timer/bg/Text"))
        if not code:
            raise SemanticGateClosed("research detail code is absent")

        # A running or finished project no longer has a start cost panel in
        # the native client.  Its stop/finish action is sufficient to prove
        # the non-startable detail state; inventing a resource for it would
        # make a later confirmation unsafe.  Some idle projects likewise cost
        # no resource.  Their live detail has no cost count or resource icon,
        # and starts directly without a confirmation prompt.
        if actions["stop"] or actions["finish"]:
            resource_id = ""
            owned = 0
            required = 0
            requirement = ""
        else:
            resource_count_path = (
                panel + "consume_panel/bg/container/item_tpl/icon_bg/count"
            )
            resource_path = panel + "consume_panel/bg/container/item_tpl/icon_bg/icon"
            resource_counts = tuple(
                item
                for item in ui_state.texts
                if item.path.endswith(resource_count_path)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            icons = tuple(
                item
                for item in ui_state.images
                if item.path.endswith(resource_path)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if not resource_counts and not icons:
                resource_id = ""
                owned = 0
                required = 0
                requirement = ""
            elif len(resource_counts) != 1 or len(icons) != 1:
                raise SemanticGateClosed("research detail resource identity is ambiguous")
            else:
                resource = re.fullmatch(
                    r"([0-9]+)/([1-9][0-9]*)",
                    re.sub(r"<[^>]*>", "", resource_counts[0].text),
                )
                if resource is None:
                    raise SemanticGateClosed("research detail resource state is malformed")
                if re.fullmatch(r"[A-Za-z0-9_.-]+", icons[0].sprite) is None:
                    raise SemanticGateClosed("research detail resource identity is ambiguous")
                owned, required = map(int, resource.groups())
                # Research Q projects display the numeric inventory sprite
                # on their detail card, while the confirmation prompt names
                # the component by family and tier. Keep the reviewed legacy
                # carrier-aircraft aliases; other component families retain
                # their exact numeric item ids so both observations agree.
                resource_id = {
                    "17041": "research_part_t1",
                    "17042": "research_part_t2",
                    "17043": "research_part_t3",
                    "17044": "research_part_t4",
                }.get(icons[0].sprite, icons[0].sprite)
                requirement = re.sub(
                    r"<[^>]*>",
                    "",
                    panel_text("consume_panel/bg/task_panel/slider/Text"),
                ).strip()
        return ResearchDetailState(
            code=code,
            subtitle=subtitle,
            duration_seconds=duration,
            resource_id=resource_id,
            resource_owned=owned,
            resource_required=required,
            requirement=requirement,
            can_start=actions["start"] and owned >= required,
            can_queue=actions["queue"],
            is_running=actions["stop"],
            is_finished=actions["finish"],
        )

    def _research_queue_add_proven(
        self, state: OracleState, ui_state: Optional[UIState] = None
    ) -> bool:
        matches = self._matches(state, "research/detail/queue")
        if len(matches) > 1:
            raise SemanticGateClosed("research queue-add target is ambiguous")
        if not matches:
            return False
        target = matches[0]
        if self._blocking_rules(state, "research/detail/queue"):
            return False
        if target.actionable:
            return True
        if (
            target.raycast_top is not None
            or not target.active_in_hierarchy
            or not target.active_and_enabled
            or not target.interactable
            or target.point is None
            or target.bounds is None
            or not target.bounds.contains(target.point)
        ):
            return False

        # The live 9.7.10 join_btn delegates raycasts to its same-path Image,
        # so the observer cannot assign a top-raycast result to the parent
        # Button.  Admit only this reviewed structure while a concurrently
        # actionable stop button proves that the selected project is running.
        stop = self._matches(state, "research/detail/stop")
        root = self._matches(state, "research/detail/root")
        if (
            len(stop) != 1
            or not stop[0].actionable
            or len(root) != 1
            or not root[0].actionable
        ):
            return False
        if ui_state is None:
            ui_state = self.read_ui_state()
        if (
            ui_state.image_truncated
            or ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("research queue-add snapshots are incomplete")
        images = tuple(
            image
            for image in ui_state.images
            if image.path == target.path
            and image.sprite == "join_btn"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.raycast_target
            and not image.truncated
            and image.bounds is not None
            and image.bounds.contains(target.point)
        )
        if len(images) > 1:
            raise SemanticGateClosed("research queue-add image is ambiguous")
        return len(images) == 1

    def research_queue_add_available(self) -> bool:
        return self._retry_transition_read(
            self._research_queue_add_available_once,
            attempts=12,
            interval_seconds=0.5,
        )

    def _research_queue_add_available_once(self) -> bool:
        state = self.read_state()
        return self._research_queue_add_proven(state)

    def click_research_queue_add(self) -> ActionReceipt:
        def exact_state() -> OracleState:
            state = self.read_state()
            if not self._research_queue_add_proven(state):
                raise SemanticGateClosed("research queue-add input is not proven")
            return state

        state = self._retry_transition_read(
            exact_state,
            attempts=12,
            interval_seconds=0.5,
        )
        target = self._unique(state, "research/detail/queue")
        assert target.point is not None
        assert target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before research queue-add")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed after research queue-add")
        return ActionReceipt(
            semantic_id="research/detail/queue",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def _dorm_back_delegated_raycast_proven(
        self, state: OracleState, ui_state: Optional[UiState] = None
    ) -> bool:
        matches = self._matches(state, "dorm/page/back")
        if len(matches) > 1:
            raise SemanticGateClosed("dorm back target is ambiguous")
        if not matches:
            return False
        target = matches[0]
        if self._blocking_rules(state, "dorm/page/back"):
            return False
        if target.actionable:
            return True
        if (
            target.raycast_top is not False
            or not target.active_in_hierarchy
            or not target.active_and_enabled
            or not target.interactable
            or target.point is None
            or target.bounds is None
            or not target.bounds.contains(target.point)
        ):
            return False

        # CourtYardUI's reviewed return control delegates raycasts to the
        # decorative Images on the Button and its children.  Keep this escape
        # hatch local to the exact path and exact 9.7.10 sprite composition.
        if ui_state is None:
            ui_state = self.read_ui_state()
        if (
            ui_state.image_truncated
            or ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("dorm back snapshots are incomplete")
        expected = {
            target.path: "back_btn_bg",
            target.path + "/Image": "return",
            target.path + "/s": "back_btn_s1",
        }
        proven = set()
        for image in ui_state.images:
            sprite = expected.get(image.path)
            if sprite is None or image.sprite != sprite:
                continue
            if (
                not image.active_in_hierarchy
                or not image.active_and_enabled
                or not image.raycast_target
                or image.truncated
                or image.bounds is None
                or not image.bounds.contains(target.point)
            ):
                return False
            if image.path in proven:
                raise SemanticGateClosed("dorm back image is ambiguous")
            proven.add(image.path)
        return proven == set(expected)

    def _dorm_empty_food_cancel_proven(
        self, state: OracleState, ui_state: Optional[UiState] = None
    ) -> bool:
        matches = self._matches(state, "dorm/empty-food/cancel")
        if len(matches) > 1:
            raise SemanticGateClosed("dorm empty-food cancel target is ambiguous")
        if not matches:
            return False
        target = matches[0]
        if self._blocking_rules(state, "dorm/empty-food/cancel"):
            return False
        if (
            target.raycast_top is not None
            or not target.active_in_hierarchy
            or not target.active_and_enabled
            or not target.interactable
            or target.point is None
            or target.bounds is None
            or not target.bounds.contains(target.point)
        ):
            return False
        if ui_state is None:
            ui_state = self.read_ui_state()
        if (
            ui_state.image_truncated
            or ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("dorm empty-food snapshots are incomplete")
        root = target.path.rsplit("/frame/cancel_btn", 1)[0]
        expected = {
            target.path: "btn_yellow",
            root + "/frame/Image": "hungry",
            root + "/frame": "msg_bg",
        }
        proven = set()
        for image in ui_state.images:
            sprite = expected.get(image.path)
            if sprite is None or image.sprite != sprite:
                continue
            if (
                not image.active_in_hierarchy
                or not image.active_and_enabled
                or not image.raycast_target
                or image.truncated
                or image.bounds is None
            ):
                return False
            if image.path == target.path and not image.bounds.contains(target.point):
                return False
            if image.path in proven:
                raise SemanticGateClosed("dorm empty-food image is ambiguous")
            proven.add(image.path)
        return proven == set(expected)

    def dorm_empty_food_cancel_available(self) -> bool:
        state = self.read_state()
        return self._dorm_empty_food_cancel_proven(state)

    def _dorm_page_control_proven(
        self,
        state: OracleState,
        semantic_id: str,
        ui_state: Optional[UiState] = None,
    ) -> bool:
        if semantic_id not in ("dorm/feed", "dorm/collect"):
            raise ValueError("unsupported delegated dorm page control")
        matches = self._matches(state, semantic_id)
        if len(matches) > 1:
            raise SemanticGateClosed("dorm page control is ambiguous")
        if not matches:
            return False
        target = matches[0]
        if self._blocking_rules(state, semantic_id):
            return False
        if target.actionable:
            return True
        if (
            target.raycast_top is not False
            or not target.active_in_hierarchy
            or not target.active_and_enabled
            or not target.interactable
            or target.point is None
            or target.bounds is None
            or not target.bounds.contains(target.point)
        ):
            return False
        page_back = self._matches(state, "dorm/page/back")
        manage = self._matches(state, "dorm/page/manage")
        if (
            len(page_back) != 1
            or not page_back[0].active_in_hierarchy
            or len(manage) != 1
            or not manage[0].active_in_hierarchy
        ):
            return False
        if ui_state is None:
            ui_state = self.read_ui_state()
        if (
            ui_state.image_truncated
            or ui_state.snapshot.get("text_truncated") is not False
            or ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("dorm page-control snapshots are incomplete")

        feed_root = (
            target.path
            if semantic_id == "dorm/feed"
            else target.path.rsplit("/rightPanel/onekey", 1)[0]
            + "/bottomPanel/bottomleft/feed_btn"
        )
        labels = tuple(
            value
            for value in ui_state.texts
            if value.path in (feed_root + "/label", feed_root + "/Text")
            and value.active_in_hierarchy
            and value.active_and_enabled
            and not value.truncated
        )
        if len(labels) != 2:
            return False
        by_path = {value.path: value.text for value in labels}
        if (
            by_path.get(feed_root + "/label") != "食量"
            or re.fullmatch(r"[0-9]+/[1-9][0-9]*", by_path.get(feed_root + "/Text", ""))
            is None
        ):
            return False

        if semantic_id == "dorm/feed":
            expected_images = {
                target.path + "/icon": "btn_feed",
                target.path + "/bg": "btn_72",
            }
            images = tuple(
                image
                for image in ui_state.images
                if image.path in expected_images
                and image.sprite == expected_images[image.path]
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
                and target.bounds.contains(
                    Point(
                        (image.bounds.left + image.bounds.right) / 2.0,
                        (image.bounds.top + image.bounds.bottom) / 2.0,
                    )
                )
            )
            return len(images) == len(expected_images) and len(
                {image.path for image in images}
            ) == len(expected_images)

        images = tuple(
            image
            for image in ui_state.images
            if image.path == target.path
            and image.sprite == "onekey"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.raycast_target
            and not image.truncated
            and image.bounds is not None
            and image.bounds.contains(target.point)
        )
        if len(images) > 1:
            raise SemanticGateClosed("dorm collect image is ambiguous")
        return len(images) == 1

    def research_queue_state(self) -> ResearchQueueState:
        """Read all non-empty queue slots and the reviewed claim control."""

        return self._retry_transition_read(self._research_queue_state_once)

    def _research_queue_state_once(self) -> ResearchQueueState:
        """Read one coherent Research queue snapshot without relaxing gates."""

        button_state = self.read_state()
        back = self._unique(button_state, "research/page/back")
        ui_state = self.read_ui_state()
        queue_title = tuple(
            image
            for image in ui_state.images
            if image.path.endswith(
                "TechnologyUI(Clone)/blur_panel/adapt/top/title_queue"
            )
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
        )
        if (
            not back.actionable
            or len(queue_title) > 1
            or ui_state.image_truncated
            or ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("research queue identity is not proven")

        def optional_text(path: str) -> Optional[str]:
            matches = tuple(
                item
                for item in ui_state.texts
                if item.path.endswith(path)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(matches) > 1:
                raise SemanticGateClosed("research queue text is ambiguous: " + path)
            return matches[0].text.strip() if matches else None

        entries = []
        for slot in range(1, 6):
            root = "TechnologyUI(Clone)/main/queue_page/queue_rect/content/{0}/frame/".format(
                slot
            )
            code = optional_text(root + "name_bg/Text")
            marker = optional_text(root + "marks/Text")
            remain = optional_text(root + "marks/time")
            version_path = root + "top/label/version"
            versions = tuple(
                image
                for image in ui_state.images
                if image.path.endswith(version_path)
                and image.active_in_hierarchy
                and image.active_and_enabled
                and not image.truncated
                and image.bounds is not None
            )
            if code is None and marker is None and remain is None and not versions:
                continue
            if code is None or marker is None or remain is None or len(versions) != 1:
                raise SemanticGateClosed("research queue slot is incomplete")
            version = re.fullmatch(r"version_([1-9][0-9]*)", versions[0].sprite)
            if version is None or not code:
                raise SemanticGateClosed("research queue identity is malformed")
            entries.append(
                ResearchQueueEntryState(
                    slot=slot,
                    code=code,
                    series=int(version.group(1)),
                    status=self._research_status_from_text(marker),
                    remaining_seconds=self.parse_countdown_seconds(remain),
                )
            )
        if not queue_title and not entries:
            raise SemanticGateClosed("research queue has no typed identity anchor")
        claim_matches = self._matches(button_state, "research/queue/claim")
        if len(claim_matches) > 1:
            raise SemanticGateClosed("research queue claim target is ambiguous")
        claimable = bool(claim_matches and claim_matches[0].actionable)
        if claimable and not any(
            entry.status == ResearchProjectStatus.FINISHED for entry in entries
        ):
            raise SemanticGateClosed("research queue claim state is inconsistent")
        return ResearchQueueState(tuple(entries), claimable)

    def tactical_slots(self) -> Tuple[TacticalSlotState, ...]:
        """Read populated tactical-class slots from typed Unity controls."""

        button_state = self.read_state()
        page = self._unique(button_state, "tactical/page/back")
        if not page.active_in_hierarchy or not page.active_and_enabled:
            raise SemanticGateClosed("tactical page identity is not proven")

        prefix = "NewNavalTacticsUI(Clone)/adpter/NewNavalTacticsStudentsPage(Clone)/"
        raw_ship_buttons = tuple(
            button
            for button in button_state.buttons
            if re.fullmatch(r"[1-9][0-9]{5}", button.name) is not None
            and prefix in button.path
            and button.path.endswith("/" + button.name)
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.bounds is not None
            and button.bounds.right > 0
            and button.bounds.bottom > 0
            and button.bounds.left < self.fingerprint.width
            and button.bounds.top < self.fingerprint.height
        )
        slot_groups: Dict[Tuple[str, float, float, float, float], List[ButtonState]] = {}
        for button in raw_ship_buttons:
            assert button.bounds is not None
            bounds = button.bounds
            slot_key = (
                button.path.rsplit("/", 1)[0],
                bounds.left,
                bounds.top,
                bounds.right,
                bounds.bottom,
            )
            slot_groups.setdefault(slot_key, []).append(button)
        ship_buttons = []
        for candidates in slot_groups.values():
            # After a course confirmation, the live client can retain the
            # previous ship button on the current physical card while
            # publishing the current identity first.  One ``info(Clone)``
            # root can also host more than one independently positioned card.
            ship_buttons.append(candidates[0])
        if len(ship_buttons) > 4 or len(
            {button.name for button in ship_buttons}
        ) != len(ship_buttons):
            raise SemanticGateClosed("tactical slot identity is ambiguous")
        ship_buttons = tuple(
            sorted(ship_buttons, key=lambda button: button.bounds.left)
        )

        ui_state = self.read_ui_state()
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("tactical snapshots are not coherent")

        def text_in_slot(
            button: ButtonState, suffix: str, *, identity_scoped: bool
        ) -> str:
            assert button.bounds is not None
            slot_root = button.path.rsplit("/", 1)[0]
            path_root = button.path if identity_scoped else slot_root
            matches = tuple(
                text
                for text in ui_state.texts
                if text.path == path_root + suffix
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
                and button.bounds.left
                <= (text.bounds.left + text.bounds.right) / 2.0
                <= button.bounds.right
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "tactical slot text is absent or ambiguous: " + suffix
                )
            return matches[0].text.strip()

        slots = []
        for slot, button in enumerate(ship_buttons, start=1):
            ship_name = text_in_slot(
                button, "/content/info/name_mask/name", identity_scoped=True
            )
            ship_level_text = text_in_slot(
                button, "/content/dockyard/lv/Text", identity_scoped=True
            )
            skill_name = text_in_slot(
                button, "/skill/name_Text", identity_scoped=False
            )
            skill_level_text = text_in_slot(
                button, "/skill/level", identity_scoped=False
            )
            progress_text = text_in_slot(
                button, "/skill/next", identity_scoped=False
            )
            timer_text = text_in_slot(
                button, "/timer_Text", identity_scoped=False
            )
            progress = re.fullmatch(r"([0-9]+)/([1-9][0-9]*)", progress_text)
            if (
                not ship_name
                or not skill_name
                or re.fullmatch(r"[1-9][0-9]{0,2}", ship_level_text) is None
                or re.fullmatch(r"[1-9][0-9]?", skill_level_text) is None
                or progress is None
            ):
                raise SemanticGateClosed("tactical slot summary is malformed")
            exp_current, exp_total = map(int, progress.groups())
            if exp_current > exp_total:
                raise SemanticGateClosed("tactical skill progress is inconsistent")
            if timer_text:
                status = TacticalSlotStatus.RUNNING
                remaining_seconds: Optional[int] = self.parse_countdown_seconds(
                    timer_text
                )
            else:
                # On the reviewed page a populated slot retains its cancel
                # control and publishes an empty timer only after completion.
                cancel_buttons = tuple(
                    candidate
                    for candidate in button_state.buttons
                    if candidate.name == "cancel_btn"
                    and candidate.path.startswith(button.path.rsplit("/", 1)[0] + "/")
                    and candidate.active_in_hierarchy
                    and candidate.active_and_enabled
                    and candidate.bounds is not None
                    and button.bounds.left
                    <= (candidate.bounds.left + candidate.bounds.right) / 2.0
                    <= button.bounds.right
                )
                if len(cancel_buttons) != 1:
                    raise SemanticGateClosed(
                        "finished tactical slot marker is absent or ambiguous"
                    )
                status = TacticalSlotStatus.FINISHED
                remaining_seconds = None
            slots.append(
                TacticalSlotState(
                    slot=slot,
                    ship_id=int(button.name),
                    ship_name=ship_name,
                    ship_level=int(ship_level_text),
                    skill_name=skill_name,
                    skill_level=int(skill_level_text),
                    exp_current=exp_current,
                    exp_total=exp_total,
                    status=status,
                    remaining_seconds=remaining_seconds,
                    button=button,
                )
            )
        return tuple(slots)

    def tactical_remaining_seconds(self) -> Tuple[int, ...]:
        return tuple(
            slot.remaining_seconds
            for slot in self.tactical_slots()
            if slot.status == TacticalSlotStatus.RUNNING
            and slot.remaining_seconds is not None
        )

    def _mapping(self, semantic_id: str) -> SemanticTarget:
        try:
            return self._targets[semantic_id]
        except KeyError as exc:
            raise SemanticGateClosed(
                "semantic target is not mapped: {0}".format(semantic_id)
            ) from exc

    def _image_mapping(self, semantic_id: str) -> SemanticImageTarget:
        try:
            return self._image_targets[semantic_id]
        except KeyError as exc:
            raise SemanticGateClosed(
                "semantic image target is not mapped: {0}".format(semantic_id)
            ) from exc

    def _toggle_mapping(self, semantic_id: str) -> SemanticToggleTarget:
        try:
            return self._toggle_targets[semantic_id]
        except KeyError as exc:
            raise SemanticGateClosed(
                "semantic toggle target is not mapped: {0}".format(semantic_id)
            ) from exc

    def _toggle_matches(
        self, state: UiState, semantic_id: str
    ) -> Tuple[ToggleState, ...]:
        target = self._toggle_mapping(semantic_id)
        suffixes = (
            target.path_suffix
            if isinstance(target.path_suffix, tuple)
            else (target.path_suffix,)
        )
        candidates = tuple(
            toggle
            for toggle in state.toggles
            if toggle.name == target.name
            and toggle.path.endswith(suffixes)
        )
        if target.expected_child_sprite is None:
            return candidates

        matching = []
        for toggle in candidates:
            if toggle.bounds is None:
                continue
            child_images = tuple(
                image
                for image in state.images
                if not image.truncated
                and image.active_in_hierarchy
                and image.active_and_enabled
                and image.bounds is not None
                and image.sprite == target.expected_child_sprite
                and image.path.startswith(toggle.path + "/")
                and toggle.bounds.contains(
                    Point(
                        (image.bounds.left + image.bounds.right) / 2.0,
                        (image.bounds.top + image.bounds.bottom) / 2.0,
                    )
                )
            )
            if len(child_images) == 1:
                matching.append(toggle)
            elif len(child_images) > 1:
                raise SemanticGateClosed(
                    "semantic toggle child sprite is ambiguous: {0}".format(semantic_id)
                )
        return tuple(matching)

    def toggle_state(self, semantic_id: str) -> ToggleState:
        state = self.read_ui_state()
        if state.method_mask & 0x1 == 0:
            raise SemanticGateClosed("typed Unity Toggle snapshot is incomplete")
        matches = self._toggle_matches(state, semantic_id)
        if len(matches) != 1:
            raise SemanticGateClosed(
                "semantic toggle target is absent or ambiguous: {0}".format(semantic_id)
            )
        return matches[0]

    def toggle_selected(self, semantic_id: str) -> bool:
        return self.toggle_state(semantic_id).checked

    def toggle_present(self, semantic_id: str) -> bool:
        """Return whether one exact typed Toggle exists on the current UI."""

        state = self.read_ui_state()
        matches = self._toggle_matches(state, semantic_id)
        if len(matches) > 1:
            raise SemanticGateClosed(
                "semantic toggle target is ambiguous: {0}".format(semantic_id)
            )
        return bool(matches)

    def campaign_auto_search_selected(self) -> bool:
        """Return the effective auto-search state on campaign preparation."""

        state = self.read_ui_state()
        if state.method_mask & 0x1 == 0:
            raise SemanticGateClosed("typed Unity Toggle snapshot is incomplete")
        matches = self._toggle_matches(state, "campaign/map-preparation/auto-search")
        if len(matches) != 1:
            raise SemanticGateClosed(
                "campaign auto-search toggle is absent or ambiguous"
            )
        toggle = matches[0]
        auto_suffixes = {
            "LevelInfoSPUI(Clone)/panel/BottomExtra/LoopGroup/"
            "view/container/AutoFight": (
                "LevelInfoSPUI(Clone)/panel/BottomExtra/LoopGroup/Loop/Toggle/off"
            ),
            "LevelStageInfoView(Clone)/panel/BottomExtra/LoopGroup/"
            "view/container/AutoFight": (
                "LevelStageInfoView(Clone)/panel/BottomExtra/LoopGroup/Loop/"
                "Toggle/off"
            ),
        }
        loop_off_suffix = next(
            (
                off_suffix
                for auto_suffix, off_suffix in auto_suffixes.items()
                if toggle.path.endswith(auto_suffix)
            ),
            None,
        )
        if loop_off_suffix is not None:
            loop_off = tuple(
                image
                for image in state.images
                if image.name == "off"
                and image.path.endswith(loop_off_suffix)
                and image.sprite == "live2d_off"
                and image.active_in_hierarchy
                and image.active_and_enabled
                and image.bounds is not None
            )
            if len(loop_off) > 1:
                raise SemanticGateClosed("campaign loop-off identity is ambiguous")
            if loop_off:
                # Both stage-info variants retain the saved AutoFight Toggle
                # value while loop mode is off.  The nested toggle is not an
                # effective or mutable state until the outer mode is enabled.
                return False
        return toggle.checked

    def _campaign_event_auto_delegated_raycast_proven(
        self,
        button_state: OracleState,
        ui_state: UiState,
        toggle: ToggleState,
    ) -> bool:
        """Prove the SP preparation AutoFight delegated-image control."""

        event_root = "LevelInfoSPUI(Clone)/panel/BottomExtra/LoopGroup/"
        if (
            not toggle.path.endswith(event_root + "view/container/AutoFight")
            or toggle.raycast_top is not None
            or not toggle.active_in_hierarchy
            or not toggle.active_and_enabled
            or not toggle.interactable
            or toggle.point is None
            or toggle.bounds is None
            or not toggle.bounds.contains(toggle.point)
        ):
            return False
        page_markers = tuple(
            button
            for button in button_state.buttons
            if button.name == "start_button"
            and button.path.endswith("LevelInfoSPUI(Clone)/panel/start_button")
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
        )
        loop_controls = tuple(
            button
            for button in button_state.buttons
            if button.name == "Toggle"
            and button.path.endswith(event_root + "Loop/Toggle")
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.raycast_top is None
            and button.bounds is not None
        )
        loop_on = tuple(
            image
            for image in ui_state.images
            if image.name == "on"
            and image.path.endswith(event_root + "Loop/Toggle/on")
            and image.sprite == "live2d_on"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.bounds is not None
        )
        loop_off = tuple(
            image
            for image in ui_state.images
            if image.name == "off"
            and image.path.endswith(event_root + "Loop/Toggle/off")
            and image.active_in_hierarchy
            and image.active_and_enabled
        )
        delegated_images = tuple(
            image
            for image in ui_state.images
            if image.name == "AutoFight"
            and image.path == toggle.path
            and image.sprite == "white_dot"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.raycast_target
            and image.raycast_top is None
            and image.bounds is not None
            and image.bounds.contains(toggle.point)
        )
        return bool(
            len(page_markers) == 1
            and len(loop_controls) == 1
            and len(loop_on) == 1
            and not loop_off
            and len(delegated_images) == 1
        )

    def _build_pool_delegated_raycast_proven(
        self,
        button_state: OracleState,
        ui_state: UiState,
        semantic_id: str,
    ) -> bool:
        expected_sprites = {
            "build/pool/event": "activity_unsel",
            "build/pool/light": "light_unsel",
            "build/pool/heavy": "heavy_unsel",
            "build/pool/special": "spec_unsel",
        }
        expected_sprite = expected_sprites.get(semantic_id)
        if expected_sprite is None:
            return False
        matches = self._toggle_matches(ui_state, semantic_id)
        if len(matches) > 1:
            raise SemanticGateClosed("construction pool Toggle is ambiguous")
        if not matches:
            return False
        toggle = matches[0]
        if (
            toggle.checked
            or toggle.raycast_top is not None
            or not toggle.active_in_hierarchy
            or not toggle.active_and_enabled
            or not toggle.interactable
            or toggle.point is None
            or toggle.bounds is None
            or not toggle.bounds.contains(toggle.point)
            or self._blocking_rules(button_state, semantic_id)
        ):
            return False

        # The live 9.7.10 construction-pool Toggle delegates its raycast to
        # the same-path Image.  The observer consequently reports no top
        # result on either component.  Admit only an unchecked, exact pool
        # Toggle with its exact unselected sprite while the pool start Button
        # proves the surrounding page.
        page_markers = tuple(
            button
            for button in button_state.buttons
            if button.name == "start_btn"
            and button.path.endswith(
                "BuildShipUI(Clone)/BuildShipPoolsPageUI(Clone)/gallery/start_btn"
            )
            and button.active_in_hierarchy
            and button.active_and_enabled
        )
        if len(page_markers) != 1:
            return False
        images = tuple(
            image
            for image in ui_state.images
            if image.path == toggle.path
            and image.name == "frame"
            and image.sprite == expected_sprite
            and image.active_in_hierarchy
            and image.active_and_enabled
            and image.raycast_target
            and image.raycast_top is None
            and not image.truncated
            and image.bounds is not None
            and image.bounds.contains(toggle.point)
        )
        if len(images) > 1:
            raise SemanticGateClosed("construction pool Image is ambiguous")
        return len(images) == 1

    def click_toggle(self, semantic_id: str) -> ActionReceipt:
        button_state: Optional[OracleState] = None
        ui_state: Optional[UiState] = None
        for attempt in range(8):
            candidate_buttons = self.read_state()
            candidate_ui = self.read_ui_state()
            if candidate_ui.method_mask & 0x1 == 0:
                raise SemanticGateClosed("typed Unity Toggle snapshot is incomplete")
            if (
                candidate_ui.generation >= candidate_buttons.generation
                and candidate_ui.generation <= candidate_buttons.generation + 2
            ):
                button_state = candidate_buttons
                ui_state = candidate_ui
                break
            if attempt < 7:
                self._sleep(0.05)
        if button_state is None or ui_state is None:
            raise SemanticGateClosed("button and toggle snapshots are not coherent")
        matches = self._toggle_matches(ui_state, semantic_id)
        delegated_build_pool = self._build_pool_delegated_raycast_proven(
            button_state, ui_state, semantic_id
        )
        delegated_guild_nav = self._guild_nav_delegated_raycast_proven(
            button_state,
            ui_state,
            semantic_id,
            matches,
        )
        delegated_campaign_auto = False
        delegated_campaign_event_auto = False
        if semantic_id == "campaign/map-preparation/auto-search" and len(matches) == 1:
            toggle = matches[0]
            standard_toggle_suffix = (
                "LevelStageInfoView(Clone)/panel/BottomExtra/LoopGroup/Loop/Toggle"
            )
            delegated_campaign_auto = any(
                button.name == "Toggle"
                and button.path.endswith(standard_toggle_suffix)
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.bounds is not None
                and button.bounds.contains(toggle.point)
                for button in button_state.buttons
            )
            delegated_campaign_event_auto = (
                self._campaign_event_auto_delegated_raycast_proven(
                    button_state,
                    ui_state,
                    toggle,
                )
            )
        strategic_toggle_ids = {
            "os/strategic-search/tab/secured",
            "os/strategic-search/zone-mode/repeat",
            "os/strategic-search/merchant/stop",
            "os/strategic-search/device/stop",
            "os/strategic-search/auto-submit/on",
        }
        strategic_page_buttons = tuple(
            button
            for button in button_state.buttons
            if button.path.endswith(
                (
                "OverlayCamera/Overlay/UIMain/WorldSwitchPlanningUI(Clone)/"
                "window/button_container/custom_button_1",
                "OverlayCamera/Overlay/UIMain/WorldSwitchPlanningUI(Clone)/"
                "window/button_container/custom_button_2",
                )
            )
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
        )
        delegated_operation_siren_strategic = bool(
            semantic_id in strategic_toggle_ids
            and len(matches) == 1
            and len(strategic_page_buttons) == 2
            and matches[0].active_in_hierarchy
            and matches[0].active_and_enabled
            and matches[0].interactable
            and matches[0].raycast_top is None
            and matches[0].point is not None
            and matches[0].bounds is not None
            and matches[0].bounds.contains(matches[0].point)
        )
        delegated_shop_nav = False
        if semantic_id == "shop/gift-pack" and len(matches) == 1:
            toggle = matches[0]
            delegated_shop_nav = bool(
                self._recommendation_shop_visible_from_states(
                    button_state, ui_state
                )
                and not toggle.checked
                and toggle.active_in_hierarchy
                and toggle.active_and_enabled
                and toggle.interactable
                and toggle.raycast_top is None
                and toggle.point is not None
                and toggle.bounds is not None
                and toggle.bounds.contains(toggle.point)
            )
        if len(matches) != 1 or (
            not matches[0].actionable
            and not delegated_build_pool
            and not delegated_campaign_auto
            and not delegated_campaign_event_auto
            and not delegated_operation_siren_strategic
            and not delegated_shop_nav
            and not delegated_guild_nav
        ):
            raise SemanticGateClosed("semantic toggle target is not actionable")
        toggle = matches[0]
        if self._blocking_rules(button_state, semantic_id):
            raise SemanticGateClosed("semantic toggle action is blocked")
        assert toggle.point is not None
        assert toggle.bounds is not None
        input_point = toggle.point
        if delegated_campaign_auto:
            controls = tuple(
                button
                for button in button_state.buttons
                if button.name == "Toggle"
                and button.path.endswith(
                    "LevelStageInfoView(Clone)/panel/BottomExtra/LoopGroup/Loop/Toggle"
                )
                and button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.bounds is not None
                and button.bounds.contains(toggle.point)
            )
            if len(controls) != 1:
                raise SemanticGateClosed("campaign auto-search control is ambiguous")
            bounds = controls[0].bounds
            assert bounds is not None
            input_point = Point(
                x=(bounds.left + bounds.right) / 2.0,
                y=(bounds.top + bounds.bottom) / 2.0,
            )
        if not (
            0 <= input_point.x < self.fingerprint.width
            and 0 <= input_point.y < self.fingerprint.height
        ):
            raise SemanticGateClosed("semantic toggle target point is invalid")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before toggle input")
        self._tap(int(round(input_point.x)), int(round(input_point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed after toggle input")
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=ui_state.generation,
            point=input_point,
            bounds=toggle.bounds,
            path=toggle.path,
        )

    def _image_matches(
        self,
        state: UiState,
        semantic_id: str,
    ) -> Tuple[ImageState, ...]:
        target = self._image_mapping(semantic_id)
        direct_suffix = target.path_parent_suffix + "/Image"
        selected_suffix = target.path_parent_suffix + "/selected/Image"
        allowed_sprites = (target.selected_sprite, target.inactive_sprite)
        return tuple(
            image
            for image in state.images
            if image.name == "Image"
            and (
                image.path.endswith(direct_suffix)
                or image.path.endswith(selected_suffix)
            )
            and image.sprite in allowed_sprites
        )

    def image_state(self, semantic_id: str) -> ImageState:
        return self._retry_transition_read(lambda: self._image_state_once(semantic_id))

    def _image_state_once(self, semantic_id: str) -> ImageState:
        state = self.read_ui_state()
        if state.image_truncated or state.method_mask & 0x8 == 0:
            raise SemanticGateClosed("typed Unity Image snapshot is incomplete")
        matches = self._image_matches(state, semantic_id)
        if len(matches) != 1:
            raise SemanticGateClosed(
                "semantic image target is absent or ambiguous: {0}".format(semantic_id)
            )
        if matches[0].truncated:
            raise SemanticGateClosed("semantic image target identity is truncated")
        return matches[0]

    def image_selected(self, semantic_id: str) -> bool:
        target = self._image_mapping(semantic_id)
        image = self.image_state(semantic_id)
        if image.sprite == target.selected_sprite:
            return True
        if image.sprite == target.inactive_sprite:
            return False
        raise SemanticGateClosed("semantic image target sprite is unexpected")

    def click_image(self, semantic_id: str) -> ActionReceipt:
        button_state = self.read_state()
        ui_state = self.read_ui_state()
        if ui_state.image_truncated or ui_state.method_mask & 0x8 == 0:
            raise SemanticGateClosed("typed Unity Image snapshot is incomplete")
        if (
            ui_state.generation < button_state.generation
            or ui_state.generation > button_state.generation + 2
        ):
            raise SemanticGateClosed("button and image snapshots are not coherent")
        matches = self._image_matches(ui_state, semantic_id)
        if len(matches) != 1:
            raise SemanticGateClosed("semantic image target is absent or ambiguous")
        image = matches[0]
        if (
            image.truncated
            or not image.active_in_hierarchy
            or not image.active_and_enabled
            or not image.raycast_target
            or image.raycast_top is not True
            or image.bounds is None
        ):
            raise SemanticGateClosed("semantic image target is not actionable")
        if semantic_id.startswith("task/nav/"):
            page_semantic_id = "task/page/back"
            page_name = "mission"
        elif semantic_id.startswith("commission/nav/"):
            page_semantic_id = "commission/page/back"
            page_name = "commission"
        else:
            raise SemanticGateClosed("semantic image action has no page identity")
        page_back = self._unique(button_state, page_semantic_id)
        if not page_back.actionable or self._blocking_rules(button_state, semantic_id):
            raise SemanticGateClosed(page_name + " page image action is blocked")
        point = Point(
            (image.bounds.left + image.bounds.right) / 2.0,
            (image.bounds.top + image.bounds.bottom) / 2.0,
        )
        if not image.bounds.contains(point) or not (
            0 <= point.x < self.fingerprint.width
            and 0 <= point.y < self.fingerprint.height
        ):
            raise SemanticGateClosed("semantic image target center is invalid")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before image input")
        self._tap(int(round(point.x)), int(round(point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed after image input")
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=ui_state.generation,
            point=point,
            bounds=image.bounds,
            path=image.path,
        )

    def _retirement_records(self) -> Tuple[OracleState, UiState]:
        """Read a coherent retirement slice while tolerating unrelated caps.

        The dock cards can exhaust the global Toggle/Image observer caps.  The
        retirement parsers therefore require every exact dialog record they use
        instead of pretending the unrelated dock-card tail is complete.
        """

        last_error: Optional[SemanticOracleError] = None
        for attempt in range(8):
            try:
                button_state = self.read_state()
                if self._foreground_component() != self.fingerprint.component:
                    raise SemanticGateClosed("game activity is not top-resumed")
                raw = self._request("GET /v1/ui\n")
                if not isinstance(raw, dict):
                    raise ObserverTransportError(
                        "UI observer response is not a mapping"
                    )
                self._validate_identity(raw, UI_SCHEMA)
                if raw.get("schema") != 1:
                    raise SemanticGateClosed("UI snapshot schema mismatch")
                if raw.get("text_truncated") is not False:
                    raise SemanticGateClosed("retirement text snapshot is truncated")
                if self._integer(raw.get("error_count"), "UI error_count") != 0:
                    raise SemanticGateClosed("UI snapshot contains extraction errors")
                raw_toggles = raw.get("toggles")
                raw_texts = raw.get("texts")
                raw_images = raw.get("images")
                if not all(
                    isinstance(value, list)
                    for value in (raw_toggles, raw_texts, raw_images)
                ):
                    raise SemanticGateClosed("UI record lists are malformed")
                assert isinstance(raw_toggles, list)
                assert isinstance(raw_texts, list)
                assert isinstance(raw_images, list)
                for field, records in (
                    ("toggle_count", raw_toggles),
                    ("text_count", raw_texts),
                    ("image_count", raw_images),
                ):
                    if self._integer(raw.get(field), field) != len(records):
                        raise SemanticGateClosed("UI record count is inconsistent")
                method_mask = self._integer(raw.get("method_mask"), "UI method_mask")
                if method_mask & 0x6 == 0:
                    raise SemanticGateClosed(
                        "typed Unity text accessors are unavailable"
                    )
                generation = self._integer(raw.get("generation"), "UI generation")
                if not (
                    button_state.generation <= generation <= button_state.generation + 2
                ):
                    raise SemanticGateClosed(
                        "retirement button and UI snapshots are not coherent"
                    )
                if (
                    self._last_generation is not None
                    and generation < self._last_generation
                ):
                    raise SemanticGateClosed("observer generation moved backwards")
                self._last_generation = generation
                skipped_count = self._integer(
                    raw.get("skipped_count"), "UI skipped_count"
                )
                if skipped_count < 0:
                    raise SemanticGateClosed("UI skipped_count is negative")
                return button_state, UiState(
                    generation=generation,
                    method_mask=method_mask,
                    skipped_count=skipped_count,
                    image_truncated=bool(raw.get("image_truncated")),
                    snapshot=raw,
                    toggles=tuple(self._parse_toggle(item) for item in raw_toggles),
                    texts=tuple(self._parse_text(item) for item in raw_texts),
                    images=tuple(self._parse_image(item) for item in raw_images),
                )
            except SemanticOracleError as exc:
                last_error = exc
                if attempt < 7:
                    self._sleep(0.05)
        raise SemanticGateClosed(
            "retirement snapshots did not stabilize"
        ) from last_error

    def _enhancement_dock_records(self) -> Tuple[OracleState, UiState]:
        """Read a coherent Dock page before enhancement navigation."""

        last_error: Optional[SemanticGateClosed] = None
        capacity_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/capacity/Text"
        )
        label_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/capacity/label"
        )
        filter_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/index_button"
        )
        for attempt in range(8):
            state, ui_state = self._retirement_records()
            capacity = tuple(
                item
                for item in ui_state.texts
                if item.path == capacity_path
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and re.fullmatch(r"[0-9]+/[0-9]+", item.text)
            )
            label = tuple(
                item
                for item in ui_state.texts
                if item.path == label_path
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.text == "船坞容量:"
            )
            filter_buttons = tuple(
                item
                for item in state.buttons
                if item.path == filter_path
                and item.name == "index_button"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
                and item.point is not None
                and item.bounds is not None
                and item.bounds.contains(item.point)
            )
            filter_images = tuple(
                item
                for item in ui_state.images
                if item.path == filter_path
                and item.sprite in ("shaixuan_on", "shaixuan_off")
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.bounds is not None
            )
            if (
                state.generation <= ui_state.generation <= state.generation + 2
                and ui_state.method_mask & 0xF == 0xF
                and len(capacity) == len(label) == len(filter_buttons) == 1
                and len(filter_images) == 1
                and filter_images[0].bounds.contains(filter_buttons[0].point)
            ):
                return state, ui_state
            last_error = SemanticGateClosed("enhancement Dock identity is incomplete")
            if attempt < 7:
                self._sleep(0.05)
        raise SemanticGateClosed("enhancement Dock snapshots did not stabilize") from last_error

    def _click_exact_image(
        self,
        state: OracleState,
        image: ImageState,
        semantic_id: str,
    ) -> ActionReceipt:
        """Tap one exact image-only control after the common input gates."""

        if (
            not image.active_in_hierarchy
            or not image.active_and_enabled
            or not image.raycast_target
            or image.truncated
            or image.bounds is None
        ):
            raise SemanticGateClosed(semantic_id + " is not safely actionable")
        point = Point(
            (image.bounds.left + image.bounds.right) / 2.0,
            (image.bounds.top + image.bounds.bottom) / 2.0,
        )
        if not image.bounds.contains(point) or self._blocking_rules(state, semantic_id):
            raise SemanticGateClosed(semantic_id + " input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before Dock input")
        self._tap(int(round(point.x)), int(round(point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed after Dock input")
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=state.generation,
            point=point,
            bounds=image.bounds,
            path=image.path,
        )

    @staticmethod
    def _enhancement_filter_option(
        ui_state: UiState,
        group: str,
        option: str,
        label: str,
    ) -> ImageState:
        root = (
            "OverlayCamera/Overlay/UIMain/CustomIndexUI(Clone)/index_panel/"
            "layout/container/indexsort_{0}/bg/{1}"
        ).format(group, option)
        images = tuple(
            item
            for item in ui_state.images
            if item.path == root
            and item.sprite in ("btn_index_grey", "btn_index_blue", "btn_index_yellow")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        texts = tuple(
            item
            for item in ui_state.texts
            if item.path == root + "/Image"
            and item.text == label
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(images) != 1 or len(texts) != 1:
            raise SemanticGateClosed("enhancement Dock filter option is incomplete")
        return images[0]

    def _wait_enhancement_filter_option(
        self,
        group: str,
        option: str,
        label: str,
    ) -> Tuple[OracleState, UiState, ImageState]:
        last_error: Optional[SemanticGateClosed] = None
        for attempt in range(30):
            try:
                state, ui_state = self._retirement_records()
                return (
                    state,
                    ui_state,
                    self._enhancement_filter_option(
                        ui_state, group, option, label
                    ),
                )
            except SemanticGateClosed as exc:
                last_error = exc
                if attempt < 29:
                    self._sleep(0.05)
        raise SemanticGateClosed(
            "enhancement Dock filter option did not stabilize"
        ) from last_error

    def set_awaken_dock_filter(
        self, use_array: bool
    ) -> Tuple[ActionReceipt, ...]:
        """Select the official cognitive-awakening Dock filter."""

        if not isinstance(use_array, bool):
            raise TypeError("awaken use_array must be boolean")
        state, ui_state = self._enhancement_dock_records()
        opener = next(
            item
            for item in ui_state.images
            if item.path.endswith("/adapt/top/index_button")
        )
        receipts = [
            self._click_exact_image(state, opener, "awaken/dock/filter/open")
        ]
        self._sleep(0.1)
        extra_option = "7" if use_array else "6"
        extra_label = (
            "<size=36>可认知觉醒</size><size=30>II</size>"
            if use_array
            else "<size=36>可认知觉醒</size>"
        )
        choices = (
            ("sort", "1", "等级", "btn_index_yellow"),
            ("index", "tpl", "全部", "btn_index_blue"),
            ("camp", "tpl", "全阵营", "btn_index_blue"),
            ("rarity", "tpl", "全部", "btn_index_blue"),
            ("extraindex", extra_option, extra_label, "btn_index_blue"),
        )
        for group, option, label, selected_sprite in choices:
            state, _, image = self._wait_enhancement_filter_option(
                group, option, label
            )
            if image.sprite == selected_sprite:
                continue
            if image.sprite != "btn_index_grey":
                raise SemanticGateClosed("awaken Dock filter state is unknown")
            receipts.append(
                self._click_exact_image(
                    state,
                    image,
                    "awaken/dock/filter/{0}/{1}".format(group, option),
                )
            )
            for _ in range(30):
                self._sleep(0.05)
                _, _, verified = self._wait_enhancement_filter_option(
                    group, option, label
                )
                if verified.sprite == selected_sprite:
                    break
                if verified.sprite != "btn_index_grey":
                    raise SemanticGateClosed(
                        "awaken Dock filter selection became unknown"
                    )
            else:
                raise SemanticGateClosed("awaken Dock filter option did not select")
        state, ui_state = self._retirement_records()
        confirm_path = (
            "OverlayCamera/Overlay/UIMain/CustomIndexUI(Clone)/index_panel/"
            "layout/btns/ok"
        )
        confirm = tuple(
            item
            for item in ui_state.images
            if item.path == confirm_path
            and item.sprite == "btn_big_blue"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        confirm_text = tuple(
            item
            for item in ui_state.texts
            if item.path == confirm_path + "/Image"
            and item.text == "确 定"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(confirm) != 1 or len(confirm_text) != 1:
            raise SemanticGateClosed("awaken Dock filter confirm is incomplete")
        receipts.append(
            self._click_exact_image(
                state, confirm[0], "awaken/dock/filter/confirm"
            )
        )
        empty_reads = 0
        expected_levels = {120} if use_array else {100, 105, 110, 115}
        for _ in range(80):
            self._sleep(0.1)
            candidates = self.awaken_dock_candidates()
            if candidates and all(
                item.level in expected_levels for item in candidates
            ):
                break
            if not candidates:
                empty_reads += 1
                if empty_reads >= 20:
                    break
            else:
                empty_reads = 0
        else:
            raise SemanticGateClosed(
                "awaken Dock filter results did not match the requested mode"
            )
        return tuple(receipts)

    def awaken_dock_candidates(self) -> Tuple[EnhancementDockCandidate, ...]:
        """Return exact visible cards admitted by the active Awaken filter."""

        return self.enhancement_dock_candidates()

    @staticmethod
    def _awaken_text(
        ui_state: UiState,
        suffix: str,
        *,
        pattern: Optional[str] = None,
        exact: Optional[str] = None,
    ) -> TextState:
        matches = tuple(
            item
            for item in ui_state.texts
            if item.path.endswith(suffix)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and (exact is None or item.text == exact)
            and (pattern is None or re.fullmatch(pattern, item.text) is not None)
        )
        if len(matches) != 1:
            raise SemanticGateClosed("awaken text identity is incomplete")
        return matches[0]

    def _awaken_detail_state(
        self,
        ship_id: int,
        ship_name: str,
        *,
        expected_level: Optional[int] = None,
        require_entry: bool = True,
    ) -> AwakenDetailState:
        state = self.read_state()
        ui_state = self.read_ui_state()
        if not state.generation <= ui_state.generation <= state.generation + 2:
            raise SemanticGateClosed("awaken detail snapshots are not coherent")
        name = self._awaken_text(
            ui_state,
            "/blur_panel/adapt/name/nameRect/name_mask/Text",
        )
        compact_name = ship_name.strip()
        if compact_name.endswith(".."):
            name_matches = name.text.startswith(compact_name[:-2])
        elif compact_name.endswith("…"):
            name_matches = name.text.startswith(compact_name[:-1])
        else:
            name_matches = name.text == compact_name
        if not name_matches:
            raise SemanticGateClosed("awaken detail ship identity changed")
        level_text = self._awaken_text(
            ui_state,
            "/ShipDetailView(Clone)/attrs/attrs/property/level_bg/level_label/Text",
            pattern=r"[1-9][0-9]{1,2}",
        )
        level = int(level_text.text)
        if expected_level is not None and level != expected_level:
            raise SemanticGateClosed("awaken detail level changed")
        exp = self._awaken_text(
            ui_state,
            "/ShipDetailView(Clone)/attrs/attrs/property/level_bg/exp_info",
            pattern=r"[0-9]+/(?:Max|[0-9]+)",
        )
        tip_path = (
            "/ShipDetailView(Clone)/attrs/attrs/property/level_bg/tip"
        )
        tips = tuple(
            item
            for item in ui_state.images
            if item.path.endswith(tip_path)
            and item.sprite == "renzhijuexing_icon"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
            and item.color[3] > 0.2
        )
        if require_entry and len(tips) != 1:
            raise SemanticGateClosed("awaken detail entry is incomplete")
        return AwakenDetailState(
            generation=max(state.generation, ui_state.generation),
            ship_id=ship_id,
            ship_name=name.text,
            level=level,
            exp_maxed=exp.text.endswith("/Max"),
            use_array=level >= 120,
        )

    def _close_awaken_help_if_present(self) -> Optional[ActionReceipt]:
        last_error: Optional[SemanticGateClosed] = None
        for attempt in range(30):
            state = self.read_state()
            try:
                ui_state = self.read_ui_state()
                break
            except SemanticGateClosed as exc:
                last_error = exc
                if attempt < 29:
                    self._sleep(0.05)
        else:
            raise SemanticGateClosed(
                "awaken detail UI did not stabilize after Dock entry"
            ) from last_error
        help_images = tuple(
            item
            for item in ui_state.images
            if item.path.endswith("/Msgbox(Clone)/window/help_panel/list/help_tpl(Clone)/icon")
            and item.sprite == "maxlevel"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if not help_images:
            return None
        backgrounds = tuple(
            item
            for item in state.buttons
            if item.path.endswith("/Msgbox(Clone)/bg")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.bounds is not None
        )
        if len(help_images) != 1 or len(backgrounds) != 1:
            raise SemanticGateClosed("awaken help overlay is ambiguous")
        background = backgrounds[0]
        assert background.bounds is not None
        point = Point(
            background.bounds.left + 100.0,
            (background.bounds.top + background.bounds.bottom) / 2.0,
        )
        if not background.bounds.contains(point):
            raise SemanticGateClosed("awaken help close point is invalid")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before awaken help close")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="awaken/help/close",
            generation=state.generation,
            point=point,
            bounds=background.bounds,
            path=background.path,
        )

    def open_awaken_dock_candidate(
        self,
        position: int,
        ship_id: int,
        ship_name: str,
        level: int,
    ) -> Tuple[AwakenDetailState, Tuple[ActionReceipt, ...]]:
        """Open one stable Awaken Dock card and prove its detail identity."""

        candidates = self.awaken_dock_candidates()
        matches = tuple(
            item
            for item in candidates
            if item.position == position
            and item.ship_id == ship_id
            and item.ship_name == ship_name
            and item.level == level
        )
        if len(matches) != 1:
            raise SemanticGateClosed("awaken Dock candidate changed")
        target = matches[0].button
        assert target.point is not None and target.bounds is not None
        state = self.read_state()
        if self._blocking_rules(state, "awaken/dock/ship"):
            raise SemanticGateClosed("awaken Dock candidate input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before awaken ship input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        receipts = [
            ActionReceipt(
                semantic_id="awaken/dock/ship/{0}".format(ship_id),
                generation=state.generation,
                point=target.point,
                bounds=target.bounds,
                path=target.path,
            )
        ]
        self._sleep(0.5)
        help_receipt = self._close_awaken_help_if_present()
        if help_receipt is not None:
            receipts.append(help_receipt)
            self._sleep(0.5)
        detail = self._retry_transition_read(
            lambda: self._awaken_detail_state(
                ship_id, ship_name, expected_level=level
            ),
            attempts=40,
            interval_seconds=0.1,
        )
        return detail, tuple(receipts)

    def open_awaken_confirmation(
        self, detail: AwakenDetailState
    ) -> Tuple[AwakenCostState, ActionReceipt]:
        """Open and parse the official modal without committing resources."""

        if not isinstance(detail, AwakenDetailState):
            raise TypeError("awaken detail state is not typed")
        verified = self._awaken_detail_state(
            detail.ship_id,
            detail.ship_name,
            expected_level=detail.level,
        )
        state = self.read_state()
        ui_state = self.read_ui_state()
        tip_path = "/ShipDetailView(Clone)/attrs/attrs/property/level_bg/tip"
        tips = tuple(
            item
            for item in ui_state.images
            if item.path.endswith(tip_path)
            and item.sprite == "renzhijuexing_icon"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.bounds is not None
            and item.color[3] > 0.2
        )
        parents = tuple(
            item
            for item in state.buttons
            if item.path.endswith(
                "/ShipDetailView(Clone)/attrs/attrs/property/level_bg"
            )
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.bounds is not None
        )
        if len(tips) != 1 or len(parents) != 1:
            raise SemanticGateClosed("awaken entry target is incomplete")
        tip = tips[0]
        parent = parents[0]
        assert tip.bounds is not None and parent.bounds is not None
        point = Point(
            (tip.bounds.left + tip.bounds.right) / 2.0,
            (tip.bounds.top + tip.bounds.bottom) / 2.0,
        )
        if not parent.bounds.contains(point):
            raise SemanticGateClosed("awaken entry point escaped its parent")
        if self._blocking_rules(state, "awaken/detail/open"):
            raise SemanticGateClosed("awaken detail input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before awaken entry")
        self._tap(int(round(point.x)), int(round(point.y)))
        receipt = ActionReceipt(
            semantic_id="awaken/detail/open",
            generation=verified.generation,
            point=point,
            bounds=tip.bounds,
            path=tip.path,
        )
        cost = self._retry_transition_read(
            lambda: self.awaken_cost_state(
                detail.ship_id, detail.ship_name
            ),
            attempts=40,
            interval_seconds=0.1,
        )
        if cost.current_level != detail.level or cost.use_array != detail.use_array:
            raise SemanticGateClosed("awaken modal changed the requested mode")
        return cost, receipt

    def awaken_cost_state(self, ship_id: int, ship_name: str) -> AwakenCostState:
        """Read exact currencies and level transition from the open modal."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        if not state.generation <= ui_state.generation <= state.generation + 2:
            raise SemanticGateClosed("awaken modal snapshots are not coherent")
        root = "OverlayCamera/Overlay/UIMain/ShipCustomMsgBox(Clone)"
        self._awaken_text(
            ui_state,
            root + "/frame/top/title_list/infomation/title",
            exact="认知觉醒",
        )
        transition = self._awaken_text(
            ui_state,
            root + "/frame/bg/item_panel/content_num",
            pattern=r"[0-9]{3}->[0-9]{3}",
        )
        current_level, target_level = (
            int(value) for value in transition.text.split("->", 1)
        )
        if target_level not in (105, 110, 115, 120, 125):
            raise SemanticGateClosed("awaken target level is unsupported")
        icon_root = root + "/frame/bg/item_panel/items/"
        icons = tuple(
            item
            for item in ui_state.images
            if item.path.startswith(icon_root)
            and item.path.endswith("/icon_bg/icon")
            and item.sprite in ("gold", "15008", "15012")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        counts = tuple(
            item
            for item in ui_state.texts
            if item.path.startswith(icon_root)
            and item.path.endswith("/icon_bg/count")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
            and re.fullmatch(
                r"<color=#[0-9A-Fa-f]{8}>[0-9]+</color>/[0-9]+",
                item.text,
            )
        )
        if len(icons) not in (2, 3) or len(counts) != len(icons):
            raise SemanticGateClosed("awaken resource rows are incomplete")
        resources: Dict[str, Tuple[int, int]] = {}
        for icon in icons:
            assert icon.bounds is not None
            center = (icon.bounds.left + icon.bounds.right) / 2.0
            aligned = tuple(
                item
                for item in counts
                if item.bounds is not None
                and abs(
                    (item.bounds.left + item.bounds.right) / 2.0 - center
                ) < 8.0
            )
            if len(aligned) != 1:
                raise SemanticGateClosed("awaken resource count is ambiguous")
            match = re.fullmatch(
                r"<color=#[0-9A-Fa-f]{8}>([0-9]+)</color>/([0-9]+)",
                aligned[0].text,
            )
            assert match is not None
            resources[icon.sprite] = (int(match.group(1)), int(match.group(2)))
        if set(resources) not in ({"gold", "15008"}, {"gold", "15008", "15012"}):
            raise SemanticGateClosed("awaken resource identity is incomplete")
        coins = resources["gold"]
        chips = resources["15008"]
        arrays = resources.get("15012")
        return AwakenCostState(
            generation=max(state.generation, ui_state.generation),
            ship_id=ship_id,
            ship_name=ship_name,
            current_level=current_level,
            target_level=target_level,
            coins_available=coins[0],
            coins_required=coins[1],
            chips_available=chips[0],
            chips_required=chips[1],
            arrays_available=arrays[0] if arrays is not None else None,
            arrays_required=arrays[1] if arrays is not None else None,
        )

    def _awaken_modal_button(
        self, semantic_id: str, name: str, label: str
    ) -> ActionReceipt:
        state = self.read_state()
        ui_state = self.read_ui_state()
        path = (
            "OverlayCamera/Overlay/UIMain/ShipCustomMsgBox(Clone)/frame/btns/"
            + name
        )
        buttons = tuple(
            item
            for item in state.buttons
            if item.path == path
            and item.name == name
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.point is not None
            and item.bounds is not None
            and item.bounds.contains(item.point)
        )
        labels = tuple(
            item
            for item in ui_state.texts
            if item.path == path + "/Image"
            and item.text == label
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(buttons) != 1 or len(labels) != 1:
            raise SemanticGateClosed(semantic_id + " is incomplete")
        target = buttons[0]
        assert target.point is not None and target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before awaken modal input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=max(state.generation, ui_state.generation),
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    @staticmethod
    def _same_awaken_cost(left: AwakenCostState, right: AwakenCostState) -> bool:
        return (
            left.ship_id,
            left.ship_name,
            left.current_level,
            left.target_level,
            left.coins_available,
            left.coins_required,
            left.chips_available,
            left.chips_required,
            left.arrays_available,
            left.arrays_required,
        ) == (
            right.ship_id,
            right.ship_name,
            right.current_level,
            right.target_level,
            right.coins_available,
            right.coins_required,
            right.chips_available,
            right.chips_required,
            right.arrays_available,
            right.arrays_required,
        )

    def cancel_awaken_confirmation(
        self, cost: AwakenCostState
    ) -> ActionReceipt:
        if not isinstance(cost, AwakenCostState):
            raise TypeError("awaken cost state is not typed")
        current = self.awaken_cost_state(cost.ship_id, cost.ship_name)
        if not self._same_awaken_cost(current, cost):
            raise SemanticGateClosed("awaken cost changed before cancellation")
        receipt = self._awaken_modal_button(
            "awaken/confirm/cancel", "cancel_btn", "取 消"
        )
        self._retry_transition_read(
            lambda: self._awaken_detail_state(
                cost.ship_id,
                cost.ship_name,
                expected_level=cost.current_level,
            ),
            attempts=30,
            interval_seconds=0.1,
        )
        return receipt

    def commit_awaken_confirmation(
        self, cost: AwakenCostState
    ) -> AwakenExecutionReceipt:
        """Commit one sufficient modal and prove the target level afterward."""

        if not isinstance(cost, AwakenCostState):
            raise TypeError("awaken cost state is not typed")
        current = self.awaken_cost_state(cost.ship_id, cost.ship_name)
        if not self._same_awaken_cost(current, cost):
            raise SemanticGateClosed("awaken cost changed before confirmation")
        if not current.sufficient:
            raise SemanticGateClosed("awaken resources are insufficient")
        actions = [
            self._awaken_modal_button(
                "awaken/confirm/commit", "confirm_btn", "确 定"
            )
        ]
        completion_state: Optional[OracleState] = None
        completion_button: Optional[ButtonState] = None
        deadline = time.monotonic() + 35.0
        expected_text = (
            "认知觉醒完成\n等级上限提升为"
            "<color=#92fc63FF>{0}</color>".format(cost.target_level)
        )
        while time.monotonic() < deadline:
            state = self.read_state()
            ui_state = self.read_ui_state()
            messages = tuple(
                item
                for item in ui_state.texts
                if item.path.endswith("/AwakenCompleteWindows(Clone)/window/desc")
                and item.text == expected_text
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
            )
            buttons = tuple(
                item
                for item in state.buttons
                if item.path.endswith("/AwakenCompleteWindows(Clone)")
                and item.name == "AwakenCompleteWindows(Clone)"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
                and item.point is not None
                and item.bounds is not None
                and item.bounds.contains(item.point)
            )
            if len(messages) == 1 and len(buttons) == 1:
                completion_state = state
                completion_button = buttons[0]
                break
            self._sleep(0.1)
        if completion_state is None or completion_button is None:
            raise SemanticGateClosed("awaken completion was not observed")
        assert completion_button.point is not None
        assert completion_button.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before awaken completion")
        self._tap(
            int(round(completion_button.point.x)),
            int(round(completion_button.point.y)),
        )
        actions.append(
            ActionReceipt(
                semantic_id="awaken/completion/close",
                generation=completion_state.generation,
                point=completion_button.point,
                bounds=completion_button.bounds,
                path=completion_button.path,
            )
        )
        after = self._retry_transition_read(
            lambda: self._awaken_detail_state(
                cost.ship_id,
                cost.ship_name,
                require_entry=False,
            ),
            attempts=50,
            interval_seconds=0.1,
        )
        if not cost.current_level <= after.level <= cost.target_level:
            raise SemanticGateClosed("awaken post-level is outside the new cap")
        return AwakenExecutionReceipt(
            ship_id=cost.ship_id,
            ship_name=after.ship_name,
            current_level=cost.current_level,
            target_level=cost.target_level,
            observed_level=after.level,
            cost=cost,
            actions=tuple(actions),
        )

    def return_from_awaken_detail_to_dock(self) -> ActionReceipt:
        """Leave the ship detail and prove the filtered Dock returns."""

        receipt: Optional[ActionReceipt] = None
        for _ in range(8):
            state = self.read_state()
            targets = tuple(
                item
                for item in state.buttons
                if item.path.endswith("/blur_panel/adapt/top/back_btn")
                and item.name == "back_btn"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
                and item.point is not None
                and item.bounds is not None
                and item.bounds.contains(item.point)
            )
            if len(targets) != 1:
                raise SemanticGateClosed("awaken detail back control is incomplete")
            target = targets[0]
            assert target.point is not None and target.bounds is not None
            if self._foreground_component() != self.fingerprint.component:
                raise SemanticGateClosed("game activity changed before awaken detail back")
            self._tap(int(round(target.point.x)), int(round(target.point.y)))
            receipt = ActionReceipt(
                semantic_id="awaken/detail/back",
                generation=state.generation,
                point=target.point,
                bounds=target.bounds,
                path=target.path,
            )
            try:
                self._retry_transition_read(
                    self._enhancement_dock_records,
                    attempts=20,
                    interval_seconds=0.1,
                )
                return receipt
            except SemanticGateClosed:
                self._sleep(0.5)
        assert receipt is not None
        raise SemanticGateClosed("awaken detail back did not restore Dock")

    def return_from_awaken_dock_to_main(self) -> ActionReceipt:
        """Leave the official Dock through its exact top-left control."""

        state, _ = self._enhancement_dock_records()
        targets = tuple(
            item
            for item in state.buttons
            if item.path.endswith("/blur_panel/adapt/top/back")
            and item.name == "back"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.point is not None
            and item.bounds is not None
            and item.bounds.contains(item.point)
        )
        if len(targets) != 1:
            raise SemanticGateClosed("awaken Dock back control is incomplete")
        target = targets[0]
        assert target.point is not None and target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before awaken Dock back")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        receipt = ActionReceipt(
            semantic_id="awaken/dock/back",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

        def require_main() -> bool:
            if not self.main_page_visible():
                raise SemanticGateClosed(
                    "main page is not visible after awaken Dock back"
                )
            return True

        self._retry_transition_read(
            require_main,
            attempts=50,
            interval_seconds=0.1,
        )
        return receipt

    def _gems_farming_formation_records(self) -> Tuple[OracleState, UiState, int]:
        """Read the exact normal Formation page and selected fleet index."""

        last_error: Optional[SemanticGateClosed] = None
        number_path = (
            "UICamera/Canvas/UIMain/FormationUI(Clone)/blur_panel/"
            "fleet_info/fleet_number"
        )
        for attempt in range(8):
            try:
                state = self.read_state()
                ui_state = self.read_ui_state()
                numbers = tuple(
                    item
                    for item in ui_state.texts
                    if item.path == number_path
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and re.fullmatch(r"[1-6]", item.text)
                )
                slots = tuple(
                    item
                    for item in ui_state.images
                    if item.path.startswith(
                        "UICamera/Canvas/UIMain/FormationUI(Clone)/adapt/"
                        "GridFrame/"
                    )
                    and item.path.endswith("/shadow")
                    and item.sprite == "shadow"
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and item.bounds is not None
                )
                if (
                    state.generation <= ui_state.generation <= state.generation + 2
                    and len(numbers) == 1
                    and len(slots) == 6
                ):
                    return state, ui_state, int(numbers[0].text)
                last_error = SemanticGateClosed(
                    "GemsFarming formation identity is incomplete"
                )
            except SemanticGateClosed as exc:
                last_error = exc
            if attempt < 7:
                self._sleep(0.05)
        raise SemanticGateClosed(
            "GemsFarming formation snapshots did not stabilize"
        ) from last_error

    def gems_farming_select_fleet_index(self, fleet_index: int) -> int:
        """Select ALAS's attacking 1-6 fleet on the normal Formation page."""

        if isinstance(fleet_index, bool) or not isinstance(fleet_index, int):
            raise TypeError("GemsFarming fleet index must be an integer")
        if not 1 <= fleet_index <= 6:
            raise SemanticGateClosed("GemsFarming fleet index is outside 1 through 6")
        for _ in range(6):
            state, ui_state, current = self._gems_farming_formation_records()
            if current == fleet_index:
                return current
            direction = "nextPage" if current < fleet_index else "prevPage"
            pages = tuple(
                item
                for item in ui_state.images
                if item.path
                == "UICamera/Canvas/UIMain/FormationUI(Clone)/adapt/" + direction
                and item.name == direction
                and item.sprite == "arr"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.raycast_target
                and item.bounds is not None
            )
            if len(pages) != 1:
                raise SemanticGateClosed(
                    "GemsFarming formation fleet navigation is incomplete"
                )
            before = current
            self._click_exact_image(
                state,
                pages[0],
                "gems-farming/formation/fleet/{0}".format(
                    "next" if current < fleet_index else "previous"
                ),
            )
            expected = before + 1 if before < fleet_index else before - 1
            for _ in range(30):
                self._sleep(0.05)
                _, _, after = self._gems_farming_formation_records()
                if after == expected:
                    break
            else:
                raise SemanticGateClosed(
                    "GemsFarming formation fleet index did not advance"
                )
        raise SemanticGateClosed("GemsFarming formation fleet selection did not settle")

    def gems_farming_open_slot(self, role: str) -> ActionReceipt:
        """Open the exact flagship or first-vanguard replacement slot."""

        slot_names = {"flagship": "main_1", "vanguard": "vanguard_1"}
        if role not in slot_names:
            raise ValueError("GemsFarming role must be flagship or vanguard")
        slot_path = (
            "UICamera/Canvas/UIMain/FormationUI(Clone)/adapt/GridFrame/"
            + slot_names[role]
            + "/shadow"
        )
        semantic_id = "gems-farming/formation/{0}/open".format(role)
        for _ in range(20):
            state, ui_state, fleet_index = self._gems_farming_formation_records()
            slots = tuple(item for item in ui_state.images if item.path == slot_path)
            if len(slots) != 1 or slots[0].bounds is None:
                raise SemanticGateClosed("GemsFarming formation slot is incomplete")
            slot_center_x = (
                slots[0].bounds.left + slots[0].bounds.right
            ) / 2.0
            ships = tuple(
                item
                for item in ui_state.images
                if item.path.startswith(
                    "UICamera/Canvas/UIMain/FormationUI(Clone)/adapt/"
                    "HeroContainer/heroInfo(Clone)/"
                )
                and item.path.endswith("_root/mouseChild")
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.raycast_target
                and not item.truncated
                and item.bounds is not None
                and abs(
                    (item.bounds.left + item.bounds.right) / 2.0 - slot_center_x
                )
                <= 2.0
            )
            if len(ships) != 1:
                raise SemanticGateClosed(
                    "GemsFarming formation ship identity is absent or ambiguous"
                )
            ship_match = re.search(r"/([^/]+)_root/mouseChild$", ships[0].path)
            if ship_match is None:
                raise SemanticGateClosed(
                    "GemsFarming formation ship sprite is incomplete"
                )
            current_ship_sprite = ship_match.group(1)
            if not self._blocking_rules(state, semantic_id):
                break
            self._sleep(0.05)
        else:
            raise SemanticGateClosed("GemsFarming formation slot stayed blocked")
        receipt = self._click_exact_image(state, ships[0], semantic_id)
        self._retry_transition_read(
            self._enhancement_dock_records,
            attempts=50,
            interval_seconds=0.1,
        )
        self._gems_farming_open_slot_context = (
            role,
            current_ship_sprite,
            fleet_index,
        )
        return receipt

    @staticmethod
    def _gems_farming_hard_role_name(role: str) -> str:
        if role == "flagship":
            return "main"
        if role == "vanguard":
            return "vanguard"
        raise ValueError("GemsFarming role must be flagship or vanguard")

    def _gems_farming_hard_role_cards(
        self, stage_code: str, fleet_index: int, role: str
    ) -> Tuple[OracleState, UiState, Tuple[ImageState, ...], Tuple[str, ...]]:
        """Read the compacted hard-fleet role row and exact ship sprites."""

        if stage_code.upper() not in ("11-4", "12-1"):
            raise SemanticGateClosed(
                "GemsFarming hard replacement is qualified only for reviewed hard stages"
            )
        if fleet_index not in (1, 2):
            raise SemanticGateClosed("GemsFarming hard fleet must be 1 or 2")
        group = self._gems_farming_hard_role_name(role)
        preparation = self.campaign_fleet_selection_state(stage_code)
        if not preparation.hard_mode:
            raise SemanticGateClosed("GemsFarming hard fleet preparation is absent")
        state = self.read_state()
        ui_state = self.read_ui_state()
        path = (
            "OverlayCamera/Overlay/UIMain/LevelFleetSelectView(Clone)/panel/"
            "ShipList/fleet/{0}/{1}/shiptpl(Clone)/icon_bg"
        ).format(fleet_index, group)
        cards = tuple(
            sorted(
                (
                    item
                    for item in ui_state.images
                    if item.path == path
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and item.raycast_target
                    and item.bounds is not None
                ),
                key=lambda item: item.bounds.left,
            )
        )
        if len(cards) not in (2, 3):
            raise SemanticGateClosed(
                "GemsFarming hard role row must contain two or three ships"
            )
        sprites = []
        for card in cards:
            assert card.bounds is not None
            icons = tuple(
                item
                for item in ui_state.images
                if item.path == path + "/icon"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.sprite
                and self._gems_equipment_in_bounds(item, card.bounds)
            )
            if len(icons) != 1:
                raise SemanticGateClosed(
                    "GemsFarming hard fleet ship identity is incomplete"
                )
            sprites.append(icons[0].sprite)
        if state.generation > ui_state.generation:
            raise SemanticGateClosed(
                "GemsFarming hard fleet snapshots are incoherent"
            )
        return state, ui_state, cards, tuple(sprites)

    def gems_farming_hard_slot_occupied(
        self, stage_code: str, fleet_index: int, role: str
    ) -> bool:
        """Return whether ALAS's compacted first hard-fleet role slot is filled."""

        _, _, cards, _ = self._gems_farming_hard_role_cards(
            stage_code, fleet_index, role
        )
        return len(cards) == 3

    def cancel_campaign_hard_recommend_prompt(self) -> ActionReceipt:
        """Cancel the exact official-recommend prompt left by hard recovery."""

        state = self.read_state()
        ui_state = self.read_ui_state()
        if not any(
            "LevelFleetSelectView(Clone)" in item.path
            and item.active_in_hierarchy
            and item.active_and_enabled
            for item in state.buttons
        ):
            raise SemanticGateClosed(
                "hard fleet recommendation prompt has no fleet owner"
            )
        root = "OverlayCamera/Overlay/UIMain/Msgbox(Clone)/window/"
        texts = {
            item.path: item.text.strip()
            for item in ui_state.texts
            if item.path in {
                root + "msg_panel/content",
                root + "button_container/custom_button_1(Clone)/pic",
                root + "button_container/custom_button_2(Clone)/pic",
            }
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        }
        content = texts.get(root + "msg_panel/content")
        confirm = "".join(
            texts.get(
                root + "button_container/custom_button_1(Clone)/pic", ""
            ).split()
        )
        cancel = "".join(
            texts.get(
                root + "button_container/custom_button_2(Clone)/pic", ""
            ).split()
        )
        if (
            content
            not in (
                "是否采用推荐配置补齐空余位置?",
                "是否使用推荐编队来填充空位?",
                "是否使用推荐编队填充空位?",
                "�Ƿ�����Ƽ����ò������λ��?",
            )
            or (cancel, confirm) not in (("取消", "确定"), ("ȡ��", "ȷ��"))
        ):
            raise SemanticGateClosed(
                "hard fleet recommendation prompt text is not reviewed"
            )
        path = root + "button_container/custom_button_2(Clone)"
        buttons = tuple(
            item
            for item in state.buttons
            if item.path == path
            and item.name == "custom_button_2(Clone)"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.raycast_top is True
            and item.point is not None
            and item.bounds is not None
            and item.bounds.contains(item.point)
        )
        images = tuple(
            item
            for item in ui_state.images
            if item.path == path
            and item.sprite == "btn_big_grey"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(buttons) != 1 or len(images) != 1:
            raise SemanticGateClosed(
                "hard fleet recommendation cancel is absent or ambiguous"
            )
        target = buttons[0]
        assert target.point is not None and target.bounds is not None
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed(
                "foreground changed before hard recommendation cancellation"
            )
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="campaign/hard/recommend/cancel",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def gems_farming_hard_unmount(
        self, stage_code: str, fleet_index: int, role: str
    ) -> ActionReceipt:
        """Unmount the compacted first hard-fleet ship and prove one-card removal."""

        state, _, cards, before = self._gems_farming_hard_role_cards(
            stage_code, fleet_index, role
        )
        if len(cards) != 3:
            raise SemanticGateClosed("GemsFarming hard source slot is already empty")
        open_receipt = self._click_exact_image(
            state,
            cards[0],
            "campaign/fleet-preparation/fleet/{0}/select".format(fleet_index),
        )
        dock_state, _ = self._retry_transition_read(
            self._enhancement_dock_records, attempts=50, interval_seconds=0.1
        )
        current = tuple(
            item
            for item in dock_state.buttons
            if item.path
            == "UICamera/Canvas/UIMain/DockyardUI(Clone)/main/ship_container/ships/0"
            and item.name == "0"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.point is not None
            and item.bounds is not None
        )
        if len(current) != 1:
            raise SemanticGateClosed(
                "GemsFarming hard current-ship placeholder is absent or ambiguous"
            )
        receipt = self._gems_equipment_click_button(
            dock_state, current[0], "tactical/dock/confirm"
        )
        for _ in range(60):
            self._sleep(0.1)
            try:
                _, _, after_cards, after = self._gems_farming_hard_role_cards(
                    stage_code, fleet_index, role
                )
            except SemanticGateClosed:
                continue
            if len(after_cards) == 2 and after == before[1:]:
                self._gems_farming_hard_open_slot_context = None
                return receipt
        raise SemanticGateClosed(
            "GemsFarming hard unmount postcondition was not proven; open receipt "
            + open_receipt.semantic_id
        )

    def gems_farming_hard_open_slot(
        self, stage_code: str, fleet_index: int, role: str
    ) -> ActionReceipt:
        """Open the unique third compacted hard-fleet slot after unmount."""

        state, ui_state, cards, before = self._gems_farming_hard_role_cards(
            stage_code, fleet_index, role
        )
        if len(cards) != 2:
            raise SemanticGateClosed(
                "GemsFarming hard target slot requires exactly two remaining ships"
            )
        group = self._gems_farming_hard_role_name(role)
        path = (
            "OverlayCamera/Overlay/UIMain/LevelFleetSelectView(Clone)/panel/"
            "ShipList/fleet/{0}/{1}/emptytpl(Clone)/icon_bg"
        ).format(fleet_index, group)
        blanks = tuple(
            item
            for item in ui_state.images
            if item.path == path
            and item.name == "icon_bg"
            and item.sprite == "tianjia_icon"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.raycast_target
            and item.bounds is not None
        )
        if len(blanks) != 1:
            raise SemanticGateClosed(
                "GemsFarming hard target blank is absent or ambiguous"
            )
        receipt = self._click_exact_image(
            state,
            blanks[0],
            "campaign/fleet-preparation/fleet/{0}/select".format(fleet_index),
        )
        self._retry_transition_read(
            self._enhancement_dock_records, attempts=50, interval_seconds=0.1
        )
        self._gems_farming_hard_open_slot_context = (
            stage_code,
            fleet_index,
            role,
            before,
        )
        return receipt

    @staticmethod
    def _gems_equipment_center(bounds: Bounds) -> Point:
        return Point(
            (bounds.left + bounds.right) / 2.0,
            (bounds.top + bounds.bottom) / 2.0,
        )

    @staticmethod
    def _gems_equipment_in_bounds(
        item: Union[ImageState, TextState], bounds: Bounds
    ) -> bool:
        return item.bounds is not None and bounds.contains(
            SemanticOracle._gems_equipment_center(item.bounds)
        )

    def _gems_equipment_click_button(
        self,
        state: OracleState,
        button: ButtonState,
        semantic_id: str,
        *,
        require_raycast_top: bool = False,
    ) -> ActionReceipt:
        if (
            not button.active_in_hierarchy
            or not button.active_and_enabled
            or not button.interactable
            or button.point is None
            or button.bounds is None
            or not button.bounds.contains(button.point)
            or (require_raycast_top and button.raycast_top is not True)
        ):
            raise SemanticGateClosed(semantic_id + " is not safely actionable")
        if self._blocking_rules(state, semantic_id):
            raise SemanticGateClosed(semantic_id + " input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before equipment input")
        self._tap(int(round(button.point.x)), int(round(button.point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed after equipment input")
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=state.generation,
            point=button.point,
            bounds=button.bounds,
            path=button.path,
        )

    def _gems_equipment_open_ship_detail(self, role: str) -> ActionReceipt:
        """Enter ALAS's flagship or first-vanguard detail through typed Formation."""

        if role not in ("flagship", "vanguard"):
            raise ValueError("GemsFarming role must be flagship or vanguard")
        state = self.read_state()
        ui_state = self.read_ui_state()
        already_detail = tuple(
            item
            for item in ui_state.toggles
            if item.path.endswith("/bottom/toggle_list/detail_toggle")
            and item.name == "detail_toggle"
            and item.checked
            and item.active_in_hierarchy
            and item.active_and_enabled
        )
        if len(already_detail) > 1:
            raise SemanticGateClosed("GemsFarming Formation detail state is ambiguous")
        if not already_detail:
            state, ui_state, _ = self._gems_farming_formation_records()
        toggles = tuple(
            item
            for item in ui_state.toggles
            if item.path.endswith("/bottom/toggle_list/detail_toggle")
            and item.name == "detail_toggle"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.point is not None
            and item.bounds is not None
            and item.bounds.contains(item.point)
        )
        if len(toggles) != 1:
            raise SemanticGateClosed("GemsFarming Formation detail toggle is incomplete")
        if not toggles[0].checked:
            if self._blocking_rules(state, "gems-farming/equipment/detail-toggle"):
                raise SemanticGateClosed("GemsFarming Formation detail toggle is blocked")
            self._tap(
                int(round(toggles[0].point.x)), int(round(toggles[0].point.y))
            )
            self._sleep(0.2)

        def detail_card() -> Tuple[OracleState, ImageState]:
            current = self.read_state()
            current_ui = self.read_ui_state()
            group = "main" if role == "flagship" else "vanguard"
            suffix = "/attr_frame/{0}/list/RectShipCardTpl(Clone)/content/detail".format(
                group
            )
            cards = tuple(
                item
                for item in current_ui.images
                if item.path.endswith(suffix)
                and item.sprite == "rect_bg"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            cards = tuple(sorted(cards, key=lambda item: item.bounds.left))
            if not cards:
                raise SemanticGateClosed("GemsFarming Formation detail cards are absent")
            target = cards[0]
            if role == "flagship":
                flags = tuple(
                    item
                    for item in current_ui.images
                    if item.path.endswith(
                        "/attr_frame/main/list/RectShipCardTpl(Clone)/content/front/flag"
                    )
                    and item.sprite == "flag_icon"
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and item.bounds is not None
                    and self._bounds_overlap(item.bounds, target.bounds) > 0
                )
                if len(flags) != 1:
                    raise SemanticGateClosed(
                        "GemsFarming flagship detail identity is incomplete"
                    )
            if current.generation > current_ui.generation:
                raise SemanticGateClosed("GemsFarming detail snapshots are incoherent")
            return current, target

        card_state, card = self._retry_transition_read(
            detail_card, attempts=120, interval_seconds=0.1
        )
        assert card.bounds is not None
        point = self._gems_equipment_center(card.bounds)
        semantic_id = "gems-farming/equipment/{0}/detail".format(role)
        if self._blocking_rules(card_state, semantic_id):
            raise SemanticGateClosed("GemsFarming detail card input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before equipment detail")
        self._tap(int(round(point.x)), int(round(point.y)))
        receipt = ActionReceipt(
            semantic_id=semantic_id,
            generation=card_state.generation,
            point=point,
            bounds=card.bounds,
            path=card.path,
        )
        self._gems_equipment_stable_detail_loadout()
        return receipt

    def _gems_equipment_read_loadout(
        self,
    ) -> Tuple[OracleState, UiState, Tuple[GemsFarmingEquipmentSlot, ...]]:
        state = self.read_state()
        ui_state = self.read_ui_state()
        regular_path = (
            "/ShipDetailView(Clone)/equipments/"
            "equipments/equipment_tpl(Clone)"
        )
        empty_path = (
            "/ShipDetailView(Clone)/equipments/equipments/empty_tpl(Clone)"
        )
        regular = tuple(
            sorted(
                (
                    item
                    for item in state.buttons
                    if item.path.endswith((regular_path, empty_path))
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and item.interactable
                    and item.point is not None
                    and item.bounds is not None
                ),
                key=lambda item: item.bounds.left,
            )
        )
        special_path = "/ShipDetailView(Clone)/equipments/SpSlot"
        special = tuple(
            item
            for item in state.buttons
            if item.path.endswith(special_path)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.point is not None
            and item.bounds is not None
        )
        if len(regular) != 5 or len(special) != 1:
            raise SemanticGateClosed("GemsFarming ship equipment slots are incomplete")
        slots = []
        for position, button in enumerate(regular, start=1):
            assert button.bounds is not None
            icon_path = button.path + "/IconTpl/icon_bg/icon"
            level_path = button.path + "/IconTpl/icon_bg/slv/Text"
            icons = tuple(
                item
                for item in ui_state.images
                if item.path == icon_path
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.sprite
                and self._gems_equipment_in_bounds(item, button.bounds)
            )
            levels = tuple(
                item
                for item in ui_state.texts
                if item.path == level_path
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and re.fullmatch(r"(?:[0-9]|1[0-5])", item.text)
                and self._gems_equipment_in_bounds(item, button.bounds)
            )
            if not icons and not levels:
                continue
            if len(icons) != 1 or len(levels) > 1:
                raise SemanticGateClosed("GemsFarming regular equipment is ambiguous")
            slots.append(
                GemsFarmingEquipmentSlot(
                    position=position,
                    equipment_id=icons[0].sprite,
                    enhancement=int(levels[0].text) if levels else 0,
                    special=False,
                )
            )
        special_button = special[0]
        assert special_button.bounds is not None
        special_icons = tuple(
            item
            for item in ui_state.images
            if item.path.endswith(special_path + "/Icon/Mask/icon_bg/icon")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.sprite
            and self._gems_equipment_in_bounds(item, special_button.bounds)
        )
        special_levels = tuple(
            item
            for item in ui_state.texts
            if item.path.endswith(special_path + "/Icon/LV/Text")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and re.fullmatch(r"(?:[0-9]|1[0-5])", item.text)
            and self._gems_equipment_in_bounds(item, special_button.bounds)
        )
        if special_icons or special_levels:
            if len(special_icons) != 1 or len(special_levels) > 1:
                raise SemanticGateClosed("GemsFarming special equipment is ambiguous")
            slots.append(
                GemsFarmingEquipmentSlot(
                    position=6,
                    equipment_id=special_icons[0].sprite,
                    enhancement=(
                        int(special_levels[0].text) if special_levels else 0
                    ),
                    special=True,
                )
            )
        if state.generation > ui_state.generation:
            raise SemanticGateClosed("GemsFarming equipment snapshots are incoherent")
        return state, ui_state, tuple(slots)

    def _gems_equipment_stable_detail_loadout(
        self,
    ) -> Tuple[OracleState, UiState, Tuple[GemsFarmingEquipmentSlot, ...]]:
        """Require five identical typed detail reads before branching on emptiness."""

        previous: Optional[Tuple[GemsFarmingEquipmentSlot, ...]] = None
        stable_reads = 0
        observed: Optional[
            Tuple[OracleState, UiState, Tuple[GemsFarmingEquipmentSlot, ...]]
        ] = None
        last_error: Optional[SemanticGateClosed] = None
        for _ in range(50):
            try:
                observed = self._gems_equipment_read_loadout()
            except SemanticGateClosed as exc:
                last_error = exc
                previous = None
                stable_reads = 0
                self._sleep(0.1)
                continue
            current = observed[2]
            if current == previous:
                stable_reads += 1
            else:
                previous = current
                stable_reads = 1
            if stable_reads >= 5:
                return observed
            self._sleep(0.1)
        raise SemanticGateClosed(
            "GemsFarming detail loadout did not stabilize"
        ) from last_error

    def _gems_equipment_unload_detail_slot(
        self, slot: GemsFarmingEquipmentSlot
    ) -> None:
        if slot.special or not 1 <= slot.position <= 5:
            raise SemanticGateClosed(
                "GemsFarming only unloads the five ALAS equipment-code slots"
            )
        state, _, current = self._gems_equipment_stable_detail_loadout()
        if tuple(item for item in current if item.position == slot.position) != (slot,):
            raise SemanticGateClosed("GemsFarming unload equipment identity changed")
        suffixes = (
            "/ShipDetailView(Clone)/equipments/equipments/equipment_tpl(Clone)",
            "/ShipDetailView(Clone)/equipments/equipments/empty_tpl(Clone)",
        )
        buttons = tuple(
            sorted(
                (
                    item
                    for item in state.buttons
                    if item.path.endswith(suffixes)
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and item.interactable
                    and item.bounds is not None
                    and item.point is not None
                ),
                key=lambda item: item.bounds.left,
            )
        )
        if len(buttons) != 5:
            raise SemanticGateClosed("GemsFarming ship equipment slots are incomplete")
        self._gems_equipment_click_button(
            state,
            buttons[slot.position - 1],
            "gems-farming/equipment/slot/{0}/unload-open".format(slot.position),
        )
        action_path = (
            "OverlayCamera/Overlay/UIMain/EquipmentInfoUI(Clone)/default/"
            "actions/action_button_4"
        )

        def require_unload() -> Tuple[OracleState, ButtonState]:
            current_state = self.read_state()
            text_state = self.read_text_state()
            actions = tuple(
                item for item in current_state.buttons if item.path == action_path
            )
            labels = tuple(
                item
                for item in text_state.texts
                if item.path == action_path + "/change"
                and item.text == "卸 下"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
            )
            if len(actions) != 1 or len(labels) != 1:
                raise SemanticGateClosed(
                    "GemsFarming unload equipment action is incomplete"
                )
            return current_state, actions[0]

        action_state, action = self._retry_transition_read(
            require_unload, attempts=30, interval_seconds=0.1
        )
        self._gems_equipment_click_button(
            action_state,
            action,
            "gems-farming/equipment/slot/{0}/unload".format(slot.position),
        )
        _, _, after = self._gems_equipment_stable_detail_loadout()
        if any(item.position == slot.position for item in after):
            raise SemanticGateClosed("GemsFarming equipment slot did not unload")

    def _gems_equipment_back_to_formation(self) -> ActionReceipt:
        receipt: Optional[ActionReceipt] = None
        for depth in range(4):
            try:
                self._gems_farming_formation_records()
                if receipt is None:
                    raise SemanticGateClosed(
                        "GemsFarming equipment return performed no navigation"
                    )
                return receipt
            except SemanticGateClosed:
                pass

            state = self.read_state()
            ui_state = self.read_ui_state()
            toggles = tuple(
                item
                for item in ui_state.toggles
                if item.path.endswith("/bottom/toggle_list/formation_toggle")
                and item.name == "formation_toggle"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
                and item.point is not None
                and item.bounds is not None
                and item.bounds.contains(item.point)
            )
            if len(toggles) > 1:
                raise SemanticGateClosed(
                    "GemsFarming Formation view toggle is ambiguous"
                )
            if len(toggles) == 1:
                toggle = toggles[0]
                if not toggle.checked:
                    semantic_id = "gems-farming/equipment/formation-toggle"
                    if self._blocking_rules(state, semantic_id):
                        self._sleep(0.1)
                        continue
                    assert toggle.point is not None and toggle.bounds is not None
                    self._tap(
                        int(round(toggle.point.x)), int(round(toggle.point.y))
                    )
                    if receipt is None:
                        receipt = ActionReceipt(
                            semantic_id=semantic_id,
                            generation=state.generation,
                            point=toggle.point,
                            bounds=toggle.bounds,
                            path=toggle.path,
                        )
                self._sleep(0.5)
                continue

            suffix = "/blur_panel/adapt/top/back_btn"
            buttons = tuple(
                item
                for item in state.buttons
                if item.name == "back_btn" and item.path.endswith(suffix)
            )
            if len(buttons) != 1:
                raise SemanticGateClosed(
                    "GemsFarming equipment back control is incomplete"
                )
            current_receipt = self._gems_equipment_click_button(
                state,
                buttons[0],
                "gems-farming/equipment/back/{0}".format(depth + 1),
            )
            if receipt is None:
                receipt = current_receipt
            self._sleep(0.2)
        raise SemanticGateClosed("GemsFarming equipment return did not settle")

    def gems_farming_equipment_take_off(
        self, role: str
    ) -> GemsFarmingEquipmentLoadout:
        """Capture and unload ALAS's five equipment-code slots."""

        if role in self._gems_farming_equipment_loadouts:
            raise SemanticGateClosed(
                "GemsFarming equipment transfer is already pending for " + role
            )
        self._gems_equipment_open_ship_detail(role)
        _, _, observed = self._gems_equipment_stable_detail_loadout()
        slots = tuple(item for item in observed if not item.special)
        special = tuple(item for item in observed if item.special)
        for slot in slots:
            self._gems_equipment_unload_detail_slot(slot)
        _, _, after = self._gems_equipment_stable_detail_loadout()
        if tuple(item for item in after if not item.special):
            raise SemanticGateClosed("GemsFarming equipment did not unload")
        if tuple(item for item in after if item.special) != special:
            raise SemanticGateClosed("GemsFarming special equipment changed")
        loadout = GemsFarmingEquipmentLoadout(role=role, slots=slots)
        self._gems_farming_equipment_loadouts[role] = loadout
        self._gems_equipment_back_to_formation()
        return loadout

    @staticmethod
    def _gems_equipment_overview_path(position: int) -> str:
        paths = {
            1: "OverlayCamera/Overlay/UIMain/equipment_r_container(Adapt)/equipment_r_container/equipment_r/equipment/equipment_r1",
            2: "OverlayCamera/Overlay/UIMain/equipment_r_container(Adapt)/equipment_r_container/equipment_r/equipment/equipment_r2",
            3: "OverlayCamera/Overlay/UIMain/equipment_r_container(Adapt)/equipment_r_container/equipment_r/equipment/equipment_r3",
            4: "OverlayCamera/Overlay/UIMain/equipment_l_container(Adapt)/equipment_l_container/equipment_l/equipment/equipment_l1",
            5: "OverlayCamera/Overlay/UIMain/equipment_l_container(Adapt)/equipment_l_container/equipment_l/equipment/equipment_l2",
            6: "OverlayCamera/Overlay/UIMain/equipment_b_container(Adapt)/equipment_b_container/equipment_b/equipment",
        }
        try:
            return paths[position]
        except KeyError as exc:
            raise ValueError("GemsFarming equipment position is invalid") from exc

    def _gems_equipment_overview_loadout(
        self,
    ) -> Tuple[OracleState, UiState, Tuple[GemsFarmingEquipmentSlot, ...]]:
        state = self.read_state()
        ui_state = self.read_ui_state()
        slots = []
        for position in range(1, 7):
            root = self._gems_equipment_overview_path(position)
            buttons = tuple(
                item
                for item in state.buttons
                if item.path == root
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
                and item.point is not None
                and item.bounds is not None
            )
            if position == 6 and not buttons:
                continue
            if len(buttons) != 1:
                raise SemanticGateClosed(
                    "GemsFarming equipment overview slot is incomplete"
                )
            icon_suffix = (
                "/info/Icon/Mask/icon_bg/icon"
                if position == 6
                else "/info/IconTpl/icon_bg/icon"
            )
            level_suffix = (
                "/info/Icon/LV/Text"
                if position == 6
                else "/info/IconTpl/icon_bg/slv/Text"
            )
            icons = tuple(
                item
                for item in ui_state.images
                if item.path == root + icon_suffix
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.sprite
            )
            levels = tuple(
                item
                for item in ui_state.texts
                if item.path == root + level_suffix
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and re.fullmatch(r"(?:[0-9]|1[0-5])", item.text)
            )
            if not icons and not levels:
                continue
            if len(icons) != 1 or len(levels) > 1:
                raise SemanticGateClosed(
                    "GemsFarming equipment overview identity is ambiguous"
                )
            slots.append(
                GemsFarmingEquipmentSlot(
                    position=position,
                    equipment_id=icons[0].sprite,
                    enhancement=int(levels[0].text) if levels else 0,
                    special=position == 6,
                )
            )
        if state.generation > ui_state.generation:
            raise SemanticGateClosed("GemsFarming overview snapshots are incoherent")
        return state, ui_state, tuple(slots)

    def _gems_equipment_open_detail_store(
        self, slot: GemsFarmingEquipmentSlot
    ) -> None:
        state, _, current = self._gems_equipment_stable_detail_loadout()
        mounted = tuple(item for item in current if item.position == slot.position)
        if len(mounted) > 1:
            raise SemanticGateClosed(
                "GemsFarming occupied equipment slot is not uniquely mounted"
            )
        regular_suffixes = (
            "/ShipDetailView(Clone)/equipments/equipments/equipment_tpl(Clone)",
            "/ShipDetailView(Clone)/equipments/equipments/empty_tpl(Clone)",
        )
        regular = tuple(
            sorted(
                (
                    item
                    for item in state.buttons
                    if item.path.endswith(regular_suffixes)
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and item.interactable
                    and item.bounds is not None
                    and item.point is not None
                ),
                key=lambda item: item.bounds.left,
            )
        )
        special = tuple(
            item
            for item in state.buttons
            if item.path.endswith("/ShipDetailView(Clone)/equipments/SpSlot")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.bounds is not None
            and item.point is not None
        )
        if len(regular) != 5 or len(special) != 1:
            raise SemanticGateClosed("GemsFarming ship equipment slots are incomplete")
        button = special[0] if slot.special else regular[slot.position - 1]
        self._gems_equipment_click_button(
            state,
            button,
            "gems-farming/equipment/slot/{0}/occupied".format(slot.position),
        )
        page = "SpWeaponStoreHouseUI(Clone)" if slot.special else "StoreHouseUI(Clone)"
        if not mounted:
            def require_empty_destination() -> str:
                current_state = self.read_state()
                if any(page in item.path for item in current_state.buttons):
                    return "store"
                try:
                    self._gems_equipment_overview_loadout()
                except SemanticGateClosed as exc:
                    raise SemanticGateClosed(
                        "GemsFarming empty equipment destination is incomplete"
                    ) from exc
                return "overview"

            destination = self._retry_transition_read(
                require_empty_destination, attempts=50, interval_seconds=0.1
            )
            if destination == "overview":
                self._gems_equipment_open_store(slot)
            return

        dialog = "SpWeaponInfoUI(Clone)" if slot.special else "EquipmentInfoUI(Clone)"
        action_path = (
            "OverlayCamera/Overlay/UIMain/{0}/default/actions/action_button_3".format(
                dialog
            )
        )

        def require_change() -> Tuple[OracleState, ButtonState]:
            current_state = self.read_state()
            text_state = self.read_text_state()
            buttons = tuple(
                item for item in current_state.buttons if item.path == action_path
            )
            texts = tuple(
                item
                for item in text_state.texts
                if item.path == action_path + "/change"
                and item.text == "更 换"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
            )
            if len(buttons) != 1 or len(texts) != 1:
                raise SemanticGateClosed(
                    "GemsFarming occupied equipment action is incomplete"
                )
            return current_state, buttons[0]

        action_state, change = self._retry_transition_read(
            require_change, attempts=30, interval_seconds=0.1
        )
        self._gems_equipment_click_button(
            action_state,
            change,
            "gems-farming/equipment/slot/{0}/change".format(slot.position),
        )
        def require_store() -> bool:
            current_state = self.read_state()
            if not any(page in item.path for item in current_state.buttons):
                raise SemanticGateClosed("GemsFarming equipment store did not open")
            return True

        self._retry_transition_read(require_store, attempts=50, interval_seconds=0.1)

    def _gems_equipment_open_store(self, slot: GemsFarmingEquipmentSlot) -> None:
        state, _, _ = self._retry_transition_read(
            self._gems_equipment_overview_loadout,
            attempts=30,
            interval_seconds=0.1,
        )
        path = self._gems_equipment_overview_path(slot.position)
        buttons = tuple(item for item in state.buttons if item.path == path)
        if len(buttons) != 1:
            raise SemanticGateClosed("GemsFarming equipment slot control changed")
        self._gems_equipment_click_button(
            state,
            buttons[0],
            "gems-farming/equipment/slot/{0}/store".format(slot.position),
        )
        page = "SpWeaponStoreHouseUI(Clone)" if slot.special else "StoreHouseUI(Clone)"

        def require_store() -> bool:
            current = self.read_state()
            if not any(page in item.path for item in current.buttons):
                raise SemanticGateClosed("GemsFarming equipment store did not open")
            return True

        self._retry_transition_read(require_store, attempts=50, interval_seconds=0.1)

    def _gems_equipment_store_candidate(
        self, slot: GemsFarmingEquipmentSlot
    ) -> Tuple[OracleState, ButtonState, Point]:
        state = self.read_state()
        ui_state = self.read_ui_state()
        candidates = []
        if slot.special:
            prefix = (
                "UICamera/Canvas/UIMain/SpWeaponStoreHouseUI(Clone)/adapt/"
                "ScrollView/Viewport/Content/StoreHouse/Grid/Template(Clone)"
            )
            cards = tuple(
                item
                for item in state.buttons
                if item.path == prefix
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
                and item.bounds is not None
                and item.point is not None
            )
            for card in cards:
                assert card.bounds is not None
                icons = tuple(
                    item
                    for item in ui_state.images
                    if item.path == prefix + "/frame/bg/icon_bg/icon"
                    and item.sprite == slot.equipment_id
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and self._gems_equipment_in_bounds(item, card.bounds)
                )
                levels = tuple(
                    item
                    for item in ui_state.texts
                    if item.path == prefix + "/frame/bg/icon_bg/slv/Text"
                    and re.fullmatch(r"(?:[0-9]|1[0-5])", item.text)
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and self._gems_equipment_in_bounds(item, card.bounds)
                )
                assigned = tuple(
                    item
                    for item in ui_state.images
                    if item.path.startswith(prefix + "/frame/bg/equip_flag")
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and self._gems_equipment_in_bounds(item, card.bounds)
                )
                observed_enhancement = (
                    int(levels[0].text) if len(levels) == 1 else 0
                )
                if (
                    len(icons) == 1
                    and len(levels) <= 1
                    and observed_enhancement == slot.enhancement
                    and not assigned
                ):
                    assert icons[0].bounds is not None
                    candidates.append(
                        (card, self._gems_equipment_center(icons[0].bounds))
                    )
        else:
            prefix = (
                "UICamera/Canvas/UIMain/StoreHouseUI(Clone)/adapt/"
                "equipment_scrollview/equipment_grid/"
            )
            for card in state.buttons:
                match = re.fullmatch(re.escape(prefix) + r"([0-9]+)", card.path)
                if (
                    match is None
                    or not card.active_in_hierarchy
                    or not card.active_and_enabled
                    or not card.interactable
                    or card.bounds is None
                    or card.point is None
                ):
                    continue
                root = card.path
                icons = tuple(
                    item
                    for item in ui_state.images
                    if item.path == root + "/frame/bg/icon_bg/icon"
                    and item.sprite == slot.equipment_id
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                )
                levels = tuple(
                    item
                    for item in ui_state.texts
                    if item.path == root + "/frame/bg/icon_bg/slv/Text"
                    and re.fullmatch(r"(?:[0-9]|1[0-5])", item.text)
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                )
                assigned = tuple(
                    item
                    for item in ui_state.images
                    if item.path.startswith(root + "/frame/bg/equip_flag")
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                )
                observed_enhancement = (
                    int(levels[0].text) if len(levels) == 1 else 0
                )
                if (
                    len(icons) == 1
                    and len(levels) <= 1
                    and observed_enhancement == slot.enhancement
                    and not assigned
                ):
                    assert icons[0].bounds is not None
                    candidates.append(
                        (card, self._gems_equipment_center(icons[0].bounds))
                    )
        visible = tuple(
            item
            for item in candidates
            if item[0].bounds is not None
            and item[0].bounds.contains(item[1])
            and item[0].bounds.top >= 40.0
            and item[0].bounds.bottom <= 680.0
        )
        visible = tuple(
            sorted(
                visible,
                key=lambda item: (
                    item[0].bounds.top,
                    item[0].bounds.left,
                    item[0].path,
                ),
            )
        )
        if not visible:
            raise SemanticGateClosed("GemsFarming equipment is not visible in store")
        if state.generation > ui_state.generation:
            raise SemanticGateClosed("GemsFarming store snapshots are incoherent")
        return state, visible[0][0], visible[0][1]

    def _gems_equipment_reset_store(self, special: bool) -> None:
        if self._swipe is None:
            raise SemanticGateClosed("GemsFarming equipment store requires typed swipe")
        previous_regular_top: Optional[Tuple[int, int]] = None
        for _ in range(12):
            state = self.read_state()
            ui_state = self.read_ui_state()
            if special:
                banner = tuple(
                    item
                    for item in ui_state.texts
                    if item.path.endswith(
                        "/SpWeaponStoreHouseUI(Clone)/adapt/ScrollView/Viewport/Content/StoreHouse/Banner/Text"
                    )
                    and item.bounds is not None
                )
                at_top = len(banner) == 1 and banner[0].bounds.top >= 0.0
            else:
                prefix = (
                    "UICamera/Canvas/UIMain/StoreHouseUI(Clone)/adapt/"
                    "equipment_scrollview/equipment_grid/"
                )
                visible_indices = tuple(
                    (
                        int(item.path[len(prefix) :]),
                        int(round(item.bounds.top)),
                    )
                    for item in state.buttons
                    if item.path.startswith(prefix)
                    and item.path[len(prefix) :].isdigit()
                    and item.bounds is not None
                    and item.bounds.bottom >= 0.0
                    and item.bounds.top <= 680.0
                )
                # A partially scrolled first page can still expose an index
                # below 7. Treating that as the top made the subsequent
                # downward-only search miss equipment immediately above the
                # viewport. Prove the upper boundary by one unchanged upward
                # swipe instead of assuming a particular grid index origin.
                regular_top = min(visible_indices) if visible_indices else None
                at_top = (
                    regular_top is not None
                    and regular_top == previous_regular_top
                )
                previous_regular_top = regular_top
            if at_top:
                return
            if self._blocking_rules(state, "gems-farming/equipment/store/reset"):
                raise SemanticGateClosed("GemsFarming equipment store swipe is blocked")
            self._swipe(640, 160, 640, 600, 400)
            self._sleep(0.15)
        raise SemanticGateClosed("GemsFarming equipment store did not reset")

    def _gems_equipment_select_from_store(
        self, slot: GemsFarmingEquipmentSlot
    ) -> str:
        self._gems_equipment_reset_store(slot.special)
        candidate: Optional[Tuple[OracleState, ButtonState, Point]] = None
        previous_signature: Optional[Tuple[str, int, int]] = None
        stable_reads = 0
        for attempt in range(120):
            try:
                observed = self._gems_equipment_store_candidate(slot)
            except SemanticGateClosed as exc:
                if "not visible in store" not in str(exc):
                    raise
                observed = None
            if observed is not None:
                _, button, point = observed
                signature = (button.path, round(point.x), round(point.y))
                if signature == previous_signature:
                    stable_reads += 1
                else:
                    previous_signature = signature
                    stable_reads = 1
                if stable_reads >= 3:
                    candidate = observed
                    break
                self._sleep(0.25)
                continue
            previous_signature = None
            stable_reads = 0
            if self._swipe is None:
                raise SemanticGateClosed("GemsFarming equipment store requires typed swipe")
            current = self.read_state()
            if self._blocking_rules(current, "gems-farming/equipment/store/search"):
                raise SemanticGateClosed("GemsFarming equipment store swipe is blocked")
            self._swipe(640, 600, 640, 350, 300)
            self._sleep(0.15)
        if candidate is None:
            raise SemanticGateClosed(
                "GemsFarming equipment is unavailable: {0} +{1}".format(
                    slot.equipment_id, slot.enhancement
                )
            )
        state, button, point = candidate
        semantic_id = "gems-farming/equipment/slot/{0}/candidate/{1}".format(
            slot.position, slot.equipment_id
        )
        if button.bounds is None or not button.bounds.contains(point):
            raise SemanticGateClosed("GemsFarming equipment candidate moved")
        if self._blocking_rules(state, semantic_id):
            raise SemanticGateClosed("GemsFarming equipment candidate is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before equipment selection")
        self._tap(int(round(point.x)), int(round(point.y)))
        dialog = "SpWeaponInfoUI(Clone)" if slot.special else "EquipmentInfoUI(Clone)"
        prefix = "OverlayCamera/Overlay/UIMain/{0}/replace".format(dialog)

        def selection() -> Tuple[OracleState, ButtonState]:
            current = self.read_state()
            current_ui = self.read_ui_state()
            buttons = tuple(
                item
                for item in current.buttons
                if item.path == prefix + "/actions/action_button_2"
            )
            icons = tuple(
                item
                for item in current_ui.images
                if item.path == prefix + "/equipment_on_ship/info/equip/icon_bg/icon"
                and item.sprite == slot.equipment_id
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
            )
            levels = tuple(
                item
                for item in current_ui.texts
                if item.path == prefix + "/equipment_on_ship/info/equip/slv/Text"
                and item.text == str(slot.enhancement)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
            )
            observed_enhancement = int(levels[0].text) if len(levels) == 1 else 0
            if (
                len(buttons) != 1
                or len(icons) != 1
                or len(levels) > 1
                or observed_enhancement != slot.enhancement
            ):
                raise SemanticGateClosed("GemsFarming equipment selection changed")
            return current, buttons[0]

        selected_state, confirm = self._retry_transition_read(
            selection, attempts=30, interval_seconds=0.1
        )
        self._gems_equipment_click_button(
            selected_state,
            confirm,
            "gems-farming/equipment/slot/{0}/confirm".format(slot.position),
        )

        def require_mounted() -> str:
            for page, reader in (
                ("overview", self._gems_equipment_overview_loadout),
                ("detail", self._gems_equipment_read_loadout),
            ):
                try:
                    _, _, mounted = reader()
                except SemanticGateClosed:
                    continue
                matches = tuple(
                    item for item in mounted if item.position == slot.position
                )
                if matches == (slot,):
                    return page
            raise SemanticGateClosed("GemsFarming equipment mount was not proven")

        return self._retry_transition_read(
            require_mounted, attempts=50, interval_seconds=0.1
        )

    def gems_farming_equipment_take_on(
        self, role: str
    ) -> GemsFarmingEquipmentLoadout:
        """Mount the pending typed loadout on ALAS's current Formation ship."""

        try:
            loadout = self._gems_farming_equipment_loadouts[role]
        except KeyError as exc:
            raise SemanticGateClosed(
                "GemsFarming equipment transfer is not pending for " + role
            ) from exc
        if any(slot.special for slot in loadout.slots):
            raise SemanticGateClosed(
                "GemsFarming pending loadout exceeds ALAS's five equipment-code slots"
            )
        self._gems_equipment_open_ship_detail(role)
        _, _, current = self._gems_equipment_stable_detail_loadout()
        current_by_position = {
            slot.position: slot for slot in current if not slot.special
        }
        desired_by_position = {slot.position: slot for slot in loadout.slots}
        for position in tuple(sorted(current_by_position)):
            if position not in desired_by_position:
                self._gems_equipment_unload_detail_slot(
                    current_by_position[position]
                )
                del current_by_position[position]
        page = "detail"
        for slot in loadout.slots:
            if current_by_position.get(slot.position) == slot:
                continue
            if page == "detail":
                self._gems_equipment_open_detail_store(slot)
            else:
                self._gems_equipment_open_store(slot)
            page = self._gems_equipment_select_from_store(slot)
            reader = (
                self._gems_equipment_overview_loadout
                if page == "overview"
                else self._gems_equipment_stable_detail_loadout
            )
            _, _, observed = self._retry_transition_read(
                reader, attempts=30, interval_seconds=0.1
            )
            current_by_position = {
                item.position: item for item in observed if not item.special
            }
        reader = (
            self._gems_equipment_overview_loadout
            if page == "overview"
            else self._gems_equipment_stable_detail_loadout
        )
        _, _, mounted = self._retry_transition_read(
            reader, attempts=30, interval_seconds=0.1
        )
        mounted_regular = tuple(item for item in mounted if not item.special)
        if mounted_regular != loadout.slots:
            raise SemanticGateClosed("GemsFarming equipment loadout did not restore")
        self._gems_equipment_back_to_formation()
        del self._gems_farming_equipment_loadouts[role]
        return loadout

    def set_gems_farming_dock_sort(self, descending: bool) -> Optional[ActionReceipt]:
        """Set the Dock result direction through its exact typed arrow."""

        if not isinstance(descending, bool):
            raise TypeError("GemsFarming Dock sort direction must be boolean")
        state, ui_state = self._enhancement_dock_records()
        root = "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/sort_button/"
        directions = {
            "desc": tuple(
                item
                for item in ui_state.images
                if item.path == root + "desc"
                and item.sprite == "down"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.raycast_target
                and not item.truncated
                and item.bounds is not None
            ),
            "asc": tuple(
                item
                for item in ui_state.images
                if item.path == root + "asc"
                and item.sprite == "up"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.raycast_target
                and not item.truncated
                and item.bounds is not None
            ),
        }
        if len(directions["desc"]) > 1 or len(directions["asc"]) > 1:
            raise SemanticGateClosed("GemsFarming Dock sort direction is ambiguous")
        current_descending = bool(directions["desc"])
        if current_descending == descending:
            return None
        current_name = "desc" if current_descending else "asc"
        if len(directions[current_name]) != 1:
            raise SemanticGateClosed("GemsFarming Dock sort direction is incomplete")
        parents = tuple(
            item
            for item in ui_state.images
            if item.path == root[:-1]
            and item.name == "sort_button"
            and item.sprite == "shaixuan01"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.raycast_target
            and not item.truncated
            and item.bounds is not None
        )
        if len(parents) != 1:
            raise SemanticGateClosed("GemsFarming Dock sort control is incomplete")
        target = parents[0]
        for _ in range(20):
            if not self._blocking_rules(state, "gems-farming/dock/sort"):
                break
            self._sleep(0.05)
            state, refreshed = self._enhancement_dock_records()
            matches = tuple(
                item
                for item in refreshed.images
                if item.path == root[:-1]
                and item.name == "sort_button"
                and item.sprite == "shaixuan01"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.raycast_target
                and not item.truncated
                and item.bounds is not None
            )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "GemsFarming Dock sort direction changed while blocked"
                )
            target = matches[0]
        else:
            raise SemanticGateClosed("GemsFarming Dock sort input stayed blocked")
        receipt = self._click_exact_image(
            state,
            target,
            "gems-farming/dock/sort/" + ("descending" if descending else "ascending"),
        )
        for _ in range(30):
            self._sleep(0.05)
            _, after = self._enhancement_dock_records()
            expected = tuple(
                item
                for item in after.images
                if item.path == root + ("desc" if descending else "asc")
                and item.active_in_hierarchy
                and item.active_and_enabled
            )
            if len(expected) == 1:
                return receipt
        raise SemanticGateClosed("GemsFarming Dock sort direction did not change")

    def set_gems_farming_dock_filter(
        self,
        role: str,
        factions: Tuple[str, ...],
        *,
        enhanceable_only: bool = True,
    ) -> Tuple[ActionReceipt, ...]:
        """Apply the exact ALAS GemsFarming Dock filter for one ship role."""

        role_options = {
            "flagship": ("7", "航母", "3", "可强化"),
            "vanguard": ("3", "驱逐", "4", "可突破"),
        }
        faction_options = {
            "all": ("tpl", "全阵营"),
            "eagle": ("1", "白鹰"),
            "iron": ("4", "铁血"),
        }
        if role not in role_options:
            raise ValueError("GemsFarming role must be flagship or vanguard")
        if not isinstance(enhanceable_only, bool):
            raise TypeError("GemsFarming enhanceable_only must be boolean")
        if (
            not isinstance(factions, tuple)
            or not factions
            or any(item not in faction_options for item in factions)
            or ("all" in factions and len(factions) != 1)
        ):
            raise SemanticGateClosed("GemsFarming Dock faction scope is invalid")
        state, ui_state = self._enhancement_dock_records()
        opener = tuple(
            item
            for item in ui_state.images
            if item.path
            == "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/index_button"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.raycast_target
            and not item.truncated
            and item.bounds is not None
        )
        if len(opener) != 1:
            raise SemanticGateClosed("GemsFarming Dock filter opener is incomplete")
        receipts = [
            self._click_exact_image(
                state, opener[0], "gems-farming/dock/filter/open"
            )
        ]
        self._sleep(0.1)
        index_option, index_label, extra_option, extra_label = role_options[role]
        if not enhanceable_only:
            extra_option, extra_label = "tpl", "无限制"
        # Match upstream ``Setting.reset_first``: selecting each group's
        # default clears stale multi-select state before applying the task
        # filter. Merely proving the desired option selected is insufficient;
        # an old incompatible option can remain selected and produce an empty
        # Dock while every desired label still looks correct.
        choices = [
            ("sort", "1", "等级", "btn_index_yellow"),
            ("index", "tpl", "全部", "btn_index_blue"),
            ("camp", "tpl", "全阵营", "btn_index_blue"),
            ("rarity", "tpl", "全部", "btn_index_blue"),
            ("extraindex", "tpl", "无限制", "btn_index_blue"),
            ("sort", "2", "综合性能", "btn_index_yellow"),
            ("index", index_option, index_label, "btn_index_blue"),
        ]
        choices.extend(
            ("camp", faction_options[item][0], faction_options[item][1], "btn_index_blue")
            for item in factions
        )
        choices.extend(
            (
                ("rarity", "1", "普通", "btn_index_blue"),
                ("extraindex", extra_option, extra_label, "btn_index_blue"),
            )
        )
        for group, option, label, selected_sprite in choices:
            semantic_id = "gems-farming/dock/filter/{0}/{1}".format(
                group, option
            )
            for click_attempt in range(3):
                state, _, image = self._wait_enhancement_filter_option(
                    group, option, label
                )
                if image.sprite == selected_sprite:
                    break
                if image.sprite != "btn_index_grey":
                    raise SemanticGateClosed(
                        "GemsFarming Dock filter state is unknown"
                    )
                for _ in range(20):
                    if not self._blocking_rules(state, semantic_id):
                        break
                    self._sleep(0.05)
                    state, _, image = self._wait_enhancement_filter_option(
                        group, option, label
                    )
                    if image.sprite == selected_sprite:
                        break
                    if image.sprite != "btn_index_grey":
                        raise SemanticGateClosed(
                            "GemsFarming Dock filter state became unknown"
                        )
                else:
                    raise SemanticGateClosed(
                        "GemsFarming Dock filter input stayed blocked"
                    )
                if image.sprite == selected_sprite:
                    break
                receipts.append(
                    self._click_exact_image(state, image, semantic_id)
                )
                for _ in range(30):
                    self._sleep(0.05)
                    _, _, verified = self._wait_enhancement_filter_option(
                        group, option, label
                    )
                    if verified.sprite == selected_sprite:
                        break
                    if verified.sprite != "btn_index_grey":
                        raise SemanticGateClosed(
                            "GemsFarming Dock filter selection became unknown"
                        )
                else:
                    if click_attempt == 2:
                        raise SemanticGateClosed(
                            "GemsFarming Dock filter option did not select"
                        )
                    continue
                break
            else:
                raise SemanticGateClosed(
                    "GemsFarming Dock filter option did not select"
                )
        expected_selected = {
            "sort": {"2"},
            "index": {index_option},
            "camp": {faction_options[item][0] for item in factions},
            "rarity": {"1"},
            "extraindex": {extra_option},
        }
        option_pattern = re.compile(
            r"OverlayCamera/Overlay/UIMain/CustomIndexUI\(Clone\)/index_panel/"
            r"layout/container/indexsort_(sort|index|camp|rarity|extraindex)/"
            r"bg/([^/]+)"
        )

        def selected_options(
            current: UiState,
        ) -> Dict[str, Dict[str, ImageState]]:
            selected: Dict[str, Dict[str, ImageState]] = {
                group: {} for group in expected_selected
            }
            for image in current.images:
                match = option_pattern.fullmatch(image.path)
                if (
                    match is None
                    or image.sprite not in ("btn_index_blue", "btn_index_yellow")
                    or not image.active_in_hierarchy
                    or not image.active_and_enabled
                    or image.truncated
                    or image.bounds is None
                ):
                    continue
                selected[match.group(1)][match.group(2)] = image
            return selected

        # These groups are multi-select in the live client.  Selecting the
        # requested item does not necessarily clear prior selections, so
        # explicitly deselect every observed extra option and prove the exact
        # final set before confirming.
        for _ in range(40):
            state, ui_state = self._retirement_records()
            selected = selected_options(ui_state)
            unexpected = [
                (group, option, image)
                for group, options in selected.items()
                for option, image in options.items()
                if option not in expected_selected[group]
            ]
            if not unexpected:
                if all(
                    set(selected[group]) == expected
                    for group, expected in expected_selected.items()
                ):
                    break
                raise SemanticGateClosed(
                    "GemsFarming Dock filter selected set is incomplete"
                )
            group, option, image = unexpected[0]
            semantic_id = "gems-farming/dock/filter/{0}/{1}/deselect".format(
                group, option
            )
            if self._blocking_rules(state, semantic_id):
                self._sleep(0.05)
                continue
            receipts.append(self._click_exact_image(state, image, semantic_id))
            self._sleep(0.05)
        else:
            raise SemanticGateClosed(
                "GemsFarming Dock filter extras did not clear"
            )
        for _ in range(20):
            state, ui_state = self._retirement_records()
            if not self._blocking_rules(
                state, "gems-farming/dock/filter/confirm"
            ):
                break
            self._sleep(0.05)
        else:
            raise SemanticGateClosed(
                "GemsFarming Dock filter confirm stayed blocked"
            )
        confirm_path = (
            "OverlayCamera/Overlay/UIMain/CustomIndexUI(Clone)/index_panel/"
            "layout/btns/ok"
        )
        confirm = tuple(
            item
            for item in ui_state.images
            if item.path == confirm_path
            and item.sprite == "btn_big_blue"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.raycast_target
            and not item.truncated
            and item.bounds is not None
        )
        confirm_text = tuple(
            item
            for item in ui_state.texts
            if item.path == confirm_path + "/Image"
            and item.text == "确 定"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(confirm) != 1 or len(confirm_text) != 1:
            raise SemanticGateClosed("GemsFarming Dock filter confirm is incomplete")
        receipts.append(
            self._click_exact_image(
                state, confirm[0], "gems-farming/dock/filter/confirm"
            )
        )
        self._retry_transition_read(
            self._enhancement_dock_records,
            attempts=30,
            interval_seconds=0.1,
        )
        return tuple(receipts)

    def cancel_gems_farming_dock_filter_if_visible(
        self,
    ) -> Optional[ActionReceipt]:
        """Cancel only the exact open CustomIndexUI and prove Dock recovery."""

        state, ui_state = self._retirement_records()
        cancel_path = (
            "OverlayCamera/Overlay/UIMain/CustomIndexUI(Clone)/index_panel/"
            "layout/btns/cancel"
        )
        controls = tuple(
            item
            for item in ui_state.images
            if item.path == cancel_path
            and item.name == "cancel"
            and item.sprite == "btn_big_red"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.raycast_target
            and not item.truncated
            and item.bounds is not None
        )
        if not controls:
            return None
        if len(controls) != 1:
            raise SemanticGateClosed(
                "GemsFarming Dock filter cancel is ambiguous"
            )
        semantic_id = "gems-farming/dock/filter/cancel"
        if self._blocking_rules(state, semantic_id):
            raise SemanticGateClosed("GemsFarming Dock filter cancel is blocked")
        receipt = self._click_exact_image(state, controls[0], semantic_id)
        self._retry_transition_read(
            self._enhancement_dock_records,
            attempts=30,
            interval_seconds=0.1,
        )
        return receipt

    def _gems_farming_dock_candidates_once(
        self,
        *,
        ship_ids: Optional[FrozenSet[int]] = None,
    ) -> Tuple[GemsFarmingDockCandidate, ...]:
        """Read one candidate snapshot after a Dock filter or scroll update."""

        state, ui_state = self._enhancement_dock_records()
        base = self.enhancement_dock_candidates()
        rarity_names = {
            "1": "common",
            "2": "rare",
            "3": "elite",
            "4": "super_rare",
            "4_0": "super_rare",
            "5": "ultra",
            # Research/PR ships use the rainbow frame variant while keeping
            # the same Dock card contract.  It may coexist with ordinary
            # GemsFarming candidates in a broad recovery view.
            "5_0": "ultra",
            "prop": "special",
            # META carriers can share a broad recovery page with the exact
            # target ship.  Classify their observed frame locally so an
            # unrelated card does not invalidate every typed candidate; it
            # still cannot satisfy GemsFarming's required common rarity.
            "3_1": "special",
            "4_1": "special",
            "prop4_1": "special",
        }
        type_names = {
            "hangmu": "cv",
            "quzhu": "dd",
            "zhongxun": "ca",
            "zhanlie": "bb",
        }
        result = []
        for candidate in base:
            if ship_ids is not None and candidate.ship_id not in ship_ids:
                continue
            root = candidate.button.path + "/content/"
            if candidate.button.bounds is None:
                raise SemanticGateClosed("GemsFarming Dock card bounds are absent")
            card_bounds = candidate.button.bounds

            def belongs_to_card(item: Union[ImageState, TextState]) -> bool:
                if item.bounds is None:
                    return False
                center = Point(
                    (item.bounds.left + item.bounds.right) / 2.0,
                    (item.bounds.top + item.bounds.bottom) / 2.0,
                )
                return card_bounds.contains(center)

            def images(suffix: str) -> Tuple[ImageState, ...]:
                return tuple(
                    item
                    for item in ui_state.images
                    if item.path == root + suffix
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and belongs_to_card(item)
                )
            emotion = tuple(
                item
                for item in ui_state.texts
                if item.path == root + "energy/Text"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and re.fullmatch(r"(?:[0-9]|[1-9][0-9]|1[0-4][0-9]|150)", item.text)
                and belongs_to_card(item)
            )
            ship_icon = images("ship_icon")
            ship_type = images("info/top/type")
            frame = images("front/frame")
            status = images("dockyard/status")
            if (
                len(emotion) != 1
                or len(ship_icon) != 1
                or len(ship_type) != 1
                or len(frame) != 1
                or len(status) > 1
                or ship_type[0].sprite not in type_names
                or frame[0].sprite not in rarity_names
                or not ship_icon[0].sprite
            ):
                raise SemanticGateClosed(
                    "GemsFarming Dock card semantics are incomplete"
                )
            status_sprite = status[0].sprite if status else ""
            fleet_match = re.fullmatch(r"biandui0?([1-6])", status_sprite)
            if fleet_match is not None:
                fleet_index = int(fleet_match.group(1))
                context = self._gems_farming_open_slot_context
                availability = (
                    "current"
                    if context is not None
                    and context[1] == ship_icon[0].sprite
                    and context[2] == fleet_index
                    else "free"
                )
            elif not status_sprite:
                fleet_index = 0
                availability = "free"
            else:
                fleet_index = 0
                availability = status_sprite
            result.append(
                GemsFarmingDockCandidate(
                    position=candidate.position,
                    ship_id=candidate.ship_id,
                    ship_name=candidate.ship_name,
                    ship_sprite=ship_icon[0].sprite,
                    ship_type=type_names[ship_type[0].sprite],
                    rarity=rarity_names[frame[0].sprite],
                    level=candidate.level,
                    emotion=int(emotion[0].text),
                    fleet_index=fleet_index,
                    status=availability,
                    button=candidate.button,
                )
            )
        if state.generation > ui_state.generation:
            raise SemanticGateClosed("GemsFarming Dock candidate snapshots are incoherent")
        return tuple(result)

    def gems_farming_dock_candidates(
        self, *, ship_ids: Optional[Iterable[int]] = None
    ) -> Tuple[GemsFarmingDockCandidate, ...]:
        """Return a stable typed Dock view without OCR or templates."""

        exact_ship_ids: Optional[FrozenSet[int]] = None
        if ship_ids is not None:
            exact_ship_ids = frozenset(ship_ids)
            if (
                not exact_ship_ids
                or any(
                    isinstance(ship_id, bool)
                    or not isinstance(ship_id, int)
                    or ship_id <= 0
                    for ship_id in exact_ship_ids
                )
            ):
                raise ValueError("GemsFarming exact ship IDs are invalid")

        retryable = (
            "enhancement Dock card identity is incomplete",
            "GemsFarming Dock card semantics are incomplete",
            "GemsFarming Dock candidate snapshots are incoherent",
        )
        last_error: Optional[SemanticGateClosed] = None
        last_result: Tuple[GemsFarmingDockCandidate, ...] = ()
        # The live Dock replaces its virtualized cards with off-screen ``-1``
        # placeholders while a new filter is loading.  Upstream deliberately
        # waits about 1.2 seconds before treating that view as empty.  Preserve
        # that timing boundary here: a non-empty typed view may return early,
        # while a genuinely empty filter still returns after the bounded wait.
        for attempt in range(13):
            try:
                if exact_ship_ids is None:
                    last_result = self._gems_farming_dock_candidates_once()
                else:
                    last_result = self._gems_farming_dock_candidates_once(
                        ship_ids=exact_ship_ids
                    )
            except SemanticGateClosed as exc:
                if str(exc) not in retryable:
                    raise
                last_error = exc
            else:
                if last_result:
                    return last_result
                last_error = None
            if attempt < 12:
                self._sleep(0.1)
        if last_error is not None:
            raise SemanticGateClosed(
                "GemsFarming Dock candidate snapshots did not stabilize"
            ) from last_error
        return last_result

    def click_gems_farming_candidate(
        self, candidate: GemsFarmingDockCandidate
    ) -> ActionReceipt:
        """Select one unchanged typed candidate and prove the 1/1 counter."""

        if not isinstance(candidate, GemsFarmingDockCandidate):
            raise TypeError("GemsFarming candidate is invalid")
        identity = (
            candidate.ship_id,
            candidate.ship_name,
            candidate.ship_sprite,
            candidate.ship_type,
            candidate.rarity,
            candidate.level,
            candidate.emotion,
            candidate.fleet_index,
            candidate.status,
        )
        stable_signature: Optional[Tuple[str, Bounds, Point]] = None
        stable_reads = 0
        for attempt in range(20):
            # A broad recovery filter may contain unrelated cards whose
            # optional semantics are incomplete. Re-prove only the selected
            # immutable ship identity here; duplicate cards with the same ID
            # remain visible and must still resolve uniquely by full identity
            # and bounds below.
            current = self.gems_farming_dock_candidates(
                ship_ids=(candidate.ship_id,)
            )
            matches = tuple(item for item in current if item == candidate)
            if len(matches) != 1:
                matches = tuple(
                    item
                    for item in current
                    if (
                        item.ship_id,
                        item.ship_name,
                        item.ship_sprite,
                        item.ship_type,
                        item.rarity,
                        item.level,
                        item.emotion,
                        item.fleet_index,
                        item.status,
                    )
                    == identity
                )
            if len(matches) != 1:
                raise SemanticGateClosed(
                    "GemsFarming Dock candidate changed or became ambiguous"
                )
            target = matches[0].button
            state = self.read_state()
            buttons = tuple(
                item
                for item in state.buttons
                if item.path == target.path
                and item.name == target.name
                and item.actionable
                and item.bounds == target.bounds
            )
            if (
                len(buttons) == 1
                and target.point is not None
                and target.bounds is not None
            ):
                signature = (target.path, target.bounds, target.point)
                if signature == stable_signature:
                    stable_reads += 1
                else:
                    stable_signature = signature
                    stable_reads = 1
                if stable_reads >= 3:
                    break
            else:
                stable_signature = None
                stable_reads = 0
            if attempt < 19:
                self._sleep(0.05)
        else:
            raise SemanticGateClosed("GemsFarming Dock candidate is not actionable")
        if self._blocking_rules(state, "gems-farming/dock/candidate"):
            raise SemanticGateClosed("GemsFarming Dock candidate input is blocked")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        receipt = ActionReceipt(
            semantic_id="gems-farming/dock/ship/{0}".format(candidate.ship_id),
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )
        count_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/select_panel/"
            "bottom_info/bg_input/count"
        )
        for _ in range(40):
            self._sleep(0.05)
            # The selected-count postcondition owns only this exact Text.
            # Large Dock views may truncate unrelated Toggle records.
            ui_state = self.read_text_state()
            selected = tuple(
                item
                for item in ui_state.texts
                if item.path == count_path
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and re.fullmatch(r"<color=#[0-9A-Fa-f]{8}>1</color>/1", item.text)
            )
            if len(selected) == 1:
                return receipt
        raise SemanticGateClosed("GemsFarming Dock candidate did not select")

    def cancel_gems_farming_candidate_selection(self) -> ActionReceipt:
        hard_context = self._gems_farming_hard_open_slot_context
        if hard_context is not None:
            state = self.read_state()
            controls = tuple(
                item
                for item in state.buttons
                if item.path.endswith("/select_panel/cancel_button")
                and item.name == "cancel_button"
            )
            if len(controls) != 1:
                raise SemanticGateClosed(
                    "GemsFarming hard Dock cancel is absent or ambiguous"
                )
            receipt = self._gems_equipment_click_button(
                state, controls[0], "tactical/dock/cancel"
            )
            stage_code, _, _, _ = hard_context
            self._retry_transition_read(
                lambda: self.campaign_fleet_selection_state(stage_code),
                attempts=50,
                interval_seconds=0.1,
            )
            self._gems_farming_hard_open_slot_context = None
            return receipt
        receipt = self.click("tactical/dock/cancel")
        self._retry_transition_read(
            self._gems_farming_formation_records,
            attempts=50,
            interval_seconds=0.1,
        )
        return receipt

    def confirm_gems_farming_candidate_selection(
        self, candidate: GemsFarmingDockCandidate, role: str
    ) -> ActionReceipt:
        """Confirm exactly one selected ship and prove it mounted in formation."""

        if not isinstance(candidate, GemsFarmingDockCandidate):
            raise TypeError("GemsFarming candidate is invalid")
        slot_names = {"flagship": "main_1", "vanguard": "vanguard_1"}
        if role not in slot_names:
            raise ValueError("GemsFarming role must be flagship or vanguard")
        # A large unfiltered Dock can exhaust the unrelated Toggle slice.
        # Confirmation owns only the exact 1/1 Text record; keep that slice
        # complete and fail closed without making Toggle completeness global.
        ui_state = self.read_text_state()
        count_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/select_panel/"
            "bottom_info/bg_input/count"
        )
        selected = tuple(
            item
            for item in ui_state.texts
            if item.path == count_path
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and re.fullmatch(r"<color=#[0-9A-Fa-f]{8}>1</color>/1", item.text)
        )
        if len(selected) != 1:
            raise SemanticGateClosed("GemsFarming Dock selection count changed")
        hard_context = self._gems_farming_hard_open_slot_context
        if hard_context is not None:
            state = self.read_state()
            controls = tuple(
                item
                for item in state.buttons
                if item.path.endswith("/select_panel/confirm_button")
                and item.name == "confirm_button"
            )
            if len(controls) != 1:
                raise SemanticGateClosed(
                    "GemsFarming hard Dock confirm is absent or ambiguous"
                )
            receipt = self._gems_equipment_click_button(
                state, controls[0], "tactical/dock/confirm"
            )
            stage_code, fleet_index, hard_role, before = hard_context
            if role != hard_role:
                raise SemanticGateClosed(
                    "GemsFarming hard replacement role changed before confirmation"
                )
            for _ in range(60):
                self._sleep(0.1)
                try:
                    _, _, cards, after = self._gems_farming_hard_role_cards(
                        stage_code, fleet_index, role
                    )
                except SemanticGateClosed:
                    continue
                if len(cards) == 3 and after == before + (candidate.ship_sprite,):
                    self._gems_farming_hard_open_slot_context = None
                    return receipt
            raise SemanticGateClosed(
                "GemsFarming hard replacement postcondition was not proven"
            )
        receipt = self.click("tactical/dock/confirm")
        expected_suffix = "/{0}_root/mouseChild".format(candidate.ship_sprite)
        for _ in range(60):
            self._sleep(0.1)
            try:
                _, after, _ = self._gems_farming_formation_records()
            except SemanticGateClosed:
                continue
            slot_path = (
                "UICamera/Canvas/UIMain/FormationUI(Clone)/adapt/GridFrame/"
                + slot_names[role]
                + "/shadow"
            )
            slots = tuple(item for item in after.images if item.path == slot_path)
            if len(slots) != 1 or slots[0].bounds is None:
                continue
            slot_center_x = (slots[0].bounds.left + slots[0].bounds.right) / 2.0
            mounted = tuple(
                item
                for item in after.images
                if item.path.endswith(expected_suffix)
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.bounds is not None
                and abs(
                    (item.bounds.left + item.bounds.right) / 2.0 - slot_center_x
                )
                <= 2.0
            )
            if len(mounted) == 1:
                return receipt
        raise SemanticGateClosed("GemsFarming replacement postcondition was not proven")

    def set_enhancement_dock_favourite(self, enabled: bool) -> Optional[ActionReceipt]:
        """Set the Dock favourite scope using its currently rendered toggle."""

        if not isinstance(enabled, bool):
            raise TypeError("enhancement favourite scope must be boolean")
        root = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/switch/toggles/"
            "preference_toggle/"
        )
        state, ui_state = self._enhancement_dock_records()
        active = {
            suffix: tuple(
                item
                for item in ui_state.images
                if item.path == root + suffix
                and item.sprite == sprite
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            for suffix, sprite in (
                ("on", "changyong_butten01"),
                ("off", "changyong_butten02"),
            )
        }
        if len(active["on"]) > 1 or len(active["off"]) > 1:
            raise SemanticGateClosed("Dock favourite state is ambiguous")
        # The live client keeps the off layer active when favourite is on;
        # the on layer is therefore the positive state discriminator.
        current = bool(active["on"])
        if current == enabled:
            return None
        target_name = "on" if enabled else "off"
        current_name = "on" if current else "off"
        if len(active[current_name]) != 1:
            raise SemanticGateClosed("Dock favourite state is incomplete")
        receipt = self._click_exact_image(
            state,
            active[current_name][0],
            "enhancement/dock/favourite/" + target_name,
        )
        deadline = time.monotonic() + 5.0
        while time.monotonic() < deadline:
            _, after = self._enhancement_dock_records()
            visible = {
                suffix: tuple(
                    item
                    for item in after.images
                    if item.path == root + suffix
                    and item.sprite == sprite
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and item.bounds is not None
                )
                for suffix, sprite in (
                    ("on", "changyong_butten01"),
                    ("off", "changyong_butten02"),
                )
            }
            if enabled and len(visible["on"]) == 1:
                return receipt
            if (
                not enabled
                and not visible["on"]
                and len(visible["off"]) == 1
            ):
                return receipt
            self._sleep(0.05)
        raise SemanticGateClosed("Dock favourite state did not change")

    def set_enhancement_dock_filter(
        self,
        ship_type: Optional[str],
        *,
        enhanceable_only: bool = True,
    ) -> Tuple[ActionReceipt, ...]:
        """Apply ALAS's Dock type filter, optionally retaining maxed ships."""

        index_options = {
            None: ("tpl", "全部"),
            "dd": ("3", "驱逐"),
            "cl": ("4", "轻巡"),
            "ca": ("5", "重巡"),
            "bb": ("6", "战列"),
            "cv": ("7", "航母"),
            "repair": ("8", "维修"),
            "ss": ("9", "潜艇"),
            "others": ("10", "其他"),
        }
        if ship_type not in index_options:
            raise ValueError("enhancement ship type is unsupported")
        if not isinstance(enhanceable_only, bool):
            raise TypeError("enhancement Dock enhanceable_only must be boolean")
        state, ui_state = self._enhancement_dock_records()
        filter_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/index_button"
        )
        opener = next(item for item in ui_state.images if item.path == filter_path)
        receipts = [
            self._click_exact_image(state, opener, "enhancement/dock/filter/open")
        ]
        self._sleep(0.1)
        choices = (
            ("sort", "1", "等级", "btn_index_yellow"),
            ("index", index_options[ship_type][0], index_options[ship_type][1], "btn_index_blue"),
            ("camp", "tpl", "全阵营", "btn_index_blue"),
            ("rarity", "tpl", "全部", "btn_index_blue"),
            (
                "extraindex",
                "3" if enhanceable_only else "tpl",
                "可强化" if enhanceable_only else "无限制",
                "btn_index_blue",
            ),
        )
        for group, option, label, selected_sprite in choices:
            semantic_id = "enhancement/dock/filter/{0}/{1}".format(
                group, option
            )
            for click_attempt in range(3):
                state, _, image = self._wait_enhancement_filter_option(
                    group, option, label
                )
                if image.sprite == selected_sprite:
                    break
                if image.sprite != "btn_index_grey":
                    raise SemanticGateClosed(
                        "enhancement Dock filter state is unknown"
                    )
                for _ in range(20):
                    if not self._blocking_rules(state, semantic_id):
                        break
                    self._sleep(0.05)
                    state, _, image = self._wait_enhancement_filter_option(
                        group, option, label
                    )
                    if image.sprite == selected_sprite:
                        break
                    if image.sprite != "btn_index_grey":
                        raise SemanticGateClosed(
                            "enhancement Dock filter state became unknown"
                        )
                else:
                    raise SemanticGateClosed(
                        "enhancement Dock filter input stayed blocked"
                    )
                if image.sprite == selected_sprite:
                    break
                receipts.append(
                    self._click_exact_image(state, image, semantic_id)
                )
                for _ in range(30):
                    self._sleep(0.05)
                    _, _, verified = self._wait_enhancement_filter_option(
                        group, option, label
                    )
                    if verified.sprite == selected_sprite:
                        break
                    if verified.sprite != "btn_index_grey":
                        raise SemanticGateClosed(
                            "enhancement Dock filter selection became unknown"
                        )
                else:
                    if click_attempt == 2:
                        raise SemanticGateClosed(
                            "enhancement Dock filter option did not select"
                        )
                    continue
                break
            else:
                raise SemanticGateClosed(
                    "enhancement Dock filter option did not select"
                )
        for _ in range(20):
            state, ui_state = self._retirement_records()
            if not self._blocking_rules(state, "enhancement/dock/filter/confirm"):
                break
            self._sleep(0.05)
        else:
            raise SemanticGateClosed("enhancement Dock filter confirm stayed blocked")
        confirm_path = (
            "OverlayCamera/Overlay/UIMain/CustomIndexUI(Clone)/index_panel/"
            "layout/btns/ok"
        )
        confirm = tuple(
            item
            for item in ui_state.images
            if item.path == confirm_path
            and item.sprite == "btn_big_blue"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        confirm_text = tuple(
            item
            for item in ui_state.texts
            if item.path == confirm_path + "/Image"
            and item.text == "确 定"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(confirm) != 1 or len(confirm_text) != 1:
            raise SemanticGateClosed("enhancement Dock filter confirm is incomplete")
        receipts.append(
            self._click_exact_image(state, confirm[0], "enhancement/dock/filter/confirm")
        )
        self._retry_transition_read(
            self._enhancement_dock_records,
            attempts=20,
            interval_seconds=0.1,
        )
        return tuple(receipts)

    def enhancement_dock_candidates(self) -> Tuple[EnhancementDockCandidate, ...]:
        """Read all currently visible enhanceable cards in Dock grid order."""

        state, ui_state = self._enhancement_dock_records()
        prefix = "UICamera/Canvas/UIMain/DockyardUI(Clone)/main/ship_container/ships/"
        buttons = tuple(
            item
            for item in state.buttons
            if re.fullmatch(r"[1-9][0-9]{5,7}", item.name)
            and item.path == prefix + item.name
            and item.actionable
            and item.bounds is not None
            and item.bounds.left >= 0
            and item.bounds.right <= self.fingerprint.width
            and item.bounds.top >= 0
            and item.bounds.bottom <= self.fingerprint.height + 20
        )
        ordered = tuple(
            sorted(buttons, key=lambda item: (item.bounds.top, item.bounds.left))
        )
        result = []
        for position, button in enumerate(ordered):
            root = button.path + "/content/"
            assert button.bounds is not None

            def belongs_to_button(item: TextState) -> bool:
                if item.bounds is None:
                    return False
                return button.bounds.contains(
                    Point(
                        (item.bounds.left + item.bounds.right) / 2.0,
                        (item.bounds.top + item.bounds.bottom) / 2.0,
                    )
                )

            name = tuple(
                item
                for item in ui_state.texts
                if item.path == root + "info/name_mask/name"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.text.strip()
                and belongs_to_button(item)
            )
            level = tuple(
                item
                for item in ui_state.texts
                if item.path == root + "dockyard/lv/Text"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and re.fullmatch(r"[1-9][0-9]{0,2}", item.text)
                and belongs_to_button(item)
            )
            if (
                not name
                or not level
                or len({item.text.strip() for item in name}) != 1
                or len({item.text for item in level}) != 1
            ):
                raise SemanticGateClosed("enhancement Dock card identity is incomplete")
            result.append(
                EnhancementDockCandidate(
                    position=position,
                    ship_id=int(button.name),
                    ship_name=name[0].text.strip(),
                    level=int(level[0].text),
                    button=button,
                )
            )
        return tuple(result)

    def open_enhancement_dock_candidate(
        self,
        position: int,
        ship_id: int,
        ship_name: str,
        level: int,
    ) -> ActionReceipt:
        """Enter one exact Dock card and switch to its enhancement page."""

        candidates = self.enhancement_dock_candidates()
        matches = tuple(
            item
            for item in candidates
            if item.position == position
            and item.ship_id == ship_id
            and item.ship_name == ship_name
            and item.level == level
        )
        if len(matches) != 1:
            raise SemanticGateClosed("enhancement Dock candidate changed")
        target = matches[0].button
        assert target.point is not None and target.bounds is not None
        state = self.read_state()
        current = tuple(
            item
            for item in state.buttons
            if item.path == target.path
            and item.actionable
            and item.bounds == target.bounds
        )
        if len(current) != 1:
            raise SemanticGateClosed("enhancement Dock candidate changed before input")
        if self._blocking_rules(state, "enhancement/dock/ship"):
            raise SemanticGateClosed("enhancement Dock candidate input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before Dock ship input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        receipt = ActionReceipt(
            semantic_id="enhancement/dock/ship/{0}".format(ship_id),
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )
        deadline = time.monotonic() + 5.0
        toggle_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/left_length/frame/root/"
            "intensify_toggle"
        )
        while time.monotonic() < deadline:
            ui_state = self._retirement_records()[1]
            toggles = tuple(
                item
                for item in ui_state.toggles
                if item.path == toggle_path
                and item.name == "intensify_toggle"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
                and item.point is not None
                and item.bounds is not None
                and item.bounds.contains(item.point)
            )
            if len(toggles) == 1:
                toggle = toggles[0]
                if not toggle.checked:
                    if self._foreground_component() != self.fingerprint.component:
                        raise SemanticGateClosed("game activity changed before enhancement tab input")
                    self._tap(int(round(toggle.point.x)), int(round(toggle.point.y)))
                self._retry_transition_read(
                    self.enhancement_preview,
                    attempts=30,
                    interval_seconds=0.1,
                )
                return receipt
            self._sleep(0.05)
        raise SemanticGateClosed("ship enhancement tab did not become available")

    def _click_exact_toggle(
        self,
        state: OracleState,
        toggle: ToggleState,
        semantic_id: str,
    ) -> ActionReceipt:
        """Tap one exact typed toggle at its exported semantic point."""

        if (
            not toggle.active_in_hierarchy
            or not toggle.active_and_enabled
            or not toggle.interactable
            or toggle.bounds is None
        ):
            raise SemanticGateClosed(semantic_id + " toggle is incomplete")
        point = toggle.point
        if point is None:
            raise SemanticGateClosed(semantic_id + " toggle has no input point")
        if not toggle.bounds.contains(point) or self._blocking_rules(
            state, semantic_id
        ):
            raise SemanticGateClosed(semantic_id + " input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before toggle input")
        self._tap(int(round(point.x)), int(round(point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed after toggle input")
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=state.generation,
            point=point,
            bounds=toggle.bounds,
            path=toggle.path,
        )

    @staticmethod
    def _enhancement_detail_toggle(
        ui_state: UiState,
        *,
        name: str,
        path: str,
    ) -> ToggleState:
        if ui_state.method_mask & 0x1 == 0:
            raise SemanticGateClosed("typed Unity Toggle snapshot is incomplete")
        toggles = tuple(
            item
            for item in ui_state.toggles
            if item.name == name
            and item.path == path
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.bounds is not None
        )
        if len(toggles) != 1:
            raise SemanticGateClosed("enhancement detail toggle is incomplete")
        return toggles[0]

    def _wait_enhancement_detail_toggle(
        self,
        *,
        name: str,
        path: str,
        checked: Optional[bool] = None,
    ) -> Tuple[OracleState, UiState, ToggleState]:
        last_error: Optional[SemanticGateClosed] = None
        for attempt in range(30):
            try:
                state, ui_state = self._retirement_records()
                toggle = self._enhancement_detail_toggle(
                    ui_state, name=name, path=path
                )
                if checked is not None and toggle.checked is not checked:
                    raise SemanticGateClosed("enhancement detail toggle has not changed")
                return state, ui_state, toggle
            except SemanticGateClosed as exc:
                last_error = exc
                if attempt < 29:
                    self._sleep(0.05)
        raise SemanticGateClosed(
            "enhancement detail toggle did not stabilize"
        ) from last_error

    @staticmethod
    def _enhancement_detail_ship_name(
        ui_state: UiState,
    ) -> str:
        path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/name/"
            "nameRect/name_mask/Text"
        )
        names = tuple(
            item.text.strip()
            for item in ui_state.texts
            if item.path == path
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.text.strip()
        )
        if len(names) != 1:
            raise SemanticGateClosed("enhancement detail ship identity is incomplete")
        return names[0]

    def _return_from_enhancement_detail_to_dock(self) -> ActionReceipt:
        """Leave the ship detail tab and prove the original Dock grid returns."""

        state = self.read_state()
        suffix = "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/back_btn"
        buttons = tuple(
            item
            for item in state.buttons
            if item.path.endswith(suffix) and item.name == "back_btn" and item.actionable
        )
        if len(buttons) != 1:
            raise SemanticGateClosed("enhancement detail back control is incomplete")
        target = buttons[0]
        assert target.point is not None and target.bounds is not None
        if self._blocking_rules(state, "enhancement/detail/back"):
            raise SemanticGateClosed("enhancement detail back input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed(
                "game activity changed before enhancement detail back input"
            )
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        receipt = ActionReceipt(
            semantic_id="enhancement/detail/back",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )
        self._retry_transition_read(
            self._enhancement_dock_records,
            attempts=30,
            interval_seconds=0.1,
        )
        return receipt

    def set_enhancement_dock_candidate_favourite(
        self,
        position: int,
        ship_id: int,
        ship_name: str,
        level: int,
        enabled: bool,
    ) -> Tuple[ActionReceipt, ...]:
        """Set one exact Dock card's in-client common/favourite state.

        This is intentionally separate from the Dock scope toggle used by the
        task.  It gives live qualification a reversible way to seed and then
        restore a real favourite target without changing ALAS task control.
        """

        if not isinstance(enabled, bool):
            raise TypeError("enhancement candidate favourite must be boolean")
        receipts = [
            self.open_enhancement_dock_candidate(
                position, ship_id, ship_name, level
            )
        ]
        detail_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/left_length/frame/root/"
            "detail_toggle"
        )
        state, ui_state, detail = self._wait_enhancement_detail_toggle(
            name="detail_toggle", path=detail_path
        )
        if detail.checked is not True:
            receipts.append(
                self._click_exact_toggle(
                    state, detail, "enhancement/detail/tab"
                )
            )
        common_path = (
            "OverlayCamera/Overlay/UIMain/detail_container(Adapt)/detail_container/"
            "ShipDetailView(Clone)/common_toggle"
        )
        state, ui_state, common = self._wait_enhancement_detail_toggle(
            name="common_toggle", path=common_path
        )
        if self._enhancement_detail_ship_name(ui_state) != ship_name:
            raise SemanticGateClosed("enhancement detail ship changed")
        expected_sprite = "common_active" if enabled else "common_deactive"
        current_sprite = "common_active" if common.checked else "common_deactive"
        visible = tuple(
            item
            for item in ui_state.images
            if item.path == common_path + ("/on" if common.checked else "/off")
            and item.sprite == current_sprite
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
        )
        if len(visible) != 1:
            raise SemanticGateClosed("enhancement candidate favourite state is incomplete")
        if common.checked != enabled:
            # The detail toggle exposes the control before its hit target is
            # ready on the live client.  Refresh the typed state once after
            # the panel has settled, then use its exact input point.
            self._sleep(0.2)
            state, ui_state, common = self._wait_enhancement_detail_toggle(
                name="common_toggle", path=common_path
            )
            if common.checked != enabled:
                if self._enhancement_detail_ship_name(ui_state) != ship_name:
                    raise SemanticGateClosed("enhancement detail ship changed")
                receipts.append(
                    self._click_exact_toggle(
                        state,
                        common,
                        "enhancement/detail/favourite/"
                        + ("on" if enabled else "off"),
                    )
                )
            _, after, common = self._wait_enhancement_detail_toggle(
                name="common_toggle", path=common_path, checked=enabled
            )
            after_visible = tuple(
                item
                for item in after.images
                if item.path == common_path + ("/on" if enabled else "/off")
                and item.sprite == expected_sprite
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.bounds is not None
            )
            if len(after_visible) != 1:
                raise SemanticGateClosed(
                    "enhancement candidate favourite did not change"
                )
        receipts.append(self._return_from_enhancement_detail_to_dock())
        return tuple(receipts)

    def return_to_enhancement_dock(self) -> ActionReceipt:
        """Leave a completed/empty enhancement target and prove Dock recovery."""

        state, _ = self._enhancement_records()
        suffix = "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/back_btn"
        buttons = tuple(
            item
            for item in state.buttons
            if item.path.endswith(suffix) and item.name == "back_btn" and item.actionable
        )
        if len(buttons) != 1:
            raise SemanticGateClosed("enhancement back control is incomplete")
        target = buttons[0]
        assert target.point is not None and target.bounds is not None
        if self._blocking_rules(state, "enhancement/dock/back"):
            raise SemanticGateClosed("enhancement back input is blocked")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before enhancement back input")
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        receipt = ActionReceipt(
            semantic_id="enhancement/dock/back",
            generation=state.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )
        self._retry_transition_read(
            self._enhancement_dock_records,
            attempts=30,
            interval_seconds=0.1,
        )
        return receipt

    def reset_enhancement_dock(self) -> Tuple[ActionReceipt, ...]:
        """Restore ALAS's normal Dock filter after an enhancement task."""

        receipts = list(self.set_enhancement_dock_filter(None))
        favourite = self.set_enhancement_dock_favourite(False)
        if favourite is not None:
            receipts.append(favourite)
        # set_enhancement_dock_filter(None) intentionally selects enhanceable;
        # reset the final extra option to the official no-limit default.
        state, ui_state = self._enhancement_dock_records()
        opener = next(
            item
            for item in ui_state.images
            if item.path.endswith("/adapt/top/index_button")
        )
        receipts.append(
            self._click_exact_image(state, opener, "enhancement/dock/reset/open")
        )
        self._sleep(0.1)
        no_limit_error: Optional[SemanticGateClosed] = None
        for attempt in range(20):
            state, ui_state = self._retirement_records()
            try:
                no_limit = self._enhancement_filter_option(
                    ui_state, "extraindex", "tpl", "无限制"
                )
            except SemanticGateClosed as exc:
                no_limit_error = exc
                self._sleep(0.05)
                continue
            if no_limit.sprite == "btn_index_blue":
                break
            if no_limit.sprite != "btn_index_grey":
                raise SemanticGateClosed("Dock reset extra filter is unknown")
            if self._blocking_rules(state, "enhancement/dock/reset/no-limit"):
                self._sleep(0.05)
                continue
            receipts.append(
                self._click_exact_image(
                    state, no_limit, "enhancement/dock/reset/no-limit"
                )
            )
            break
        else:
            raise SemanticGateClosed(
                "Dock reset extra filter did not stabilize"
            ) from no_limit_error
        for attempt in range(20):
            state, ui_state = self._retirement_records()
            if not self._blocking_rules(state, "enhancement/dock/reset/confirm"):
                break
            self._sleep(0.05)
        else:
            raise SemanticGateClosed("Dock reset confirmation stayed blocked")
        confirm_path = (
            "OverlayCamera/Overlay/UIMain/CustomIndexUI(Clone)/index_panel/"
            "layout/btns/ok"
        )
        confirm = tuple(
            item
            for item in ui_state.images
            if item.path == confirm_path
            and item.sprite == "btn_big_blue"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if len(confirm) != 1:
            raise SemanticGateClosed("Dock reset confirmation is incomplete")
        receipts.append(
            self._click_exact_image(state, confirm[0], "enhancement/dock/reset/confirm")
        )
        self._retry_transition_read(
            self._enhancement_dock_records,
            attempts=20,
            interval_seconds=0.1,
        )
        return tuple(receipts)

    def _enhancement_records(self) -> Tuple[OracleState, UiState]:
        """Read one coherent official enhancement-page slice."""

        last_error: Optional[SemanticGateClosed] = None
        for attempt in range(8):
            state = self.read_state()
            ui_state = self.read_ui_state()
            if not state.generation <= ui_state.generation <= state.generation + 2:
                last_error = SemanticGateClosed(
                    "enhancement button and UI snapshots are not coherent"
                )
            elif ui_state.method_mask & 0xF != 0xF:
                last_error = SemanticGateClosed(
                    "typed enhancement UI access is incomplete"
                )
            else:
                target_path = (
                    "OverlayCamera/Overlay/UIMain/blur_panel/adapt/name/"
                    "nameRect/name_mask/Text"
                )
                target = tuple(
                    item
                    for item in ui_state.texts
                    if item.path.endswith(target_path)
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                    and item.text.strip()
                )
                toggle = tuple(
                    item
                    for item in ui_state.toggles
                    if item.name == "intensify_toggle"
                    and item.path.endswith(
                        "OverlayCamera/Overlay/UIMain/blur_panel/adapt/"
                        "left_length/frame/root/intensify_toggle"
                    )
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and item.checked
                )
                title = tuple(
                    item
                    for item in ui_state.texts
                    if item.path.endswith(
                        "blur_panel(Adapt)/blur_panel/main/bg/"
                        "add_ship_panel/title/Image"
                    )
                    and item.text == "添 加 素 材"
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and not item.truncated
                )
                if len(target) == len(toggle) == len(title) == 1:
                    return state, ui_state
                last_error = SemanticGateClosed(
                    "official enhancement page identity is incomplete"
                )
            if attempt < 7:
                self._sleep(0.05)
        raise SemanticGateClosed(
            "enhancement snapshots did not stabilize"
        ) from last_error

    def enhancement_preview(self) -> EnhancementPreview:
        """Read target, attributes, and selected materials without consuming ships."""

        state, ui_state = self._enhancement_records()
        target_path = (
            "OverlayCamera/Overlay/UIMain/blur_panel/adapt/name/nameRect/name_mask/Text"
        )
        target = next(
            item.text.strip()
            for item in ui_state.texts
            if item.path.endswith(target_path)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.text.strip()
        )
        attribute_root = (
            "OverlayCamera/Overlay/UIMain/blur_panel(Adapt)/blur_panel/main/"
            "bg/property_panel/attrs/attr_"
        )
        grouped: Dict[int, Dict[str, str]] = {}
        for item in ui_state.texts:
            if (
                not item.path.startswith(attribute_root)
                or not item.active_in_hierarchy
                or not item.active_and_enabled
                or item.truncated
            ):
                continue
            match = re.match(re.escape(attribute_root) + r"([0-9]+)/(.+)$", item.path)
            if match is None:
                continue
            index = int(match.group(1))
            suffix = match.group(2)
            keys = {
                "info/info_container/name": "name",
                "info/info_container/value": "current",
                "info/info_container/addition": "addition",
                "info/max_container/Text": "maximum",
                "exp_container/Text": "exp",
            }
            key = keys.get(suffix)
            if key is not None:
                grouped.setdefault(index, {})[key] = item.text.strip()
        attributes: List[EnhancementAttributeState] = []
        for index, values in sorted(grouped.items()):
            if set(values) != {"name", "current", "addition", "maximum", "exp"}:
                raise SemanticGateClosed("enhancement attribute row is incomplete")
            addition_match = re.fullmatch(r"\+([0-9]+)", values["addition"])
            if (
                addition_match is None
                or not values["current"].isdigit()
                or not values["maximum"].isdigit()
            ):
                raise SemanticGateClosed("enhancement attribute values are malformed")
            exp_current: Optional[int]
            exp_total: Optional[int]
            if values["exp"] == "MAX":
                exp_current = exp_total = None
            else:
                exp_match = re.fullmatch(r"([0-9]+)/([0-9]+)", values["exp"])
                if exp_match is None:
                    raise SemanticGateClosed("enhancement experience is malformed")
                exp_current, exp_total = map(int, exp_match.groups())
            attributes.append(
                EnhancementAttributeState(
                    index=index,
                    name=values["name"],
                    current=int(values["current"]),
                    maximum=int(values["maximum"]),
                    addition=int(addition_match.group(1)),
                    exp_current=exp_current,
                    exp_total=exp_total,
                )
            )
        if not attributes:
            raise SemanticGateClosed("enhancement attributes are absent")

        ship_root = (
            "OverlayCamera/Overlay/UIMain/blur_panel(Adapt)/blur_panel/main/"
            "bg/add_ship_panel/ships/shiptpl"
        )
        selected = tuple(
            button
            for button in state.buttons
            if re.fullmatch(re.escape(ship_root) + r"(?: \(([0-9]+)\))?", button.path)
            and button.name.startswith("shiptpl")
            and button.active_in_hierarchy
            and button.active_and_enabled
        )
        materials: List[EnhancementMaterialState] = []
        material_shapes: List[bool] = []
        for button in sorted(
            selected,
            key=lambda item: item.bounds.left if item.bounds is not None else 9999,
        ):
            suffix_match = re.fullmatch(
                re.escape(ship_root) + r"(?: \(([0-9]+)\))?", button.path
            )
            assert suffix_match is not None
            slot = 0 if suffix_match.group(1) is None else int(suffix_match.group(1))
            level = tuple(
                item
                for item in ui_state.texts
                if item.path == button.path + "/IconTpl/icon_bg/lv/Text"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.text.isdigit()
            )
            # Unity keeps the material-slot Button objects active after the
            # official clear action.  The populated card identity is the
            # exact level Text plus rarity/icon Images, not the retained
            # parent Button alone.
            if not level:
                continue
            rarity = tuple(
                item
                for item in ui_state.images
                if item.path == button.path + "/IconTpl/icon_bg"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
            )
            icon = tuple(
                item
                for item in ui_state.images
                if item.path == button.path + "/IconTpl/icon_bg/icon"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
                and item.sprite
            )
            if len(level) != 1 or len(rarity) != 1 or len(icon) != 1:
                raise SemanticGateClosed("enhancement material identity is incomplete")
            child_images = tuple(
                item
                for item in ui_state.images
                if item.path.startswith(button.path + "/")
                and item.active_in_hierarchy
                and item.active_and_enabled
                and not item.truncated
            )
            exact_signatures = {
                "/IconTpl/icon_bg/lv/lv_bg": "bg_lv",
                "/IconTpl/icon_bg/frame": "frame",
                "/IconTpl/bg": "white_dot",
                "/IconTpl": "white_dot",
                "/add": "sucai_butten",
            }
            observed_exact = {
                suffix: tuple(
                    item
                    for item in child_images
                    if item.path == button.path + suffix
                    and item.sprite == expected_sprite
                )
                for suffix, expected_sprite in exact_signatures.items()
            }
            star_background = tuple(
                item
                for item in child_images
                if re.fullmatch(
                    re.escape(button.path)
                    + r"/IconTpl/icon_bg/stars/startpl(?:\(Clone\))?",
                    item.path,
                )
                and item.sprite == "star_bg"
            )
            stars = tuple(
                item
                for item in child_images
                if re.fullmatch(
                    re.escape(button.path)
                    + r"/IconTpl/icon_bg/stars/startpl(?:\(Clone\))?/star",
                    item.path,
                )
                and item.sprite == "star"
            )
            allowed_paths = {button.path + suffix for suffix in exact_signatures} | {
                button.path + "/IconTpl/icon_bg",
                button.path + "/IconTpl/icon_bg/icon",
            }
            unexpected = tuple(
                item
                for item in child_images
                if item.path not in allowed_paths
                and item not in star_background
                and item not in stars
            )
            material_shapes.append(
                rarity[0].sprite == "bg1"
                and int(level[0].text) == 1
                and all(len(matches) == 1 for matches in observed_exact.values())
                and len(star_background) == 1
                and len(stars) == 1
                and not unexpected
            )
            materials.append(
                EnhancementMaterialState(
                    slot=slot,
                    level=int(level[0].text),
                    rarity_sprite=rarity[0].sprite,
                    ship_sprite=icon[0].sprite,
                )
            )
        source_complete = bool(
            not ui_state.image_truncated
            and ui_state.image_source_count is not None
            and ui_state.image_source_capacity is not None
            and ui_state.image_source_count <= ui_state.image_source_capacity
        )
        # A complete source enumeration plus a closed card-child whitelist
        # turns icon absence into positive evidence: any lock, favourite,
        # equipment, or other overlay adds an unexpected active child Image.
        return EnhancementPreview(
            generation=max(state.generation, ui_state.generation),
            target_name=target,
            attributes=tuple(attributes),
            materials=tuple(materials),
            image_snapshot_truncated=ui_state.image_truncated,
            material_protection_proven=bool(
                materials and source_complete and all(material_shapes)
            ),
            image_source_count=ui_state.image_source_count,
            image_source_capacity=ui_state.image_source_capacity,
        )

    def _click_enhancement_control(
        self, semantic_id: str, name: str, sprite: str
    ) -> ActionReceipt:
        state, ui_state = self._enhancement_records()
        path = "OverlayCamera/Overlay/UIMain/blur_panel(Adapt)/blur_panel/main/" + name
        buttons = tuple(
            item
            for item in state.buttons
            if item.name == name
            and item.path == path
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.point is not None
            and item.bounds is not None
            and item.bounds.contains(item.point)
        )
        images = tuple(
            item
            for item in ui_state.images
            if item.name == name
            and item.path == path
            and item.sprite == sprite
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.raycast_target
            and item.bounds is not None
        )
        if len(buttons) != 1 or len(images) != 1:
            raise SemanticGateClosed("enhancement control identity is incomplete")
        button = buttons[0]
        assert button.point is not None and button.bounds is not None
        if not images[0].bounds.contains(button.point):
            raise SemanticGateClosed("enhancement control layers disagree")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed before enhancement input")
        self._tap(int(round(button.point.x)), int(round(button.point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("game activity changed after enhancement input")
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=max(state.generation, ui_state.generation),
            point=button.point,
            bounds=button.bounds,
            path=button.path,
        )

    def recommend_enhancement_materials(
        self, timeout_seconds: float = 5.0
    ) -> EnhancementPreview:
        """Ask the official client to select materials, without confirming."""

        if timeout_seconds <= 0:
            raise ValueError("enhancement timeout must be positive")
        if self.enhancement_preview().materials:
            raise SemanticGateClosed("enhancement recommendation requires empty slots")
        self._click_enhancement_control(
            "enhancement/recommend", "select_btn", "recommand"
        )
        deadline = time.monotonic() + timeout_seconds
        while time.monotonic() < deadline:
            try:
                preview = self.enhancement_preview()
            except SemanticGateClosed:
                preview = None
            if preview is not None and preview.materials:
                return preview
            self._sleep(0.05)
        raise SemanticGateClosed(
            "official enhancement recommendation found no material"
        )

    def clear_enhancement_materials(
        self, timeout_seconds: float = 5.0
    ) -> ActionReceipt:
        """Clear a recommendation and prove that no material was consumed."""

        if timeout_seconds <= 0:
            raise ValueError("enhancement timeout must be positive")
        if not self.enhancement_preview().materials:
            raise SemanticGateClosed("enhancement material slots are already empty")
        receipt = self._click_enhancement_control(
            "enhancement/clear", "cancel_btn", "qingkong_butten"
        )
        deadline = time.monotonic() + timeout_seconds
        while time.monotonic() < deadline:
            try:
                preview = self.enhancement_preview()
            except SemanticGateClosed:
                preview = None
            if preview is not None and not preview.materials:
                return receipt
            self._sleep(0.05)
        raise SemanticGateClosed("enhancement materials did not clear")

    def enhance_with_official_recommendation(
        self, timeout_seconds: float = 5.0
    ) -> Union[EnhancementExecutionReceipt, EnhancementNoMaterialReceipt]:
        """Use the official recommendation and confirm one protected enhancement.

        No material is a successful skip. Any incomplete card, non-level-1 or
        non-N material, unknown overlay, target change, or attribute mismatch
        closes the gate before another destructive input can be sent.
        """

        if timeout_seconds <= 0:
            raise ValueError("enhancement timeout must be positive")
        initial = self.enhancement_preview()
        if initial.materials:
            raise SemanticGateClosed("official enhancement requires empty slots")
        recommendation = self._click_enhancement_control(
            "enhancement/recommend", "select_btn", "recommand"
        )
        deadline = time.monotonic() + timeout_seconds
        selected: Optional[EnhancementPreview] = None
        last_stable = initial
        while time.monotonic() < deadline:
            try:
                preview = self.enhancement_preview()
            except SemanticGateClosed:
                preview = None
            if preview is not None:
                last_stable = preview
                if preview.materials:
                    selected = preview
                    break
            self._sleep(0.05)
        if selected is None:
            if last_stable.target_name != initial.target_name or last_stable.materials:
                raise SemanticGateClosed(
                    "official enhancement no-material state is incoherent"
                )
            return EnhancementNoMaterialReceipt(
                generation=last_stable.generation,
                target_name=last_stable.target_name,
                recommendation=recommendation,
            )
        materials_safe = bool(
            selected.material_protection_proven
            and all(
                material.level == 1 and material.rarity_sprite == "bg1"
                for material in selected.materials
            )
            and any(attribute.addition > 0 for attribute in selected.attributes)
        )
        if not materials_safe:
            try:
                self.clear_enhancement_materials(timeout_seconds=timeout_seconds)
            finally:
                raise SemanticGateClosed(
                    "official enhancement recommendation is not consumption-safe"
                )
        confirmation = self._click_enhancement_control(
            "enhancement/confirm", "ok_btn", "qianghua_butten"
        )

        def result_gain(preview: EnhancementPreview) -> Optional[int]:
            """Return the exact observed gain once the client has settled."""

            if preview.target_name != selected.target_name:
                return None
            before_by_index = {item.index: item for item in selected.attributes}
            after_by_index = {item.index: item for item in preview.attributes}
            if before_by_index.keys() != after_by_index.keys():
                return None
            gain = 0
            for index, before in before_by_index.items():
                after = after_by_index[index]
                expected = min(before.maximum, before.current + before.addition)
                if (
                    after.name != before.name
                    or after.maximum != before.maximum
                    or after.current != expected
                    or after.addition != 0
                ):
                    return None
                gain += after.current - before.current
            return gain if gain > 0 else None

        deadline = time.monotonic() + timeout_seconds
        completed: Optional[EnhancementPreview] = None
        equipment_result: Optional[
            Tuple[Tuple[Tuple[int, int], ...], Tuple[ActionReceipt, ...]]
        ] = None
        while time.monotonic() < deadline:
            try:
                preview = self.enhancement_preview()
            except SemanticGateClosed:
                preview = None
            # The live client clears its material slots one observer frame
            # before applying the corresponding attribute values.  Do not
            # mistake that transitional empty panel for the completed order.
            if (
                preview is not None
                and not preview.materials
                and result_gain(preview) is not None
            ):
                completed = preview
                break
            if preview is not None:
                # This remains the known enhancement panel, so avoid mixing
                # in a second page probe while its rows are still animating.
                self._sleep(0.05)
                continue
            state, ui_state = self._retirement_records()
            active_paths = tuple(
                item.path
                for item in state.buttons
                if item.active_in_hierarchy and item.active_and_enabled
            )
            equipment_visible = any(
                path.endswith("ResolveEquipmentUI(Clone)/main/cancel_btn")
                for path in active_paths
            )
            preserve_visible = bool(
                self._active_retirement_texts(
                    ui_state,
                    "Msgbox(Clone)/window/msg_panel/content",
                    "不进行任何操作，所有装备会放入"
                    "<color=#5f984d>仓库</color>\n是否退出？",
                )
            )
            if equipment_visible or preserve_visible:
                # The stock client's equipment-resolution handoff is visibly
                # slower than recommendation/confirmation (and has exceeded
                # the five-second transaction window on the live client).
                # It is an already-confirmed order at this point, so wait for
                # its normal preservation exit rather than misclassifying the
                # completed enhancement as retryable.
                equipment_result = self._finish_enhancement_equipment_preservation(
                    timeout_seconds=max(timeout_seconds, 30.0)
                )
                completed = self.enhancement_preview()
                if completed.materials:
                    raise SemanticGateClosed(
                        "enhancement material slots remained populated"
                    )
                break
            self._sleep(0.05)
        if completed is None:
            raise SemanticGateClosed(
                "official enhancement result was not observed; do not retry"
            )
        observed_gain = result_gain(completed)
        if observed_gain is None:
            raise SemanticGateClosed(
                "enhancement attribute result does not match the preview"
            )
        if equipment_result is None:
            equipment_result = self._finish_enhancement_equipment_preservation(
                timeout_seconds=max(timeout_seconds, 30.0)
            )
        equipment_quantities, equipment_actions = equipment_result
        return EnhancementExecutionReceipt(
            target_name=completed.target_name,
            materials=selected.materials,
            attributes_before=selected.attributes,
            attributes_after=completed.attributes,
            confirmation=confirmation,
            equipment_quantities=equipment_quantities,
            equipment_actions=equipment_actions,
            equipment_preserved=True,
            generation_after=completed.generation,
        )

    @staticmethod
    def _active_retirement_texts(
        ui_state: UiState,
        path_suffix: str,
        expected: Optional[str] = None,
    ) -> Tuple[TextState, ...]:
        return tuple(
            item
            for item in ui_state.texts
            if item.path.endswith(path_suffix)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and (expected is None or item.text == expected)
        )

    @staticmethod
    def _active_retirement_buttons(
        state: OracleState,
        path_suffix: str,
    ) -> Tuple[ButtonState, ...]:
        return tuple(
            item
            for item in state.buttons
            if item.path.endswith(path_suffix)
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
        )

    def _click_retirement_button(
        self,
        semantic_id: str,
        path_suffix: str,
        *,
        identity_text_suffix: str,
        identity_text: str,
    ) -> ActionReceipt:
        state, ui_state = self._retirement_records()
        buttons = self._active_retirement_buttons(state, path_suffix)
        identity = self._active_retirement_texts(
            ui_state, identity_text_suffix, identity_text
        )
        if len(buttons) != 1 or len(identity) != 1:
            raise SemanticGateClosed("retirement control identity is ambiguous")
        button = buttons[0]
        if (
            button.raycast_top is False
            or button.point is None
            or button.bounds is None
            or not button.bounds.contains(button.point)
            or not (
                0 <= button.point.x < self.fingerprint.width
                and 0 <= button.point.y < self.fingerprint.height
            )
        ):
            raise SemanticGateClosed("retirement control is not actionable")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(button.point.x)), int(round(button.point.y)))
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately after input")
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=ui_state.generation,
            point=button.point,
            bounds=button.bounds,
            path=button.path,
        )

    def retirement_selection_state(self) -> RetirementSelectionState:
        state, ui_state = self._retirement_records()
        tip_suffix = "/blur_panel/select_panel/tip"
        tip = self._active_retirement_texts(
            ui_state,
            tip_suffix,
            "请选择用于<color=#92fc63>退役</color>的角色：",
        )
        capacity = self._active_retirement_texts(
            ui_state, "/blur_panel/adapt/top/capacity/Text"
        )
        count = self._active_retirement_texts(
            ui_state, "/blur_panel/select_panel/bottom_info/bg_input/count"
        )
        controls = (
            "/blur_panel/adapt/left_length/frame/setting",
            "/blur_panel/select_panel/quick_select",
            "/blur_panel/select_panel/confirm_button",
            "/blur_panel/select_panel/cancel_button",
        )
        if (
            len(tip) != 1
            or len(capacity) != 1
            or len(count) != 1
            or any(
                len(self._active_retirement_buttons(state, path)) != 1
                for path in controls
            )
        ):
            raise SemanticGateClosed("retirement selection page is incomplete")
        capacity_match = re.fullmatch(
            r"([0-9]+)/([1-9][0-9]*)", capacity[0].text.strip()
        )
        count_match = re.fullmatch(r"[0-9]+", count[0].text.strip())
        if capacity_match is None or count_match is None:
            raise SemanticGateClosed("retirement counters are malformed")
        used, total = (int(value) for value in capacity_match.groups())
        selected = int(count_match.group(0))
        if used > total or selected > used:
            raise SemanticGateClosed("retirement counters are inconsistent")
        return RetirementSelectionState(
            generation=ui_state.generation,
            capacity_used=used,
            capacity_total=total,
            selected_count=selected,
        )

    def click_retirement_page_back(self) -> ActionReceipt:
        """Exit only an idle, unselected retirement page."""

        selection = self.retirement_selection_state()
        if selection.selected_count != 0:
            raise SemanticGateClosed("retirement page has a live selection")
        state, _ui_state = self._retirement_records()
        matches = tuple(
            button
            for button in state.buttons
            if button.name == "back"
            and button.path
            == "OverlayCamera/Overlay/UIMain/blur_panel/adapt/top/back"
            and button.actionable
        )
        if len(matches) != 1:
            raise SemanticGateClosed("retirement page back control is ambiguous")
        target = matches[0]
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        assert target.point is not None and target.bounds is not None
        self._tap(int(round(target.point.x)), int(round(target.point.y)))
        return ActionReceipt(
            semantic_id="retirement/page/back",
            generation=selection.generation,
            point=target.point,
            bounds=target.bounds,
            path=target.path,
        )

    def open_retirement_settings(self) -> ActionReceipt:
        page = self.retirement_selection_state()
        if page.selected_count:
            raise SemanticGateClosed("retirement settings require an empty selection")
        return self._click_retirement_button(
            "retirement/settings/open",
            "/blur_panel/adapt/left_length/frame/setting",
            identity_text_suffix="/blur_panel/select_panel/tip",
            identity_text="请选择用于<color=#92fc63>退役</color>的角色：",
        )

    def retirement_settings_state(self) -> RetirementSettingsState:
        _, ui_state = self._retirement_records()
        if ui_state.method_mask & 0x1 == 0:
            raise SemanticGateClosed("typed retirement Toggle access is unavailable")
        root = "DockyardQuickSelectSettingUI(Clone)/window/notifications/options/"
        expected_options = {
            0: ("on", "off"),
            1: ("sr", "r", "n", "empty"),
            2: ("sr", "r", "n", "empty"),
            3: ("sr", "r", "n", "empty"),
            4: ("keep_all", "keep_one", "keep_none"),
            5: ("keep_all", "keep_needed", "keep_none"),
        }
        selected: Dict[int, str] = {}
        for group, options in expected_options.items():
            records = {}
            for option in options:
                suffix = root + "notify_tpl_{0}/{1}".format(group, option)
                matches = tuple(
                    item
                    for item in ui_state.toggles
                    if item.path.endswith(suffix)
                    and item.name == option
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                    and item.interactable
                    and item.raycast_top is None
                )
                if len(matches) != 1:
                    raise SemanticGateClosed(
                        "retirement setting option is absent or ambiguous"
                    )
                records[option] = matches[0]
            checked = tuple(option for option, item in records.items() if item.checked)
            if len(checked) != 1:
                raise SemanticGateClosed("retirement setting group is not exclusive")
            selected[group] = checked[0]

        expected_labels = {
            0: "唯一舰船退役保护",
            1: "选择优先级1",
            2: "选择优先级2",
            3: "选择优先级3",
            4: (
                "<color=#92fc63>「拥有」</color>满星的同名舰船时，"
                "保留几艘<color=#92fc63>符合退役条件</color>的同名舰船"
            ),
            5: (
                "<color=#ff5c5c>「没有」</color>满星的同名舰船时，"
                "保留几艘<color=#92fc63>符合退役条件</color>的同名舰船"
            ),
        }
        for group, text in expected_labels.items():
            if (
                len(
                    self._active_retirement_texts(
                        ui_state,
                        root + "notify_tpl_{0}/Text".format(group),
                        text,
                    )
                )
                != 1
            ):
                raise SemanticGateClosed("retirement setting label changed")
        title = self._active_retirement_texts(
            ui_state,
            "DockyardQuickSelectSettingUI(Clone)/window/top/bg/obtain/title",
            "退役设置",
        )
        if len(title) != 1:
            raise SemanticGateClosed("retirement setting page title changed")
        return RetirementSettingsState(
            generation=ui_state.generation,
            unique_ship_protection=selected[0] == "on",
            priority=tuple(selected[index].upper() for index in (1, 2, 3)),
            full_star_policy=selected[4],
            no_full_star_policy=selected[5],
        )

    def _click_retirement_setting_option(
        self, group: int, option: str
    ) -> ActionReceipt:
        state, ui_state = self._retirement_records()
        root = (
            "DockyardQuickSelectSettingUI(Clone)/window/notifications/options/"
            "notify_tpl_{0}/{1}".format(group, option)
        )
        toggles = tuple(
            item
            for item in ui_state.toggles
            if item.path.endswith(root)
            and item.name == option
            and item.active_in_hierarchy
            and item.active_and_enabled
            and item.interactable
            and item.raycast_top is None
        )
        if len(toggles) != 1 or toggles[0].checked:
            raise SemanticGateClosed("retirement setting target is not selectable")
        toggle = toggles[0]
        point = toggle.point
        bounds = toggle.bounds
        if group == 0:
            image_suffix = root + "/Image2"
            images = tuple(
                item
                for item in ui_state.images
                if item.path.endswith(image_suffix)
                and item.sprite == "toggle_on"
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.raycast_target
                and item.raycast_top is None
                and item.bounds is not None
            )
            if len(images) != 1:
                raise SemanticGateClosed("unique-protection input surface changed")
            bounds = images[0].bounds
            assert bounds is not None
            point = Point(
                (bounds.left + bounds.right) / 2.0,
                (bounds.top + bounds.bottom) / 2.0,
            )
        if (
            point is None
            or bounds is None
            or not bounds.contains(point)
            or not (
                0 <= point.x < self.fingerprint.width
                and 0 <= point.y < self.fingerprint.height
            )
        ):
            raise SemanticGateClosed("retirement setting input point is invalid")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="retirement/settings/{0}/{1}".format(group, option),
            generation=ui_state.generation,
            point=point,
            bounds=bounds,
            path=toggle.path,
        )

    def configure_retirement_settings(
        self, keep_limit_break: bool
    ) -> Tuple[RetirementSettingsState, Tuple[ActionReceipt, ...]]:
        if not isinstance(keep_limit_break, bool):
            raise TypeError("retirement limit-break policy must be boolean")
        desired = {
            0: "on",
            1: "r",
            2: "sr",
            3: "n",
            4: "keep_none",
            5: "keep_needed" if keep_limit_break else "keep_none",
        }
        receipts: List[ActionReceipt] = []
        for group, option in desired.items():
            current = self.retirement_settings_state()
            actual = {
                0: "on" if current.unique_ship_protection else "off",
                1: current.priority[0].lower(),
                2: current.priority[1].lower(),
                3: current.priority[2].lower(),
                4: current.full_star_policy,
                5: current.no_full_star_policy,
            }[group]
            if actual == option:
                continue
            receipts.append(self._click_retirement_setting_option(group, option))
            self._sleep(0.2)
            updated = self.retirement_settings_state()
            updated_actual = {
                0: "on" if updated.unique_ship_protection else "off",
                1: updated.priority[0].lower(),
                2: updated.priority[1].lower(),
                3: updated.priority[2].lower(),
                4: updated.full_star_policy,
                5: updated.no_full_star_policy,
            }[group]
            if updated_actual != option:
                raise SemanticGateClosed("retirement setting did not settle")
        final = self.retirement_settings_state()
        expected_state = RetirementSettingsState(
            generation=final.generation,
            unique_ship_protection=True,
            priority=("R", "SR", "N"),
            full_star_policy="keep_none",
            no_full_star_policy=("keep_needed" if keep_limit_break else "keep_none"),
        )
        if final != expected_state:
            raise SemanticGateClosed("official retirement settings are not exact")
        return final, tuple(receipts)

    def close_retirement_settings(self) -> ActionReceipt:
        self.retirement_settings_state()
        return self._click_retirement_button(
            "retirement/settings/close",
            "DockyardQuickSelectSettingUI(Clone)/window/top/btnBack",
            identity_text_suffix=(
                "DockyardQuickSelectSettingUI(Clone)/window/top/bg/obtain/title"
            ),
            identity_text="退役设置",
        )

    def _retirement_preconfirm(self) -> Optional[Tuple[int, int]]:
        state, ui_state = self._retirement_records()
        confirm = self._active_retirement_buttons(
            state, "DestoryInfoUI(Clone)/frame/confirm_button"
        )
        if not confirm:
            return None
        count = self._active_retirement_texts(
            ui_state, "/blur_panel/select_panel/bottom_info/bg_input/count"
        )
        title = self._active_retirement_texts(
            ui_state,
            "DestoryInfoUI(Clone)/frame/top/title_list/infomation/title",
            "信息",
        )
        if len(confirm) != 1 or len(count) != 1 or len(title) != 1:
            raise SemanticGateClosed("retirement confirmation is incomplete")
        if re.fullmatch(r"[1-9][0-9]*", count[0].text.strip()) is None:
            raise SemanticGateClosed("retirement selected count is malformed")
        return int(count[0].text.strip()), ui_state.generation

    def _retirement_screen_kind(self) -> str:
        state, ui_state = self._retirement_records()
        paths = tuple(
            item.path
            for item in state.buttons
            if item.active_in_hierarchy and item.active_and_enabled
        )
        if any(
            path.endswith("DestoryConfirmWindow(Clone)/window/confirm_btn")
            for path in paths
        ):
            return "rarity-warning"
        if any(path.endswith("AwardInfoUI(Clone)/items/close") for path in paths):
            return "award"
        preserve_message = self._active_retirement_texts(
            ui_state,
            "Msgbox(Clone)/window/msg_panel/content",
            "不进行任何操作，所有装备会放入<color=#5f984d>仓库</color>\n是否退出？",
        )
        if preserve_message:
            return "equipment-preserve-confirm"
        if any(
            path.endswith("ResolveEquipmentUI(Clone)/main/cancel_btn") for path in paths
        ):
            return "equipment"
        if any(
            path.endswith("DestoryInfoUI(Clone)/frame/confirm_button") for path in paths
        ):
            return "preconfirm"
        if self._active_retirement_texts(
            ui_state,
            "/blur_panel/select_panel/tip",
            "请选择用于<color=#92fc63>退役</color>的角色：",
        ):
            return "selection"
        return "transition"

    def _retirement_no_candidate_message(self) -> Optional[str]:
        _, ui_state = self._retirement_records()
        messages = self._active_retirement_texts(
            ui_state,
            "TipPanel(Clone)/Grid/toolTip(Clone)/Text",
        )
        if not messages:
            return None
        if (
            len(messages) != 1
            or messages[0].text != "<color=white>没找到符合条件的舰船</color>"
        ):
            raise SemanticGateClosed("official retirement no-candidate tip changed")
        return messages[0].text

    def _recover_retirement_network_reconnect(self) -> Optional[ActionReceipt]:
        """Resume only the independently reviewed exact reconnect prompt."""

        state, ui_state = self._retirement_records()
        confirm = self._matches(state, "overlay/network-reconnect/confirm")
        cancel = self._matches(state, "overlay/network-reconnect/cancel")
        if not confirm and not cancel:
            return None
        # Other reviewed retirement dialogs can reuse one of the generic
        # Msgbox button paths.  A reconnect prompt always owns the exact pair.
        if not confirm or not cancel:
            return None
        if len(confirm) != 1 or len(cancel) != 1:
            raise SemanticGateClosed("retirement reconnect prompt is ambiguous")
        content = self._active_retirement_texts(
            ui_state, "Msgbox(Clone)/window/msg_panel/content"
        )
        confirm_text = self._active_retirement_texts(
            ui_state,
            "Msgbox(Clone)/window/button_container/custom_button_1(Clone)/pic",
        )
        cancel_text = self._active_retirement_texts(
            ui_state,
            "Msgbox(Clone)/window/button_container/custom_button_2(Clone)/pic",
        )
        if len(content) != 1 or len(confirm_text) != 1 or len(cancel_text) != 1:
            return None
        plain = re.sub(r"<[^>]*>", "", content[0].text).strip()
        if not (
            re.fullmatch(
                r"服务器连接失败，是否重新连接？\s*"
                r"\[(?:NetworkDown|HostNotFound|ConnectionReset)\]",
                plain,
            )
            and "".join(confirm_text[0].text.split()) == "确定"
            and "".join(cancel_text[0].text.split()) == "取消"
        ):
            # Rarity/equipment dialogs own their own exact branches below.
            return None
        return self._click_retirement_button(
            "overlay/network-reconnect/confirm",
            "Msgbox(Clone)/window/button_container/custom_button_1(Clone)",
            identity_text_suffix="Msgbox(Clone)/window/msg_panel/content",
            identity_text=content[0].text,
        )

    def _retirement_reward_state(self) -> RetirementRewardState:
        state, ui_state = self._retirement_records()
        close = self._active_retirement_buttons(state, "AwardInfoUI(Clone)/items/close")
        prefix = "AwardInfoUI(Clone)/items/items_scroll/content/item_tpl(Clone)/bg/"
        names = tuple(
            item.text.strip()
            for item in ui_state.texts
            if item.path.endswith(prefix + "name_mask/name")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.text.strip()
        )
        counts = tuple(
            item.text.strip()
            for item in ui_state.texts
            if item.path.endswith(prefix + "icon_bg/count")
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
        )
        if (
            len(close) != 1
            or len(names) != len(counts)
            or not names
            or len(set(names)) != len(names)
            or any(re.fullmatch(r"[1-9][0-9]*", value) is None for value in counts)
        ):
            raise SemanticGateClosed("retirement reward dialog is incomplete")
        return RetirementRewardState(
            generation=ui_state.generation,
            rewards=tuple(sorted(zip(names, (int(value) for value in counts)))),
        )

    def _retirement_equipment_state(self) -> RetirementEquipmentState:
        state, ui_state = self._retirement_records()
        cancel = self._active_retirement_buttons(
            state, "ResolveEquipmentUI(Clone)/main/cancel_btn"
        )
        title = self._active_retirement_texts(
            ui_state,
            "ResolveEquipmentUI(Clone)/main/title/Text",
            "请选择需要拆解的装备，未选的装备将放入仓库",
        )
        if len(cancel) != 1 or len(title) != 1:
            raise SemanticGateClosed("retirement equipment dialog is incomplete")
        quantity_pattern = re.compile(
            r"ResolveEquipmentUI\(Clone\)/main/frame/view/content/"
            r"([0-9]+)/frame/bg/icon_bg/count$"
        )
        selected_pattern = re.compile(
            r"ResolveEquipmentUI\(Clone\)/main/frame/view/content/"
            r"([0-9]+)/frame/bg/selected/reduce$"
        )
        quantities = []
        for item in ui_state.texts:
            match = quantity_pattern.search(item.path)
            if (
                match is not None
                and item.active_in_hierarchy
                and item.active_and_enabled
            ):
                if re.fullmatch(r"[1-9][0-9]*", item.text.strip()) is None:
                    raise SemanticGateClosed("equipment quantity is malformed")
                quantities.append((int(match.group(1)), int(item.text.strip())))
        selected = sorted(
            {
                int(match.group(1))
                for item in state.buttons
                if (match := selected_pattern.search(item.path)) is not None
                and item.active_in_hierarchy
                and item.active_and_enabled
                and item.interactable
            }
        )
        if not quantities or len(dict(quantities)) != len(quantities):
            raise SemanticGateClosed("equipment item list is ambiguous")
        slots = {slot for slot, _ in quantities}
        if not set(selected).issubset(slots):
            raise SemanticGateClosed("equipment selection is inconsistent")
        all_checked = (
            len(
                tuple(
                    item
                    for item in ui_state.images
                    if item.path.endswith(
                        "ResolveEquipmentUI(Clone)/main/options/ALL/Background/Checkmark"
                    )
                    and item.sprite == "toggle_on"
                    and item.active_in_hierarchy
                    and item.active_and_enabled
                )
            )
            == 1
        )
        return RetirementEquipmentState(
            generation=ui_state.generation,
            item_quantities=tuple(sorted(quantities)),
            selected_slots=tuple(selected),
            all_checked=all_checked,
        )

    def _finish_enhancement_equipment_preservation(
        self, timeout_seconds: float
    ) -> Tuple[Tuple[Tuple[int, int], ...], Tuple[ActionReceipt, ...]]:
        """Preserve every piece of equipment after material consumption."""

        deadline = self._monotonic() + timeout_seconds
        actions: List[ActionReceipt] = []
        quantities: Optional[Tuple[Tuple[int, int], ...]] = None
        clean_samples = 0
        awaiting_preserve_completion = False
        while self._monotonic() < deadline:
            state, ui_state = self._retirement_records()
            active_paths = tuple(
                item.path
                for item in state.buttons
                if item.active_in_hierarchy and item.active_and_enabled
            )
            preserve_message = self._active_retirement_texts(
                ui_state,
                "Msgbox(Clone)/window/msg_panel/content",
                "不进行任何操作，所有装备会放入<color=#5f984d>仓库</color>\n是否退出？",
            )
            if preserve_message:
                actions.append(
                    self._click_retirement_button(
                        "enhancement/equipment/preserve/confirm",
                        "Msgbox(Clone)/window/button_container/custom_button_1(Clone)",
                        identity_text_suffix=("Msgbox(Clone)/window/msg_panel/content"),
                        identity_text=(
                            "不进行任何操作，所有装备会放入"
                            "<color=#5f984d>仓库</color>\n是否退出？"
                        ),
                    )
                )
                awaiting_preserve_completion = True
                clean_samples = 0
                self._sleep(0.2)
                continue
            if any("Msgbox(Clone)" in path for path in active_paths):
                raise SemanticGateClosed(
                    "unknown dialog interrupted enhancement equipment handling"
                )
            if awaiting_preserve_completion:
                # The resolve panel can remain reported for one observer
                # generation behind the preservation prompt.  Once its
                # affirmative exit is sent, only accept the settled
                # enhancement panel; do not issue a second cancellation.
                try:
                    preview = self.enhancement_preview()
                except SemanticGateClosed:
                    preview = None
                if preview is not None and not preview.materials:
                    clean_samples += 1
                    if clean_samples >= 3:
                        return quantities or (), tuple(actions)
                else:
                    clean_samples = 0
                self._sleep(0.2)
                continue
            if any(
                path.endswith("ResolveEquipmentUI(Clone)/main/cancel_btn")
                for path in active_paths
            ):
                equipment = self._retirement_equipment_state()
                if quantities is None:
                    quantities = equipment.item_quantities
                elif quantities != equipment.item_quantities:
                    raise SemanticGateClosed("enhancement equipment quantities changed")
                if equipment.selected_slots:
                    if not equipment.all_checked or set(equipment.selected_slots) != {
                        slot for slot, _ in equipment.item_quantities
                    }:
                        raise SemanticGateClosed(
                            "equipment preservation requires exact all-selection"
                        )
                    actions.append(
                        self._click_retirement_button(
                            "enhancement/equipment/deselect-all",
                            "ResolveEquipmentUI(Clone)/main/options/ALL",
                            identity_text_suffix=(
                                "ResolveEquipmentUI(Clone)/main/options/ALL/Label"
                            ),
                            identity_text="全部",
                        )
                    )
                else:
                    actions.append(
                        self._click_retirement_button(
                            "enhancement/equipment/cancel-disassembly",
                            "ResolveEquipmentUI(Clone)/main/cancel_btn",
                            identity_text_suffix=(
                                "ResolveEquipmentUI(Clone)/main/cancel_btn/Image"
                            ),
                            identity_text="取 消",
                        )
                    )
                    awaiting_preserve_completion = True
                clean_samples = 0
                self._sleep(0.2)
                continue
            try:
                preview = self.enhancement_preview()
            except SemanticGateClosed:
                preview = None
            if preview is not None and not preview.materials:
                clean_samples += 1
                if clean_samples >= 3:
                    return quantities or (), tuple(actions)
            else:
                clean_samples = 0
            self._sleep(0.2)
        raise SemanticGateClosed(
            "enhancement equipment preservation did not complete; do not retry"
        )

    def retire_ships_one_click(
        self,
        keep_limit_break: bool,
        timeout_seconds: float = 60.0,
    ) -> Union[RetirementExecutionReceipt, RetirementNoCandidateReceipt]:
        """Execute one official one-click retirement transaction fail closed."""

        if not isinstance(keep_limit_break, bool):
            raise TypeError("retirement limit-break policy must be boolean")
        if timeout_seconds <= 0:
            raise ValueError("retirement timeout must be positive")
        before = self.retirement_selection_state()
        if before.selected_count:
            raise SemanticGateClosed("retirement transaction requires empty selection")
        actions: List[ActionReceipt] = [self.open_retirement_settings()]
        settings_deadline = self._monotonic() + min(timeout_seconds, 10.0)
        while True:
            reconnect = self._recover_retirement_network_reconnect()
            if reconnect is not None:
                actions.append(reconnect)
                self._sleep(0.2)
                continue
            try:
                self.retirement_settings_state()
                break
            except SemanticOracleError:
                if self._monotonic() >= settings_deadline:
                    raise SemanticGateClosed("retirement settings did not open")
                self._sleep(0.2)
        settings, setting_actions = self.configure_retirement_settings(keep_limit_break)
        actions.extend(setting_actions)
        actions.append(self.close_retirement_settings())
        selection_deadline = self._monotonic() + min(timeout_seconds, 10.0)
        while True:
            reconnect = self._recover_retirement_network_reconnect()
            if reconnect is not None:
                actions.append(reconnect)
                self._sleep(0.2)
                continue
            try:
                returned = self.retirement_selection_state()
                if (
                    returned.capacity_used != before.capacity_used
                    or returned.capacity_total != before.capacity_total
                    or returned.selected_count != 0
                ):
                    raise SemanticGateClosed(
                        "retirement selection changed while configuring settings"
                    )
                break
            except SemanticOracleError:
                pass
            if self._monotonic() >= selection_deadline:
                raise SemanticGateClosed("retirement settings did not close")
            self._sleep(0.2)

        actions.append(
            self._click_retirement_button(
                "retirement/one-click",
                "/blur_panel/select_panel/quick_select",
                identity_text_suffix="/blur_panel/select_panel/quick_select/confirm",
                identity_text="一键退役",
            )
        )
        confirmation_deadline = self._monotonic() + timeout_seconds
        selected_count: Optional[int] = None
        while self._monotonic() < confirmation_deadline:
            reconnect = self._recover_retirement_network_reconnect()
            if reconnect is not None:
                actions.append(reconnect)
                self._sleep(0.2)
                continue
            preconfirm = self._retirement_preconfirm()
            if preconfirm is not None:
                selected_count = preconfirm[0]
                break
            message = self._retirement_no_candidate_message()
            if message is not None:
                idle = self.retirement_selection_state()
                if (
                    idle.capacity_used != before.capacity_used
                    or idle.capacity_total != before.capacity_total
                    or idle.selected_count != 0
                ):
                    raise SemanticGateClosed(
                        "no-candidate retirement changed dock selection"
                    )
                return RetirementNoCandidateReceipt(
                    capacity_used=idle.capacity_used,
                    capacity_total=idle.capacity_total,
                    settings=settings,
                    official_message=message,
                    actions=tuple(actions),
                )
            self._sleep(0.25)
        if selected_count is None:
            raise SemanticGateClosed("official one-click selection did not settle")
        if selected_count > before.capacity_used:
            raise SemanticGateClosed("official retirement count exceeds dock usage")
        actions.append(
            self._click_retirement_button(
                "retirement/ships/confirm",
                "DestoryInfoUI(Clone)/frame/confirm_button",
                identity_text_suffix=("DestoryInfoUI(Clone)/frame/confirm_button/pic"),
                identity_text="确 定",
            )
        )

        rewards: Tuple[Tuple[str, int], ...] = ()
        warning_confirmed = False
        equipment_preserved = False
        completion_deadline = self._monotonic() + timeout_seconds
        while self._monotonic() < completion_deadline:
            reconnect = self._recover_retirement_network_reconnect()
            if reconnect is not None:
                actions.append(reconnect)
                self._sleep(0.2)
                continue
            kind = self._retirement_screen_kind()
            if kind in ("transition", "preconfirm"):
                self._sleep(0.2)
                continue
            if kind == "rarity-warning":
                state, ui_state = self._retirement_records()
                warning = self._active_retirement_texts(
                    ui_state,
                    "DestoryConfirmWindow(Clone)/window/content/Text",
                    "选择角色中有<color=#92fc63>精锐以上</color>的角色：",
                )
                if len(warning) != 1:
                    raise SemanticGateClosed("retirement rarity warning changed")
                actions.append(
                    self._click_retirement_button(
                        "retirement/rarity-warning/confirm",
                        "DestoryConfirmWindow(Clone)/window/confirm_btn",
                        identity_text_suffix=(
                            "DestoryConfirmWindow(Clone)/window/content/desc/label"
                        ),
                        identity_text="是否确认",
                    )
                )
                warning_confirmed = True
                self._sleep(0.2)
                continue
            if kind == "award":
                reward_state = self._retirement_reward_state()
                rewards = reward_state.rewards
                actions.append(
                    self._click_retirement_button(
                        "retirement/reward/close",
                        "AwardInfoUI(Clone)/items/close",
                        identity_text_suffix=(
                            "AwardInfoUI(Clone)/items/items_scroll/content/"
                            "item_tpl(Clone)/bg/name_mask/name"
                        ),
                        identity_text=rewards[0][0],
                    )
                )
                self._sleep(0.2)
                continue
            if kind == "equipment":
                equipment = self._retirement_equipment_state()
                if equipment.selected_slots:
                    if not equipment.all_checked or set(equipment.selected_slots) != {
                        slot for slot, _ in equipment.item_quantities
                    }:
                        raise SemanticGateClosed(
                            "equipment preservation requires exact all-selection"
                        )
                    actions.append(
                        self._click_retirement_button(
                            "retirement/equipment/deselect-all",
                            "ResolveEquipmentUI(Clone)/main/options/ALL",
                            identity_text_suffix=(
                                "ResolveEquipmentUI(Clone)/main/options/ALL/Label"
                            ),
                            identity_text="全部",
                        )
                    )
                    self._sleep(0.2)
                    cleared = self._retirement_equipment_state()
                    if cleared.selected_slots or cleared.all_checked:
                        raise SemanticGateClosed("equipment selection did not clear")
                    continue
                actions.append(
                    self._click_retirement_button(
                        "retirement/equipment/cancel-disassembly",
                        "ResolveEquipmentUI(Clone)/main/cancel_btn",
                        identity_text_suffix=(
                            "ResolveEquipmentUI(Clone)/main/cancel_btn/Image"
                        ),
                        identity_text="取 消",
                    )
                )
                self._sleep(0.2)
                continue
            if kind == "equipment-preserve-confirm":
                actions.append(
                    self._click_retirement_button(
                        "retirement/equipment/preserve/confirm",
                        "Msgbox(Clone)/window/button_container/custom_button_1(Clone)",
                        identity_text_suffix=("Msgbox(Clone)/window/msg_panel/content"),
                        identity_text=(
                            "不进行任何操作，所有装备会放入"
                            "<color=#5f984d>仓库</color>\n是否退出？"
                        ),
                    )
                )
                equipment_preserved = True
                self._sleep(0.2)
                continue
            if kind == "selection":
                after = self.retirement_selection_state()
                if after.selected_count != 0:
                    raise SemanticGateClosed("retirement selection did not clear")
                if after.capacity_total != before.capacity_total:
                    raise SemanticGateClosed(
                        "dock capacity limit changed during retirement"
                    )
                if before.capacity_used - after.capacity_used != selected_count:
                    raise SemanticGateClosed(
                        "retirement count and capacity delta disagree"
                    )
                return RetirementExecutionReceipt(
                    retired_count=selected_count,
                    capacity_before=before.capacity_used,
                    capacity_after=after.capacity_used,
                    capacity_total=after.capacity_total,
                    settings=settings,
                    rewards=rewards,
                    rarity_warning_confirmed=warning_confirmed,
                    equipment_preserved=equipment_preserved,
                    actions=tuple(actions),
                )
        raise SemanticGateClosed("official retirement transaction did not close")

    def _matches(self, state: OracleState, semantic_id: str) -> Tuple[ButtonState, ...]:
        target = self._mapping(semantic_id)
        suffixes = (
            target.path_suffix
            if isinstance(target.path_suffix, tuple)
            else (target.path_suffix,)
        )
        return tuple(
            button
            for button in state.buttons
            if button.name == target.name and button.path.endswith(suffixes)
        )

    def _unique(self, state: OracleState, semantic_id: str) -> ButtonState:
        matches = self._matches(state, semantic_id)
        if not matches:
            raise SemanticTargetMissing(
                "semantic target is absent: {0}".format(semantic_id)
            )
        if len(matches) != 1:
            raise SemanticGateClosed(
                "semantic target mapping is ambiguous: {0}".format(semantic_id)
            )
        return matches[0]

    def _blocking_rules(
        self, state: OracleState, semantic_id: str
    ) -> Tuple[BlockerRule, ...]:
        if semantic_id in (
            "overlay/network-reconnect/cancel",
            "overlay/network-reconnect/confirm",
            "overlay/login-data-expired/confirm",
        ):
            # A proven topmost NetworkDown Msgbox intentionally crosses page
            # ownership. Its exact text/labels and top raycast are still
            # required before either button can be considered actionable.
            return ()
        return tuple(
            rule
            for rule in self._blockers
            if semantic_id not in rule.allowed_target_ids
            and not (
                rule.blocker_id == "tactical-dock"
                and (
                    semantic_id.startswith("enhancement/dock/")
                    or semantic_id.startswith("awaken/")
                    or semantic_id.startswith("os/port/dock/")
                    or semantic_id.startswith("gems-farming/dock/")
                )
            )
            and not (
                rule.blocker_id == "tactical-page"
                and semantic_id.startswith("enhancement/dock/favourite/")
            )
            and not (
                rule.blocker_id == "archive-page"
                and (
                    semantic_id.startswith("archive/category/")
                    or semantic_id.startswith("archive/campaign/")
                )
            )
            and not (
                rule.blocker_id == "campaign-menu"
                and (
                    semantic_id.startswith("archive/category/")
                    or semantic_id.startswith("archive/campaign/")
                )
            )
            and any(rule.path_fragment in button.path for button in state.buttons)
        )

    def _msgbox_prompt_parts(
        self, state: OracleState
    ) -> Optional[Tuple[str, str, str]]:
        ui_state = self._stable_msgbox_ui_state(state)

        def exact_text(suffix: str) -> Optional[str]:
            matches = tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )
            if len(matches) > 1:
                raise SemanticGateClosed("Msgbox text is ambiguous")
            return matches[0].text if matches else None

        content = exact_text("Msgbox(Clone)/window/msg_panel/content")
        cancel = exact_text(
            "Msgbox(Clone)/window/button_container/custom_button_2(Clone)/pic"
        )
        confirm = exact_text(
            "Msgbox(Clone)/window/button_container/custom_button_1(Clone)/pic"
        )
        if content is None or cancel is None or confirm is None:
            return None
        return (
            re.sub(r"<[^>]*>", "", content).strip(),
            "".join(cancel.split()),
            "".join(confirm.split()),
        )

    def _guild_dispatch_prompt_matches(self, state: OracleState) -> bool:
        parts = self._msgbox_prompt_parts(state)
        if parts is None or parts[1:] not in (("取消", "确定"), ("ȡ��", "ȷ��")):
            return False
        ui_state = self._stable_msgbox_ui_state(state)
        formation_roots = tuple(
            button
            for button in state.buttons
            if button.name == "GuildMissionFormationPage(Clone)"
            and button.path.endswith(
                "UICamera/Canvas/UIOrigin/GuildMissionFormationPage(Clone)"
            )
            and button.active_in_hierarchy
            and button.active_and_enabled
        )
        button_sprites = {
            image.sprite
            for image in ui_state.images
            if image.path.endswith(
                "Msgbox(Clone)/window/button_container/custom_button_1(Clone)"
            )
            or image.path.endswith(
                "Msgbox(Clone)/window/button_container/custom_button_2(Clone)"
            )
        }
        content = parts[0]
        text_shape = bool(
            content
            and (
                ("派遣" in content and "无法" in content and "确定" in content)
                or ("��ǲ" in content and "�޷�" in content and "ȷ��" in content)
            )
        )
        return bool(
            len(formation_roots) == 1
            and text_shape
            and button_sprites == {"btn_big_blue", "btn_big_grey"}
        )

    def _guild_exchange_prompt_matches(self, state: OracleState) -> bool:
        parts = self._msgbox_prompt_parts(state)
        if parts is None or parts[1:] != ("取消", "确定"):
            return False
        ui_state = self._stable_msgbox_ui_state(state)
        logistics_roots = tuple(
            button
            for button in state.buttons
            if "/TaskPanel(Adapt)/TaskPanel/SubmitPanel/" in button.path
            and button.name == "submit"
            and button.active_in_hierarchy
            and button.active_and_enabled
        )
        button_sprites = {
            image.sprite
            for image in ui_state.images
            if image.path.endswith(
                "Msgbox(Clone)/window/button_container/custom_button_1(Clone)"
            )
            or image.path.endswith(
                "Msgbox(Clone)/window/button_container/custom_button_2(Clone)"
            )
        }
        prompt = re.fullmatch(
            r"即将提交(.+?)([1-9][0-9]*)个\(目前拥有([1-9][0-9]*)个\)，"
            r"为大舰队提供后勤补给，是否确定？",
            parts[0],
        )
        return bool(
            len(logistics_roots) == 3
            and prompt is not None
            and int(prompt.group(3)) >= int(prompt.group(2))
            and button_sprites == {"btn_big_blue", "btn_big_grey"}
        )

    @staticmethod
    def _msgbox_button_signature(state: OracleState) -> Tuple[Any, ...]:
        def point(value: Optional[Point]) -> Optional[Tuple[float, float]]:
            return None if value is None else (value.x, value.y)

        def bounds(
            value: Optional[Bounds],
        ) -> Optional[Tuple[float, float, float, float]]:
            return (
                None
                if value is None
                else (value.left, value.top, value.right, value.bottom)
            )

        return tuple(
            sorted(
                (
                    (
                        button.name,
                        button.path,
                        button.active_in_hierarchy,
                        button.active_and_enabled,
                        button.interactable,
                        button.raycast_top,
                        point(button.point),
                        bounds(button.bounds),
                    )
                    for button in state.buttons
                    if "/Msgbox(Clone)/" in button.path
                ),
                key=repr,
            )
        )

    def _stable_msgbox_ui_state(self, before: OracleState) -> UiState:
        """Sandwich Msgbox text between two identical Button snapshots."""

        before_signature = self._msgbox_button_signature(before)

        def reader() -> UiState:
            ui_state = self.read_ui_state()
            after = self.read_state()
            if not (
                before.generation <= ui_state.generation <= after.generation
                and before.scene_handle == after.scene_handle
                and before_signature == self._msgbox_button_signature(after)
            ):
                raise SemanticGateClosed("Msgbox snapshots are not coherent")
            return ui_state

        # Unity can publish the text slice one observer turn after the modal
        # Button tree during its opening transition.  Repeat only this
        # read-only sandwich; every accepted attempt still has to bind the
        # original exact modal Button signature to its typed text and closing
        # Button snapshot.
        return self._retry_transition_read(reader)

    def _tactical_continue_prompt_text(self, state: OracleState) -> Optional[str]:
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return None
        plain, cancel, confirm = parts
        if (
            re.fullmatch(
                r"「[^」]+」学习完成，「[^」]+」技能获得[1-9][0-9]*点经验"
                r"(?:[(（]技能等级提升:[1-9][0-9]?→[1-9][0-9]?[)）]！)?"
                r"是否继续学习该(?:角色)?技能？",
                plain,
            )
            and cancel == "取消"
            and confirm == "确定"
        ):
            return plain
        return None

    def _network_reconnect_prompt_matches(self, state: OracleState) -> bool:
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return False
        plain, cancel, confirm = parts
        return bool(
            re.fullmatch(
                r"服务器连接失败，是否重新连接？\s*"
                r"\[(?:NetworkDown|HostNotFound|ConnectionReset)\]",
                plain,
            )
            and cancel == "取消"
            and confirm == "确定"
        )

    def _login_data_expired_prompt_matches(self, state: OracleState) -> bool:
        ui_state = self._stable_msgbox_ui_state(state)

        def matches(suffix: str) -> Tuple[TextState, ...]:
            return tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )

        content = matches("Msgbox(Clone)/window/msg_panel/content")
        confirm = matches(
            "Msgbox(Clone)/window/button_container/custom_button_1(Clone)/pic"
        )
        cancel = matches(
            "Msgbox(Clone)/window/button_container/custom_button_2(Clone)/pic"
        )
        buttons = self._matches(state, "overlay/login-data-expired/confirm")
        return bool(
            len(content) == 1
            and content[0].text.strip() in {"登录数据失效", "您在别处登录"}
            and len(confirm) == 1
            and "".join(confirm[0].text.split()) == "确定"
            and not cancel
            and len(buttons) == 1
        )

    def server_maintenance_visible(self) -> bool:
        """Recognize the exact one-button CN server-maintenance prompt."""

        state = self.read_state()
        ui_state = self._stable_msgbox_ui_state(state)

        def matches(suffix: str) -> Tuple[TextState, ...]:
            return tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )

        content = matches("Msgbox(Clone)/window/msg_panel/content")
        confirm = matches(
            "Msgbox(Clone)/window/button_container/custom_button_1(Clone)/pic"
        )
        cancel = matches(
            "Msgbox(Clone)/window/button_container/custom_button_2(Clone)/pic"
        )
        buttons = self._matches(state, "overlay/server-maintenance/confirm")
        return bool(
            len(content) == 1
            and content[0].text.strip() == "服务器维护"
            and len(confirm) == 1
            and "".join(confirm[0].text.split()) == "确定"
            and not cancel
            and len(buttons) == 1
            and buttons[0].actionable
        )

    def _login_update_download_prompt_matches(self, state: OracleState) -> bool:
        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("login update snapshots are not coherent")
        content = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith("DialogPanel/dialog/content/Text")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        download = self._matches(state, "login/update/download")
        cancel = self._matches(state, "login/update/cancel")
        if len(content) != 1 or not self._login_update_download_text_matches(
            content[0].text
        ):
            return False
        return bool(
            len(download) == 1
            and len(cancel) == 1
            and all(
                button.active_in_hierarchy
                and button.active_and_enabled
                and button.interactable
                and button.raycast_top is None
                and button.point is not None
                and button.bounds is not None
                and button.bounds.contains(button.point)
                for button in (download[0], cancel[0])
            )
        )

    def login_update_download_available(self) -> bool:
        return self._retry_transition_read(
            lambda: self._login_update_download_prompt_matches(self.read_state())
        )

    @staticmethod
    def _login_update_restart_text_matches(value: str) -> bool:
        plain = "".join(value.split())
        if (
            plain
            == "指挥官，当前客户端的游戏版本不是最新的，推荐您重新打开游戏进行更新"
        ):
            return True
        return (
            re.fullmatch(
                r"(?:热更新|资源更新|更新)(?:已)?完成[，,]?(?:需要|请|请点击确定)"
                r"(?:重启游戏|重新启动游戏)[。.]?",
                plain,
            )
            is not None
        )

    def _login_update_restart_prompt_target(self, state: OracleState) -> Optional[str]:
        """Return the sole reviewed explicit post-update restart control.

        Current CN 9.7.324 has no such button.  These two structures are the
        client's existing dialog families, so a future hot update is accepted
        only when its exact update/restart wording and sole affirmative label
        agree.  Any mixed or ambiguous surface remains closed.
        """

        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("login update restart snapshots are not coherent")

        def active_text(suffix: str) -> Tuple[TextState, ...]:
            return tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )

        candidates = []
        variants = (
            (
                "login/update/restart-dialog",
                "DialogPanel/dialog/content/Text",
                "DialogPanel/dialog/action_button/Text",
                "login/update/cancel",
            ),
            (
                "login/update/restart-msgbox",
                "Msgbox(Clone)/window/msg_panel/content",
                "Msgbox(Clone)/window/button_container/custom_button_1(Clone)/pic",
                None,
            ),
        )
        for semantic_id, content_suffix, label_suffix, cancel_id in variants:
            content = active_text(content_suffix)
            label = active_text(label_suffix)
            button = self._matches(state, semantic_id)
            cancel = self._matches(state, cancel_id) if cancel_id is not None else ()
            if not content and not label and not button:
                continue
            # DialogPanel is shared by download confirmation and many other
            # login notices.  It is a restart candidate only when its exact
            # content says so; unrelated complete dialogs belong to their own
            # semantic branches and are not a malformed restart prompt.
            if content and not any(
                self._login_update_restart_text_matches(item.text) for item in content
            ):
                if any(
                    "".join(item.text.split()) in ("重启", "重启游戏", "重新启动")
                    for item in label
                ):
                    raise SemanticGateClosed(
                        "explicit login update restart prompt is incomplete"
                    )
                continue
            if (
                len(content) == 1
                and self._login_update_restart_text_matches(content[0].text)
                and len(label) == 1
                and "".join(label[0].text.split())
                in ("确定", "重启", "重启游戏", "重新启动")
                and len(button) == 1
                and not cancel
                and button[0].active_in_hierarchy
                and button[0].active_and_enabled
                and button[0].interactable
                and button[0].point is not None
                and button[0].bounds is not None
                and button[0].bounds.contains(button[0].point)
            ):
                candidates.append(semantic_id)
            else:
                raise SemanticGateClosed(
                    "explicit login update restart prompt is incomplete"
                )
        if len(candidates) > 1:
            raise SemanticGateClosed("login update restart prompt is ambiguous")
        return candidates[0] if candidates else None

    def login_update_restart_prompt_available(self) -> bool:
        return self._retry_transition_read(
            lambda: (
                self._login_update_restart_prompt_target(self.read_state()) is not None
            )
        )

    def click_login_update_restart_prompt(self) -> ActionReceipt:
        state = self.read_state()
        semantic_id = self._login_update_restart_prompt_target(state)
        if semantic_id is None:
            raise SemanticGateClosed("login update restart prompt is absent")
        receipt = self.click(semantic_id)
        self._login_update_seen = True
        return receipt

    @staticmethod
    def _login_update_download_text_matches(value: str) -> bool:
        """Match the reviewed CN maintenance-update download prompts.

        The client uses the same dialog for a byte-size update, a file-count
        update, the newer split-file summary, and the initial resource-size
        advisory.  Optional background-download copy is part of that exact
        prompt; unrelated manual APK and optional Live2D/full-client downloads
        remain excluded.
        """

        plain = "".join(value.split())
        background = r"(?:（本次更新可以后台下载）|\(本次更新可以后台下载\))?"
        size = r"[1-9][0-9]*(?:\.[0-9]+)?(?:B|KB|MB|GB)"
        count = r"[1-9][0-9]*"
        payload = (
            r"(?:"
            + size
            + r"的文件|"
            + count
            + r"(?:个)?文件(?:（其中已选文件"
            + count
            + r"，本地文件更新"
            + count
            + r"）)?|"
            + count
            + r"的文件)"
        )
        update_prompt = (
            background
            + r"本次更新(?:共)?需要下载"
            + payload
            + r"，是否继续更新？"
            + background
        )
        resource_advisory = (
            r"本次更新需要下载的资源大小约为" + size + r"（建议在WIFI环境下下载）"
        )
        return (
            re.fullmatch(
                r"(?:" + update_prompt + r"|" + resource_advisory + r")",
                plain,
            )
            is not None
        )

    @staticmethod
    def _login_update_status_text_matches(value: str) -> bool:
        """Recognize only client-owned update/check/download status text."""

        plain = "".join(value.split())
        patterns = (
            r"正在检查更新\.\.\.",
            r"正在获取最新版本\.\.\.",
            r"正在检查资源配置文件",
            r"正在下载资源配置文件:[^\r\n]{1,200}",
            r"校验中：[0-9]{1,3}%",
            r"正在下载[^\r\n]{1,200}\([0-9]+/[0-9]+\)",
            r"正在下载更新:进度[0-9]+(?:\.[0-9]+)?(?:B|KB|MB|GB)/"
            r"[0-9]+(?:\.[0-9]+)?(?:B|KB|MB|GB)总共[0-9]+个"
            r"已完成[0-9]+个失败[0-9]+个速度"
            r"[0-9]+(?:\.[0-9]+)?(?:B|KB|MB|GB)/S",
            # This is an automatic client transition, not a request for an
            # external restart.  Interrupting it with force-stop leaves the CN
            # client in its package-switch state and repeats this panel.
            r"更新完成，正在进入游戏\.\.\.",
        )
        return any(re.fullmatch(pattern, plain) is not None for pattern in patterns)

    def login_update_in_progress(self) -> bool:
        # UpdatePanel keeps its background "checking" status visible while
        # DialogPanel is waiting for the user's download confirmation.  The
        # prompt is the actionable state and must win; otherwise ALAS keeps
        # treating the screen as passive progress and never reaches its
        # LOGIN_GAME_UPDATE click branch.
        if self.login_update_download_available():
            return False
        state = self.read_ui_state()
        progress = tuple(
            text
            for text in state.texts
            if text.path.endswith("UpdatePanel/progressInfo")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and self._login_update_status_text_matches(text.text)
        )
        if len(progress) > 1:
            raise SemanticGateClosed("login update progress is ambiguous")
        visible = bool(progress)
        if visible:
            self._login_update_seen = True
        return visible

    def stale_login_update_in_progress(self) -> bool:
        """Recognize one passive UpdatePanel status after frame freshness expires.

        This is deliberately narrower than :meth:`login_update_in_progress`:
        it admits no frame, records no update transition, and exposes no
        actionable control. It exists only so the GameManager-owned cold-start
        wait can remain fail-closed while Unity has left a same-process,
        identity-valid UpdatePanel snapshot stale during update checking. The
        stale wait does not interpret status text: some pre-login Unity text is
        emitted lossily, and this method never converts the observation into an
        action or an update-completion latch.
        """

        if self._foreground_component() != self.fingerprint.component:
            return False
        ui_snapshot = self._request("GET /v1/ui\n")
        if not isinstance(ui_snapshot, dict):
            return False
        try:
            self._validate_identity(
                ui_snapshot,
                UI_SCHEMA,
                allow_stale=True,
            )
            if self._integer(ui_snapshot.get("age_ms"), "UI age_ms") <= (
                self.fingerprint.max_age_ms
            ):
                return False
            if (
                ui_snapshot.get("schema") != 1
                or ui_snapshot.get("text_truncated") is not False
                or self._integer(ui_snapshot.get("error_count"), "UI error_count")
                != 0
            ):
                return False
            raw_texts = ui_snapshot.get("texts")
            if (
                not isinstance(raw_texts, list)
                or self._integer(ui_snapshot.get("text_count"), "text_count")
                != len(raw_texts)
            ):
                return False
            if self._integer(ui_snapshot.get("method_mask"), "UI method_mask") & 0x6 == 0:
                return False
            progress = tuple(
                text
                for text in (self._parse_text(raw) for raw in raw_texts)
                if text.path.endswith("UpdatePanel/progressInfo")
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
                and bool(text.text.strip())
            )
        except (ObserverTransportError, SemanticGateClosed):
            return False
        return len(progress) == 1

    def login_update_restart_required(self) -> bool:
        """Recognize the inert black transition left by a completed CN update.

        The surface is actionable only after this oracle observed the typed
        download progress in the same process.  This prevents a normal startup
        animation from being mistaken for an update restart boundary.
        """

        if self._login_update_restart_consumed:
            return False
        state, ui_state = self._retirement_records()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed("login update restart snapshots are not coherent")

        opening = tuple(
            button
            for button in state.buttons
            if button.name == "opening(Clone)"
            and button.path.endswith("OverlayCamera/Overlay/UIMain/opening(Clone)")
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.raycast_top is None
            and button.point is not None
            and button.bounds is not None
            and button.bounds.contains(button.point)
        )
        login_root = tuple(
            button
            for button in state.buttons
            if button.name == "LoginUI2(Clone)"
            and button.path.endswith("UICamera/Canvas/UIMain/LoginUI2(Clone)")
            and button.active_in_hierarchy
            and button.active_and_enabled
            and button.interactable
            and button.raycast_top is False
        )

        def active_text(suffix: str) -> Tuple[TextState, ...]:
            return tuple(
                text
                for text in ui_state.texts
                if text.path.endswith(suffix)
                and text.active_in_hierarchy
                and text.active_and_enabled
                and not text.truncated
                and text.bounds is not None
            )

        # Current client metadata contains no normal hot-update restart
        # button.  The only explicit restart surface is repair completion;
        # restart it through the owned ADB runtime rather than inventing a tap.
        repair_completion = tuple(
            text
            for text in ui_state.texts
            if (
                text.path.endswith("UpdatePanel/progressInfo")
                or text.path.endswith("DialogPanel/dialog/content/Text")
            )
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
            and "".join(text.text.split()) == "修复完毕，即将重启游戏"
        )
        if len(repair_completion) > 1:
            raise SemanticGateClosed("login repair restart state is ambiguous")
        if repair_completion:
            self._login_update_restart_consumed = True
            return True

        if not self._login_update_seen:
            return False

        change_server = active_text("LoginUI2(Clone)/adapt/current_server/Text")
        server_name = active_text("LoginUI2(Clone)/adapt/current_server/server_name")
        versions = active_text("LoginUI2(Clone)/adapt/version")
        progress = active_text("UpdatePanel/progressInfo")
        matched = bool(
            len(opening) == 1
            and len(login_root) == 1
            and len(change_server) == 1
            and change_server[0].text.strip() == "点击更换"
            and not server_name
            and len(versions) == 1
            and re.fullmatch(r"ver [0-9]+\.[0-9]+\.[0-9]+", versions[0].text.strip())
            and not progress
        )
        if matched:
            self._login_update_restart_consumed = True
        return matched

    def _dock_full_prompt_matches(self, state: OracleState) -> bool:
        ui_state = self._stable_msgbox_ui_state(state)
        content = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith("Msgbox(Clone)/window/msg_panel/content")
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        labels = tuple(
            text
            for text in ui_state.texts
            if text.path.endswith(
                "Msgbox(Clone)/window/button_container/custom_button_1(Clone)/pic"
            )
            and text.active_in_hierarchy
            and text.active_and_enabled
            and not text.truncated
            and text.bounds is not None
        )
        buttons = self._matches(state, "overlay/network-reconnect/confirm")
        return bool(
            len(content) == 1
            and content[0].text.strip() == "船坞已满，请前往整理或扩展"
            and len(buttons) == 3
            and sorted("".join(label.text.split()) for label in labels)
            == sorted(("整理", "拓展", "强化"))
        )

    def dock_full_prompt_active(self) -> bool:
        return self._retry_transition_read(
            lambda: self._dock_full_prompt_matches(self.read_state())
        )

    def _build_warning_prompt_matches(self, state: OracleState) -> bool:
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return False
        plain, cancel, confirm = parts
        return bool(
            plain
            == "常驻UR兑换点数已达上限，未兑换UR角色前继续建造不能获得点数，是否继续建造？"
            and cancel == "取消"
            and confirm == "确定"
        )

    def _build_queue_finish_prompt_cost(
        self, state: OracleState
    ) -> Optional[Tuple[int, int]]:
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return None
        plain, cancel, confirm = parts
        match = re.fullmatch(
            r"快速完成需要消耗([1-9][0-9]*)个快速完成工具\s*"
            r"剩余加速道具:\s*([0-9]+)个",
            plain,
        )
        if match is None or cancel != "取消" or confirm != "确定":
            return None
        required, owned = (int(match.group(1)), int(match.group(2)))
        if owned < required:
            raise SemanticGateClosed(
                "construction quick-finish resources are insufficient"
            )
        return required, owned

    def _tactical_course_prompt_matches(self, state: OracleState) -> bool:
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return False
        plain, cancel, confirm = parts
        return bool(
            re.fullmatch(
                r"是否消耗1本「舰艇(?:攻击|防御|辅助)教材T[1-4]」，"
                r"训练「[^」]+」的[^「」]+技能？",
                plain,
            )
            and cancel == "取消"
            and confirm == "确定"
        )

    def _research_start_prompt_cost(
        self, state: OracleState
    ) -> Optional[Tuple[str, int]]:
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return None
        plain, cancel, confirm = parts
        match = re.fullmatch(
            r"开启该科研项目需要消耗\s*:\s*"
            r"(物资|心智魔方|(?:通用|主炮|鱼雷|防空炮|舰载机)部件T[1-4])"
            r"x([1-9][0-9]*)",
            plain,
        )
        if match is None or cancel != "取消" or confirm != "确定":
            return None
        resource_id = {
            "物资": "gold",
            "心智魔方": "20001",
            "舰载机部件T1": "research_part_t1",
            "舰载机部件T2": "research_part_t2",
            "舰载机部件T3": "research_part_t3",
            "舰载机部件T4": "research_part_t4",
            "通用部件T1": "17001",
            "通用部件T2": "17002",
            "通用部件T3": "17003",
            "通用部件T4": "17004",
            "主炮部件T1": "17011",
            "主炮部件T2": "17012",
            "主炮部件T3": "17013",
            "主炮部件T4": "17014",
            "鱼雷部件T1": "17021",
            "鱼雷部件T2": "17022",
            "鱼雷部件T3": "17023",
            "鱼雷部件T4": "17024",
            "防空炮部件T1": "17031",
            "防空炮部件T2": "17032",
            "防空炮部件T3": "17033",
            "防空炮部件T4": "17034",
        }[match.group(1)]
        return resource_id, int(match.group(2))

    def commission_start_prompt_cost(self) -> Optional[int]:
        state = self.read_state()
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return None
        plain, cancel, confirm = parts
        match = re.fullmatch(r"本次委托需要花费([1-9][0-9]*)石油", plain)
        if match is None or cancel != "取消" or confirm != "确定":
            return None
        return int(match.group(1))

    def _research_queue_prompt_matches(self, state: OracleState) -> bool:
        parts = self._msgbox_prompt_parts(state)
        if parts is None:
            return False
        plain, cancel, confirm = parts
        return bool(
            plain
            == "确定将该科研项目加入研究队列吗，加入队列的研究项目将顺序完成，不可取消"
            and cancel == "取消"
            and confirm == "确定"
        )

    def research_start_prompt_cost(self) -> Optional[Tuple[str, int]]:
        state = self.read_state()
        target = self._matches(state, "research/start/confirm")
        if len(target) > 1:
            raise SemanticGateClosed("research start prompt is ambiguous")
        if not target or not target[0].actionable:
            return None
        return self._research_start_prompt_cost(state)

    def _tactical_continue_prompt_matches(self, state: OracleState) -> bool:
        return self._tactical_continue_prompt_text(state) is not None

    def tactical_continue_prompt_text(self) -> Optional[str]:
        state = self.read_state()
        matches = self._matches(state, "tactical/continue/cancel")
        if len(matches) > 1:
            raise SemanticGateClosed("tactical prompt cancel target is ambiguous")
        if (
            not matches
            or not matches[0].actionable
            or self._blocking_rules(state, "tactical/continue/cancel")
        ):
            return None
        return self._tactical_continue_prompt_text(state)

    def exists(self, semantic_id: str) -> bool:
        return self._retry_transition_read(lambda: self._exists_once(semantic_id))

    def _exists_once(self, semantic_id: str) -> bool:
        state = self.read_state()
        matches = self._matches(state, semantic_id)
        if semantic_id == "tactical/continue/cancel":
            return bool(matches and self._tactical_continue_prompt_matches(state))
        if semantic_id in (
            "overlay/network-reconnect/cancel",
            "overlay/network-reconnect/confirm",
        ):
            return bool(matches and self._network_reconnect_prompt_matches(state))
        if semantic_id == "overlay/login-data-expired/confirm":
            return bool(matches and self._login_data_expired_prompt_matches(state))
        if semantic_id in ("build/warning/cancel", "build/warning/confirm"):
            return bool(matches and self._build_warning_prompt_matches(state))
        if semantic_id in (
            "build/queue/finish-cancel",
            "build/queue/finish-confirm",
        ):
            return bool(matches and self._build_queue_finish_prompt_cost(state) is not None)
        if semantic_id in ("tactical/course/cancel", "tactical/course/confirm"):
            return bool(matches and self._tactical_course_prompt_matches(state))
        if semantic_id in ("research/start/cancel", "research/start/confirm"):
            return bool(matches and self._research_start_prompt_cost(state) is not None)
        if semantic_id in ("research/queue/cancel", "research/queue/confirm"):
            return bool(matches and self._research_queue_prompt_matches(state))
        if semantic_id in ("guild/dispatch/cancel", "guild/dispatch/confirm"):
            return bool(matches and self._guild_dispatch_prompt_matches(state))
        if semantic_id in ("guild/exchange/cancel", "guild/exchange/confirm"):
            return bool(matches and self._guild_exchange_prompt_matches(state))
        return bool(matches)

    def enabled(self, semantic_id: str) -> bool:
        return self._retry_transition_read(lambda: self._enabled_once(semantic_id))

    def _enabled_once(self, semantic_id: str) -> bool:
        state = self.read_state()
        if semantic_id == "main/raid":
            return bool(
                self._main_raid_entry_proven(state)
                and not self._blocking_rules(state, semantic_id)
            )
        if semantic_id == "os/boss/start":
            return self.operation_siren_boss_preparation_visible()
        if semantic_id == "reward/new-ship/continue":
            return self._new_ship_reward_visible_in_state(state)
        if semantic_id in (
            "meowfficer/buy/min",
            "meowfficer/buy/add",
            "meowfficer/buy/max",
            "meowfficer/buy/submit",
        ):
            try:
                self.meowfficer_purchase_state()
            except SemanticGateClosed:
                return False
            matches = self._matches(state, semantic_id)
            return bool(
                len(matches) == 1
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].raycast_top is None
                and matches[0].point is not None
                and matches[0].bounds is not None
                and matches[0].bounds.contains(matches[0].point)
            )
        if semantic_id == "meowfficer/buy/skip":
            return self._meowfficer_purchase_skip_proven(state)
        if semantic_id in (
            "meowfficer/buy/cancel",
            "meowfficer/buy/confirm",
        ):
            return self._meowfficer_purchase_prompt_proven(state)
        if semantic_id == "meowfficer/enhance/open":
            try:
                self.meowfficer_dock_state()
            except SemanticGateClosed:
                return False
            return self._meowfficer_reviewed_control_proven(state, semantic_id)
        if semantic_id in (
            "meowfficer/enhance/back",
            "meowfficer/feed/open",
            "meowfficer/enhance/submit",
        ):
            try:
                self.meowfficer_enhance_state()
            except SemanticGateClosed:
                return False
            return self._meowfficer_reviewed_control_proven(state, semantic_id)
        if semantic_id in (
            "meowfficer/feed/cancel",
            "meowfficer/feed/confirm",
        ):
            try:
                self.meowfficer_feed_state()
            except SemanticGateClosed:
                return False
            return self._meowfficer_reviewed_control_proven(state, semantic_id)
        if semantic_id in (
            "meowfficer/enhance/cancel",
            "meowfficer/enhance/confirm",
        ):
            return self._meowfficer_enhance_prompt_proven(state)
        if semantic_id == "meowfficer/get/continue":
            return self._meowfficer_get_continue_proven(state)
        if semantic_id in (
            "meowfficer/get/lock",
            "meowfficer/get/unlock",
        ):
            return self._meowfficer_lock_toggle_proven(state, semantic_id)
        if semantic_id in (
            "meowfficer/get/lock-cancel",
            "meowfficer/get/lock-confirm",
        ):
            return self._meowfficer_lock_prompt_proven(state)
        if semantic_id == "meowfficer/get/result/close":
            return self._meowfficer_get_result_proven(state)
        if semantic_id == "meowfficer/fort/close":
            return self._meowfficer_fort_close_proven(state)
        if semantic_id in (
            "meowfficer/queue/auto",
            "meowfficer/queue/start",
            "meowfficer/queue/close",
        ):
            try:
                self.meowfficer_queue_state()
            except SemanticGateClosed:
                return False
            matches = self._matches(state, semantic_id)
            return bool(
                len(matches) == 1
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].raycast_top is None
                and matches[0].point is not None
                and matches[0].bounds is not None
                and matches[0].bounds.contains(matches[0].point)
            )
        if semantic_id in (
            "meowfficer/queue/cancel",
            "meowfficer/queue/confirm",
        ):
            return self._meowfficer_queue_prompt_proven(state)
        if semantic_id == "academy/munitions":
            return self.academy_munitions_available()
        if semantic_id == "shipyard/series/open":
            matches = self._matches(state, semantic_id)
            return bool(
                self.shipyard_page_visible()
                and len(matches) == 1
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].point is not None
                and matches[0].bounds is not None
            )
        if semantic_id.startswith("shipyard/series/"):
            matches = self._matches(state, semantic_id)
            return bool(
                len(matches) == 1
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].point is not None
                and matches[0].bounds is not None
            )
        if semantic_id == "login/update/download":
            return self._login_update_download_prompt_matches(state)
        if semantic_id == "mail/manage/back":
            return self._mail_manager_back_delegated_raycast_proven(state)
        if semantic_id == "exercise/opponent/start":
            return self.exercise_opponent_detail_visible()
        matches = self._matches(state, semantic_id)
        if semantic_id in (
            "overlay/network-reconnect/cancel",
            "overlay/network-reconnect/confirm",
        ) and not matches:
            # Dock pages can legitimately exceed the observer toggle budget.
            # Do not demand an unrelated full Msgbox/UI snapshot when the
            # colliding NetworkDown button target is absent in typed state.
            return False
        if semantic_id in (
            "overlay/network-reconnect/cancel",
            "overlay/network-reconnect/confirm",
        ) and self._dock_full_prompt_matches(state):
            return False
        if (
            semantic_id == "overlay/login-data-expired/confirm"
            and not self._login_data_expired_prompt_matches(state)
        ):
            return False
        if len(matches) > 1:
            raise SemanticGateClosed("semantic target mapping is ambiguous")
        if semantic_id.startswith("guild/") and semantic_id in (
            "guild/lobby/report",
            "guild/logistics/supply",
            "guild/logistics/mission",
            "guild/operations/formation",
            "guild/operations/report",
            "guild/operations/dispatch/open",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild control snapshots are not coherent")
            return bool(
                len(matches) == 1
                and self._guild_delegated_button_proven(
                    state, ui_state, semantic_id, matches[0]
                )
                and not self._blocking_rules(state, semantic_id)
            )
        if semantic_id in (
            "guild/dispatch-detail/close",
            "guild/dispatch-detail/formation",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild dispatch snapshots are not coherent")
            return bool(
                len(matches) == 1
                and self._guild_dispatch_detail_control_proven(
                    state, ui_state, semantic_id, matches[0]
                )
                and not self._blocking_rules(state, semantic_id)
            )
        if semantic_id in (
            "guild/report/close",
            "guild/report/claim-all",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild report snapshots are not coherent")
            return bool(
                len(matches) == 1
                and self._guild_report_control_proven(
                    state, ui_state, semantic_id, matches[0]
                )
                and not self._blocking_rules(state, semantic_id)
            )
        if semantic_id in (
            "guild/formation/close",
            "guild/formation/recommend",
            "guild/formation/go",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild formation snapshots are not coherent")
            return bool(
                len(matches) == 1
                and self._guild_formation_control_proven(
                    state, ui_state, semantic_id, matches[0]
                )
                and not self._blocking_rules(state, semantic_id)
            )
        if semantic_id == "main/guild":
            return bool(
                self.main_page_visible()
                and matches
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].raycast_top is None
                and matches[0].point is not None
                and matches[0].bounds is not None
                and matches[0].bounds.contains(matches[0].point)
                and not self._blocking_rules(state, semantic_id)
            )
        if semantic_id == "dorm/empty-food/cancel":
            return self._dorm_empty_food_cancel_proven(state)
        if semantic_id in ("dorm/feed", "dorm/collect"):
            return self._dorm_page_control_proven(state, semantic_id)
        if semantic_id in (
            "meowfficer/page/back",
            "meowfficer/fort/enter",
            "meowfficer/buy/enter",
            "meowfficer/train/enter",
        ):
            try:
                self.meowfficer_dock_state()
            except SemanticGateClosed:
                return False
            return bool(
                matches
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].raycast_top is None
                and matches[0].point is not None
                and matches[0].bounds is not None
                and matches[0].bounds.contains(matches[0].point)
            )
        if semantic_id in (
            "meowfficer/train/close",
            "meowfficer/train/complete/first",
            "meowfficer/train/finish-all",
            "meowfficer/train/start",
        ):
            try:
                training = self.meowfficer_training_state()
            except SemanticGateClosed:
                return False
            return bool(
                matches
                and (
                    semantic_id != "meowfficer/train/complete/first"
                    or training.completed > 0
                )
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].raycast_top is None
                and matches[0].point is not None
                and matches[0].bounds is not None
                and matches[0].bounds.contains(matches[0].point)
            )
        if (
            semantic_id == "tactical/continue/cancel"
            and not self._tactical_continue_prompt_matches(state)
        ):
            return False
        if semantic_id in (
            "overlay/network-reconnect/cancel",
            "overlay/network-reconnect/confirm",
        ) and not self._network_reconnect_prompt_matches(state):
            return False
        if semantic_id in (
            "build/warning/cancel",
            "build/warning/confirm",
        ) and not self._build_warning_prompt_matches(state):
            return False
        if semantic_id in (
            "build/queue/finish-cancel",
            "build/queue/finish-confirm",
        ) and self._build_queue_finish_prompt_cost(state) is None:
            return False
        if semantic_id in (
            "tactical/course/cancel",
            "tactical/course/confirm",
        ) and not self._tactical_course_prompt_matches(state):
            return False
        if (
            semantic_id in ("research/start/cancel", "research/start/confirm")
            and self._research_start_prompt_cost(state) is None
        ):
            return False
        if semantic_id in (
            "research/queue/cancel",
            "research/queue/confirm",
        ) and not self._research_queue_prompt_matches(state):
            return False
        if semantic_id in (
            "guild/dispatch/cancel",
            "guild/dispatch/confirm",
        ) and not self._guild_dispatch_prompt_matches(state):
            return False
        if semantic_id in (
            "guild/exchange/cancel",
            "guild/exchange/confirm",
        ) and not self._guild_exchange_prompt_matches(state):
            return False
        if semantic_id in (
            "os/map/auto-search/off",
            "os/map/auto-search/on",
            "os/map/mission-list",
            "os/map/storage",
            "os/map/order",
            "os/order/back",
            "os/order/scan",
            "os/order/submarine",
            "os/port/enter",
            "os/port/supply",
            "os/port/dock",
            "os/port/dock/back",
            "os/port/dock/repair-all",
            "os/port/back",
            "os/shop/back",
            "os/globe/voucher",
            "os/globe/mission-overview",
            "os/mission-list/close",
            "os/voucher/back",
            "os/storage/back",
        ):
            return bool(
                matches
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].raycast_top is None
                and matches[0].point is not None
                and matches[0].bounds is not None
                and matches[0].bounds.contains(matches[0].point)
                and not self._blocking_rules(state, semantic_id)
            )
        if semantic_id == "os/help/close":
            return bool(
                matches
                and matches[0].active_in_hierarchy
                and matches[0].active_and_enabled
                and matches[0].interactable
                and matches[0].raycast_top is None
                and matches[0].point is not None
                and matches[0].bounds is not None
                and matches[0].bounds.contains(matches[0].point)
                and not self._blocking_rules(state, semantic_id)
            )
        return bool(
            matches
            and matches[0].actionable
            and not self._blocking_rules(state, semantic_id)
        )

    def bounds(self, semantic_id: str) -> Bounds:
        target = self._unique(self.read_state(), semantic_id)
        if target.bounds is None:
            raise SemanticGateClosed("semantic target has no screen bounds")
        return target.bounds

    def current_scene(self) -> int:
        return self.read_state().scene_handle

    @staticmethod
    def _mission_rows(state: OracleState, button_name: str) -> Tuple[ButtonState, ...]:
        pattern = re.compile(
            r"(?:^|/)TaskScene\(Clone\)/pages/TaskListPage\(Clone\)/"
            r"right_panel/content/([0-9]+)/frame/" + re.escape(button_name) + r"$"
        )
        rows = []
        indexes = set()
        for button in state.buttons:
            if button.name != button_name:
                continue
            match = pattern.search(button.path)
            if match is None:
                continue
            index = int(match.group(1))
            if index in indexes:
                raise SemanticGateClosed(
                    "mission row Button index is ambiguous: {0}".format(index)
                )
            indexes.add(index)
            rows.append((index, button))
        rows.sort(key=lambda item: item[0])
        return tuple(button for _, button in rows)

    def mission_page_state(self) -> MissionPageState:
        """Classify the reviewed TaskScene without treating absence as empty."""

        return self._retry_transition_read(self._mission_page_state_once)

    def _mission_page_state_once(self) -> MissionPageState:
        state = self.read_state()
        back = self._unique(state, "task/page/back")
        if not back.actionable or self._blocking_rules(state, "task/page/back"):
            raise SemanticGateClosed("mission page identity is not safely actionable")

        claim_all_matches = self._matches(state, "task/claim/all")
        if len(claim_all_matches) > 1:
            raise SemanticGateClosed("mission claim-all target is ambiguous")
        claim_all = claim_all_matches[0] if claim_all_matches else None
        claim_rows = self._mission_rows(state, "get_btn")
        unfinished_rows = self._mission_rows(state, "go_btn")

        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed(
                "button and mission text snapshots are not coherent"
            )
        empty_markers = tuple(
            item
            for item in ui_state.texts
            if item.name == "Text"
            and item.path.endswith("TaskScene(Clone)/TaskEmptyListUI(Clone)/Text")
            and item.text == "没有进行中的任务"
            and item.active_in_hierarchy
            and item.active_and_enabled
            and not item.truncated
            and item.bounds is not None
            and item.bounds.right > 0
            and item.bounds.bottom > 0
            and item.bounds.left < self.fingerprint.width
            and item.bounds.top < self.fingerprint.height
        )
        if len(empty_markers) > 1:
            raise SemanticGateClosed("mission empty marker is ambiguous")

        actionable_claim_rows = tuple(
            button for button in claim_rows if button.actionable
        )
        actionable_unfinished_rows = tuple(
            button for button in unfinished_rows if button.actionable
        )
        if claim_all is not None and claim_all.actionable:
            disposition = MissionDisposition.CLAIMABLE_ALL
        elif actionable_claim_rows:
            disposition = MissionDisposition.CLAIMABLE_ROW
        elif claim_all is not None or claim_rows:
            # A claim object hidden by clipping or an overlay is not evidence of
            # a safe click, and it must not be misreported as no work.
            disposition = MissionDisposition.UNKNOWN
        elif actionable_unfinished_rows:
            disposition = MissionDisposition.UNFINISHED
        elif empty_markers:
            disposition = MissionDisposition.EMPTY
        else:
            # Never infer EMPTY from mere absence while a page may still load.
            disposition = MissionDisposition.UNKNOWN

        return MissionPageState(
            disposition=disposition,
            generation=state.generation,
            back=back,
            claim_all=claim_all,
            claim_rows=actionable_claim_rows,
            unfinished_rows=actionable_unfinished_rows,
        )

    def mission_weekly_reward_available(self) -> bool:
        """Read the exact weekly-task badge on the current TaskScene."""

        return self._retry_transition_read(self._mission_weekly_reward_available_once)

    def _mission_weekly_reward_available_once(self) -> bool:
        state = self.read_state()
        back = self._unique(state, "task/page/back")
        if not back.actionable or self._blocking_rules(state, "task/page/back"):
            raise SemanticGateClosed("mission page identity is not safely actionable")
        ui_state = self.read_ui_state()
        matches = tuple(
            image
            for image in ui_state.images
            if image.name == "tip"
            and image.path.endswith(
                "TaskScene(Clone)/blur_panel/adapt/left_length/frame/"
                "tagRoot/weekly/tip"
            )
            and image.sprite == "exclamation_mark"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
        )
        if len(matches) > 1:
            raise SemanticGateClosed("mission weekly badge is ambiguous")
        return bool(matches)

    def weekly_mission_progress_claim_available(self) -> bool:
        """Return whether the selected weekly tab exposes its progress reward."""

        return self._retry_transition_read(
            lambda: self._weekly_mission_progress_claim_target_once() is not None
        )

    def _weekly_mission_progress_claim_target_once(
        self,
    ) -> Optional[ButtonState]:
        state = self.read_state()
        back = self._unique(state, "task/page/back")
        if not back.actionable or self._blocking_rules(state, "task/page/back"):
            raise SemanticGateClosed("mission page identity is not safely actionable")
        path = (
            "TaskScene(Clone)/pages/TaskListForWeekPage(Clone)/task_progress/"
            "get_btn"
        )
        matches = tuple(
            button
            for button in state.buttons
            if button.name == "get_btn" and button.path.endswith(path)
        )
        if len(matches) > 1:
            raise SemanticGateClosed("weekly mission progress claim is ambiguous")
        if not matches:
            return None
        target = matches[0]
        if (
            not target.active_in_hierarchy
            or not target.active_and_enabled
            or not target.interactable
            or target.bounds is None
            or self._blocking_rules(state, "task/weekly-progress/claim")
        ):
            return None

        ui_state = self.read_ui_state()
        if (
            ui_state.generation < state.generation
            or ui_state.generation > state.generation + 2
        ):
            raise SemanticGateClosed(
                "weekly mission button and UI snapshots are not coherent"
            )
        weekly_selected = tuple(
            image
            for image in ui_state.images
            if image.path.endswith(
                "TaskScene(Clone)/blur_panel/adapt/left_length/frame/"
                "tagRoot/weekly/selected/Image"
            )
            and image.sprite == "icon_week_sel"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
        )
        button_images = tuple(
            image
            for image in ui_state.images
            if image.path.endswith(path)
            and image.sprite == "get_btn"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds == target.bounds
        )
        enabled_images = tuple(
            image
            for image in ui_state.images
            if image.path.endswith(path + "/enable")
            and image.sprite == "finish_btn_tran_1"
            and image.active_in_hierarchy
            and image.active_and_enabled
            and not image.truncated
            and image.bounds is not None
            and target.bounds.contains(
                Point(
                    (image.bounds.left + image.bounds.right) / 2.0,
                    (image.bounds.top + image.bounds.bottom) / 2.0,
                )
            )
        )
        if len(weekly_selected) != 1:
            raise SemanticGateClosed("weekly mission tab identity is absent or ambiguous")
        if len(button_images) != 1 or len(enabled_images) != 1:
            return None
        return target

    def click_weekly_mission_progress_claim(self) -> ActionReceipt:
        """Claim the unique currently enabled weekly progress reward once."""

        target = self._retry_transition_read(
            self._weekly_mission_progress_claim_target_once
        )
        if target is None or target.bounds is None:
            raise SemanticGateClosed("weekly mission progress claim is absent")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before weekly mission claim")
        point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        if not target.bounds.contains(point):
            raise SemanticGateClosed("weekly mission claim point is invalid")
        self._tap(int(round(point.x)), int(round(point.y)))
        return ActionReceipt(
            semantic_id="task/weekly-progress/claim",
            generation=self._last_generation or 0,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def wait_for_mission_state(
        self,
        timeout_seconds: float,
        interval_seconds: float = 0.5,
        required_generations: int = 2,
    ) -> MissionPageState:
        if required_generations < 2:
            raise ValueError("mission state requires at least two generations")
        deadline = self._monotonic() + timeout_seconds
        last_state: Optional[MissionPageState] = None
        stable_generations = 0
        last_error: Optional[SemanticOracleError] = None
        while self._monotonic() < deadline:
            try:
                candidate = self.mission_page_state()
                if candidate.disposition == MissionDisposition.UNKNOWN:
                    last_state = None
                    stable_generations = 0
                elif last_state is None or candidate.signature != last_state.signature:
                    last_state = candidate
                    stable_generations = 1
                elif candidate.generation > last_state.generation:
                    last_state = candidate
                    stable_generations += 1
                if (
                    last_state is not None
                    and stable_generations >= required_generations
                ):
                    return last_state
            except SemanticOracleError as exc:
                last_error = exc
                last_state = None
                stable_generations = 0
            self._sleep(interval_seconds)
        if last_error is not None:
            raise SemanticGateClosed(
                "stable mission-state wait timed out"
            ) from last_error
        raise SemanticGateClosed("stable mission-state wait timed out")

    def click_mission_claim_row(self, expected_path: str) -> ActionReceipt:
        """Claim one uniquely actionable task row by its current typed path."""

        if not isinstance(expected_path, str) or not expected_path:
            raise ValueError("mission claim row path must be non-empty")
        page = self.mission_page_state()
        if page.disposition != MissionDisposition.CLAIMABLE_ROW:
            raise SemanticGateClosed("mission page is not row-claimable")
        matches = tuple(
            row for row in page.claim_rows if row.path == expected_path
        )
        if len(page.claim_rows) != 1 or len(matches) != 1:
            raise SemanticGateClosed("mission claim row is absent or ambiguous")
        target = matches[0]
        match = re.search(r"/content/([0-9]+)/frame/get_btn$", target.path)
        if match is None:
            raise SemanticGateClosed("mission claim row path is malformed")
        if not target.actionable or target.point is None or target.bounds is None:
            raise SemanticGateClosed("mission claim row is not actionable")
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed before mission row claim")
        click_point = Point(
            (target.bounds.left + target.bounds.right) / 2.0,
            (target.bounds.top + target.bounds.bottom) / 2.0,
        )
        if not target.bounds.contains(click_point):
            raise SemanticGateClosed("mission claim row click point is invalid")
        self._tap(int(round(click_point.x)), int(round(click_point.y)))
        return ActionReceipt(
            semantic_id="task/claim/row/" + match.group(1),
            generation=page.generation,
            point=click_point,
            bounds=target.bounds,
            path=target.path,
        )

    def click(self, semantic_id: str) -> ActionReceipt:
        delegated_new_ship_reward = semantic_id == "reward/new-ship/continue"
        state = (
            self._new_ship_reward_action_state()
            if delegated_new_ship_reward
            else self.read_state()
        )
        delegated_login_update = (
            semantic_id == "login/update/download"
            and self._login_update_download_prompt_matches(state)
        )
        delegated_login_restart = (
            semantic_id
            in ("login/update/restart-dialog", "login/update/restart-msgbox")
            and self._login_update_restart_prompt_target(state) == semantic_id
        )
        delegated_activity_main_back = bool(
            semantic_id == "event-list/page/back"
            and len(self._matches(state, "event-list/page/back")) == 1
            and not self._matches(state, "reward/award-info/close")
            and not self._matches(state, "reward/award-info1/close")
        )
        delegated_mail_confirmation = bool(
            semantic_id in ("mail/confirm/claim", "mail/confirm/cancel")
            and self.mail_confirmation_kind() is not None
        )
        delegated_exercise_opponent = bool(
            semantic_id.startswith("exercise/opponent/")
            and self.exercise_page_visible()
        )
        delegated_exercise_start = bool(
            semantic_id == "exercise/opponent/start"
            and self.exercise_opponent_detail_visible()
        )
        delegated_exercise_detail_back = bool(
            semantic_id == "exercise/opponent/back"
            and self.exercise_opponent_detail_visible()
        )
        delegated_exercise_back = bool(
            semantic_id == "exercise/page/back" and self.exercise_page_visible()
        )
        delegated_academy_munitions = bool(
            semantic_id == "academy/munitions" and self.academy_munitions_available()
        )
        delegated_academy_game_room = bool(
            semantic_id == "academy/game-room" and self.academy_page_visible()
        )
        delegated_shipyard_series = bool(
            semantic_id.startswith("shipyard/series/")
            and (semantic_id != "shipyard/series/open" or self.shipyard_page_visible())
        )
        if semantic_id in (
            "overlay/network-reconnect/cancel",
            "overlay/network-reconnect/confirm",
        ):
            if self._dock_full_prompt_matches(state):
                raise SemanticGateClosed(
                    "dock-full prompt cannot use network reconnect input"
                )
            if not self._network_reconnect_prompt_matches(state):
                raise SemanticGateClosed(
                    "network reconnect prompt identity is not proven"
                )
        if (
            semantic_id == "overlay/login-data-expired/confirm"
            and not self._login_data_expired_prompt_matches(state)
        ):
            raise SemanticGateClosed("login-data-expired prompt identity is not proven")
        if semantic_id in (
            "minigame/tickets/cancel",
            "minigame/tickets/confirm",
        ) and not self._minigame_ticket_prompt_matches(state):
            raise SemanticGateClosed("minigame ticket prompt identity is not proven")
        target = self._unique(state, semantic_id)
        delegated_guild_control = False
        if semantic_id in (
            "guild/lobby/report",
            "guild/logistics/supply",
            "guild/logistics/mission",
            "guild/operations/formation",
            "guild/operations/report",
            "guild/operations/dispatch/open",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild control snapshots are not coherent")
            delegated_guild_control = self._guild_delegated_button_proven(
                state, ui_state, semantic_id, target
            )
        delegated_guild_dispatch_detail = False
        if semantic_id in (
            "guild/dispatch-detail/close",
            "guild/dispatch-detail/formation",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild dispatch snapshots are not coherent")
            delegated_guild_dispatch_detail = (
                self._guild_dispatch_detail_control_proven(
                    state, ui_state, semantic_id, target
                )
            )
        delegated_guild_report = False
        if semantic_id in (
            "guild/report/close",
            "guild/report/claim-all",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild report snapshots are not coherent")
            delegated_guild_report = self._guild_report_control_proven(
                state, ui_state, semantic_id, target
            )
        delegated_guild_formation = False
        if semantic_id in (
            "guild/formation/close",
            "guild/formation/recommend",
            "guild/formation/go",
        ):
            ui_state = self.read_ui_state()
            if (
                ui_state.generation < state.generation
                or ui_state.generation > state.generation + 2
            ):
                raise SemanticGateClosed("guild formation snapshots are not coherent")
            delegated_guild_formation = self._guild_formation_control_proven(
                state, ui_state, semantic_id, target
            )
        delegated_main_guild = bool(
            semantic_id == "main/guild"
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
            and self.main_page_visible()
        )
        delegated_main_raid = bool(
            semantic_id == "main/raid" and self._main_raid_entry_proven(state)
        )
        delegated_meowfficer_get_continue = bool(
            semantic_id == "meowfficer/get/continue"
            and self._meowfficer_get_continue_proven(state)
        )
        delegated_meowfficer_purchase_control = False
        if semantic_id in (
            "meowfficer/buy/min",
            "meowfficer/buy/add",
            "meowfficer/buy/max",
            "meowfficer/buy/submit",
        ):
            try:
                self.meowfficer_purchase_state()
            except SemanticGateClosed:
                pass
            else:
                delegated_meowfficer_purchase_control = bool(
                    target.active_in_hierarchy
                    and target.active_and_enabled
                    and target.interactable
                    and target.raycast_top is None
                    and target.point is not None
                    and target.bounds is not None
                    and target.bounds.contains(target.point)
                )
        delegated_meowfficer_purchase_skip = bool(
            semantic_id == "meowfficer/buy/skip"
            and self._meowfficer_purchase_skip_proven(state)
        )
        delegated_meowfficer_purchase_prompt = bool(
            semantic_id
            in ("meowfficer/buy/cancel", "meowfficer/buy/confirm")
            and self._meowfficer_purchase_prompt_proven(state)
        )
        delegated_meowfficer_enhance_control = False
        if semantic_id == "meowfficer/enhance/open":
            try:
                self.meowfficer_dock_state()
            except SemanticGateClosed:
                pass
            else:
                delegated_meowfficer_enhance_control = (
                    self._meowfficer_reviewed_control_proven(state, semantic_id)
                )
        elif semantic_id in (
            "meowfficer/enhance/back",
            "meowfficer/feed/open",
            "meowfficer/enhance/submit",
        ):
            try:
                self.meowfficer_enhance_state()
            except SemanticGateClosed:
                pass
            else:
                delegated_meowfficer_enhance_control = (
                    self._meowfficer_reviewed_control_proven(state, semantic_id)
                )
        elif semantic_id in (
            "meowfficer/feed/cancel",
            "meowfficer/feed/confirm",
        ):
            try:
                self.meowfficer_feed_state()
            except SemanticGateClosed:
                pass
            else:
                delegated_meowfficer_enhance_control = (
                    self._meowfficer_reviewed_control_proven(state, semantic_id)
                )
        delegated_meowfficer_enhance_prompt = bool(
            semantic_id
            in ("meowfficer/enhance/cancel", "meowfficer/enhance/confirm")
            and self._meowfficer_enhance_prompt_proven(state)
        )
        delegated_meowfficer_lock_toggle = bool(
            semantic_id in ("meowfficer/get/lock", "meowfficer/get/unlock")
            and self._meowfficer_lock_toggle_proven(state, semantic_id)
        )
        delegated_meowfficer_lock_prompt = bool(
            semantic_id
            in (
                "meowfficer/get/lock-cancel",
                "meowfficer/get/lock-confirm",
            )
            and self._meowfficer_lock_prompt_proven(state)
        )
        delegated_meowfficer_get_result = bool(
            semantic_id == "meowfficer/get/result/close"
            and self._meowfficer_get_result_proven(state)
        )
        delegated_meowfficer_fort_close = bool(
            semantic_id == "meowfficer/fort/close"
            and self._meowfficer_fort_close_proven(state)
        )
        delegated_meowfficer_queue_control = False
        if semantic_id in (
            "meowfficer/queue/auto",
            "meowfficer/queue/start",
            "meowfficer/queue/close",
        ):
            try:
                self.meowfficer_queue_state()
            except SemanticGateClosed:
                pass
            else:
                delegated_meowfficer_queue_control = bool(
                    target.active_in_hierarchy
                    and target.active_and_enabled
                    and target.interactable
                    and target.raycast_top is None
                    and target.point is not None
                    and target.bounds is not None
                    and target.bounds.contains(target.point)
                )
        delegated_meowfficer_queue_prompt = bool(
            semantic_id
            in (
                "meowfficer/queue/cancel",
                "meowfficer/queue/confirm",
            )
            and self._meowfficer_queue_prompt_proven(state)
        )
        delegated_meowfficer_dock_control = False
        if semantic_id in (
            "meowfficer/page/back",
            "meowfficer/fort/enter",
            "meowfficer/buy/enter",
            "meowfficer/train/enter",
        ):
            try:
                self.meowfficer_dock_state()
            except SemanticGateClosed:
                pass
            else:
                delegated_meowfficer_dock_control = bool(
                    target.active_in_hierarchy
                    and target.active_and_enabled
                    and target.interactable
                    and target.raycast_top is None
                    and target.point is not None
                    and target.bounds is not None
                    and target.bounds.contains(target.point)
                )
        delegated_meowfficer_training_control = False
        if semantic_id in (
            "meowfficer/train/close",
            "meowfficer/train/complete/first",
            "meowfficer/train/finish-all",
            "meowfficer/train/start",
        ):
            try:
                training = self.meowfficer_training_state()
            except SemanticGateClosed:
                pass
            else:
                delegated_meowfficer_training_control = bool(
                    (
                        semantic_id != "meowfficer/train/complete/first"
                        or training.completed > 0
                    )
                    and target.active_in_hierarchy
                    and target.active_and_enabled
                    and target.interactable
                    and target.raycast_top is None
                    and target.point is not None
                    and target.bounds is not None
                    and target.bounds.contains(target.point)
                )
        delegated_operation_siren_control = bool(
            semantic_id
            in (
                "os/map/auto-search/off",
                "os/map/auto-search/on",
                "os/map/strategic-search/off",
                "os/map/strategic-search/on",
                "os/strategic-search/confirm",
                "os/strategic-search/cancel",
                "os/map/mission-list",
                "os/map/storage",
                "os/map/order",
                "os/order/back",
                "os/order/scan",
                "os/order/submarine",
                "os/port/enter",
                "os/port/supply",
                "os/port/dock",
                "os/port/dock/back",
                "os/port/dock/repair-all",
                "os/port/back",
                "os/shop/back",
                "os/globe/voucher",
                "os/globe/mission-overview",
                "os/mission-overview/back",
                "os/mission-list/close",
                "os/voucher/back",
                "os/storage/back",
            )
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
            and (
                self.operation_siren_state()
                if semantic_id
                in (
                    "os/map/auto-search/off",
                    "os/map/auto-search/on",
                    "os/map/strategic-search/off",
                    "os/map/strategic-search/on",
                    "os/map/mission-list",
                    "os/map/storage",
                    "os/port/enter",
                )
                else True
            )
        )
        delegated_operation_siren_boss_start = bool(
            semantic_id == "os/boss/start"
            and self.operation_siren_boss_preparation_visible()
        )
        delegated_operation_siren_help = bool(
            semantic_id == "os/help/close"
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
        )
        delegated_meta_back = bool(
            semantic_id == "meta/page/back"
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and target.bounds.contains(target.point)
            and not self._blocking_rules(state, semantic_id)
        )
        delegated_game_room_list = bool(
            semantic_id == "game-room/list"
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
        )
        delegated_game_room_home = bool(
            semantic_id == "game-room/home"
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and self.game_room_page_visible()
        )
        delegated_game_room_back = bool(
            semantic_id == "game-room/back"
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and self.game_room_page_visible()
        )
        delegated_shop_home = bool(
            semantic_id == "shop/home"
            and target.active_in_hierarchy
            and target.active_and_enabled
            and target.interactable
            and target.raycast_top is None
            and target.point is not None
            and target.bounds is not None
            and (self.recommendation_shop_visible() or self.game_room_page_visible())
        )
        dorm_back_delegated = (
            semantic_id == "dorm/page/back"
            and self._dorm_back_delegated_raycast_proven(state)
        )
        dorm_empty_food_cancel = (
            semantic_id == "dorm/empty-food/cancel"
            and self._dorm_empty_food_cancel_proven(state)
        )
        dorm_page_control = semantic_id in (
            "dorm/feed",
            "dorm/collect",
        ) and self._dorm_page_control_proven(state, semantic_id)
        mail_manager_back_delegated = (
            semantic_id == "mail/manage/back"
            and self._mail_manager_back_delegated_raycast_proven(state)
        )
        if (
            semantic_id == "tactical/continue/cancel"
            and not self._tactical_continue_prompt_matches(state)
        ):
            raise SemanticGateClosed("tactical continue prompt identity is not proven")
        if semantic_id in (
            "build/warning/cancel",
            "build/warning/confirm",
        ) and not self._build_warning_prompt_matches(state):
            raise SemanticGateClosed("build warning prompt identity is not proven")
        if semantic_id in (
            "build/queue/finish-cancel",
            "build/queue/finish-confirm",
        ) and self._build_queue_finish_prompt_cost(state) is None:
            raise SemanticGateClosed(
                "construction quick-finish prompt identity is not proven"
            )
        if semantic_id in (
            "tactical/course/cancel",
            "tactical/course/confirm",
        ) and not self._tactical_course_prompt_matches(state):
            raise SemanticGateClosed("tactical course prompt identity is not proven")
        if semantic_id in (
            "commission/start/cancel",
            "commission/start/confirm",
        ):
            parts = self._msgbox_prompt_parts(state)
            if parts is None or re.fullmatch(
                r"本次委托需要花费([1-9][0-9]*)石油", parts[0]
            ) is None or parts[1:] != ("取消", "确定"):
                raise SemanticGateClosed(
                    "commission start prompt identity is not proven"
                )
        if semantic_id in (
            "commission/cancel/cancel",
            "commission/cancel/confirm",
        ):
            parts = self._msgbox_prompt_parts(state)
            if parts != ("确定放弃任务？", "取消", "确定"):
                raise SemanticGateClosed(
                    "commission cancel prompt identity is not proven"
                )
        if (
            semantic_id in ("research/start/cancel", "research/start/confirm")
            and self._research_start_prompt_cost(state) is None
        ):
            raise SemanticGateClosed("research start prompt identity is not proven")
        if semantic_id in (
            "research/queue/cancel",
            "research/queue/confirm",
        ) and not self._research_queue_prompt_matches(state):
            raise SemanticGateClosed("research queue prompt identity is not proven")
        if semantic_id in (
            "guild/dispatch/cancel",
            "guild/dispatch/confirm",
        ) and not self._guild_dispatch_prompt_matches(state):
            raise SemanticGateClosed("guild dispatch prompt identity is not proven")
        if semantic_id in (
            "guild/exchange/cancel",
            "guild/exchange/confirm",
        ) and not self._guild_exchange_prompt_matches(state):
            raise SemanticGateClosed("guild exchange prompt identity is not proven")
        if semantic_id == "research/detail/root" and any(
            candidate.actionable
            for candidate in self._matches(state, "research/detail/finish")
        ):
            raise SemanticGateClosed(
                "research detail cannot close through the root while finish is actionable"
            )
        if (
            (
                not target.actionable
                and not delegated_login_update
                and not delegated_login_restart
                and not delegated_activity_main_back
                and not delegated_shop_home
                and not delegated_mail_confirmation
                and not delegated_exercise_opponent
                and not delegated_exercise_start
                and not delegated_exercise_detail_back
                and not delegated_exercise_back
                and not delegated_academy_munitions
                and not delegated_academy_game_room
                and not delegated_game_room_list
                and not delegated_game_room_home
                and not delegated_game_room_back
                and not delegated_shipyard_series
                and not delegated_operation_siren_control
                and not delegated_operation_siren_boss_start
                and not delegated_operation_siren_help
                and not delegated_meta_back
                and not dorm_back_delegated
                and not dorm_empty_food_cancel
                and not dorm_page_control
                and not mail_manager_back_delegated
                and not delegated_new_ship_reward
                and not delegated_meowfficer_dock_control
                and not delegated_meowfficer_training_control
                and not delegated_meowfficer_purchase_control
                and not delegated_meowfficer_purchase_skip
                and not delegated_meowfficer_purchase_prompt
                and not delegated_meowfficer_enhance_control
                and not delegated_meowfficer_enhance_prompt
                and not delegated_meowfficer_get_continue
                and not delegated_meowfficer_lock_toggle
                and not delegated_meowfficer_lock_prompt
                and not delegated_meowfficer_get_result
                and not delegated_meowfficer_fort_close
                and not delegated_meowfficer_queue_control
                and not delegated_meowfficer_queue_prompt
                and not delegated_main_guild
                and not delegated_main_raid
                and not delegated_guild_control
                and not delegated_guild_dispatch_detail
                and not delegated_guild_report
                and not delegated_guild_formation
            )
            or target.point is None
            or target.bounds is None
        ):
            raise SemanticGateClosed("semantic target is not actionable")
        point = target.point
        if (
            delegated_guild_control
            or delegated_guild_dispatch_detail
            or delegated_guild_report
            or delegated_guild_formation
        ):
            # Guild controls commonly expose an edge pivot while their exact
            # typed Button and matching Image cover a much larger visible
            # rectangle.  Use the centre of that proven rectangle.
            point = Point(
                (target.bounds.left + target.bounds.right) / 2.0,
                (target.bounds.top + target.bounds.bottom) / 2.0,
            )
        if semantic_id == "os/order/back":
            # SVOrderPanel anchors this wide back hit area at its left edge.
            # Use the centre of the exact visible bounds so the tap is not
            # delivered on the boundary shared with the panel background.
            assert target.bounds is not None
            point = Point(
                (target.bounds.left + target.bounds.right) / 2.0,
                (target.bounds.top + target.bounds.bottom) / 2.0,
            )
        if semantic_id == "os/help/close":
            # WorldHelpUI anchors its back Button pivot on x=0.  Use the
            # centre of its fully visible proven bounds so Android receives an
            # in-screen coordinate rather than a boundary tap ignored by Unity.
            assert target.bounds is not None
            point = Point(
                (target.bounds.left + target.bounds.right) / 2.0,
                (target.bounds.top + target.bounds.bottom) / 2.0,
            )
        if semantic_id == "meowfficer/page/back":
            # CommanderCatUI docks this button partly outside the left/top
            # viewport and reports that clipped pivot as its input point.
            # The full dock identity was proven above; tap the centre of the
            # visible part of the exact button bounds.
            assert target.bounds is not None
            point = Point(
                (
                    max(target.bounds.left, 0.0)
                    + min(target.bounds.right, self.fingerprint.width - 1.0)
                )
                / 2.0,
                (
                    max(target.bounds.top, 0.0)
                    + min(target.bounds.bottom, self.fingerprint.height - 1.0)
                )
                / 2.0,
            )
        if semantic_id == "meowfficer/train/complete/first":
            # CommanderBoxesUI anchors each completed-slot Button on the top
            # edge of its exact RectTransform.  That pivot is inside the
            # reported bounds but Unity ignores it as a boundary tap.  The
            # training identity and completed-slot text were proven above, so
            # use the centre of this uniquely mapped Button rectangle.
            assert target.bounds is not None
            point = Point(
                (target.bounds.left + target.bounds.right) / 2.0,
                (target.bounds.top + target.bounds.bottom) / 2.0,
            )
        if dorm_page_control:
            ui_state = self.read_ui_state()
            if not self._dorm_page_control_proven(
                state, semantic_id, ui_state=ui_state
            ):
                raise SemanticGateClosed("dorm page control changed before input")
            image_path = (
                target.path + "/icon" if semantic_id == "dorm/feed" else target.path
            )
            image_sprite = "btn_feed" if semantic_id == "dorm/feed" else "onekey"
            click_images = tuple(
                image
                for image in ui_state.images
                if image.path == image_path
                and image.sprite == image_sprite
                and image.bounds is not None
            )
            if len(click_images) != 1:
                raise SemanticGateClosed("dorm page-control click image is ambiguous")
            click_bounds = click_images[0].bounds
            assert click_bounds is not None
            point = Point(
                (click_bounds.left + click_bounds.right) / 2.0,
                (click_bounds.top + click_bounds.bottom) / 2.0,
            )
            if not target.bounds.contains(point):
                raise SemanticGateClosed("dorm page-control click point is invalid")
        if (
            semantic_id == "research/queue/claim"
            and math.isclose(point.x, float(self.fingerprint.width), abs_tol=0.01)
            and math.isclose(
                target.bounds.right, float(self.fingerprint.width), abs_tol=0.01
            )
            and 0 <= target.bounds.left < target.bounds.right
            and 0 <= target.bounds.top < target.bounds.bottom <= self.fingerprint.height
        ):
            # This reviewed edge-docked Button reports its right-edge pivot as
            # the screen point.  Its complete visible bounds and top raycast
            # are proven, so use the centre of the visible in-screen rectangle.
            point = Point(
                (
                    target.bounds.left
                    + min(target.bounds.right, self.fingerprint.width - 1.0)
                )
                / 2.0,
                (target.bounds.top + target.bounds.bottom) / 2.0,
            )
        if not (
            0 <= point.x < self.fingerprint.width
            and 0 <= point.y < self.fingerprint.height
        ):
            raise SemanticGateClosed("semantic target point is outside the screen")

        disallowed = tuple(
            rule.blocker_id for rule in self._blocking_rules(state, semantic_id)
        )
        if disallowed:
            raise SemanticGateClosed(
                "semantic input is blocked by: {0}".format(", ".join(disallowed))
            )
        if self._foreground_component() != self.fingerprint.component:
            raise SemanticGateClosed("foreground changed immediately before input")

        x = int(round(point.x))
        y = int(round(point.y))
        self._tap(x, y)
        if delegated_login_update or delegated_login_restart:
            # A small maintenance patch can finish between observer frames.
            # The exact reviewed confirmation is sufficient to establish the
            # update session for the later completion/restart gate.
            self._login_update_seen = True
        return ActionReceipt(
            semantic_id=semantic_id,
            generation=state.generation,
            point=point,
            bounds=target.bounds,
            path=target.path,
        )

    def wait_for(
        self,
        semantic_id: str,
        timeout_seconds: float,
        minimum_generation: Optional[int] = None,
        interval_seconds: float = 0.5,
    ) -> ButtonState:
        deadline = self._monotonic() + timeout_seconds
        last_error: Optional[SemanticOracleError] = None
        while self._monotonic() < deadline:
            try:
                state = self.read_state()
                matches = self._matches(state, semantic_id)
                if len(matches) > 1:
                    raise SemanticGateClosed("semantic target mapping is ambiguous")
                if (
                    matches
                    and matches[0].actionable
                    and not self._blocking_rules(state, semantic_id)
                    and (
                        minimum_generation is None
                        or state.generation > minimum_generation
                    )
                ):
                    return matches[0]
            except SemanticOracleError as exc:
                last_error = exc
            self._sleep(interval_seconds)
        if last_error is not None:
            raise SemanticGateClosed("semantic wait timed out") from last_error
        raise SemanticGateClosed("semantic wait timed out")

    def wait_for_any(
        self,
        semantic_ids: Tuple[str, ...],
        timeout_seconds: float,
        minimum_generation: Optional[int] = None,
        interval_seconds: float = 0.5,
    ) -> Tuple[str, ButtonState]:
        if not semantic_ids or len(set(semantic_ids)) != len(semantic_ids):
            raise ValueError("semantic wait set must contain unique targets")
        deadline = self._monotonic() + timeout_seconds
        last_error: Optional[SemanticOracleError] = None
        while self._monotonic() < deadline:
            try:
                state = self.read_state()
                actionable = []
                for semantic_id in semantic_ids:
                    matches = self._matches(state, semantic_id)
                    if len(matches) > 1:
                        raise SemanticGateClosed("semantic target mapping is ambiguous")
                    if semantic_id == "reward/new-ship/continue":
                        if matches and self._new_ship_reward_visible_in_state(state):
                            actionable.append((semantic_id, matches[0]))
                        continue
                    if (
                        matches
                        and matches[0].actionable
                        and not self._blocking_rules(state, semantic_id)
                    ):
                        actionable.append((semantic_id, matches[0]))
                if len(actionable) > 1:
                    raise SemanticGateClosed("semantic wait set is ambiguous")
                if len(actionable) == 1 and (
                    minimum_generation is None or state.generation > minimum_generation
                ):
                    return actionable[0]
            except SemanticOracleError as exc:
                last_error = exc
            self._sleep(interval_seconds)
        if last_error is not None:
            raise SemanticGateClosed("semantic wait timed out") from last_error
        raise SemanticGateClosed("semantic wait timed out")

    def click_and_wait(
        self,
        semantic_id: str,
        expected_semantic_id: str,
        timeout_seconds: float,
    ) -> ButtonState:
        receipt = self.click(semantic_id)
        return self.wait_for(
            expected_semantic_id,
            timeout_seconds,
            minimum_generation=receipt.generation,
        )
